INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70dd722d-46ab-4b0c-a711-ceaf6d82555a', '顧道士亡弟子以束帛乞銘于余魯望因賦戲贈日休奉和', '顧道士亡弟子以束帛乞銘于余魯望因賦戲贈日休奉和', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["師去東華卻鍊形，門人求我誌金庭。","大椿枯後新爲記，仙鶴亡來始有銘。","瓊板欲刊知不朽，冰紈將受恐通靈。","君才莫歎無茲分，合注神玄劒解經。"]', '["師去东华卻鍊形，门人求我誌金庭。","大椿枯後新爲記，仙鹤亡来始有銘。","瓊板欲刊知不朽，冰紈將受恐通靈。","君才莫歎無茲分，合注神玄劒解經。"]', '诗', 'shi', '', NULL, '顧道士亡弟子以束帛乞銘于余魯望因賦戲贈日休奉和 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155a53e9-12ae-4b30-92c2-a37055f0b5bf', '秋夕文宴得遙字', '秋夕文宴得遙字', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["啼螿衰葉共蕭蕭，文宴無喧夜轉遙。","高韻最宜題雪讚，逸才偏稱和雲謠。","風吹翠蠟應難刻，月照清香太易消。","無限玄言一杯酒，可能容得蓋寬饒。"]', '["啼螿衰葉共蕭蕭，文宴無喧夜轉遙。","高韻最宜題雪讚，逸才偏稱和云謠。","风吹翠蠟應难刻，月照清香太易消。","無限玄言一杯酒，可能容得蓋寬饒。"]', '诗', 'shi', '', NULL, '秋夕文宴得遙字 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7983376d-f8af-42ba-a39e-6e20933e57bc', '南陽廣文欲於荆襄卜居因而有贈', '南陽廣文欲於荆襄卜居因而有贈', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["地脉從來是福鄉，廣文高致更無雙。","青精飯熟雲侵竈，白{衤劫}裘成雪濺窗。","度日竹書千萬字，經冬朮煎兩三缸。","鱸魚自是君家味，莫背松江憶漢江。"]', '["地脉從来是福乡，廣文高致更無雙。","青精飯熟云侵竈，白{衤劫}裘成雪濺窗。","度日竹书千万字，經冬朮煎兩三缸。","鱸鱼自是君家味，莫背松江憶漢江。"]', '诗', 'shi', '', NULL, '南陽廣文欲於荆襄卜居因而有贈 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe03fe0-b069-4dcc-b283-cf8cd6e3fc0d', '寄毘陵魏處士朴', '寄毘陵魏处士朴', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["文籍先生不肯官，絮巾衝雪把魚竿。","一堆方冊爲侯印，三級幽巖是將[壇]。","醉少最因吟月冷，瘦多偏爲臥雲寒。","兔皮衾暖篷舟穩，欲共誰遊七里灘。"]', '["文籍先生不肯官，絮巾衝雪把鱼竿。","一堆方冊爲侯印，三級幽巖是將[壇]。","醉少最因吟月冷，瘦多偏爲臥云寒。","兔皮衾暖篷舟穩，欲共誰游七里灘。"]', '诗', 'shi', '', NULL, '寄毘陵魏處士朴 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d02643b-5365-4118-bf32-06a361a849fd', '初冬偶作寄南陽潤卿', '初冬偶作寄南陽潤卿', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["寓居無事入清冬，雖設樽罍酒半空。","白菊爲霜翻帶紫，蒼苔因雨卻成紅。","迎潮預遣收魚笱，防雪先教蓋鶴籠。","唯待支硎最寒夜，共君披氅訪林公。"]', '["寓居無事入清冬，雖設樽罍酒半空。","白菊爲霜翻带紫，蒼苔因雨卻成紅。","迎潮預遣收鱼笱，防雪先教蓋鹤籠。","唯待支硎最寒夜，共君披氅訪林公。"]', '诗', 'shi', '', NULL, '初冬偶作寄南陽潤卿 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e019882-6413-489e-b549-8b6d4f7d4238', '冬曉章上人院', '冬晓章上人院', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["山堂冬曉寂無聞，一句清言憶領軍。","琥珀珠黏行處雪，椶櫚箒掃臥來雲。","松扉欲啓如鳴鶴，石鼎初煎若聚蚊。","不是戀師終去晚，陸機茸內足毛羣。"]', '["山堂冬晓寂無闻，一句清言憶領軍。","琥珀珠黏行处雪，椶櫚箒掃臥来云。","松扉欲啓如鳴鹤，石鼎初煎若聚蚊。","不是戀師終去晚，陸機茸內足毛羣。"]', '诗', 'shi', '', NULL, '冬曉章上人院 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('461135a3-239b-4147-a1e1-190cc89ddc07', '寄題鏡巖周尊師所居', '寄題镜巖周尊師所居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["八十餘年住鏡巖，鹿皮巾下雪髟髟。","牀寒不奈雲縈枕，經潤何妨雨滴函。","飲澗猨迴窺絕洞，緣梯人歇倚危杉。","如何計吏窮於鳥，欲望仙都舉一帆。"]', '["八十餘年住镜巖，鹿皮巾下雪髟髟。","牀寒不奈云縈枕，經潤何妨雨滴函。","饮澗猨迴窺絕洞，緣梯人歇倚危杉。","如何計吏窮於鸟，欲望仙都舉一帆。"]', '诗', 'shi', '', NULL, '寄題鏡巖周尊師所居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5716cfa5-dd43-4784-9f97-c4bb3a83e4bc', '寒夜文宴得泉字', '寒夜文宴得泉字', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["分明競襞七香牋，王郎風姿盡列仙。","盈篋共開華頂藥，滿缾同坼惠山泉。","蟹因霜重金膏溢，橘爲風多玉腦鮮。","吟罷不知詩首數，隔林明月過中天。"]', '["分明競襞七香牋，王郎风姿尽列仙。","盈篋共开华頂藥，满缾同坼惠山泉。","蟹因霜重金膏溢，橘爲风多玉腦鲜。","吟罷不知诗首數，隔林明月過中天。"]', '诗', 'shi', '', NULL, '寒夜文宴得泉字 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b2586c-c6c8-4432-9bf0-a0436690869d', '庚寅歲十一月新羅弘惠上人與本國同書請日休爲靈鷲山周禪師碑將還以詩送之', '庚寅歲十一月新羅弘惠上人與本国同书請日休爲靈鷲山周禪師碑將還以诗送之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["三十麻衣弄渚禽，豈知名字徹雞林。","勒銘雖即多遺草，越海還能抵萬金。","鯨鬣曉掀峰正燒，鼇睛夜沒島還陰。","二千餘字終天別，東望辰韓淚灑襟。"]', '["三十麻衣弄渚禽，豈知名字徹雞林。","勒銘雖即多遺草，越海還能抵万金。","鯨鬣晓掀峰正燒，鼇睛夜沒島還陰。","二千餘字終天別，东望辰韓泪灑襟。"]', '诗', 'shi', '', NULL, '庚寅歲十一月新羅弘惠上人與本國同書請日休爲靈鷲山周禪師碑將還以詩送之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68392941-41d8-4d1d-825f-b6da6488f05d', '送潤卿博士還華陽', '送潤卿博士還华陽', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雪打篷舟離酒旗，華陽居士半酣歸。","逍遙只恐逢雲將，恬澹真應降月妃。","仙市鹿胎如錦嫩，陰宮燕肉似酥肥。","公車草合蒲輪壞，爭不教他白日飛。"]', '["雪打篷舟離酒旗，华陽居士半酣归。","逍遙只恐逢云將，恬澹真應降月妃。","仙市鹿胎如錦嫩，陰宮燕肉似酥肥。","公车草合蒲輪壞，爭不教他白日飞。"]', '诗', 'shi', '', NULL, '送潤卿博士還華陽 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d738da-1ef0-4317-a435-ad2740825278', '寒日書齋即事三首 一', '寒日书斋即事三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["參佐三間似草堂，恬然無事可成忙。","移時寂歷燒松子，盡日殷勤拂乳牀。","將近道齋先衣褐，欲清詩思更焚香。","空庭好待中宵月，獨禮星辰學步罡。"]', '["參佐三间似草堂，恬然無事可成忙。","移时寂歷燒松子，尽日殷勤拂乳牀。","將近道斋先衣褐，欲清诗思更焚香。","空庭好待中宵月，独禮星辰学步罡。"]', '诗', 'shi', '', NULL, '寒日書齋即事三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe88c0b-4b17-45a7-bdce-e572cfab8244', '寒日書齋即事三首 二', '寒日书斋即事三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["不知何事有生涯，皮褐親裁學道家。","深夜數甌唯柏葉，清晨一器是雲華。","盆池有鷺窺蘋沫，石版無人掃桂花。","江漢欲歸應未得，夜來頻夢赤城霞。"]', '["不知何事有生涯，皮褐親裁学道家。","深夜數甌唯柏葉，清晨一器是云华。","盆池有鷺窺蘋沫，石版無人掃桂花。","江漢欲归應未得，夜来頻梦赤城霞。"]', '诗', 'shi', '', NULL, '寒日書齋即事三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a89434e3-a9e5-4ab0-9bdf-aadcb3e296eb', '寒日書齋即事三首 三', '寒日书斋即事三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["方朔家貧未有車，肯從榮利捨樵漁。","從公未怪多侵酒，見客唯求轉借書。","暫聽松風生意足，偶看溪月世情疎。","如鉤得貴非吾事，合向煙波爲五魚。"]', '["方朔家貧未有车，肯從榮利捨樵漁。","從公未怪多侵酒，见客唯求轉借书。","暫听松风生意足，偶看溪月世情疎。","如鉤得貴非吾事，合向煙波爲五鱼。"]', '诗', 'shi', '', NULL, '寒日書齋即事三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('719ef17d-c4f2-4db5-a003-20563e43357c', '臘後送內大德從勗遊天台', '臘後送內大德從勗游天台', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["講散重雲下九天，大君恩賜許隨緣。","霜中一鉢無辭乞，湖上孤舟不廢禪。","夢入瓊樓寒有月，行過石樹凍無煙他時瓜鏡知何用，吳越風光滿御筵。"]', '["講散重云下九天，大君恩賜許隨緣。","霜中一鉢無辞乞，湖上孤舟不廢禪。","梦入瓊楼寒有月，行過石樹凍無煙他时瓜镜知何用，吳越风光满御筵。"]', '诗', 'shi', '', NULL, '臘後送內大德從勗遊天台 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d43e3ff-6078-4459-a640-27d32c61e8ea', '寄題玉霄峰葉涵象尊師所居', '寄題玉霄峰葉涵象尊師所居', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["青冥向上玉霄峰，元始先生戴紫蓉。","曉案瓊文光洞壑，夜壇香氣惹杉松。","閑迎仙客來爲鶴，靜噀靈符去是龍。","子細捫心無偃骨，欲隨師去肯相容。"]', '["青冥向上玉霄峰，元始先生戴紫蓉。","晓案瓊文光洞壑，夜壇香氣惹杉松。","闲迎仙客来爲鹤，静噀靈符去是龙。","子細捫心無偃骨，欲隨師去肯相容。"]', '诗', 'shi', '', NULL, '寄題玉霄峰葉涵象尊師所居 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994c3a5d-d60b-4534-b83b-092fce9f9ec9', '奉和魯望寄南陽廣文次韻', '奉和魯望寄南陽廣文次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["春彩融融釋凍塘，日精閑嚥坐巖房。","瓊函靜啓從猨覰，金液初開與鶴嘗。","八會舊文多搭寫，七真遺語剩思量。","不知夢到爲何處，紅藥滿山煙月香。"]', '["春彩融融釋凍塘，日精闲嚥坐巖房。","瓊函静啓從猨覰，金液初开與鹤嘗。","八會旧文多搭寫，七真遺語剩思量。","不知梦到爲何处，紅藥满山煙月香。"]', '诗', 'shi', '', NULL, '奉和魯望寄南陽廣文次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b399661-7243-43fa-af6a-a818009d30ff', '題支山南峰僧', '題支山南峰僧', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雲侵壞衲重隈肩，不下南峰不記年。","池裏羣魚曾受戒，林間孤鶴欲參禪。","雞頭竹上開危徑，鴨脚花中擿廢泉。","無限吳都堪賞事，何如來此看師眠。"]', '["云侵壞衲重隈肩，不下南峰不記年。","池裏羣鱼曾受戒，林间孤鹤欲參禪。","雞头竹上开危徑，鴨脚花中擿廢泉。","無限吳都堪賞事，何如来此看師眠。"]', '诗', 'shi', '', NULL, '題支山南峰僧 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4fbbd2-6462-4408-bd0e-70d395800562', '送董少卿游茅山', '送董少卿游茅山', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["名卿風度足杓斜，一舸閑尋二許家。","天影曉通金井水，山靈深護玉門沙。","空壇禮後銷香母，陰洞緣時觸乳花。","盡待于公作廷尉，不須從此便餐霞。"]', '["名卿风度足杓斜，一舸闲尋二許家。","天影晓通金井水，山靈深護玉门沙。","空壇禮後銷香母，陰洞緣时觸乳花。","尽待于公作廷尉，不須從此便餐霞。"]', '诗', 'shi', '', NULL, '送董少卿游茅山 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d4ad43-6744-4942-9dc1-0723ad56f7e0', '詶魯望見迎綠罽次韻', '詶魯望见迎綠罽次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["輕裁鴨綠任金刀，不怕西風斷野蒿。","詶贈既無青玉案，纖華猶欠赤霜袍。","煙披怪石難同逸，竹映仙禽未勝高。","成後料君無別事，只應酣飲詠離騷。"]', '["轻裁鴨綠任金刀，不怕西风斷野蒿。","詶贈既無青玉案，纖华猶欠赤霜袍。","煙披怪石难同逸，竹映仙禽未勝高。","成後料君無別事，只應酣饮詠離騷。"]', '诗', 'shi', '', NULL, '詶魯望見迎綠罽次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4dba9f-e1c1-41c3-9a91-e0d1f7825aa7', '寄懷南陽潤卿', '寄懷南陽潤卿', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鹿門山下捕魚郎，今向江南作渴羌。","無事只陪看藕樣，有錢唯欲買湖光。","醉來渾忘移花處，病起空聞焙藥香。","何事對君猶有媿，一篷衝雪返華陽。"]', '["鹿门山下捕鱼郎，今向江南作渴羌。","無事只陪看藕樣，有錢唯欲買湖光。","醉来渾忘移花处，病起空闻焙藥香。","何事对君猶有媿，一篷衝雪返华陽。"]', '诗', 'shi', '', NULL, '寄懷南陽潤卿 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee1e079-46f0-4c94-ade0-b3617e03a6e5', '魯望憫承吉之孤爲詩序邀予屬和欲用予道振其孤而利之噫承吉之困身後乎魯望視予困與承吉生前孰若哉未有已困而能振人者抑爲之辭用塞良友', '魯望憫承吉之孤爲诗序邀予屬和欲用予道振其孤而利之噫承吉之困身後乎魯望視予困與承吉生前孰若哉未有已困而能振人者抑爲之辞用塞良友', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["先生清骨葬煙霞，業破孤存孰爲嗟。","幾篋詩編分貴位，一林石笋散豪家。","兒過舊宅啼楓影，姬繞荒田泣稗花。","唯我共君堪便戒，莫將文譽作生涯。"]', '["先生清骨葬煙霞，業破孤存孰爲嗟。","幾篋诗編分貴位，一林石笋散豪家。","兒過旧宅啼楓影，姬繞荒田泣稗花。","唯我共君堪便戒，莫將文譽作生涯。"]', '诗', 'shi', '', NULL, '魯望憫承吉之孤爲詩序邀予屬和欲用予道振其孤而利之噫承吉之困身後乎魯望視予困與承吉生前孰若哉未有已困而能振人者抑爲之辭用塞良友 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd329561-421d-4b5e-b0a3-ff4deabb3b56', '寄潤卿博士', '寄潤卿博士', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["高眠可爲要玄纁，鵲尾金爐一世焚。","塵外鄉人爲許掾，山中地主是茅君。","將收芝菌唯防雪，欲曬圖書不奈雲。","若使華陽終臥去，漢家封禪用誰文。"]', '["高眠可爲要玄纁，鵲尾金爐一世焚。","塵外乡人爲許掾，山中地主是茅君。","將收芝菌唯防雪，欲曬圖书不奈云。","若使华陽終臥去，漢家封禪用誰文。"]', '诗', 'shi', '', NULL, '寄潤卿博士 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b1fa7eb-4658-477b-9a58-622ca51385b5', '奉和魯望白菊', '奉和魯望白菊', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["已過重陽半月天，琅華千點照寒煙。","蘂香亦似浮金靨，花樣還如鏤玉錢。","玩影馮妃堪比豔，鍊形蕭史好爭妍。","無由擿向牙箱裏，飛上方諸贈列仙。"]', '["已過重陽半月天，琅华千点照寒煙。","蘂香亦似浮金靨，花樣還如鏤玉錢。","玩影馮妃堪比豔，鍊形蕭史好爭妍。","無由擿向牙箱裏，飞上方諸贈列仙。"]', '诗', 'shi', '', NULL, '奉和魯望白菊 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e62f6f-b341-4e1d-9696-f02732fc1e6b', '華亭鶴聞之舊矣及來吳中以錢半千得一隻養之殆經歲不幸爲飲啄所誤經夕而卒悼之不已遂繼以詩南陽潤卿博士浙東德師侍御毘陵魏不琢處士東吳陸魯望秀才及厚於予者悉寄之請垂見和', '华亭鹤闻之旧矣及来吳中以錢半千得一隻養之殆經歲不幸爲饮啄所誤經夕而卒悼之不已遂繼以诗南陽潤卿博士浙东德師侍御毘陵魏不琢处士东吳陸魯望秀才及厚於予者悉寄之請垂见和', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["池上低摧病不行，誰教仙魄反層城。","陰苔尚有前朝跡，皎月新無昨夜聲。","菰米正殘三日料，筠籠休礙九霄程。","不知此恨何時盡，遇著雲泉即愴情。"]', '["池上低摧病不行，誰教仙魄反層城。","陰苔尚有前朝跡，皎月新無昨夜声。","菰米正殘三日料，筠籠休礙九霄程。","不知此恨何时尽，遇著云泉即愴情。"]', '诗', 'shi', '', NULL, '華亭鶴聞之舊矣及來吳中以錢半千得一隻養之殆經歲不幸爲飲啄所誤經夕而卒悼之不已遂繼以詩南陽潤卿博士浙東德師侍御毘陵魏不琢處士東吳陸魯望秀才及厚於予者悉寄之請垂見和 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef09f295-4911-43d2-a86f-69bf36315a04', '傷開元觀顧道士', '傷开元观顧道士', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["協晨宮上啓金扉，詔使先生坐蛻歸。","鶴有一聲應是哭，丹無餘粒恐潛飛。","煙淒玉笥封雲篆，月慘琪花葬羽衣。","腸斷雷平舊遊處，五芝無影草微微。"]', '["協晨宮上啓金扉，詔使先生坐蛻归。","鹤有一声應是哭，丹無餘粒恐潛飞。","煙淒玉笥封云篆，月慘琪花葬羽衣。","腸斷雷平旧游处，五芝無影草微微。"]', '诗', 'shi', '', NULL, '傷開元觀顧道士 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db480703-258d-4f0a-b209-cc82ba3350b7', '醉中即席贈潤卿博士', '醉中即席贈潤卿博士', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["適越遊吳一散仙，銀缾玉柄兩翛然。","茅山頂上攜書簏，笠澤心中漾酒船。","桐木布溫吟倦後，桃花飯熟醉醒前。","謝安四十餘方起，猶自高閑得數年。"]', '["適越游吳一散仙，銀缾玉柄兩翛然。","茅山頂上携书簏，笠澤心中漾酒船。","桐木布溫吟倦後，桃花飯熟醉醒前。","謝安四十餘方起，猶自高闲得數年。"]', '诗', 'shi', '', NULL, '醉中即席贈潤卿博士 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78939f21-3c87-4a39-8954-51086fc6830c', '偶留羊振文先輩及一二文友小飲日休以眼病初平不敢飲酒遣侍密歡因成四韻', '偶留羊振文先輩及一二文友小饮日休以眼病初平不敢饮酒遣侍密歡因成四韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["謝莊初起恰花晴，強侍紅筵不避觥。","久斷杯盂華蓋喜，忽聞歌吹谷神驚。","䙰褷正重新開柳，呫囁難通乍囀鶯。","猶有僧虔多蜜炬，不辭相伴到天明。"]', '["謝莊初起恰花晴，強侍紅筵不避觥。","久斷杯盂华蓋喜，忽闻歌吹谷神驚。","䙰褷正重新开柳，呫囁难通乍囀鶯。","猶有僧虔多蜜炬，不辞相伴到天明。"]', '诗', 'shi', '', NULL, '偶留羊振文先輩及一二文友小飲日休以眼病初平不敢飲酒遣侍密歡因成四韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e70f181-d336-4125-b8e3-11b280d38fe2', '奉送浙東德師侍御罷府西歸', '奉送浙东德師侍御罷府西归', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["建安才子太微仙，暫上金臺許二年。","形影欲歸溫室樹，夢魂猶傍越溪蓮。","空將海月爲京信，尚使樵風送酒船。","從此受恩知有處，免爲傖鬼恨吳天。"]', '["建安才子太微仙，暫上金台許二年。","形影欲归溫室樹，梦魂猶傍越溪蓮。","空將海月爲京信，尚使樵风送酒船。","從此受恩知有处，免爲傖鬼恨吳天。"]', '诗', 'shi', '', NULL, '奉送浙東德師侍御罷府西歸 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60558d98-1895-4b5d-bc3e-5bed6d5c313e', '送羊振文先輩往桂陽歸覲', '送羊振文先輩往桂陽归覲', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["桂陽新命下彤墀，彩服行當欲雪時。","登第已聞傳禰賦，問安猶聽講韓詩。","竹人臨水迎符節，風母穿雲避信旗。","無限湘中悼騷恨，憑君此去謝江蘺。"]', '["桂陽新命下彤墀，彩服行當欲雪时。","登第已闻傳禰賦，问安猶听講韓诗。","竹人臨水迎符節，风母穿云避信旗。","無限湘中悼騷恨，憑君此去謝江蘺。"]', '诗', 'shi', '', NULL, '送羊振文先輩往桂陽歸覲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c8f4370-5613-40cf-8c28-a6d4536cf314', '褚家林亭', '褚家林亭', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["廣亭遙對舊娃宮，竹島蘿溪委曲通。","茂苑樓臺低檻外，太湖魚鳥徹池中。","蕭疎桂影移茶具，狼籍蘋花上釣筒。","爭得共君來此住，便披鶴氅對清風。"]', '["廣亭遙对旧娃宮，竹島蘿溪委曲通。","茂苑楼台低檻外，太湖鱼鸟徹池中。","蕭疎桂影移茶具，狼籍蘋花上釣筒。","爭得共君来此住，便披鹤氅对清风。"]', '诗', 'shi', '', NULL, '褚家林亭 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e268c498-ac2c-46bb-b1db-76f43de3eeb2', '送圓載上人歸日本國', '送圓載上人归日本国', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["講殿談餘著賜衣，椰帆卻返舊禪扉。","貝多紙上經文動，如意缾中佛爪飛。","颶母影邊持戒宿，波神宮裏受齋歸。","家山到日將何入，白象新秋十二圍。"]', '["講殿談餘著賜衣，椰帆卻返旧禪扉。","貝多紙上經文动，如意缾中佛爪飞。","颶母影邊持戒宿，波神宮裏受斋归。","家山到日將何入，白象新秋十二圍。"]', '诗', 'shi', '', NULL, '送圓載上人歸日本國 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e905c088-2149-446f-b6da-0361f0f1e9c9', '重送', '重送', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雲濤萬里最東頭，射馬臺深玉署秋。","無限屬城爲躶國，幾多分界是亶州。","取經海底開龍藏，誦咒空中散蜃樓。","不奈此時貧且病，乘桴直欲伴師遊。"]', '["云濤万里最东头，射马台深玉署秋。","無限屬城爲躶国，幾多分界是亶州。","取經海底开龙藏，誦咒空中散蜃楼。","不奈此时貧且病，乘桴直欲伴師游。"]', '诗', 'shi', '', NULL, '重送 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ba1830-90f1-46ec-9c0d-d5061bd43cce', '潤卿遺青䭀飯兼之一絕聊用荅謝', '潤卿遺青䭀飯兼之一絕聊用荅謝', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["傳得三元䭀飯名，大宛聞說有仙卿。","分泉過屋舂青稻，拂霧彯衣折紫莖。","蒸處不教雙鶴見，服來唯怕五雲生。","草堂空坐無飢色，時把金津漱一聲。"]', '["傳得三元䭀飯名，大宛闻说有仙卿。","分泉過屋舂青稻，拂霧彯衣折紫莖。","蒸处不教雙鹤见，服来唯怕五云生。","草堂空坐無飢色，时把金津漱一声。"]', '诗', 'shi', '', NULL, '潤卿遺青䭀飯兼之一絕聊用荅謝 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72806c1c-61a0-41e1-a694-12b1a1598ca0', '鴛鴦二首 一', '鴛鴦二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["雙絲絹上爲新樣，連理枝頭是故園。","翠浪萬迴同過影，玉沙千處共棲痕。","若非足恨佳人魄，即是多情年少魂。","應念孤飛爭別宿，蘆花蕭瑟雨黃昏。"]', '["雙絲絹上爲新樣，連理枝头是故园。","翠浪万迴同過影，玉沙千处共棲痕。","若非足恨佳人魄，即是多情年少魂。","應念孤飞爭別宿，蘆花蕭瑟雨黄昏。"]', '诗', 'shi', '', NULL, '鴛鴦二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be1e1c0-de13-4551-b30c-66955ac3c8f6', '鴛鴦二首 二', '鴛鴦二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鈿𨯥雕鏤費深功，舞妓衣邊繡莫窮。","無日不來湘渚上，有時還在鏡湖中。","煙濃共拂芭蕉雨，浪細雙遊菡萏風。","應笑豪家鸚鵡伴，年年徒被鎖金籠。"]', '["鈿𨯥雕鏤費深功，舞妓衣邊繡莫窮。","無日不来湘渚上，有时還在镜湖中。","煙濃共拂芭蕉雨，浪細雙游菡萏风。","應笑豪家鸚鵡伴，年年徒被鎖金籠。"]', '诗', 'shi', '', NULL, '鴛鴦二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2326c5f-68bc-41d0-ba00-6fba3cb629f8', '傷小女', '傷小女', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一歲猶未滿，九泉何太深。","唯餘卷書草，相對共傷心。"]', '["一歲猶未满，九泉何太深。","唯餘卷书草，相对共傷心。"]', '诗', 'shi', '', NULL, '傷小女 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be95a0c-7676-49f2-bf54-441d9a1b2a56', '秋江曉望', '秋江晓望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["萬頃湖天碧，一星飛鷺白。","此時放懷望，不厭爲浮客。"]', '["万頃湖天碧，一星飞鷺白。","此时放懷望，不厭爲浮客。"]', '诗', 'shi', '', NULL, '秋江曉望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3771b63b-bb2e-4e63-afed-12ddc6d1e539', '閑夜酒醒', '闲夜酒醒', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["醒來山月高，孤枕羣書裏。","酒渴漫思茶，山童呼不起。"]', '["醒来山月高，孤枕羣书裏。","酒渴漫思茶，山童呼不起。"]', '诗', 'shi', '', NULL, '閑夜酒醒 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f56a36fe-6139-4ffd-a38f-afcce31c6ef6', '和魯望風人詩三首 一', '和魯望风人诗三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["刻石書離恨，因成別後悲。","莫言春繭薄，猶有萬重思。"]', '["刻石书離恨，因成別後悲。","莫言春繭薄，猶有万重思。"]', '诗', 'shi', '', NULL, '和魯望風人詩三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b94b546-cf83-458b-9a02-a4f2c270e622', '和魯望風人詩三首 二', '和魯望风人诗三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鏤出容刀飾，親逢巧笑難。","日中騷客佩，爭奈即闌干。"]', '["鏤出容刀飾，親逢巧笑难。","日中騷客佩，爭奈即闌干。"]', '诗', 'shi', '', NULL, '和魯望風人詩三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2cf08f-fc4e-4c8e-a4de-251895a51d42', '和魯望風人詩三首 三', '和魯望风人诗三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["江上秋聲起，從來浪得名。","逆風猶挂席，若不會凡情。"]', '["江上秋声起，從来浪得名。","逆风猶挂席，若不會凡情。"]', '诗', 'shi', '', NULL, '和魯望風人詩三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('806923da-4389-4936-8191-07798c192e10', '古函關', '古函关', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["破落古關城，猶能扼帝京。","今朝行客過，不待曉雞鳴。"]', '["破落古关城，猶能扼帝京。","今朝行客過，不待晓雞鳴。"]', '诗', 'shi', '', NULL, '古函關 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20edc4ff-7afd-4a52-a5ec-905b4b486d8a', '聰明泉', '聰明泉', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一勺如瓊液，將愚擬望賢。","欲知心不變，還似飲貪泉。"]', '["一勺如瓊液，將愚擬望賢。","欲知心不变，還似饮貪泉。"]', '诗', 'shi', '', NULL, '聰明泉 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18728bd3-126c-41e7-a794-deea2b067e51', '史處士', '史处士', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["山期須早赴，世累莫遲留。","忽遇狂風起，閑心不自由。"]', '["山期須早赴，世累莫遲留。","忽遇狂风起，闲心不自由。"]', '诗', 'shi', '', NULL, '史處士 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b36469-4476-4d60-80b8-738e051e8124', '芳草渡', '芳草渡', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["溪南越鄉音，古柳渡江深。","日晚無來客，閑船繫綠陰。"]', '["溪南越乡音，古柳渡江深。","日晚無来客，闲船繫綠陰。"]', '诗', 'shi', '', NULL, '芳草渡 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0eac395-46d4-4f8a-a084-adac771db81c', '古宮詞三首 一', '古宮词三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["樓殿倚明月，參差如亂峰。","宮花半夜發，不待景陽鐘。"]', '["楼殿倚明月，參差如亂峰。","宮花半夜發，不待景陽鐘。"]', '诗', 'shi', '', NULL, '古宮詞三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f31b462-6701-4f9c-864b-7369d2ac512c', '古宮詞三首 二', '古宮词三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["閑騎小步馬，獨遶萬年枝。","盡日看花足，君王自不知。"]', '["闲騎小步马，独遶万年枝。","尽日看花足，君王自不知。"]', '诗', 'shi', '', NULL, '古宮詞三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('919ba400-76f3-49a1-aa14-c9acbad68553', '古宮詞三首 三', '古宮词三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["玉枕寐不足，宮花空觸簷。","梁間燕不睡，應怪夜明簾。"]', '["玉枕寐不足，宮花空觸簷。","梁间燕不睡，應怪夜明簾。"]', '诗', 'shi', '', NULL, '古宮詞三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b9c7dd-04ba-446d-95e9-cfdeb477d767', '春日陪崔諫議櫻桃園宴', '春日陪崔諫議櫻桃园宴', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["萬樹香飄水麝風，蠟燻花雪盡成紅。","夜深歡態狀不得，醉客圖開明月中。"]', '["万樹香飄水麝风，蠟燻花雪尽成紅。","夜深歡態狀不得，醉客圖开明月中。"]', '诗', 'shi', '', NULL, '春日陪崔諫議櫻桃園宴 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e01d799-ea31-44b9-beda-39f919271104', '松江早春', '松江早春', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["松陵清淨雪消初，見底新安恐未如。","穩凭船舷無一事，分明數得鱠殘魚。"]', '["松陵清淨雪消初，见底新安恐未如。","穩凭船舷無一事，分明數得鱠殘鱼。"]', '诗', 'shi', '', NULL, '松江早春 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb2c63be-c0e6-4780-be8f-922644353b70', '女墳湖', '女墳湖', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["萬貴千奢已寂寥，可憐幽憤爲誰嬌。","須知韓重相思骨，直在芙蓉向下消。"]', '["万貴千奢已寂寥，可怜幽憤爲誰嬌。","須知韓重相思骨，直在芙蓉向下消。"]', '诗', 'shi', '', NULL, '女墳湖 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbe62480-4dbf-44bd-adee-6686095afa8a', '泰伯廟', '泰伯廟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一廟爭祠兩讓君，幾千年後轉清[芬]。","當時盡解稱高義，誰敢教他莽卓聞。"]', '["一廟爭祠兩讓君，幾千年後轉清[芬]。","當时尽解稱高義，誰敢教他莽卓闻。"]', '诗', 'shi', '', NULL, '泰伯廟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28d617b-cd14-40bd-a004-6b49bfd89bfd', '宿木蘭院', '宿木蘭院', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["木蘭院裏雙棲鶴，長被金鉦聒不眠。","今夜宿來還似爾，到明無計夢雲泉。"]', '["木蘭院裏雙棲鹤，长被金鉦聒不眠。","今夜宿来還似爾，到明無計梦云泉。"]', '诗', 'shi', '', NULL, '宿木蘭院 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a56e85-7a2a-443f-9c5c-de4f6623b245', '重題薔薇', '重題薔薇', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["濃似猩猩初染素，輕如燕燕欲凌空。","可憐細麗難勝日，照得深紅作淺紅。"]', '["濃似猩猩初染素，轻如燕燕欲凌空。","可怜細丽难勝日，照得深紅作淺紅。"]', '诗', 'shi', '', NULL, '重題薔薇 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f347949-2a6a-447c-9e8a-60f9b6094f0a', '春夕酒醒', '春夕酒醒', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["四弦纔罷醉蠻奴，酃醁餘香在翠爐。","夜半醒來紅蠟短，一枝寒淚作珊瑚。"]', '["四弦纔罷醉蠻奴，酃醁餘香在翠爐。","夜半醒来紅蠟短，一枝寒泪作珊瑚。"]', '诗', 'shi', '', NULL, '春夕酒醒 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56dbedd-5899-4ff1-a954-ea40534388ad', '青門閑泛', '青门闲泛', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["青翰虛徐夏思清，愁煙漠漠荇花平。","醉來欲把田田葉，盡裹當時醒酒鯖。"]', '["青翰虛徐夏思清，愁煙漠漠荇花平。","醉来欲把田田葉，尽裹當时醒酒鯖。"]', '诗', 'shi', '', NULL, '青門閑泛 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210076fa-9033-40c3-8a90-0cc079083d43', '木蘭後池三詠 重臺蓮花', '木蘭後池三詠 重台蓮花', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["欹紅婑媠力難任，每葉頭邊半米金。","可得教他水妃見，兩重元是一重心。"]', '["欹紅婑媠力难任，每葉头邊半米金。","可得教他水妃见，兩重元是一重心。"]', '诗', 'shi', '', NULL, '木蘭後池三詠 重臺蓮花 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26de7702-1236-4736-8e37-9bc5098d5c0a', '木蘭後池三詠 浮萍', '木蘭後池三詠 浮萍', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["嫩似金脂颺似煙，多情渾欲擁紅蓮。","明朝擬附南風信，寄與湘妃作翠鈿。"]', '["嫩似金脂颺似煙，多情渾欲擁紅蓮。","明朝擬附南风信，寄與湘妃作翠鈿。"]', '诗', 'shi', '', NULL, '木蘭後池三詠 浮萍 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf9a0162-36c9-4ca6-bed6-b98152f96764', '木蘭後池三詠 白蓮', '木蘭後池三詠 白蓮', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["但恐醍醐難並潔，秖應薝蔔可齊香。","半垂金粉知何似，靜婉臨溪照額黃。"]', '["但恐醍醐难並潔，秖應薝蔔可齊香。","半垂金粉知何似，静婉臨溪照額黄。"]', '诗', 'shi', '', NULL, '木蘭後池三詠 白蓮 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('244d56ad-693a-4d59-8f78-4733f43ea221', '重題後池', '重題後池', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["細雨闌珊眠鷺覺，鈿波悠漾並鴛嬌。","適來會得荆王意，秖爲蓮莖重細腰。"]', '["細雨闌珊眠鷺覺，鈿波悠漾並鴛嬌。","適来會得荆王意，秖爲蓮莖重細腰。"]', '诗', 'shi', '', NULL, '重題後池 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e4b14f8-93bf-4f8c-b2ee-74e5235fe359', '庭中初植松桂魯望偶題奉和次韻', '庭中初植松桂魯望偶題奉和次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["毿毿綠髪垂輕露，獵獵丹華動細風。","恰似青童君欲會，儼然相向立庭中。"]', '["毿毿綠髪垂轻露，獵獵丹华动細风。","恰似青童君欲會，儼然相向立庭中。"]', '诗', 'shi', '', NULL, '庭中初植松桂魯望偶題奉和次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f5a26c-b3d4-43e7-a521-5912808eb1b1', '魯望戲題書印囊奉和次韻', '魯望戲題书印囊奉和次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["金篆方圓一寸餘，可憐銀艾未思渠。","不知夫子將心印，印破人間萬卷書。"]', '["金篆方圓一寸餘，可怜銀艾未思渠。","不知夫子將心印，印破人间万卷书。"]', '诗', 'shi', '', NULL, '魯望戲題書印囊奉和次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fa525b-ae2e-4d86-8397-85757c742433', '館娃宮懷古五絕 一', '館娃宮懷古五絕 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["綺閤飄香下太湖，亂兵侵曉上姑蘇。","越王大有堪羞處，秖把西施賺得吳。"]', '["綺閤飄香下太湖，亂兵侵晓上姑蘇。","越王大有堪羞处，秖把西施賺得吳。"]', '诗', 'shi', '', NULL, '館娃宮懷古五絕 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf213c77-954f-4d7d-8e08-a61a34b898d1', '館娃宮懷古五絕 二', '館娃宮懷古五絕 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鄭妲無言下玉墀，夜來飛箭滿罘罳。","越王定指高臺笑，却見當時金鏤楣。"]', '["鄭妲無言下玉墀，夜来飞箭满罘罳。","越王定指高台笑，却见當时金鏤楣。"]', '诗', 'shi', '', NULL, '館娃宮懷古五絕 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f21805fb-39a6-42d4-8413-6beb7d99fd6c', '館娃宮懷古五絕 三', '館娃宮懷古五絕 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["半夜娃宮作戰場，血腥猶雜宴時香。","西施不及燒殘蠟，猶爲君王泣數行。"]', '["半夜娃宮作戰場，血腥猶杂宴时香。","西施不及燒殘蠟，猶爲君王泣數行。"]', '诗', 'shi', '', NULL, '館娃宮懷古五絕 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea347ec7-2a68-49a9-8a60-899ce81320df', '館娃宮懷古五絕 四', '館娃宮懷古五絕 四', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["素襪雖遮未掩羞，越[兵]猶怕伍員頭。","吳王恨魄今如在，只合西施瀨上遊。"]', '["素襪雖遮未掩羞，越[兵]猶怕伍員头。","吳王恨魄今如在，只合西施瀨上游。"]', '诗', 'shi', '', NULL, '館娃宮懷古五絕 四 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77143ba-7c54-4583-95b3-f9d5d849aeba', '館娃宮懷古五絕 五', '館娃宮懷古五絕 五', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["響屧廊中金玉步，采蘋山上綺羅身。","不知水葬今何處，溪月彎彎欲效顰。"]', '["响屧廊中金玉步，采蘋山上綺羅身。","不知水葬今何处，溪月彎彎欲效顰。"]', '诗', 'shi', '', NULL, '館娃宮懷古五絕 五 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7f3281f-280e-4ac0-bef9-1cdd8e3f6580', '虎丘寺西小溪閑泛三絕 一', '虎丘寺西小溪闲泛三絕 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鼓子花明白石岸，桃枝竹覆翠嵐溪。","分明似對天台洞，應厭頑仙不肯迷。"]', '["鼓子花明白石岸，桃枝竹覆翠嵐溪。","分明似对天台洞，應厭頑仙不肯迷。"]', '诗', 'shi', '', NULL, '虎丘寺西小溪閑泛三絕 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fcf8cd-5248-4d18-9ef9-0065da1a61e5', '虎丘寺西小溪閑泛三絕 二', '虎丘寺西小溪闲泛三絕 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["絕壑秖憐白羽傲，窮溪唯覺錦鱗癡。","更深尚有通樵處，或是秦人未可知。"]', '["絕壑秖怜白羽傲，窮溪唯覺錦鱗癡。","更深尚有通樵处，或是秦人未可知。"]', '诗', 'shi', '', NULL, '虎丘寺西小溪閑泛三絕 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78e6f208-9a90-42f7-ba00-09ca6ba96259', '虎丘寺西小溪閑泛三絕 三', '虎丘寺西小溪闲泛三絕 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["高下不驚紅翡翠，淺深還礙白薔薇。","船頭繫箇松根上，欲待逢仙不擬歸。"]', '["高下不驚紅翡翠，淺深還礙白薔薇。","船头繫箇松根上，欲待逢仙不擬归。"]', '诗', 'shi', '', NULL, '虎丘寺西小溪閑泛三絕 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c8b568-e69e-4eb8-aa49-cb808e316dbe', '天竺寺八月十五日夜桂子', '天竺寺八月十五日夜桂子', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["玉顆珊珊下月輪，殿前拾得露華新。","至今不會天中事，應是嫦娥擲與人。"]', '["玉顆珊珊下月輪，殿前拾得露华新。","至今不會天中事，應是嫦娥擲與人。"]', '诗', 'shi', '', NULL, '天竺寺八月十五日夜桂子 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e91183-38bc-4a69-b254-31bff930267e', '釣侶二章 一', '釣侶二章 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["趁眠無事避風濤，一斗霜鱗換濁醪。","驚怪兒童呼不得，盡衝煙雨漉車螯。"]', '["趁眠無事避风濤，一斗霜鱗換濁醪。","驚怪兒童呼不得，尽衝煙雨漉车螯。"]', '诗', 'shi', '', NULL, '釣侶二章 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0266d93d-fad5-4ef1-8497-6ce6bd347771', '釣侶二章 二', '釣侶二章 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["嚴陵灘勢似雲崩，釣具歸來放石層。","煙浪濺篷寒不睡，更將枯蚌點漁燈。"]', '["嚴陵灘勢似云崩，釣具归来放石層。","煙浪濺篷寒不睡，更將枯蚌点漁灯。"]', '诗', 'shi', '', NULL, '釣侶二章 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('075e544d-2f69-4806-9759-394fa94efad0', '寄同年韋校書', '寄同年韋校书', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["二年疎放飽江潭，水物山容盡足躭。","唯有故人憐未替，欲封乾鱠寄終南。"]', '["二年疎放飽江潭，水物山容尽足躭。","唯有故人怜未替，欲封乾鱠寄終南。"]', '诗', 'shi', '', NULL, '寄同年韋校書 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7750ef1e-6f7c-4777-80b0-b762f321e59e', '初冬偶作', '初冬偶作', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["豹皮茵下百餘錢，劉墮閑沽盡醉眠。","酒病校來無一事，鶴亡松老似經年。"]', '["豹皮茵下百餘錢，劉墮闲沽尽醉眠。","酒病校来無一事，鹤亡松老似經年。"]', '诗', 'shi', '', NULL, '初冬偶作 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8c6926-70af-4abd-b4aa-d61502f9de22', '醉中寄魯望一壺幷一絕', '醉中寄魯望一壺幷一絕', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["門巷寥寥空紫苔，先生應渴解酲杯。","醉中不得親相倚，故遣青州從事來。"]', '["门巷寥寥空紫苔，先生應渴解酲杯。","醉中不得親相倚，故遣青州從事来。"]', '诗', 'shi', '', NULL, '醉中寄魯望一壺幷一絕 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86321e27-a244-4e5b-a420-f9d355b1be2f', '更次來韻寄魯望', '更次来韻寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["蕭蕭紅葉擲蒼苔，玄晏先生欠一杯。","從此問君還酒債，顏延之送幾錢來。"]', '["蕭蕭紅葉擲蒼苔，玄晏先生欠一杯。","從此问君還酒債，顏延之送幾錢来。"]', '诗', 'shi', '', NULL, '更次來韻寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f30293-8c39-4d14-a0cb-f3e0df2998f9', '重玄寺雙矮檜', '重玄寺雙矮檜', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["撲地枝回是翠鈿，碧絲籠細不成煙。","應如天竺難陀寺，一對狻猊相枕眠。"]', '["撲地枝回是翠鈿，碧絲籠細不成煙。","應如天竺难陀寺，一对狻猊相枕眠。"]', '诗', 'shi', '', NULL, '重玄寺雙矮檜 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f5c39e-d0a2-46c2-98c9-cfd74c7a61fa', '奉酬魯望醉中戲贈', '奉酬魯望醉中戲贈', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["秦吳風俗昔難同，唯有才情事事通。","剛戀水雲歸不得，前身應是太湖公。"]', '["秦吳风俗昔难同，唯有才情事事通。","剛戀水云归不得，前身應是太湖公。"]', '诗', 'shi', '', NULL, '奉酬魯望醉中戲贈 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddbe127b-6fe1-482b-a1ea-bbf1fb4879e7', '臯橋', '臯橋', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["臯橋依舊綠楊中，閭里猶生隱士風。","唯我到來居上館，不知何道勝梁鴻。"]', '["臯橋依旧綠楊中，閭里猶生隐士风。","唯我到来居上館，不知何道勝梁鴻。"]', '诗', 'shi', '', NULL, '臯橋 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa17eef-441f-4e0f-bb10-37d2d71f601c', '軍事院霜菊盛開因書一絕寄上諫議', '軍事院霜菊盛开因书一絕寄上諫議', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["金華千點曉霜凝，獨對壺觴又不能。","已過重陽三十日，至今猶自待王弘。"]', '["金华千点晓霜凝，独对壺觴又不能。","已過重陽三十日，至今猶自待王弘。"]', '诗', 'shi', '', NULL, '軍事院霜菊盛開因書一絕寄上諫議 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b86d4c-932e-49d1-aca4-bb5fed4074a1', '悼鶴', '悼鹤', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["莫怪朝來淚滿衣，墜毛猶傍水花飛。","遼東舊事今千古，却向人間葬令威。"]', '["莫怪朝来泪满衣，墜毛猶傍水花飞。","遼东旧事今千古，却向人间葬令威。"]', '诗', 'shi', '', NULL, '悼鶴 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0e51e1-c2be-41b4-aa64-cf4bd190e8ab', '醉中先起李縠戲贈走筆奉詶', '醉中先起李縠戲贈走笔奉詶', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["麝煙苒苒生銀兔，蠟淚漣漣滴繡閨。","舞袖莫欺先醉去，醒來還解驗金泥。"]', '["麝煙苒苒生銀兔，蠟泪漣漣滴繡閨。","舞袖莫欺先醉去，醒来還解驗金泥。"]', '诗', 'shi', '', NULL, '醉中先起李縠戲贈走筆奉詶 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('050d0475-3bdb-462f-bba7-6c8b7fbbbf1b', '奉和魯望招潤卿博士辭以道侶將至之作', '奉和魯望招潤卿博士辞以道侶將至之作', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["癭木樽前地胏圖，爲君偏輟俗功夫。","靈真散盡光來此，莫戀安妃在後無。"]', '["癭木樽前地胏圖，爲君偏輟俗功夫。","靈真散尽光来此，莫戀安妃在後無。"]', '诗', 'shi', '', NULL, '奉和魯望招潤卿博士辭以道侶將至之作 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e06205-1ea4-47ed-b00d-45cb6f1654de', '奉和再招', '奉和再招', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["飆御已應歸杳眇，博山猶自對氛氳。","不知入夜能來否，紅蠟先教刻五分。"]', '["飆御已應归杳眇，博山猶自对氛氳。","不知入夜能来否，紅蠟先教刻五分。"]', '诗', 'shi', '', NULL, '奉和再招 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('014d8d62-78db-454c-80cb-ab0289c4739c', '酒病偶作', '酒病偶作', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鬱林步障晝遮明，一炷濃香養病酲。","何事晚來還欲飲，隔牆聞賣蛤蜊聲。"]', '["鬱林步障晝遮明，一炷濃香養病酲。","何事晚来還欲饮，隔牆闻賣蛤蜊声。"]', '诗', 'shi', '', NULL, '酒病偶作 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a99793-6762-452e-8a28-a16010ccc08b', '潤卿魯望寒夜見訪各惜其志遂成一絕', '潤卿魯望寒夜见訪各惜其志遂成一絕', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["世外爲交不是親，醉吟俱岸白綸巾。","清風月白更三點，未放華陽鶴上人。"]', '["世外爲交不是親，醉吟俱岸白綸巾。","清风月白更三点，未放华陽鹤上人。"]', '诗', 'shi', '', NULL, '潤卿魯望寒夜見訪各惜其志遂成一絕 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ff95b7-7c2d-4060-8d7d-784e8ec18af8', '奉和魯望玩金鸂鶒戲贈', '奉和魯望玩金鸂鶒戲贈', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["鏤羽彫毛迥出羣，溫黁飄出麝臍熏。","夜來曾吐紅茵畔，猶似溪邊睡不聞。"]', '["鏤羽彫毛迥出羣，溫黁飄出麝臍熏。","夜来曾吐紅茵畔，猶似溪邊睡不闻。"]', '诗', 'shi', '', NULL, '奉和魯望玩金鸂鶒戲贈 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f67de6-d3d8-4029-a846-435dd3175d41', '友人許惠酒以詩徵之', '友人許惠酒以诗徵之', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["野客蕭然訪我家，霜威白菊兩三花。","子山病起無餘事，只望蒲臺酒一車。"]', '["野客蕭然訪我家，霜威白菊兩三花。","子山病起無餘事，只望蒲台酒一车。"]', '诗', 'shi', '', NULL, '友人許惠酒以詩徵之 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5126a8b4-f3a5-4a0f-b422-7167bc73ae7e', '寒夜文讌潤卿有期不至', '寒夜文讌潤卿有期不至', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["草堂虛灑待高真，不意清齋避世塵。","料得焚香無別事，存心應降月夫人。"]', '["草堂虛灑待高真，不意清斋避世塵。","料得焚香無別事，存心應降月夫人。"]', '诗', 'shi', '', NULL, '寒夜文讌潤卿有期不至 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71fc38f0-e40f-48ac-a0f0-68e0f275a90e', '汴河懷古二首 一', '汴河懷古二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["萬艘龍舸綠絲間，載到揚州盡不還。","應是天教開汴水，一千餘里地無山。"]', '["万艘龙舸綠絲间，載到揚州尽不還。","應是天教开汴水，一千餘里地無山。"]', '诗', 'shi', '', NULL, '汴河懷古二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f88db8-3548-4e2e-87f7-aa0aac87af2c', '汴河懷古二首 二', '汴河懷古二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["盡道隋亡爲此河，至今千里賴通波。","若無水殿龍舟事，共禹論功不較多。"]', '["尽道隋亡爲此河，至今千里賴通波。","若無水殿龙舟事，共禹論功不較多。"]', '诗', 'shi', '', NULL, '汴河懷古二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1faf9880-47a4-4130-930d-cf2786f2ae9c', '寄題天台國清寺齊梁體', '寄題天台国清寺齊梁體', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["十里松門國清路，飯猨臺上菩提樹。","怪來煙雨落晴天，元是海風吹瀑布。"]', '["十里松门国清路，飯猨台上菩提樹。","怪来煙雨落晴天，元是海风吹瀑布。"]', '诗', 'shi', '', NULL, '寄題天台國清寺齊梁體 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d5bb73-c562-4b1a-9834-4e72ebeb2679', '詠蟹', '詠蟹', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["未遊滄海早知名，有骨還從肉上生。","莫道無心畏雷電，海龍王處也橫行。"]', '["未游滄海早知名，有骨還從肉上生。","莫道無心畏雷電，海龙王处也橫行。"]', '诗', 'shi', '', NULL, '詠蟹 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9082684d-25bf-40f4-a186-c6224c5d42e8', '金錢花', '金錢花', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["陰陽爲炭地爲爐，鑄出金錢不用模。","莫向人間逞顏色，不知還解濟貧無。"]', '["陰陽爲炭地爲爐，鑄出金錢不用模。","莫向人间逞顏色，不知還解濟貧無。"]', '诗', 'shi', '', NULL, '金錢花 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa70e811-8631-4efa-bb6b-3dfb29196e35', '惠山聽松菴', '惠山听松菴', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["千葉蓮花舊有香，半山金剎照方塘。","殿前日暮高風起，松子聲聲打石牀。"]', '["千葉蓮花旧有香，半山金剎照方塘。","殿前日暮高风起，松子声声打石牀。"]', '诗', 'shi', '', NULL, '惠山聽松菴 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a096aa-a4f9-468e-938a-d61271f6835d', '雜體詩 苦雨雜言寄魯望', '杂體诗 苦雨杂言寄魯望', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["吳中十日涔涔雨，歊蒸庳下豪家苦。","可憐臨頓陸先生，獨自翛然守環堵。","兒飢僕病漏空廚，無人肯典破衣裾。","{果/虫虫}蠃時時上几案，鼃黽往往跳琴書。","桃花米斗半百錢，枯荒濕壞炊不然。","兩牀苮席一素几，仰臥高聲吟太玄。","知君志氣如鐵石，甌冶雖神銷不得。","乃知苦雨不復侵，枉費畢星無限力。","鹿門人作州從事，周章似鼠唯知醉。","府金廩粟虛請來，憶著先生便知媿。","媿多饋少真徒然，相見唯知攜酒錢。","豪華滿眼語不信，不如直上天公牋。","天公牋，方修次，且榜鳴篷來一醉。"]', '["吳中十日涔涔雨，歊蒸庳下豪家苦。","可怜臨頓陸先生，独自翛然守环堵。","兒飢僕病漏空廚，無人肯典破衣裾。","{果/虫虫}蠃时时上几案，鼃黽往往跳琴书。","桃花米斗半百錢，枯荒濕壞炊不然。","兩牀苮席一素几，仰臥高声吟太玄。","知君志氣如鐵石，甌冶雖神銷不得。","乃知苦雨不复侵，枉費畢星無限力。","鹿门人作州從事，周章似鼠唯知醉。","府金廩粟虛請来，憶著先生便知媿。","媿多饋少真徒然，相见唯知携酒錢。","豪华满眼語不信，不如直上天公牋。","天公牋，方修次，且榜鳴篷来一醉。"]', '诗', 'shi', '', NULL, '雜體詩 苦雨雜言寄魯望 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc8b3bf-c8af-4198-b66b-ddb8becf1558', '雜體詩 奉和魯望齊梁怨別次韻', '杂體诗 奉和魯望齊梁怨別次韻', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["芙蓉泣恨紅鉛落，一朵別時煙似幕。","鴛鴦剛解惱離心，夜夜飛來櫂邊泊。"]', '["芙蓉泣恨紅鉛落，一朵別时煙似幕。","鴛鴦剛解惱離心，夜夜飞来櫂邊泊。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望齊梁怨別次韻 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cfbb9e3-7474-4e17-9375-a6d8541c07a7', '雜體詩 奉和魯望曉起迴文', '杂體诗 奉和魯望晓起迴文', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["孤煙曉起初原曲，碎樹微分半浪中。","湖後釣筒移夜雨，竹傍眠几側晨風。","圖梅帶潤輕霑墨，畫蘚經蒸半失紅。","無事有杯持永日，共君惟好隱牆東。"]', '["孤煙晓起初原曲，碎樹微分半浪中。","湖後釣筒移夜雨，竹傍眠几側晨风。","圖梅带潤轻霑墨，畫蘚經蒸半失紅。","無事有杯持永日，共君惟好隐牆东。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望曉起迴文 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86bab490-295d-4808-845e-16d1e0d84293', '雜體詩 奉詶魯望夏日四聲四首 平聲', '杂體诗 奉詶魯望夏日四声四首 平声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["塘平芙蓉低，庭閑梧桐高。","清煙埋陽烏，藍空含秋毫。","冠傾慵移簪，杯乾將餔糟。","翛然非隨時，夫君真吾曹。"]', '["塘平芙蓉低，庭闲梧桐高。","清煙埋陽烏，藍空含秋毫。","冠傾慵移簪，杯乾將餔糟。","翛然非隨时，夫君真吾曹。"]', '诗', 'shi', '', NULL, '雜體詩 奉詶魯望夏日四聲四首 平聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ea2a09-bbec-45da-a65d-cf5f1dfb8f79', '雜體詩 奉詶魯望夏日四聲四首 平上聲', '杂體诗 奉詶魯望夏日四声四首 平上声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["溝渠通疎荷，浦嶼隱淺篠。","舟閑攢輕蘋，槳動起靜鳥。","陰稀餘桑閑，縷盡晚繭小。","吾徒當斯時，此道可以了。"]', '["溝渠通疎荷，浦嶼隐淺篠。","舟闲攢轻蘋，槳动起静鸟。","陰稀餘桑闲，縷尽晚繭小。","吾徒當斯时，此道可以了。"]', '诗', 'shi', '', NULL, '雜體詩 奉詶魯望夏日四聲四首 平上聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f385ef5a-727d-4d27-bcaf-457ae8df8c34', '雜體詩 奉詶魯望夏日四聲四首 平去聲', '杂體诗 奉詶魯望夏日四声四首 平去声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["怡神時高吟，快意乍四顧。","村深啼愁鵑，浪霽醒睡鷺。","書疲行終朝，罩困臥至暮。","吁嗟當今交，暫貴便異路。"]', '["怡神时高吟，快意乍四顧。","村深啼愁鵑，浪霽醒睡鷺。","书疲行終朝，罩困臥至暮。","吁嗟當今交，暫貴便異路。"]', '诗', 'shi', '', NULL, '雜體詩 奉詶魯望夏日四聲四首 平去聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be00cab6-aced-4f37-b75b-c6dd3785e8d4', '雜體詩 奉詶魯望夏日四聲四首 平入聲', '杂體诗 奉詶魯望夏日四声四首 平入声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["先生何違時，一室習寂歷。","松聲將飄堂，岳色欲壓席。","彈琴奔玄雲，斸藥折白石。","如教題君詩，若得札玉冊。"]', '["先生何違时，一室習寂歷。","松声將飄堂，岳色欲壓席。","彈琴奔玄云，斸藥折白石。","如教題君诗，若得札玉冊。"]', '诗', 'shi', '', NULL, '雜體詩 奉詶魯望夏日四聲四首 平入聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4981a848-c045-4c18-9ff9-10b04e94ce4c', '雜體詩 苦雨中又作四聲詩寄魯望 平聲', '杂體诗 苦雨中又作四声诗寄魯望 平声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["涔涔將經旬，昏昏空迷天。","鸕鷀成羣嬉，芙蓉相偎眠。","魚通蓑衣城，帆過菱花田。","秋收吾無望，悲之真徒然。"]', '["涔涔將經旬，昏昏空迷天。","鸕鷀成羣嬉，芙蓉相偎眠。","鱼通蓑衣城，帆過菱花田。","秋收吾無望，悲之真徒然。"]', '诗', 'shi', '', NULL, '雜體詩 苦雨中又作四聲詩寄魯望 平聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe40c635-f913-401a-962c-8a929ef40b0d', '雜體詩 苦雨中又作四聲詩寄魯望 平上聲', '杂體诗 苦雨中又作四声诗寄魯望 平上声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["河平州橋危，壘晚水鳥上。","衝崖搜松根，點沼寫芡響。","舟輕通縈紆，棧墮阻指掌。","攜橈將尋君，渚滿坐可往。"]', '["河平州橋危，壘晚水鸟上。","衝崖搜松根，点沼寫芡响。","舟轻通縈紆，棧墮阻指掌。","携橈將尋君，渚满坐可往。"]', '诗', 'shi', '', NULL, '雜體詩 苦雨中又作四聲詩寄魯望 平上聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fa5a1b-4299-4bfe-bc7a-2617026f987c', '雜體詩 苦雨中又作四聲詩寄魯望 平去聲', '杂體诗 苦雨中又作四声诗寄魯望 平去声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["狂霖昏悲吟，瘦桂對病臥。","檐虛能彯斜，舍蠹易漏破。","宵愁將琴攻，晝悶用睡過。","堆書仍傾觴，富貴未換箇。"]', '["狂霖昏悲吟，瘦桂对病臥。","檐虛能彯斜，舍蠹易漏破。","宵愁將琴攻，晝悶用睡過。","堆书仍傾觴，富貴未換箇。"]', '诗', 'shi', '', NULL, '雜體詩 苦雨中又作四聲詩寄魯望 平去聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10743f98-8154-46f8-bdf4-61ed8b3b6f5b', '雜體詩 苦雨中又作四聲詩寄魯望 平入聲', '杂體诗 苦雨中又作四声诗寄魯望 平入声', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["羇棲愁霖中，缺宅屋木惡。","荷傾還驚魚，竹滴復觸鶴。","閑僧千聲琴，宿客一笈藥。","悠然思夫君，忽憶蠟屐著。"]', '["羇棲愁霖中，缺宅屋木惡。","荷傾還驚鱼，竹滴复觸鹤。","闲僧千声琴，宿客一笈藥。","悠然思夫君，忽憶蠟屐著。"]', '诗', 'shi', '', NULL, '雜體詩 苦雨中又作四聲詩寄魯望 平入聲 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152f2727-d2dd-409c-b7fe-251f455ba49c', '雜體詩 奉和魯望疊韻雙聲二首 疊韻山中吟', '杂體诗 奉和魯望叠韻雙声二首 叠韻山中吟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["穿煙泉潺湲，觸竹犢觳觫。","荒篁香牆匡，熟鹿伏屋曲。"]', '["穿煙泉潺湲，觸竹犢觳觫。","荒篁香牆匡，熟鹿伏屋曲。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望疊韻雙聲二首 疊韻山中吟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efa2022-5391-4cf6-b6ad-1ec76d2798f9', '雜體詩 奉和魯望疊韻雙聲二首 雙聲溪上思', '杂體诗 奉和魯望叠韻雙声二首 雙声溪上思', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["疎杉低通灘，冷鷺立亂浪。","草彩欲夷猶，雲容空澹蕩。"]', '["疎杉低通灘，冷鷺立亂浪。","草彩欲夷猶，云容空澹蕩。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望疊韻雙聲二首 雙聲溪上思 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299d66dc-57f9-4b65-82be-1570afa10e1b', '雜體詩 奉和魯望疊韻吳宮詞二首 一', '杂體诗 奉和魯望叠韻吳宮词二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["侵深尋嶔岑，勢厲衛睥睨。","荒王將鄉亡，細麗蔽袂逝。"]', '["侵深尋嶔岑，勢厲衛睥睨。","荒王將乡亡，細丽蔽袂逝。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望疊韻吳宮詞二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1d8d7b-8a82-4fc7-89f2-75e55c43476c', '雜體詩 奉和魯望疊韻吳宮詞二首 二', '杂體诗 奉和魯望叠韻吳宮词二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["枍指替製曳，康莊傷荒涼。","主虜部伍苦，嬙亡房廊香。"]', '["枍指替製曳，康莊傷荒涼。","主虜部伍苦，嬙亡房廊香。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望疊韻吳宮詞二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4654faef-ddd4-4474-8ccd-4ed90b867939', '雜體詩 奉和魯望閑居雜題五首 晚秋吟', '杂體诗 奉和魯望闲居杂題五首 晚秋吟', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["東臯煙雨歸耕日，免去玄冠手刈禾。","火滿酒爐詩在口，今人無計奈儂何。"]', '["东臯煙雨归耕日，免去玄冠手刈禾。","火满酒爐诗在口，今人無計奈儂何。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望閑居雜題五首 晚秋吟 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44dc113-2534-4e52-ab40-64d202955d8a', '雜體詩 奉和魯望閑居雜題五首 好詩景', '杂體诗 奉和魯望闲居杂題五首 好诗景', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["青盤香露傾荷女，子墨風流更不言。","寺寺雲蘿堪度日，京塵到死撲侯門。"]', '["青盤香露傾荷女，子墨风流更不言。","寺寺云蘿堪度日，京塵到死撲侯门。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望閑居雜題五首 好詩景 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e480d9d3-d8d2-408b-bb56-8d45e70d985b', '雜體詩 奉和魯望閑居雜題五首 醒聞檜', '杂體诗 奉和魯望闲居杂題五首 醒闻檜', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["解洗餘酲晨半酉，星星仙吹起雲門。","耳根無厭聽佳木，會盡山中寂靜源。"]', '["解洗餘酲晨半酉，星星仙吹起云门。","耳根無厭听佳木，會尽山中寂静源。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望閑居雜題五首 醒聞檜 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55e9f3d9-c007-4329-b80f-9f0299a1f256', '雜體詩 奉和魯望閑居雜題五首 寺鐘暝', '杂體诗 奉和魯望闲居杂題五首 寺鐘暝', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["百緣斗藪無塵土，寸地章煌欲布金。","重擊蒲牢唅山日，冥冥煙樹覩棲禽。"]', '["百緣斗藪無塵土，寸地章煌欲布金。","重擊蒲牢唅山日，冥冥煙樹覩棲禽。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望閑居雜題五首 寺鐘暝 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aefb735-f7b0-4f11-bb03-58770437e4e6', '雜體詩 奉和魯望閑居雜題五首 砌思步', '杂體诗 奉和魯望闲居杂題五首 砌思步', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["襹襹古薜繃危石，切切陰螿應晚田。","心事萬端何處止，少夷峰下舊雲泉。"]', '["襹襹古薜繃危石，切切陰螿應晚田。","心事万端何处止，少夷峰下旧云泉。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望閑居雜題五首 砌思步 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4f96b7-a091-4bef-81ee-7c7730754164', '雜體詩 奉和魯望藥名離合夏月即事三首 一', '杂體诗 奉和魯望藥名離合夏月即事三首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["季春人病拋芳杜，仲夏溪波繞壞垣。","衣典濁醪身倚桂，心中無事到雲昏。"]', '["季春人病拋芳杜，仲夏溪波繞壞垣。","衣典濁醪身倚桂，心中無事到云昏。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望藥名離合夏月即事三首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3259a666-932d-42e2-87ad-cbcb4609a11d', '雜體詩 奉和魯望藥名離合夏月即事三首 二', '杂體诗 奉和魯望藥名離合夏月即事三首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["數曲急溪衝細竹，葉舟來往盡能通。","草香石冷無辭遠，志在天台一遇中。"]', '["數曲急溪衝細竹，葉舟来往尽能通。","草香石冷無辞远，志在天台一遇中。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望藥名離合夏月即事三首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c085aea-d122-4321-bda6-08e0bab33d65', '雜體詩 奉和魯望藥名離合夏月即事三首 三', '杂體诗 奉和魯望藥名離合夏月即事三首 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["桂葉似茸含露紫，葛花如綬蘸溪黃。","連雲更入幽深地，骨錄閑攜相獵郎。"]', '["桂葉似茸含露紫，葛花如綬蘸溪黄。","連云更入幽深地，骨錄闲携相獵郎。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望藥名離合夏月即事三首 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c063d7f-235d-4918-87fc-cad59895410a', '雜體詩 懷錫山藥名離合二首 一', '杂體诗 懷錫山藥名離合二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["暗竇養泉容決決，明園護桂放亭亭。","歷山居處當天半，夏裏松風盡足聽。"]', '["暗竇養泉容決決，明园護桂放亭亭。","歷山居处當天半，夏裏松风尽足听。"]', '诗', 'shi', '', NULL, '雜體詩 懷錫山藥名離合二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b864570-6f48-4337-8481-24fd5994242a', '雜體詩 懷錫山藥名離合二首 二', '杂體诗 懷錫山藥名離合二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["曉景半和山氣白，薇香清淨雜纖雲。","實頭自是眠平石，腦側空林看虎羣。"]', '["晓景半和山氣白，薇香清淨杂纖云。","實头自是眠平石，腦側空林看虎羣。"]', '诗', 'shi', '', NULL, '雜體詩 懷錫山藥名離合二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f86bd9db-ecd4-4e55-b6d2-ce8fedd99be7', '雜體詩 懷鹿門縣名離合二首 一', '杂體诗 懷鹿门縣名離合二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["山瘦更培秋後桂，溪澄閑數晚來魚。","臺前過雁盈千百，泉石無情不寄書。"]', '["山瘦更培秋後桂，溪澄闲數晚来鱼。","台前過雁盈千百，泉石無情不寄书。"]', '诗', 'shi', '', NULL, '雜體詩 懷鹿門縣名離合二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23951e9f-ce10-4b4d-bd0c-c6160956ee70', '雜體詩 懷鹿門縣名離合二首 二', '杂體诗 懷鹿门縣名離合二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["十里松蘿陰亂石，門前幽事雨來新。","野霜濃處憐殘菊，潭上花開不見人。"]', '["十里松蘿陰亂石，门前幽事雨来新。","野霜濃处怜殘菊，潭上花开不见人。"]', '诗', 'shi', '', NULL, '雜體詩 懷鹿門縣名離合二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0017457-d6b4-47bd-8da0-2ac01986fc44', '雜體詩 奉和魯望寒日古人名一絕', '杂體诗 奉和魯望寒日古人名一絕', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["北顧歡遊悲沈宋，南徐陵寢歎齊梁。","水邊韶景無窮柳，寒被江淹一半黃。"]', '["北顧歡游悲沈宋，南徐陵寢歎齊梁。","水邊韶景無窮柳，寒被江淹一半黄。"]', '诗', 'shi', '', NULL, '雜體詩 奉和魯望寒日古人名一絕 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ce1e4a6-e96e-4efe-ac5a-494a68c3f39a', '雜體詩 胥口即事六言二首 一', '杂體诗 胥口即事六言二首 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["波光杳杳不極，霽景澹澹初斜。","黑蛺蝶粘蓮蘂，紅蜻蜓褭蔆花。","鴛鴦一處兩處，舴艋三家五家。","會把酒船偎荻，共君作箇生涯。"]', '["波光杳杳不極，霽景澹澹初斜。","黑蛺蝶粘蓮蘂，紅蜻蜓褭蔆花。","鴛鴦一处兩处，舴艋三家五家。","會把酒船偎荻，共君作箇生涯。"]', '诗', 'shi', '', NULL, '雜體詩 胥口即事六言二首 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f428c03c-3783-4e70-b0af-14a100b27088', '雜體詩 胥口即事六言二首 二', '杂體诗 胥口即事六言二首 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["拂釣清風細麗，飄蓑暑雨霏微。","湖雲欲散未散，嶼鳥將飛不飛。","換酒帩頭把看，載蓮艇子撐歸。","斯人到死還樂，誰道剛須用機。"]', '["拂釣清风細丽，飄蓑暑雨霏微。","湖云欲散未散，嶼鸟將飞不飞。","換酒帩头把看，載蓮艇子撐归。","斯人到死還乐，誰道剛須用機。"]', '诗', 'shi', '', NULL, '雜體詩 胥口即事六言二首 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60268b90-4dce-4805-9cf8-17697d930f68', '雜體詩 夜會問荅十 一', '杂體诗 夜會问荅十 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["寒夜清，簾外迢迢星斗明。","況有蕭閑洞中客，吟爲紫鳳呼凰聲。"]', '["寒夜清，簾外迢迢星斗明。","況有蕭闲洞中客，吟爲紫鳳呼凰声。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e132cb0-e69b-45f2-aa39-dfde523eea6e', '雜體詩 夜會問荅十 二', '杂體诗 夜會问荅十 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["癭木杯，杉贅楠瘤刳得來。","莫怪家人畔邊笑，渠心祗愛黃金罍。"]', '["癭木杯，杉贅楠瘤刳得来。","莫怪家人畔邊笑，渠心祗愛黄金罍。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b0af06-a2a7-4a4a-928c-cd41f64428ca', '雜體詩 夜會問荅十 三', '杂體诗 夜會问荅十 三', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["落霞琴，寥寥山水揚清音。","玉皇仙馭碧雲遠，空使松風終日吟。"]', '["落霞琴，寥寥山水揚清音。","玉皇仙馭碧云远，空使松风終日吟。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 三 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ebac4a-097d-4bfa-875c-bb781c449eaf', '雜體詩 夜會問荅十 四', '杂體诗 夜會问荅十 四', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["蓮花燭，亭亭嫩蘂生紅玉。","不知含淚怨何人，欲問無由得心曲。"]', '["蓮花燭，亭亭嫩蘂生紅玉。","不知含泪怨何人，欲问無由得心曲。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 四 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a41b9637-bb30-4f75-aa42-fc16af3e7f29', '雜體詩 夜會問荅十 五', '杂體诗 夜會问荅十 五', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["金火障，紅獸飛來射羅幌。","夜來斜展掩深爐，半睡芙蓉香蕩漾。"]', '["金火障，紅獸飞来射羅幌。","夜来斜展掩深爐，半睡芙蓉香蕩漾。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 五 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c3199b-5c16-4cd4-a077-9a4c246c0991', '雜體詩 夜會問荅十 六', '杂體诗 夜會问荅十 六', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["憶山月，前溪後溪清復絕。","看看又及桂花時，空寄子規啼處血。"]', '["憶山月，前溪後溪清复絕。","看看又及桂花时，空寄子規啼处血。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 六 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300921e1-468b-4870-b9ba-49427be16b9d', '雜體詩 夜會問荅十 七', '杂體诗 夜會问荅十 七', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["錦鯨薦，碧香紅膩承君宴。","幾度閑眠却覺來，彩鱗飛出雲濤面。"]', '["錦鯨薦，碧香紅膩承君宴。","幾度闲眠却覺来，彩鱗飞出云濤面。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 七 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f54e277-db72-410c-83e6-5c0013486c00', '雜體詩 夜會問荅十 八', '杂體诗 夜會问荅十 八', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["懷溪雲，漠漠閑籠鷗鷺羣。","有時日暮碧將合，還被魚舟來觸分。"]', '["懷溪云，漠漠闲籠鷗鷺羣。","有时日暮碧將合，還被鱼舟来觸分。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 八 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('622977b9-dd17-4469-952c-91ec4ffa5fdc', '雜體詩 夜會問荅十 九', '杂體诗 夜會问荅十 九', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["霜中笛，落梅一曲瑤華滴。","不知青女是何人，三奏未終頭已白。"]', '["霜中笛，落梅一曲瑤华滴。","不知青女是何人，三奏未終头已白。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 九 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6bd82c-fa19-48f5-9ed3-57332036ca98', '雜體詩 夜會問荅十 十', '杂體诗 夜會问荅十 十', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["月下橋，風外拂殘衰柳條。","倚欄杆處獨自立，青翰何人吹玉簫。"]', '["月下橋，风外拂殘衰柳條。","倚欄杆处独自立，青翰何人吹玉簫。"]', '诗', 'shi', '', NULL, '雜體詩 夜會問荅十 十 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d496f0-b9f3-4c3e-97e7-1ed24bcfac41', '讀襄陽耆舊傳因作詩五百言寄皮襲美', '读襄陽耆旧傳因作诗五百言寄皮襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["漢臯古來雄，山水天下秀。","高當軫翼分，化作英髦囿。","暴秦之前人，灰滅不可究。","自從宋生賢，特立冠耆舊。","離騷既日月，九辯即列宿。","卓哉悲秋辭，合在風雅右。","龐公樂幽隱，辟聘無所就。","祗愛鹿門泉，泠泠倚巖漱。","孔明臥龍者，潛伏躬耕耨。","忽遭玄德雲，遂起鱗角鬬。","三胡節皆峻，二習名亦茂。","其餘文武家，相望如斥堠。","緬思齊梁降，寂寞寡清胄。","凝融爲漪瀾，復結作瑩琇。","不知粹和氣，有得方大受。","將生皮夫子，上帝可其奏。","幷包數公才，用以殿厥後。","嘗聞兒童歲，嬉戲陳俎豆。","積漸開詞源，一派分萬溜。","先崇丘旦室，大懼隳結構。","次補荀孟垣，所貴亡罅漏。","仰瞻三皇道，蟣虱在宇宙。","却視五霸圖，股掌弄孩幼。","或能醢髖髀，或與翼雛鷇。","或喜掉直舌，或樂斬邪脰。","或耨鋤翳薈，或整理錯謬。","或如百千騎，合沓原野狩。","又如曉江平，風死波不皺。","幽埋力須掘，遺落貲必購。","乃於文學中，十倍猗頓富。","囊乏向咸鎬，馬重遲步驟。","專場射策時，縛虎當羿彀。","歸來把通籍，且作高堂壽。","未足逞戈矛，誰云被文繡。","從知偶東下，帆影拂吳岫。","物象悉摧藏，精靈畏雕鏤。","伊余抱沈疾，顦顇守圭竇。","方推洪範疇，更念大玄首。","陳詩採風俗，學古窮篆籀。","朝朝貰薪米，往往逢責詬。","既被鄰里輕，亦爲妻子陋。","持冠適甌越，敢怨不得售。","窘若曬沙魚，悲如哭霜狖。","唯君枉車轍，以逐海上臭。","披襟兩相對，半夜忽白晝。","執熱濯清風，忘憂飲醇酎。","驅爲文翰侶，駑皁參驥廐。","有時諧宮商，自喜真邂逅。","道孤情易苦，語直詩還瘦。","藻匠如見酬，終身致懷袖。"]', '["漢臯古来雄，山水天下秀。","高當軫翼分，化作英髦囿。","暴秦之前人，灰滅不可究。","自從宋生賢，特立冠耆旧。","離騷既日月，九辯即列宿。","卓哉悲秋辞，合在风雅右。","龐公乐幽隐，辟聘無所就。","祗愛鹿门泉，泠泠倚巖漱。","孔明臥龙者，潛伏躬耕耨。","忽遭玄德云，遂起鱗角鬬。","三胡節皆峻，二習名亦茂。","其餘文武家，相望如斥堠。","緬思齊梁降，寂寞寡清胄。","凝融爲漪瀾，复結作瑩琇。","不知粹和氣，有得方大受。","將生皮夫子，上帝可其奏。","幷包數公才，用以殿厥後。","嘗闻兒童歲，嬉戲陳俎豆。","積漸开词源，一派分万溜。","先崇丘旦室，大懼隳結構。","次補荀孟垣，所貴亡罅漏。","仰瞻三皇道，蟣虱在宇宙。","却視五霸圖，股掌弄孩幼。","或能醢髖髀，或與翼雛鷇。","或喜掉直舌，或乐斬邪脰。","或耨鋤翳薈，或整理錯謬。","或如百千騎，合沓原野狩。","又如晓江平，风死波不皺。","幽埋力須掘，遺落貲必購。","乃於文学中，十倍猗頓富。","囊乏向咸鎬，马重遲步驟。","專場射策时，縛虎當羿彀。","归来把通籍，且作高堂壽。","未足逞戈矛，誰云被文繡。","從知偶东下，帆影拂吳岫。","物象悉摧藏，精靈畏雕鏤。","伊余抱沈疾，顦顇守圭竇。","方推洪範疇，更念大玄首。","陳诗採风俗，学古窮篆籀。","朝朝貰薪米，往往逢責詬。","既被鄰里轻，亦爲妻子陋。","持冠適甌越，敢怨不得售。","窘若曬沙鱼，悲如哭霜狖。","唯君枉车轍，以逐海上臭。","披襟兩相对，半夜忽白晝。","執熱濯清风，忘憂饮醇酎。","驱爲文翰侶，駑皁參驥廐。","有时諧宮商，自喜真邂逅。","道孤情易苦，語直诗還瘦。","藻匠如见酬，終身致懷袖。"]', '诗', 'shi', '', NULL, '讀襄陽耆舊傳因作詩五百言寄皮襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6272d0c-1f88-4689-9e20-cd58c806ba09', '襲美先輩以龜蒙所獻五百言既蒙見和復示榮唱至於千字提獎之重蔑有稱實再抒鄙懷用伸酬謝', '襲美先輩以龟蒙所獻五百言既蒙见和复示榮唱至於千字提獎之重蔑有稱實再抒鄙懷用伸酬謝', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["洪範分九疇，轉成天下規。","河圖孕八卦，煥作玄中奇。","先開否臧源，次築經緯基。","粵若魯聖出，正當周德衰。","越疆必載質，歷國將扶危。","諸侯恣崛強，王室方陵遲。","歌鳳時不偶，獲麟心益悲。","始嗟吾道窮，竟使空言垂。","首贊五十易，又刪三百詩。","遂令篇籍光，可竝日月姿。","向非筆削功，未必無瑕疵。","迨至夫子沒，微言散如枝。","所宗既不同，所得亦異宜。","名法在深刻，虛玄至希夷。","自從戰伐來，一派縱橫馳。","寒谷生豔木，沸潭結流澌。","驚奔失壯士，好惡隨纖兒。","嬴氏幷六合，勢尊丞相斯。","加於挾書律，盡取坑焚之。","南勒會稽頌，北恢胡亥阺。","猶懷徧巡狩，不暇親維持。","及漢文景後，鴻生方鎃摫。","簸揚堯舜風，反作三代吹。","飄颻四百載，左右爲藩籬。","鄴下曹父子，獵賢甚熊羆。","發論若霞駁，裁詩如錦摛。","徐王應劉輩，頭角咸相衰。","或有妙絕賞，或爲獨步推。","或許潤色美，或嫌詆訶癡。","倏以中利病，且非混醇醨。","雅當乎魏文，麗矣哉陳思。","不肯少選妄，恐貽後世嗤。","吾祖仗才力，革車蒙虎皮。","手持一白旄，直向文場麾。","輕若脫鉗釱，豁如抽扊扅。","精鋼不足利，騕褭何勞追。","大可罩山岳，微堪析毫釐。","十體免負贅，百家咸起痿。","爭入鬼神奧，不容天地私。","一篇邁華藻，萬古無孑遺。","刻鵠尚未已，雕龍奮而爲。","劉生吐英辯，上下窮高卑。","下臻宋與齊，上指軒從羲。","豈但標八索，殆將包兩儀。","人謠洞野老，騷怨明湘纍。","立本以致詰，驅宏來抵隵。","清如朔雪嚴，緩若春煙羸。","或欲開戶牖，或將飾纓緌。","雖非倚天劒，亦是囊中錐。","皆由內史意，致得東莞詞。","梁元盡索虜，後主終亡隋。","哀音但浮脆，豈望分雄雌。","吾唐揖讓初，陛列森咎夔。","作頌媲吉甫，直言過祖伊。","明皇踐中日，墨客肩參差。","岳淨秀擢削，海寒光陸離。","皆能取穴鳳，盡擬乘雲螭。","邇來二十祀，俊造相追隨。","余生落其下，亦值文明時。","少小不好弄，逡巡奉弓箕。","雖然苦貧賤，未省親嚅㖇。","秋倚抱風桂，曉烹承露葵。","窮年只敗袍，積日無晨炊。","遠訪賣藥客，閑尋捕魚師。","歸來蠹編上，得以含情窺。","抗韻吟比雅，覃思念棿攡。","因知昭明前，剖石呈清琪。","又嗟昭明後，敗葉埋芳蕤。","縱有月旦評，未能天下知。","徒爲強貔豹，不免參狐貍。","誰蹇行地足，誰抽刺天鬐。","誰作河畔草，誰爲洞中芝。","誰若靈囿鹿，誰猶清廟犧。","誰輕如鴻毛，誰密如凝脂。","誰比蜀嚴靜，誰方巴賨貲。","誰能釣抃鼇，誰能灼神龜。","誰背如水火，誰同若塤篪。","誰可作梁棟，誰敢驅谷蠡。","用此常不快，無人動交鈹。","空消病裏骨，枉白愁中髭。","鹿門先生才，大小無不怡。","就彼六籍內，說詩直解頤。","顧我迷未遠，開懷潰其疑。","初開鑿本源，漸乃疏旁支。","邃古派泛濫，皇朝光赫曦。","揣摩是非際，一一如襟期。","李杜氣不易，孟陳節難移。","信知君子言，可竝神明蓍。","枯腐尚求律，膏肓猶謁醫。","況將太牢味，見啗逋懸飢。","今來置家地，正枕吳江湄。","餌薄鉤不曲，跫然守空坻。","嘿坐無影響，唯君欵茅茨。","抽書亂籤帙，酌茗煩甌㰕。","或伴補缺砌，或偕詣荒祠。","孤筇倚煙蔓，細木橫風漪。","觸雨妨屝屨，臨流泥江蘺。","既狎野人調，甘爲豪士訾。","不敢負建鼓，唯憂掉降旗。","希君念餘勇，挽袖登文陴。"]', '["洪範分九疇，轉成天下規。","河圖孕八卦，煥作玄中奇。","先开否臧源，次築經緯基。","粵若魯聖出，正當周德衰。","越疆必載質，歷国將扶危。","諸侯恣崛強，王室方陵遲。","歌鳳时不偶，獲麟心益悲。","始嗟吾道窮，竟使空言垂。","首贊五十易，又刪三百诗。","遂令篇籍光，可竝日月姿。","向非笔削功，未必無瑕疵。","迨至夫子沒，微言散如枝。","所宗既不同，所得亦異宜。","名法在深刻，虛玄至希夷。","自從戰伐来，一派縱橫驰。","寒谷生豔木，沸潭結流澌。","驚奔失壯士，好惡隨纖兒。","嬴氏幷六合，勢尊丞相斯。","加於挾书律，尽取坑焚之。","南勒會稽頌，北恢胡亥阺。","猶懷徧巡狩，不暇親維持。","及漢文景後，鴻生方鎃摫。","簸揚堯舜风，反作三代吹。","飄颻四百載，左右爲藩籬。","鄴下曹父子，獵賢甚熊羆。","發論若霞駁，裁诗如錦摛。","徐王應劉輩，头角咸相衰。","或有妙絕賞，或爲独步推。","或許潤色美，或嫌詆訶癡。","倏以中利病，且非混醇醨。","雅當乎魏文，丽矣哉陳思。","不肯少選妄，恐貽後世嗤。","吾祖仗才力，革车蒙虎皮。","手持一白旄，直向文場麾。","轻若脫鉗釱，豁如抽扊扅。","精鋼不足利，騕褭何勞追。","大可罩山岳，微堪析毫釐。","十體免負贅，百家咸起痿。","爭入鬼神奧，不容天地私。","一篇邁华藻，万古無孑遺。","刻鵠尚未已，雕龙奮而爲。","劉生吐英辯，上下窮高卑。","下臻宋與齊，上指軒從羲。","豈但標八索，殆將包兩儀。","人謠洞野老，騷怨明湘纍。","立本以致詰，驱宏来抵隵。","清如朔雪嚴，緩若春煙羸。","或欲开戶牖，或將飾纓緌。","雖非倚天劒，亦是囊中錐。","皆由內史意，致得东莞词。","梁元尽索虜，後主終亡隋。","哀音但浮脆，豈望分雄雌。","吾唐揖讓初，陛列森咎夔。","作頌媲吉甫，直言過祖伊。","明皇踐中日，墨客肩參差。","岳淨秀擢削，海寒光陸離。","皆能取穴鳳，尽擬乘云螭。","邇来二十祀，俊造相追隨。","余生落其下，亦值文明时。","少小不好弄，逡巡奉弓箕。","雖然苦貧賤，未省親嚅㖇。","秋倚抱风桂，晓烹承露葵。","窮年只敗袍，積日無晨炊。","远訪賣藥客，闲尋捕鱼師。","归来蠹編上，得以含情窺。","抗韻吟比雅，覃思念棿攡。","因知昭明前，剖石呈清琪。","又嗟昭明後，敗葉埋芳蕤。","縱有月旦評，未能天下知。","徒爲強貔豹，不免參狐貍。","誰蹇行地足，誰抽刺天鬐。","誰作河畔草，誰爲洞中芝。","誰若靈囿鹿，誰猶清廟犧。","誰轻如鴻毛，誰密如凝脂。","誰比蜀嚴静，誰方巴賨貲。","誰能釣抃鼇，誰能灼神龟。","誰背如水火，誰同若塤篪。","誰可作梁棟，誰敢驱谷蠡。","用此常不快，無人动交鈹。","空消病裏骨，枉白愁中髭。","鹿门先生才，大小無不怡。","就彼六籍內，说诗直解頤。","顧我迷未远，开懷潰其疑。","初开鑿本源，漸乃疏旁支。","邃古派泛濫，皇朝光赫曦。","揣摩是非際，一一如襟期。","李杜氣不易，孟陳節难移。","信知君子言，可竝神明蓍。","枯腐尚求律，膏肓猶謁醫。","況將太牢味，见啗逋懸飢。","今来置家地，正枕吳江湄。","餌薄鉤不曲，跫然守空坻。","嘿坐無影响，唯君欵茅茨。","抽书亂籤帙，酌茗煩甌㰕。","或伴補缺砌，或偕詣荒祠。","孤筇倚煙蔓，細木橫风漪。","觸雨妨屝屨，臨流泥江蘺。","既狎野人調，甘爲豪士訾。","不敢負建鼓，唯憂掉降旗。","希君念餘勇，挽袖登文陴。"]', '诗', 'shi', '', NULL, '襲美先輩以龜蒙所獻五百言既蒙見和復示榮唱至於千字提獎之重蔑有稱實再抒鄙懷用伸酬謝 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd16fbf-3223-44d5-8f01-09a6834faa03', '奉酬襲美先輩吳中苦雨一百韻', '奉酬襲美先輩吳中苦雨一百韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["微生參最靈，天與意緒拙。","人皆機巧求，百逕無一達。","家爲唐臣來，奕世唯稷卨。","只垂青白風，凜凜自貽厥。","猶殘賜書在，編簡苦斷絕。","其間忠孝字，萬古光不滅。","孱孫誠瞢昧，有志常搰搰。","敢云嗣良弓，但欲終守節。","諠譁不入耳，讒佞不挂舌。","仰詠堯舜言，俯遵周孔轍。","所貪既仁義，豈暇理生活。","縱有舊田園，拋來亦蕪沒。","因之成否塞，十載真契闊。","凍骭一襜褕，飢腸少糠籺。","甘心付天壤，委分任迴斡。","笠澤臥孤雲，桐江釣明月。","盈筐盛芡芰，滿釜煮鱸鱖。","酒幟風外㩻，茶槍露中擷。","歌謠非大雅，捃摭爲小說。","上可補熏莖，傍堪跐芽蘗。","方當賣罾罩，盡以易紙札。","蹤跡尚吳門，夢魂先魏闕。","尋聞天子詔，赫怒誅叛卒。","宵旰憫烝黎，謨明問征伐。","王師雖繼下，賊壘未即拔。","此時淮海波，半是生人血。","霜戈驅少壯，敗屋葉羸耋。","踐蹋比塵埃，焚燒同稿秸。","吾皇自神聖，執事皆間傑。","射策亦何爲，春卿遂聊輟。","伊余將貢技，未有耻可刷。","却問漁樵津，重耕煙雨墢。","諸侯急兵食，冗賸方翦截。","不可抱詞章，巡門事干謁。","歸來闔蓬楗，壁立空豎褐。","煖手抱孤煙，披書向殘雪。","幽憂和憤懣，忽愁自驚蹶。","文兮乏寸毫，武也無尺鐵。","平生所韜蓄，到死不開豁。","念此令人悲，翕然生內熱。","加之被皸瘃，況復久藜糲。","既爲霜露侵，一臥增百疾。","筋骸將束縛，腠理如箠撻。","初謂抵狂貙，又如當毒蝎。","江南多事鬼，巫覡連甌粵。","可口是妖訛，恣情專賞罰。","良醫只備位，藥肆或虛設。","而我正萎痿，安能致訶咄。","椒蘭任芳苾，精粣從羅列。","醆斝既屢傾，錢刀亦隨爇。","兼之凟財賄，不止行盜竊。","天地如有知，微妖豈逃殺。","其時心力憤，益使氣息惙。","永夜更呻吟，空牀但皮骨。","君來贊賢牧，野鶴聊簪笏。","謂我同光塵，心中有溟渤。","輪蹄相壓至，問遺無虛月。","首到春鴻濛，猶殘病根茇。","看花雖眼暈，見酒忘肺渴。","隱几還自怡，逢盧亦爭喝。","抽毫更唱和，劒戟相磨戛。","何大不包羅，何微不挑刮。","今來值霖雨，晝夜無暫歇。","雜若碎淵淪，高如破轇轕。","何勞鼉吼岸，詎要鸛鳴垤。","祗意江海翻，更愁山岳裂。","初驚蚩尤陣，虎豹爭搏嚙。","又疑伍胥濤，蛟蜃相蹙拶。","千家濛瀑練，忽似好披拂。","萬瓦垂玉繩，如堪取縈結。","況余居低下，本是蛙蚓窟。","邇來增號呼，得以恣唐突。","先夸屋舍好，又恃頭角凸。","厚地雖直方，身能徧穿穴。","常參莊辯裏，亦造揚玄末。","偃仰縱無機，形容且相忽。","低頭增歎詫，到口復嗢咽。","沮洳漬琴書，莓苔染巾襪。","解衣換倉粟，秕稗猶未脫。","飢鳥屢窺臨，泥僮苦舂䑔。","或聞秋稼穡，大半沈澎汃。","耕父蠹齊民，農夫思旱魃。","吾觀天之意，未必洪水割。","且要虐飛龍，又圖滋跛鼈。","三吳明太守，左右皆儒哲。","有力即扶危，懷仁過救暍。","鹿門皮夫子，氣調真俊逸。","截海上雲鷹，橫空下霜鶻。","文壇如命將，可以持玉鉞。","不獨扆羲軒，便當城老佛。","顧余爲山者，所得纔簣撮。","譬如飾箭材，尚欠鏃與筈。","閑將歈兒唱，強倚帝子瑟。","幸得遠瀟湘，不然嗤賈屈。","開緘窺寶肆，璣貝光比櫛。","朗詠衝樂懸，陶匏響鏗擖。","古來愁霖賦，不是不清越。","非君頓挫才，沴氣難摧折。","馳情扣虛寂，力盡無所掇。","不足謝徽音，祗令凋鬢髪。"]', '["微生參最靈，天與意緒拙。","人皆機巧求，百逕無一達。","家爲唐臣来，奕世唯稷卨。","只垂青白风，凜凜自貽厥。","猶殘賜书在，編簡苦斷絕。","其间忠孝字，万古光不滅。","孱孫誠瞢昧，有志常搰搰。","敢云嗣良弓，但欲終守節。","諠譁不入耳，讒佞不挂舌。","仰詠堯舜言，俯遵周孔轍。","所貪既仁義，豈暇理生活。","縱有旧田园，拋来亦蕪沒。","因之成否塞，十載真契闊。","凍骭一襜褕，飢腸少糠籺。","甘心付天壤，委分任迴斡。","笠澤臥孤云，桐江釣明月。","盈筐盛芡芰，满釜煮鱸鱖。","酒幟风外㩻，茶槍露中擷。","歌謠非大雅，捃摭爲小说。","上可補熏莖，傍堪跐芽蘗。","方當賣罾罩，尽以易紙札。","蹤跡尚吳门，梦魂先魏闕。","尋闻天子詔，赫怒誅叛卒。","宵旰憫烝黎，謨明问征伐。","王師雖繼下，賊壘未即拔。","此时淮海波，半是生人血。","霜戈驱少壯，敗屋葉羸耋。","踐蹋比塵埃，焚燒同稿秸。","吾皇自神聖，執事皆间傑。","射策亦何爲，春卿遂聊輟。","伊余將貢技，未有耻可刷。","却问漁樵津，重耕煙雨墢。","諸侯急兵食，冗賸方翦截。","不可抱词章，巡门事干謁。","归来闔蓬楗，壁立空豎褐。","煖手抱孤煙，披书向殘雪。","幽憂和憤懣，忽愁自驚蹶。","文兮乏寸毫，武也無尺鐵。","平生所韜蓄，到死不开豁。","念此令人悲，翕然生內熱。","加之被皸瘃，況复久藜糲。","既爲霜露侵，一臥增百疾。","筋骸將束縛，腠理如箠撻。","初謂抵狂貙，又如當毒蝎。","江南多事鬼，巫覡連甌粵。","可口是妖訛，恣情專賞罰。","良醫只備位，藥肆或虛設。","而我正萎痿，安能致訶咄。","椒蘭任芳苾，精粣從羅列。","醆斝既屢傾，錢刀亦隨爇。","兼之凟財賄，不止行盜竊。","天地如有知，微妖豈逃殺。","其时心力憤，益使氣息惙。","永夜更呻吟，空牀但皮骨。","君来贊賢牧，野鹤聊簪笏。","謂我同光塵，心中有溟渤。","輪蹄相壓至，问遺無虛月。","首到春鴻濛，猶殘病根茇。","看花雖眼暈，见酒忘肺渴。","隐几還自怡，逢盧亦爭喝。","抽毫更唱和，劒戟相磨戛。","何大不包羅，何微不挑刮。","今来值霖雨，晝夜無暫歇。","杂若碎淵淪，高如破轇轕。","何勞鼉吼岸，詎要鸛鳴垤。","祗意江海翻，更愁山岳裂。","初驚蚩尤陣，虎豹爭搏嚙。","又疑伍胥濤，蛟蜃相蹙拶。","千家濛瀑練，忽似好披拂。","万瓦垂玉繩，如堪取縈結。","況余居低下，本是蛙蚓窟。","邇来增號呼，得以恣唐突。","先夸屋舍好，又恃头角凸。","厚地雖直方，身能徧穿穴。","常參莊辯裏，亦造揚玄末。","偃仰縱無機，形容且相忽。","低头增歎詫，到口复嗢咽。","沮洳漬琴书，莓苔染巾襪。","解衣換倉粟，秕稗猶未脫。","飢鸟屢窺臨，泥僮苦舂䑔。","或闻秋稼穡，大半沈澎汃。","耕父蠹齊民，農夫思旱魃。","吾观天之意，未必洪水割。","且要虐飞龙，又圖滋跛鼈。","三吳明太守，左右皆儒哲。","有力即扶危，懷仁過救暍。","鹿门皮夫子，氣調真俊逸。","截海上云鷹，橫空下霜鶻。","文壇如命將，可以持玉鉞。","不独扆羲軒，便當城老佛。","顧余爲山者，所得纔簣撮。","譬如飾箭材，尚欠鏃與筈。","闲將歈兒唱，強倚帝子瑟。","幸得远瀟湘，不然嗤賈屈。","开緘窺寶肆，璣貝光比櫛。","朗詠衝乐懸，陶匏响鏗擖。","古来愁霖賦，不是不清越。","非君頓挫才，沴氣难摧折。","驰情扣虛寂，力尽無所掇。","不足謝徽音，祗令凋鬢髪。"]', '诗', 'shi', '', NULL, '奉酬襲美先輩吳中苦雨一百韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae7f372-78fc-4149-9ba4-ea99993fba2e', '奉酬襲美先輩初夏見寄次韻', '奉酬襲美先輩初夏见寄次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["積雨晦臯圃，門前煙水平。","蘋蘅增遙吹，枕席分餘清。","村斾詫酒美，賒來滿鋞程。","未必減宣子，何羨謝公榮。","借宅去人遠，敗牆連古城。","愁鴟占枯枿，野鼠趨前楹。","昨日雲破損，晚林先覺晴。","幽篁倚微照，碧粉含疎莖。","蠹簡有遺字，㪇琴無泛聲。","蠶寒繭尚薄，燕喜雛新成。","覽物正搖思，得君初夏行。","誠明復散誕，化匠安能爭。","海浪刷三島，天風吹六英。","洪崖領玉節，坐使虛音生。","吾祖傲洛客，因言幾爲傖。","末裔實漁者，敢懷干墨卿。","唯思釣璜老，遂得持竿情。","何須乞鵝炙，豈在斟羊羹。","畦蔬與甕醁，便可相攜迎。","蟠木几甚曲，筍皮冠且輕。","閑心放羈靮，醉脚從欹傾。","一逕有餘遠，一窗有餘明。","秦皇苦不達，天下何足幷。"]', '["積雨晦臯圃，门前煙水平。","蘋蘅增遙吹，枕席分餘清。","村斾詫酒美，賒来满鋞程。","未必減宣子，何羨謝公榮。","借宅去人远，敗牆連古城。","愁鴟占枯枿，野鼠趨前楹。","昨日云破損，晚林先覺晴。","幽篁倚微照，碧粉含疎莖。","蠹簡有遺字，㪇琴無泛声。","蠶寒繭尚薄，燕喜雛新成。","覽物正搖思，得君初夏行。","誠明复散誕，化匠安能爭。","海浪刷三島，天风吹六英。","洪崖領玉節，坐使虛音生。","吾祖傲洛客，因言幾爲傖。","末裔實漁者，敢懷干墨卿。","唯思釣璜老，遂得持竿情。","何須乞鵝炙，豈在斟羊羹。","畦蔬與甕醁，便可相携迎。","蟠木几甚曲，筍皮冠且轻。","闲心放羈靮，醉脚從欹傾。","一逕有餘远，一窗有餘明。","秦皇苦不達，天下何足幷。"]', '诗', 'shi', '', NULL, '奉酬襲美先輩初夏見寄次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717431a9-c01e-463a-acc2-3521da004caa', '奉和襲美二遊詩 徐詩', '奉和襲美二游诗 徐诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["嘗聞四書曰，經史子集焉。","苟非天祿中，此事無由全。","自從秦火來，歷代逢迍邅。","漢祖入關日，蕭何爲政年。","盡力取圖籍，遂持天下權。","中興熹平時，教化還相宣。","立石刻五經，置於太學前。","賊卓亂王室，君臣如轉圜。","洛陽且煨燼，載籍宜爲煙。","逮晉武革命，生民纔息肩。","惠懷亟寡昧，戎羯俄腥羶。","已覺天地閉，競爲東南遷。","日既不暇給，墳索何由專。","爾後國脆弱，人多尚虛玄。","任學者得謗，清言者爲賢。","直至沈范輩，始家藏簡編。","御府有不足，仍令就之傳。","梁元渚宮日，盡取如蚳蝝。","兵威忽破碎，焚爇無遺篇。","近者隋後主，搜羅勢駢闐。","寶函映玉軸，彩翠明霞鮮。","伊唐受命初，載史聲連延。","砥柱不我助，驚波湧淪漣。","遂令因去書，半在餘浮泉。","貞觀購亡逸，蓬瀛漸周旋。","炅然東壁光，與月爭流天。","偉矣開元中，王道真平平。","八萬五千卷，一一皆塗鉛。","人間盛傳寫，海內奔窮研。","目云西齋書，有過東臯田。","吾聞徐氏子，奕世皆才賢。","因知遺孫謀，不[在]黃金錢。","插架幾萬軸，森森若戈鋋。","風吹籤牌聲，滿室鏗鏘然。","佳哉鹿門子，好問如除㾓。","倏來參卿處，遂得參卿憐。","開懷展櫥簏，唯在性所便。","素業已千仞，今爲峻雲巔。","雄才舊百派，相近浮日川。","君抱王佐圖，縱步凌陶甄。","他時若報德，誰在參卿先。"]', '["嘗闻四书曰，經史子集焉。","苟非天祿中，此事無由全。","自從秦火来，歷代逢迍邅。","漢祖入关日，蕭何爲政年。","尽力取圖籍，遂持天下權。","中兴熹平时，教化還相宣。","立石刻五經，置於太学前。","賊卓亂王室，君臣如轉圜。","洛陽且煨燼，載籍宜爲煙。","逮晉武革命，生民纔息肩。","惠懷亟寡昧，戎羯俄腥羶。","已覺天地閉，競爲东南遷。","日既不暇給，墳索何由專。","爾後国脆弱，人多尚虛玄。","任学者得謗，清言者爲賢。","直至沈范輩，始家藏簡編。","御府有不足，仍令就之傳。","梁元渚宮日，尽取如蚳蝝。","兵威忽破碎，焚爇無遺篇。","近者隋後主，搜羅勢駢闐。","寶函映玉軸，彩翠明霞鲜。","伊唐受命初，載史声連延。","砥柱不我助，驚波湧淪漣。","遂令因去书，半在餘浮泉。","貞观購亡逸，蓬瀛漸周旋。","炅然东壁光，與月爭流天。","偉矣开元中，王道真平平。","八万五千卷，一一皆塗鉛。","人间盛傳寫，海內奔窮研。","目云西斋书，有過东臯田。","吾闻徐氏子，奕世皆才賢。","因知遺孫謀，不[在]黄金錢。","插架幾万軸，森森若戈鋋。","风吹籤牌声，满室鏗鏘然。","佳哉鹿门子，好问如除㾓。","倏来參卿处，遂得參卿怜。","开懷展櫥簏，唯在性所便。","素業已千仞，今爲峻云巔。","雄才旧百派，相近浮日川。","君抱王佐圖，縱步凌陶甄。","他时若報德，誰在參卿先。"]', '诗', 'shi', '', NULL, '奉和襲美二遊詩 徐詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60477426-0c33-411e-bbf0-622a1c8d44a2', '奉和襲美二遊詩 任詩', '奉和襲美二游诗 任诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["吳之辟疆園，在昔勝概敵。","前聞富脩竹，後說紛怪石。","風煙慘無主，載祀將六百。","草色與行人，誰能問遺跡。","不知清景在，盡付任君宅。","却是五湖光，偷來傍簷隙。","出門向城路，車馬聲躪躒。","入門望亭隈，水木氣岑寂。","犨牆繞曲岸，勢似行無極。","十步一危梁，乍疑當絕壁。","池容澹而古，樹意蒼然僻。","魚驚尾半紅，鳥下衣全碧。","斜來島嶼隱，恍若瀟湘隔。","雨靜挂殘絲，煙消有餘脉。","朅來任公子，擺落名利役。","雖將祿代耕，頗愛巾隨策。","秋籠支遁鶴，夜榻戴顒客。","說史足爲師，譚禪差作伯。","君多鹿門思，到此情便適。","偶蔭桂堪帷，縱吟苔可席。","顧余真任誕，雅遂中心獲。","但知醉還醒，豈知玄尚白。","甘閑在雞口，不貴封龍額。","即此自怡神，何勞謝公屐。"]', '["吳之辟疆园，在昔勝概敵。","前闻富脩竹，後说紛怪石。","风煙慘無主，載祀將六百。","草色與行人，誰能问遺跡。","不知清景在，尽付任君宅。","却是五湖光，偷来傍簷隙。","出门向城路，车马声躪躒。","入门望亭隈，水木氣岑寂。","犨牆繞曲岸，勢似行無極。","十步一危梁，乍疑當絕壁。","池容澹而古，樹意蒼然僻。","鱼驚尾半紅，鸟下衣全碧。","斜来島嶼隐，恍若瀟湘隔。","雨静挂殘絲，煙消有餘脉。","朅来任公子，擺落名利役。","雖將祿代耕，頗愛巾隨策。","秋籠支遁鹤，夜榻戴顒客。","说史足爲師，譚禪差作伯。","君多鹿门思，到此情便適。","偶蔭桂堪帷，縱吟苔可席。","顧余真任誕，雅遂中心獲。","但知醉還醒，豈知玄尚白。","甘闲在雞口，不貴封龙額。","即此自怡神，何勞謝公屐。"]', '诗', 'shi', '', NULL, '奉和襲美二遊詩 任詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd5e9c1-eecd-461d-bb82-56503debd7b2', '次追和清遠道士詩韻', '次追和清远道士诗韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一代先後賢，聲容劇河漢。","況茲邁古士，復歷蒼崖竄。","辰經幾十萬，邈與靈壽翫。","海嶽尚推移，都鄙固蕪漫。","羸僧下高閣，獨鳥沒遠岸。","嘯初風雨來，吟餘鐘唄亂。","如何鍊精魄，萬祀忽欲半。","寧爲斷臂憂，肯作秋柏散。","吾聞酆宮內，日月自昏旦。","左右修文郎，縱橫灑篇翰。","斯人久冥漠，得不垂慨歎。","庶或有神交，相從重興讚。"]', '["一代先後賢，声容劇河漢。","況茲邁古士，复歷蒼崖竄。","辰經幾十万，邈與靈壽翫。","海嶽尚推移，都鄙固蕪漫。","羸僧下高閣，独鸟沒远岸。","嘯初风雨来，吟餘鐘唄亂。","如何鍊精魄，万祀忽欲半。","寧爲斷臂憂，肯作秋柏散。","吾闻酆宮內，日月自昏旦。","左右修文郎，縱橫灑篇翰。","斯人久冥漠，得不垂慨歎。","庶或有神交，相從重兴讚。"]', '诗', 'shi', '', NULL, '次追和清遠道士詩韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f99f74-e61c-44b7-aac4-86dcf08a1fe6', '補沈恭子詩', '補沈恭子诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靈質貫軒昊，遐年越商周。","自然失遠裔，安得怨寡儔。","我亦小國胤，易名慙見優。","雖非放曠懷，雅奉逍遙遊。","攜手桂枝下，屬詞山之幽。","風雨一以過，林麓颯然秋。","落日倚石壁，天寒登古丘。","荒泉已無夕，敗葉翳不流。","亂翠缺月隱，衰紅清露愁。","覽物性未逸，反爲情所囚。","異才偶絕境，佳藻窮冥搜。","虛傾寂寞音，敢作雜珮酬。"]', '["靈質貫軒昊，遐年越商周。","自然失远裔，安得怨寡儔。","我亦小国胤，易名慙见優。","雖非放曠懷，雅奉逍遙游。","携手桂枝下，屬词山之幽。","风雨一以過，林麓颯然秋。","落日倚石壁，天寒登古丘。","荒泉已無夕，敗葉翳不流。","亂翠缺月隐，衰紅清露愁。","覽物性未逸，反爲情所囚。","異才偶絕境，佳藻窮冥搜。","虛傾寂寞音，敢作杂珮酬。"]', '诗', 'shi', '', NULL, '補沈恭子詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f184be37-4589-4078-8cf6-9151c5eb5ec7', '讀陰符經寄鹿門子', '读陰符經寄鹿门子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["清晨整冠坐，朗詠三百言。","備識天地意，獻詞犯乾坤。","何事不隱德，降靈生軒轅。","口銜造化斧，鑿破機關門。","五賊忽迸逸，萬物爭崩奔。","虛施神仙要，莫救華池源。","但學戰勝術，相高甲兵屯。","龍蛇競起陸，鬬血浮中原。","成湯與周武，反覆更爲尊。","下及秦漢得，黷弄兵亦煩。","姦強自林據，仁弱無枝蹲。","狂喉恣吞噬，逆翼爭飛翻。","家家伺天發，不肯匡淫昏。","生民墜塗炭，比屋爲冤魂。","祗爲讀此書，大樸難久存。","微臣與軒轅，亦是萬世孫。","未能窮意義，豈敢求瑕痕。","曾亦愛兩句，可與賢達論。","生者死之根，死者生之根。","方寸了十字，萬化皆胚腪。","身外更何事，眼前徒自喧。","黃河但東注，不見歸崑崙。","晝短苦夜永，勸君傾一尊。"]', '["清晨整冠坐，朗詠三百言。","備識天地意，獻词犯乾坤。","何事不隐德，降靈生軒轅。","口銜造化斧，鑿破機关门。","五賊忽迸逸，万物爭崩奔。","虛施神仙要，莫救华池源。","但学戰勝術，相高甲兵屯。","龙蛇競起陸，鬬血浮中原。","成湯與周武，反覆更爲尊。","下及秦漢得，黷弄兵亦煩。","姦強自林據，仁弱無枝蹲。","狂喉恣吞噬，逆翼爭飞翻。","家家伺天發，不肯匡淫昏。","生民墜塗炭，比屋爲冤魂。","祗爲读此书，大樸难久存。","微臣與軒轅，亦是万世孫。","未能窮意義，豈敢求瑕痕。","曾亦愛兩句，可與賢達論。","生者死之根，死者生之根。","方寸了十字，万化皆胚腪。","身外更何事，眼前徒自喧。","黄河但东注，不见归崑崙。","晝短苦夜永，勸君傾一尊。"]', '诗', 'shi', '', NULL, '讀陰符經寄鹿門子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08915c1b-2083-4540-a060-6fc69c5b1a6b', '奉和襲美初夏遊楞伽精舍次韻', '奉和襲美初夏游楞伽精舍次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["吳都涵汀洲，碧液浸郡郭。","微雨蕩春醉，上下一清廓。","奇蹤欲探討，靈物先瘵瘼。","飄然蘭葉舟，旋倚煙霞泊。","吟譚亂篙艣，夢寐雜巘崿。","纖情不可逃，洪筆難暫閣。","豈知楞伽會，乃在山水箔。","金仙著書日，世界名極樂。","薝蔔冠諸香，琉璃代華堊。","禽言經不輟，象口川寧涸。","萬善峻爲城，巉巉扞羣惡。","清晨欲登造，安得無自愕。","險穴駭坤牢，高蘿挂天笮。","池容澹相向，蛟怪如可摸。","苔蔽石髓根，蒲差水心鍔。","嵐侵荅摩髻，日照狻猊絡。","仰首乍眩旋，迴眸更輝㸌。","簷端凝飛羽，磴外浮碧落。","到迴解風襟，臨幽濯雲屩。","塵機性非便，靜境心所著。","自取海鷗知，何煩尸祝酢。","峯圍震澤岸，翠浪舞綃幕。","瀲灩豈堯遭，㟞嵃非禹鑿。","潛聽鐘梵處，別有松桂壑。","靄重燈不光，泉寒網猶薄。","僮能躡孤剎，鳥慣親摐鐸。","服道身可遺，乞閑心已諾。","人間亦何事，萬態相毒蠚。","戰壘競高深，儒衣謾褒博。","宣尼名位達，未必春秋作。","管氏包霸圖，須人解其縛。","伊余採樵者，蓬藋方索寞。","近得風雅情，聊將聖賢度。","多君富遒采，識度兩清恪。","詎寵生滅詞，肯教夷夏錯。","未爲堯舜用，且向煙霞託。","我亦擺塵埃，他年附鴻鶴。"]', '["吳都涵汀洲，碧液浸郡郭。","微雨蕩春醉，上下一清廓。","奇蹤欲探討，靈物先瘵瘼。","飄然蘭葉舟，旋倚煙霞泊。","吟譚亂篙艣，梦寐杂巘崿。","纖情不可逃，洪笔难暫閣。","豈知楞伽會，乃在山水箔。","金仙著书日，世界名極乐。","薝蔔冠諸香，琉璃代华堊。","禽言經不輟，象口川寧涸。","万善峻爲城，巉巉扞羣惡。","清晨欲登造，安得無自愕。","險穴駭坤牢，高蘿挂天笮。","池容澹相向，蛟怪如可摸。","苔蔽石髓根，蒲差水心鍔。","嵐侵荅摩髻，日照狻猊絡。","仰首乍眩旋，迴眸更輝㸌。","簷端凝飞羽，磴外浮碧落。","到迴解风襟，臨幽濯云屩。","塵機性非便，静境心所著。","自取海鷗知，何煩尸祝酢。","峯圍震澤岸，翠浪舞綃幕。","瀲灩豈堯遭，㟞嵃非禹鑿。","潛听鐘梵处，別有松桂壑。","靄重灯不光，泉寒網猶薄。","僮能躡孤剎，鸟慣親摐鐸。","服道身可遺，乞闲心已諾。","人间亦何事，万態相毒蠚。","戰壘競高深，儒衣謾褒博。","宣尼名位達，未必春秋作。","管氏包霸圖，須人解其縛。","伊余採樵者，蓬藋方索寞。","近得风雅情，聊將聖賢度。","多君富遒采，識度兩清恪。","詎寵生滅词，肯教夷夏錯。","未爲堯舜用，且向煙霞託。","我亦擺塵埃，他年附鴻鹤。"]', '诗', 'shi', '', NULL, '奉和襲美初夏遊楞伽精舍次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04a162c-c793-4db6-bd3f-19718742080c', '奉和襲美公齋四詠次韻 小松', '奉和襲美公斋四詠次韻 小松', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["擢秀逋客巖，遺根飛鳥逕。","因求飾清閟，遂得辭危敻。","貞同柏有心，立若珠無脛。","枝形短未怪，鬣數差難定。","況密三天風，方遵四時柄。","那興培塿歎，免荅鄰里病。","微霜靜可分，片月疎堪映。","奇當虎頭筆，韻叶通明性。","會拂陽烏胸，掄才膺帝命。"]', '["擢秀逋客巖，遺根飞鸟逕。","因求飾清閟，遂得辞危敻。","貞同柏有心，立若珠無脛。","枝形短未怪，鬣數差难定。","況密三天风，方遵四时柄。","那兴培塿歎，免荅鄰里病。","微霜静可分，片月疎堪映。","奇當虎头笔，韻叶通明性。","會拂陽烏胸，掄才膺帝命。"]', '诗', 'shi', '', NULL, '奉和襲美公齋四詠次韻 小松 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36065dc3-00b8-489d-a155-35fc6779c7af', '奉和襲美公齋四詠次韻 小桂', '奉和襲美公斋四詠次韻 小桂', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["諷賦輕八植，擅名方一枝。","才高不滿意，更自寒山移。","宛宛別雲態，蒼蒼出塵姿。","煙歸助華杪，雪點迎芳蕤。","青條坐可結，白日如奔螭。","諒無𠠜翦憂，即是蕭森時。","洛浦雖有蔭，騷人聊自怡。","終爲濟川檝，豈在論高卑。"]', '["諷賦轻八植，擅名方一枝。","才高不满意，更自寒山移。","宛宛別云態，蒼蒼出塵姿。","煙归助华杪，雪点迎芳蕤。","青條坐可結，白日如奔螭。","諒無𠠜翦憂，即是蕭森时。","洛浦雖有蔭，騷人聊自怡。","終爲濟川檝，豈在論高卑。"]', '诗', 'shi', '', NULL, '奉和襲美公齋四詠次韻 小桂 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685fdb44-4e24-4c80-92b2-7a5f95e30c9d', '奉和襲美公齋四詠次韻 新竹', '奉和襲美公斋四詠次韻 新竹', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["別塢破苔蘚，嚴城樹軒楹。","恭聞稟璇璣，化質離青冥。","色可定雞頸，實堪招鳳翎。","立窺五嶺秀，坐對三都屏。","晴月窈窕入，曙煙霏微生。","昔者尚借宅，況來處賓庭。","金罍縱傾倒，碧露還鮮醒。","若非抱苦節，何以偶惟馨。","徐觀穉龍出，更賦錦苞零。"]', '["別塢破苔蘚，嚴城樹軒楹。","恭闻稟璇璣，化質離青冥。","色可定雞頸，實堪招鳳翎。","立窺五嶺秀，坐对三都屏。","晴月窈窕入，曙煙霏微生。","昔者尚借宅，況来处賓庭。","金罍縱傾倒，碧露還鲜醒。","若非抱苦節，何以偶惟馨。","徐观穉龙出，更賦錦苞零。"]', '诗', 'shi', '', NULL, '奉和襲美公齋四詠次韻 新竹 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6404cb5-3033-46d8-b59d-193d5534705e', '奉和襲美公齋四詠次韻 鶴屏', '奉和襲美公斋四詠次韻 鹤屏', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["時人重花屏，獨即胎化狀。","叢毛練分彩，疎節筇相望。","曾無氃氋態，頗得連軒樣。","勢擬搶高尋，身猶在函丈。","如憂雞鶩鬬，似憶煙霞向。","塵世任縱橫，霜襟自閑放。","空資明遠思，不待浮丘相。","何由振玉衣，一舉棲瀛閬。"]', '["时人重花屏，独即胎化狀。","叢毛練分彩，疎節筇相望。","曾無氃氋態，頗得連軒樣。","勢擬搶高尋，身猶在函丈。","如憂雞鶩鬬，似憶煙霞向。","塵世任縱橫，霜襟自闲放。","空資明远思，不待浮丘相。","何由振玉衣，一舉棲瀛閬。"]', '诗', 'shi', '', NULL, '奉和襲美公齋四詠次韻 鶴屏 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('329751a4-c351-4b39-b419-a22eff15dd0d', '奉和襲美酬前進士崔潞盛製見寄因贈至一百四十言', '奉和襲美酬前進士崔潞盛製见寄因贈至一百四十言', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["孔聖鑄顏事，垂之千載餘。","其間王道乖，化作荆榛墟。","天必授賢哲，爲時攻翦除。","軻雄骨已朽，百代徒趦趄。","近者韓文公，首爲閑闢鋤。","夫子又繼起，陰霾終廓如。","搜得萬古遺，裁成十編書。","南山盛雲雨，東序堆瓊琚。","偶此真籍客，悠揚兩情攄。","清詞忽窈窕，雅韻何虛徐。","唱既野芳坼，酬還天籟疎。","輕波掠翡翠，曉露披芙渠。","儷曲信寡合，末流難嗣初。","空持一竿餌，有意鯨魚。"]', '["孔聖鑄顏事，垂之千載餘。","其间王道乖，化作荆榛墟。","天必授賢哲，爲时攻翦除。","軻雄骨已朽，百代徒趦趄。","近者韓文公，首爲闲闢鋤。","夫子又繼起，陰霾終廓如。","搜得万古遺，裁成十編书。","南山盛云雨，东序堆瓊琚。","偶此真籍客，悠揚兩情攄。","清词忽窈窕，雅韻何虛徐。","唱既野芳坼，酬還天籟疎。","轻波掠翡翠，晓露披芙渠。","儷曲信寡合，末流难嗣初。","空持一竿餌，有意鯨鱼。"]', '诗', 'shi', '', NULL, '奉和襲美酬前進士崔潞盛製見寄因贈至一百四十言 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a9d3d5-95a1-44f6-a403-36c8f72e6b74', '奉和襲美太湖詩二十首 初入太湖', '奉和襲美太湖诗二十首 初入太湖', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["東南具區雄，天水合爲一。","高帆大弓滿，羿射爭箭疾。","時當暑雨後，氣象仍鬱密。","乍如開雕笯，聳翅忽飛出。","行將十洲近，坐覺八極溢。","耳目駭鴻濛，精神寒佶栗。","坑來斗呀豁，湧處驚嵳崒。","嶮異拔龍湫，喧如破蛟室。","斯須風妥帖，若受命平秩。","微茫誠端倪，遠嶠疑格筆。","巉巉見銅闕，左右皆輔弼。","盤空儼相趨，去勢猶橫逸。","嘗聞咸池氣，下注作清質。","至今涵赤霄，尚且浴白日。","又云構浮玉，宛與崑閬匹。","肅爲靈官家，此事難致詰。","纔迎沙嶼好，指顧俄已失。","山川互蔽虧，魚鳥空聱耴。","何當授真檢，得召天吳術。","一一問朝宗，方應可譚悉。"]', '["东南具區雄，天水合爲一。","高帆大弓满，羿射爭箭疾。","时當暑雨後，氣象仍鬱密。","乍如开雕笯，聳翅忽飞出。","行將十洲近，坐覺八極溢。","耳目駭鴻濛，精神寒佶栗。","坑来斗呀豁，湧处驚嵳崒。","嶮異拔龙湫，喧如破蛟室。","斯須风妥帖，若受命平秩。","微茫誠端倪，远嶠疑格笔。","巉巉见銅闕，左右皆輔弼。","盤空儼相趨，去勢猶橫逸。","嘗闻咸池氣，下注作清質。","至今涵赤霄，尚且浴白日。","又云構浮玉，宛與崑閬匹。","肅爲靈官家，此事难致詰。","纔迎沙嶼好，指顧俄已失。","山川互蔽虧，鱼鸟空聱耴。","何當授真檢，得召天吳術。","一一问朝宗，方應可譚悉。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 初入太湖 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e341e40d-93f8-4a94-8ca4-f3b3301f6dc2', '奉和襲美太湖詩二十首 曉次神景宮', '奉和襲美太湖诗二十首 晓次神景宮', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曉帆逗碕岸，高步入神景。","灑灑襟袖清，如臨蘂珠屏。","雖然羣動息，此地常寂靜。","翠鑷有寒鏘，碧花無定影。","憑軒羽人傲，夾戶天獸猛。","稽首朝元君，褰衣就虛省。","呀空雪牙利，嗽水石齒冷。","香母未垂嬰，芝田不論頃。","遙通河漢口，近撫松桂頂。","飯薦七白蔬，杯釃九光杏。","人間附塵躅，固陋真鉗頸。","肯信抃鼇傾，猶疑夏蟲永。","玄津蕩瓊壟，紫汞啼金鼎。","盡出冰霜書，期君一披省。"]', '["晓帆逗碕岸，高步入神景。","灑灑襟袖清，如臨蘂珠屏。","雖然羣动息，此地常寂静。","翠鑷有寒鏘，碧花無定影。","憑軒羽人傲，夾戶天獸猛。","稽首朝元君，褰衣就虛省。","呀空雪牙利，嗽水石齒冷。","香母未垂嬰，芝田不論頃。","遙通河漢口，近撫松桂頂。","飯薦七白蔬，杯釃九光杏。","人间附塵躅，固陋真鉗頸。","肯信抃鼇傾，猶疑夏蟲永。","玄津蕩瓊壟，紫汞啼金鼎。","尽出冰霜书，期君一披省。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 曉次神景宮 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ee1e11-8141-4716-aab3-dc7410ef6a45', '奉和襲美太湖詩二十首 入林屋洞', '奉和襲美太湖诗二十首 入林屋洞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["知名十小天，林屋當第九。","題之爲左神，理之以天后。","魁堆辟邪輩，左右專備守。","自非方瞳人，不敢窺洞口。","唯君好奇士，復嘯忘情友。","致傘在風林，低冠入雲竇。","中深劇苔井，傍坎纔藥臼。","石角忽支頤，藤根時束肘。","初爲大幽怖，漸見微明誘。","屹若造靈封，森如達仙藪。","嘗聞白芝秀，狀與琅花偶。","又坐紫泉光，甘如酌天酒。","何人能挹嚼，餌以代漿糗。","却笑探五符，徒勞步雙斗。","真君不可見，焚盥空遲久。","眷戀玉碣文，行行但迴首。"]', '["知名十小天，林屋當第九。","題之爲左神，理之以天后。","魁堆辟邪輩，左右專備守。","自非方瞳人，不敢窺洞口。","唯君好奇士，复嘯忘情友。","致傘在风林，低冠入云竇。","中深劇苔井，傍坎纔藥臼。","石角忽支頤，藤根时束肘。","初爲大幽怖，漸见微明誘。","屹若造靈封，森如達仙藪。","嘗闻白芝秀，狀與琅花偶。","又坐紫泉光，甘如酌天酒。","何人能挹嚼，餌以代漿糗。","却笑探五符，徒勞步雙斗。","真君不可见，焚盥空遲久。","眷戀玉碣文，行行但迴首。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 入林屋洞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8a696c-cd7e-491d-8b82-38f9cc3bfe73', '奉和襲美太湖詩二十首 雨中遊包山精舍', '奉和襲美太湖诗二十首 雨中游包山精舍', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["包山信神仙，主者上真職。","及棲鐘梵侶，又是清涼域。","乃知煙霞地，絕俗無不得。","巖開一逕分，柏擁深殿黑。","僧閑若圖畫，像古非雕刻。","海客施明珠，湘蕤料淨食。","有魚皆玉尾，有烏盡金臆。","手攜鞞鐸佉，若在中印國。","千峰殘雨過，萬籟清且極。","此時空寂心，可以遺智識。","知君戰未勝，尚倚功名力。","却下聽經徒，孤帆有行色。"]', '["包山信神仙，主者上真職。","及棲鐘梵侶，又是清涼域。","乃知煙霞地，絕俗無不得。","巖开一逕分，柏擁深殿黑。","僧闲若圖畫，像古非雕刻。","海客施明珠，湘蕤料淨食。","有鱼皆玉尾，有烏尽金臆。","手携鞞鐸佉，若在中印国。","千峰殘雨過，万籟清且極。","此时空寂心，可以遺智識。","知君戰未勝，尚倚功名力。","却下听經徒，孤帆有行色。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 雨中遊包山精舍 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489b5f09-4bed-45b4-9d6c-6fb7b4c3d837', '奉和襲美太湖詩二十首 毛公壇', '奉和襲美太湖诗二十首 毛公壇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["古有韓終道，授之劉先生。","身如碧鳳皇，羽翼披輕輕。","先生盛驅役，臣伏甲與丁。","勢可倒五嶽，不唯鞭羣靈。","飄颻駕翔螭，白日朝太清。","空遺古壇在，稠疊煙蘿屏。","遠懷步罡夕，列宿森然明。","四角鎮露獸，三層差羽嬰。","迴眸盼七炁，運足馳疎星。","象外真既感，區中道俄成。","邇來向千祀，雲嶠空崢嶸。","石上橘花落，石根瑤草青。","時時白鹿下，此外無人行。","我訪岑寂境，自言齋戒精。","如今君安死，魂魄猶羶腥。","有芨皆綠字，有芝皆紫莖。","相將望瀛島，浩蕩凌滄溟。"]', '["古有韓終道，授之劉先生。","身如碧鳳皇，羽翼披轻轻。","先生盛驱役，臣伏甲與丁。","勢可倒五嶽，不唯鞭羣靈。","飄颻駕翔螭，白日朝太清。","空遺古壇在，稠叠煙蘿屏。","远懷步罡夕，列宿森然明。","四角鎮露獸，三層差羽嬰。","迴眸盼七炁，運足驰疎星。","象外真既感，區中道俄成。","邇来向千祀，云嶠空崢嶸。","石上橘花落，石根瑤草青。","时时白鹿下，此外無人行。","我訪岑寂境，自言斋戒精。","如今君安死，魂魄猶羶腥。","有芨皆綠字，有芝皆紫莖。","相將望瀛島，浩蕩凌滄溟。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 毛公壇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da08d9cb-2c24-4e1c-ac3c-0c7ab8d3ed4e', '奉和襲美太湖詩二十首 三宿神景宮', '奉和襲美太湖诗二十首 三宿神景宮', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靈蹤未徧尋，不覺谿色瞑。","迴頭問棲所，稍下杉蘿逕。","巖居更幽絕，澗戶相隱映。","過此即神宮，虛堂愜雲性。","四軒盡疎達，一榻何清零。","髣髴聞玉笙，鼓鏗動涼磬。","風凝古松粒，露壓脩荷柄。","萬籟既無聲，澄明但心聽。","希微辨真語，若授虛皇命。","尺宅按來平，華池漱餘淨。","頻窺宿羽麗，三吸晨霞盛。","豈獨冷衣襟，便堪遺造請。","徒深物外趣，未脫塵中病。","舉首謝靈峰，徜徉事歸榜。"]', '["靈蹤未徧尋，不覺谿色瞑。","迴头问棲所，稍下杉蘿逕。","巖居更幽絕，澗戶相隐映。","過此即神宮，虛堂愜云性。","四軒尽疎達，一榻何清零。","髣髴闻玉笙，鼓鏗动涼磬。","风凝古松粒，露壓脩荷柄。","万籟既無声，澄明但心听。","希微辨真語，若授虛皇命。","尺宅按来平，华池漱餘淨。","頻窺宿羽丽，三吸晨霞盛。","豈独冷衣襟，便堪遺造請。","徒深物外趣，未脫塵中病。","舉首謝靈峰，徜徉事归榜。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 三宿神景宮 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec103b8-efa8-4a5d-b24b-97125b4a2c7a', '奉和襲美太湖詩二十首 以毛公泉獻大諫清河公', '奉和襲美太湖诗二十首 以毛公泉獻大諫清河公', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["先生鍊飛精，羽化成翩翻。","荒壇與古甃，隱軫清泠存。","四面蹙山骨，中心含月魂。","除非紫水脉，即是金沙源。","香實灑桂蘂，甘惟漬雲根。","向來探幽人，酌罷祛蒙昏。","況公珪璋質，近處諫諍垣。","又聞虛靜姿，早挂冰雪痕。","君對瑤華味，重獻蘭薰言。","當應滌煩暑，朗詠翬飛軒。","我願得一掬，攀天呌重閽。","霏霏散爲雨，用以移焦原。"]', '["先生鍊飞精，羽化成翩翻。","荒壇與古甃，隐軫清泠存。","四面蹙山骨，中心含月魂。","除非紫水脉，即是金沙源。","香實灑桂蘂，甘惟漬云根。","向来探幽人，酌罷祛蒙昏。","況公珪璋質，近处諫諍垣。","又闻虛静姿，早挂冰雪痕。","君对瑤华味，重獻蘭薰言。","當應滌煩暑，朗詠翬飞軒。","我願得一掬，攀天呌重閽。","霏霏散爲雨，用以移焦原。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 以毛公泉獻大諫清河公 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f50ee9-058f-4378-99c2-6f2e572e60b6', '奉和襲美太湖詩二十首 縹緲峰', '奉和襲美太湖诗二十首 縹緲峰', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["左右皆跳岑，孤峰挺然起。","因思縹緲稱，乃在虛無裏。","清晨躋磴道，便是孱顏始。","據石即更歌，遇泉還徙倚。","花奇忽如薦，樹曲渾成几。","樂靜煙靄知，忘機猨狖喜。","頻攀峻過斗，末造平如砥。","舉首閡青冥，迴眸聊下視。","高帆大於鳥，廣墠纔類蟻。","就此微茫中，爭先未嘗已。","葛洪話剛氣，去地四千里。","苟能乘之遊，止若道路耳。","吾將自峰頂，便可朝帝扆。","盡欲活羣生，不唯私一己。","超騎明月蜍，復弄華星蘂。","却下蓬萊巔，重窺清淺水。","身爲大塊客，自號天隨子。","他日向華陽，敲雲問名氏。"]', '["左右皆跳岑，孤峰挺然起。","因思縹緲稱，乃在虛無裏。","清晨躋磴道，便是孱顏始。","據石即更歌，遇泉還徙倚。","花奇忽如薦，樹曲渾成几。","乐静煙靄知，忘機猨狖喜。","頻攀峻過斗，末造平如砥。","舉首閡青冥，迴眸聊下視。","高帆大於鸟，廣墠纔類蟻。","就此微茫中，爭先未嘗已。","葛洪話剛氣，去地四千里。","苟能乘之游，止若道路耳。","吾將自峰頂，便可朝帝扆。","尽欲活羣生，不唯私一己。","超騎明月蜍，复弄华星蘂。","却下蓬萊巔，重窺清淺水。","身爲大塊客，自號天隨子。","他日向华陽，敲云问名氏。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 縹緲峰 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c132ca-63a9-4aeb-8394-a36e0e90f0af', '奉和襲美太湖詩二十首 桃花塢', '奉和襲美太湖诗二十首 桃花塢', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["行行問絕境，貴與名相親。","空經桃花塢，不見秦時人。","願此爲東風，吹起枝上春。","願此作流水，潛浮蘂中塵。","願此爲好鳥，得棲花際鄰。","願此作幽蝶，得隨花下賓。","朝爲照花日，暮作涵花津。","試爲探花士，作此偷桃臣。","桃源不我棄，庶可全天真。"]', '["行行问絕境，貴與名相親。","空經桃花塢，不见秦时人。","願此爲东风，吹起枝上春。","願此作流水，潛浮蘂中塵。","願此爲好鸟，得棲花際鄰。","願此作幽蝶，得隨花下賓。","朝爲照花日，暮作涵花津。","試爲探花士，作此偷桃臣。","桃源不我棄，庶可全天真。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 桃花塢 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e11dee2-3272-4230-bdd5-7f5fb55d2106', '奉和襲美太湖詩二十首 明月灣', '奉和襲美太湖诗二十首 明月灣', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["昔聞明月觀，祗傷荒野基。","今逢明月灣，不值三五時。","擇此二明月，洞庭看最奇。","連山忽中斷，遠樹分毫釐。","周迴二十里，一片澄風漪。","見說秋半夜，淨無雲物欺。","兼之星斗藏，獨有神仙期。","初聞鏘鐐跳，積漸調參差。","空中卓羽衛，波上停龍螭。","蹤舞玉煙節，高歌碧霜詞。","清光悄不動，萬象寒咿咿。","此會非俗致，無由得旁窺。","但當乘扁舟，酒甕仍相隨。","或徹三弄笛，或成數聯詩。","自然瑩心骨，何用神仙爲。"]', '["昔闻明月观，祗傷荒野基。","今逢明月灣，不值三五时。","擇此二明月，洞庭看最奇。","連山忽中斷，远樹分毫釐。","周迴二十里，一片澄风漪。","见说秋半夜，淨無云物欺。","兼之星斗藏，独有神仙期。","初闻鏘鐐跳，積漸調參差。","空中卓羽衛，波上停龙螭。","蹤舞玉煙節，高歌碧霜词。","清光悄不动，万象寒咿咿。","此會非俗致，無由得旁窺。","但當乘扁舟，酒甕仍相隨。","或徹三弄笛，或成數聯诗。","自然瑩心骨，何用神仙爲。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 明月灣 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24a1ee6-ee5b-413b-8a20-015a2294aa8e', '奉和襲美太湖詩二十首 練瀆', '奉和襲美太湖诗二十首 練瀆', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["越恃君子衆，大將壓全吳。","吳將派天澤，以練舟師徒。","一鏡止千里，支流忽然迂。","蒼匳朿洪波，坐似馮夷軀。","戰艦百萬輩，浮宮三十餘。","平川盛丁寧，絕島分儲胥。","鳳押半鶴膝，錦杠雜肥胡。","香煙與殺氣，浩浩隨風驅。","彈射盡高鳥，杯觥醉潛魚。","山靈恐見鞭，水府愁爲墟。","兵利德日削，反爲讎國屠。","至今鉤鏃殘，尚與泥沙俱。","照此月倍苦，來茲煙亦孤。","丁魂尚有淚，合灑青楓枯。"]', '["越恃君子衆，大將壓全吳。","吳將派天澤，以練舟師徒。","一镜止千里，支流忽然迂。","蒼匳朿洪波，坐似馮夷軀。","戰艦百万輩，浮宮三十餘。","平川盛丁寧，絕島分儲胥。","鳳押半鹤膝，錦杠杂肥胡。","香煙與殺氣，浩浩隨风驱。","彈射尽高鸟，杯觥醉潛鱼。","山靈恐见鞭，水府愁爲墟。","兵利德日削，反爲讎国屠。","至今鉤鏃殘，尚與泥沙俱。","照此月倍苦，来茲煙亦孤。","丁魂尚有泪，合灑青楓枯。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 練瀆 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d863fb3-649d-4e63-92cd-b6008942c289', '奉和襲美太湖詩二十首 投龍潭', '奉和襲美太湖诗二十首 投龙潭', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["名山潭洞中，自古多祕邃。","君將接神物，聊用申祀事。","鎔金象牙角，尺木無不備。","亦既奉真官，因之徇前志。","持來展明誥，敬以投嘉瑞。","鱗光煥水容，目色燒山翠。","吾皇病秦漢，豈獨探幽異。","所貴風雨時，民皆受其賜。","良田爲巨浸，污澤成赤地。","掌職一不行，精靈又何寄。","唯貪血食飽，但據驪珠睡。","何必費黃金，年年授星使。"]', '["名山潭洞中，自古多祕邃。","君將接神物，聊用申祀事。","鎔金象牙角，尺木無不備。","亦既奉真官，因之徇前志。","持来展明誥，敬以投嘉瑞。","鱗光煥水容，目色燒山翠。","吾皇病秦漢，豈独探幽異。","所貴风雨时，民皆受其賜。","良田爲巨浸，污澤成赤地。","掌職一不行，精靈又何寄。","唯貪血食飽，但據驪珠睡。","何必費黄金，年年授星使。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 投龍潭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2333e7aa-fbb6-40bb-b733-fadf85a20b31', '奉和襲美太湖詩二十首 孤園寺', '奉和襲美太湖诗二十首 孤园寺', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["浮屠從西來，事者極梁武。","巖幽與水曲，結構無遺土。","窮山林幹盡，竭海珠璣聚。","況即侍從臣，敢愛煙波塢。","幡條玉龍扣，殿角金虬舞。","釋子厭樓臺，生人露風雨。","今來四百載，像設藏雲浦。","輕鴿亂馴鷗，鳴鐘和朝艣。","庭蕉裂旗斾，野蔓差纓組。","石上解空人，窗前聽經虎。","林虛葉如織，水淨沙堪數。","徧問得中天，歸脩釋迦譜。"]', '["浮屠從西来，事者極梁武。","巖幽與水曲，結構無遺土。","窮山林幹尽，竭海珠璣聚。","況即侍從臣，敢愛煙波塢。","幡條玉龙扣，殿角金虬舞。","釋子厭楼台，生人露风雨。","今来四百載，像設藏云浦。","轻鴿亂馴鷗，鳴鐘和朝艣。","庭蕉裂旗斾，野蔓差纓組。","石上解空人，窗前听經虎。","林虛葉如织，水淨沙堪數。","徧问得中天，归脩釋迦譜。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 孤園寺 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8417f22-03ae-4ce1-967e-4c416525322b', '奉和襲美太湖詩二十首 上真觀', '奉和襲美太湖诗二十首 上真观', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["嘗聞昇三清，真有上中下。","官居乘佩服，一一自相亞。","霄裙或霞粲，侍女忽玉姹。","坐進金碧腴，去馳飆歘駕。","今來上真觀，恍若心靈訝。","祗恐暫神遊，又疑新羽化。","風餘撼朱草，雲破生瑤榭。","望極覺波平，行虛信煙藉。","閑開飛龜帙，靜倚宿鳳架。","俗狀既能遺，塵冠聊以卸。","人間方大火，此境無朱夏。","松蓋蔭日車，泉紳垂天罅。","窮幽不知倦，復息芝園舍。","鏘珮引涼姿，焚香禮遙夜。","無情走聲利，有志依閑暇。","何處好迎僧，希將石樓借。"]', '["嘗闻昇三清，真有上中下。","官居乘佩服，一一自相亞。","霄裙或霞粲，侍女忽玉姹。","坐進金碧腴，去驰飆歘駕。","今来上真观，恍若心靈訝。","祗恐暫神游，又疑新羽化。","风餘撼朱草，云破生瑤榭。","望極覺波平，行虛信煙藉。","闲开飞龟帙，静倚宿鳳架。","俗狀既能遺，塵冠聊以卸。","人间方大火，此境無朱夏。","松蓋蔭日车，泉紳垂天罅。","窮幽不知倦，复息芝园舍。","鏘珮引涼姿，焚香禮遙夜。","無情走声利，有志依闲暇。","何处好迎僧，希將石楼借。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 上真觀 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be2b3d29-41a0-4a18-a07c-bf83f6be4bd7', '奉和襲美太湖詩二十首 銷夏灣', '奉和襲美太湖诗二十首 銷夏灣', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["霞島焰難泊，雲峰奇未收。","蕭條千里灣，獨自清如秋。","古岸過新雨，高蘿蔭橫流。","遙風吹蒹葭，折處鳴颼颼。","昔予守圭竇，過於回祿囚。","日爲蘧筁徒，分作祗裯讎。","願狎寒水怪，不封朱轂侯。","豈知煙浪涯，坐可思重裘。","健若數尺鯉，泛然雙白鷗。","不識號火井，孰問名焦丘。","我真魚鳥家，盡室營扁舟。","遺名復避世，消夏還消憂。"]', '["霞島焰难泊，云峰奇未收。","蕭條千里灣，独自清如秋。","古岸過新雨，高蘿蔭橫流。","遙风吹蒹葭，折处鳴颼颼。","昔予守圭竇，過於回祿囚。","日爲蘧筁徒，分作祗裯讎。","願狎寒水怪，不封朱轂侯。","豈知煙浪涯，坐可思重裘。","健若數尺鯉，泛然雙白鷗。","不識號火井，孰问名焦丘。","我真鱼鸟家，尽室營扁舟。","遺名复避世，消夏還消憂。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 銷夏灣 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25f0e41-aa28-4cee-bf79-3809c9c488f8', '奉和襲美太湖詩二十首 包山祠', '奉和襲美太湖诗二十首 包山祠', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靜境林麓好，古祠煙靄濃。","自非通靈才，敢陟羣仙峰。","百里波浪沓，中堂簫鼓重。","真君具瓊輿，髣髴來相從。","清露濯巢鳥，陰雲生晝龍。","風飄橘柚香，日動旛蓋容。","將命禮且潔，所祈年不凶。","終當以疏聞，特用諸侯封。"]', '["静境林麓好，古祠煙靄濃。","自非通靈才，敢陟羣仙峰。","百里波浪沓，中堂簫鼓重。","真君具瓊輿，髣髴来相從。","清露濯巢鸟，陰云生晝龙。","风飄橘柚香，日动旛蓋容。","將命禮且潔，所祈年不凶。","終當以疏闻，特用諸侯封。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 包山祠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15daca87-cbd8-4d67-a042-0b7964a81e06', '奉和襲美太湖詩二十首 聖姑廟', '奉和襲美太湖诗二十首 聖姑廟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["渺渺洞庭水，盈盈芳嶼神。","因知古佳麗，不獨湘夫人。","流蘇蕩遙吹，斜領生輕塵。","蜀彩駮霞碎，吳綃盤霧勻。","可憐飛燕姿，合是乘鸞賓。","坐想煙雨夕，兼知花草春。","空登油壁車，窈窕誰相親。","好贈玉條脫，堪攜紫綸巾。","殷勤撥香池，重薦汀洲蘋。","明朝動蘭檝，不翅星河津。"]', '["渺渺洞庭水，盈盈芳嶼神。","因知古佳丽，不独湘夫人。","流蘇蕩遙吹，斜領生轻塵。","蜀彩駮霞碎，吳綃盤霧勻。","可怜飞燕姿，合是乘鸾賓。","坐想煙雨夕，兼知花草春。","空登油壁车，窈窕誰相親。","好贈玉條脫，堪携紫綸巾。","殷勤撥香池，重薦汀洲蘋。","明朝动蘭檝，不翅星河津。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 聖姑廟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f2b07d-9662-435d-a4d7-9507fc5e048d', '奉和襲美太湖詩二十首 太湖石', '奉和襲美太湖诗二十首 太湖石', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["他山豈無石，厥狀皆可薦。","端然遇良工，坐使天質變。","或裁基棟宇，礧砢成廣殿。","或剖出溫瑜，精光具華瑱。","或將破仇敵，百礮資苦戰。","或用鏡功名，萬古如會面。","今之洞庭者，一以非此選。","槎牙真不才，反作天下彥。","所奇者嵌崆，所尚者蔥蒨。","旁穿參洞穴，內竅均環釧。","刻削九琳窗，玲瓏五明扇。","新雕碧霞段，旋破秋天片。","無力置池塘，臨風只流眄。"]', '["他山豈無石，厥狀皆可薦。","端然遇良工，坐使天質变。","或裁基棟宇，礧砢成廣殿。","或剖出溫瑜，精光具华瑱。","或將破仇敵，百礮資苦戰。","或用镜功名，万古如會面。","今之洞庭者，一以非此選。","槎牙真不才，反作天下彥。","所奇者嵌崆，所尚者蔥蒨。","旁穿參洞穴，內竅均环釧。","刻削九琳窗，玲瓏五明扇。","新雕碧霞段，旋破秋天片。","無力置池塘，臨风只流眄。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 太湖石 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ffeef9-9cdd-45ca-a7a5-28a8517d24af', '奉和襲美太湖詩二十首 崦裏', '奉和襲美太湖诗二十首 崦裏', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山橫路若絕，轉檝逢平川。","川中水木幽，高下兼良田。","溝塍墮微溜，桑柘含疎煙。","處處倚蠶箔，家家下魚筌。","騃犢臥新𦬻，野禽爭折蓮。","試招搔首翁，共語殘陽邊。","今來九州內，未得皆恬然。","賊陣始吉語，狂波又凶年。","吾翁欲何道，守此常安眠。","笑我掉頭去，蘆中聞刺船。","余知隱地術，可以齊真仙。","終當從之遊，庶復全於天。"]', '["山橫路若絕，轉檝逢平川。","川中水木幽，高下兼良田。","溝塍墮微溜，桑柘含疎煙。","处处倚蠶箔，家家下鱼筌。","騃犢臥新𦬻，野禽爭折蓮。","試招搔首翁，共語殘陽邊。","今来九州內，未得皆恬然。","賊陣始吉語，狂波又凶年。","吾翁欲何道，守此常安眠。","笑我掉头去，蘆中闻刺船。","余知隐地術，可以齊真仙。","終當從之游，庶复全於天。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 崦裏 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e8e4bac-4b05-4680-aa37-f0806ed90d81', '奉和襲美太湖詩二十首 石板', '奉和襲美太湖诗二十首 石板', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一片倒山屏，何時隳洞門。","屹然空闊中，萬古波濤痕。","我意上帝命，持來壓泉源。","恐爲庚辰官，囚怪力所掀。","又疑廣袤次，零落潛驚奔。","不然遭霹靂，強半沈無垠。","如何造化首，便截秋雲根。","往事不足問，奇蹤安可論。","吾今病煩暑，據簟常昏昏。","欲從石公乞，瑩理平如璊。","前後植桂檜，東西置琴尊。","盡攜天壤徒，浩唱羲皇言。"]', '["一片倒山屏，何时隳洞门。","屹然空闊中，万古波濤痕。","我意上帝命，持来壓泉源。","恐爲庚辰官，囚怪力所掀。","又疑廣袤次，零落潛驚奔。","不然遭霹靂，強半沈無垠。","如何造化首，便截秋云根。","往事不足问，奇蹤安可論。","吾今病煩暑，據簟常昏昏。","欲從石公乞，瑩理平如璊。","前後植桂檜，东西置琴尊。","尽携天壤徒，浩唱羲皇言。"]', '诗', 'shi', '', NULL, '奉和襲美太湖詩二十首 石板 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1b0f8d-726e-4cdb-8f0a-6134d6381984', '雜諷九首 一', '杂諷九首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["紅蠶緣枯桑，青繭大如甕。","人爭捩其臂，羿矢亦不中。","微微待賢祿，一一希入夢。","縱操上吉言，口噤難即貢。","蛟龍在怒水，拔取牙角弄。","丹穴如可遊，家家畜孤鳳。","凶門尚兒戲，戰血波澒溶。","社鬼苟有靈，誰能遏秋慟。"]', '["紅蠶緣枯桑，青繭大如甕。","人爭捩其臂，羿矢亦不中。","微微待賢祿，一一希入梦。","縱操上吉言，口噤难即貢。","蛟龙在怒水，拔取牙角弄。","丹穴如可游，家家畜孤鳳。","凶门尚兒戲，戰血波澒溶。","社鬼苟有靈，誰能遏秋慟。"]', '诗', 'shi', '', NULL, '雜諷九首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab233e8c-fdd2-42c5-8d60-a9fb2ff8b5f7', '雜諷九首 二', '杂諷九首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["童麋來觸犀，德力不相及。","伊無愜心事，祗有碎首泣。","況將鵬蝨校，數又百與十。","攻如餓鴟呌，勢若脫兔急。","斯爲朽關鍵，怒犖抉以入。","年來橫干戈，未見拔城邑。","得非佐饔者，齒齒待啜汁。","羈維豪傑輩，四駭方少縶。","此皆乘時利，縱舍在呼吸。","吾欲斧其吭，無雷動幽蟄。"]', '["童麋来觸犀，德力不相及。","伊無愜心事，祗有碎首泣。","況將鵬蝨校，數又百與十。","攻如餓鴟呌，勢若脫兔急。","斯爲朽关鍵，怒犖抉以入。","年来橫干戈，未见拔城邑。","得非佐饔者，齒齒待啜汁。","羈維豪傑輩，四駭方少縶。","此皆乘时利，縱舍在呼吸。","吾欲斧其吭，無雷动幽蟄。"]', '诗', 'shi', '', NULL, '雜諷九首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa221fac-4309-4669-b11c-5b31f9a8422e', '雜諷九首 三', '杂諷九首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["𪃿鵝慘於冰，陸立懷所適。","斯人道仍閟，不得不嗚呃。","當時布衣士，亦作天子客。","至今東方生，滿口自誇白。","終爲萬乘交，談笑無所隔。","致君非有書，乃是堯舜畫。","祗今侯門峻，日掃貧賤迹。","朝趨九韶音，暮列五鼎食。","如聞恭儉語，謇謇事夕惕。","可拍伊牧肩，功名被金石。"]', '["𪃿鵝慘於冰，陸立懷所適。","斯人道仍閟，不得不嗚呃。","當时布衣士，亦作天子客。","至今东方生，满口自誇白。","終爲万乘交，談笑無所隔。","致君非有书，乃是堯舜畫。","祗今侯门峻，日掃貧賤迹。","朝趨九韶音，暮列五鼎食。","如闻恭儉語，謇謇事夕惕。","可拍伊牧肩，功名被金石。"]', '诗', 'shi', '', NULL, '雜諷九首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2736ec1-6b36-425f-99fc-d7f53f445a86', '雜諷九首 四', '杂諷九首 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["赤舌可燒城，讒邪易爲伍。","詩人疾之甚，取俾投豺虎。","長風吹窾木，始有音韻吐。","無木亦無風，笙簧由喜怒。","女媧鍊五石，天缺猶可補。","當其利口銜，罅漏不復數。","元精遺萬類，雙目如牖戶。","非是既相參，重瞳亦爲瞽。"]', '["赤舌可燒城，讒邪易爲伍。","诗人疾之甚，取俾投豺虎。","长风吹窾木，始有音韻吐。","無木亦無风，笙簧由喜怒。","女媧鍊五石，天缺猶可補。","當其利口銜，罅漏不复數。","元精遺万類，雙目如牖戶。","非是既相參，重瞳亦爲瞽。"]', '诗', 'shi', '', NULL, '雜諷九首 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a4fc569-340e-4560-8589-b591cb262aff', '雜諷九首 五', '杂諷九首 五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["東南有狂兕，獵者西北矢。","利塵白冥冥，獨此清夜止。","無人語其事，偶坐窺天紀。","安得東壁明，洪洪用墳史。","搜揚好古士，一以罄雲水。","流堪灑菁英，風足去稗秕。","如能出奇計，坐可平賊壘。","徐陳羲皇道，高駕太平軌。","攫疏成特雄，濯垢爲具美。","貢賢當上賞，景福視所履。","永播南熏音，垂之萬年耳。"]', '["东南有狂兕，獵者西北矢。","利塵白冥冥，独此清夜止。","無人語其事，偶坐窺天紀。","安得东壁明，洪洪用墳史。","搜揚好古士，一以罄云水。","流堪灑菁英，风足去稗秕。","如能出奇計，坐可平賊壘。","徐陳羲皇道，高駕太平軌。","攫疏成特雄，濯垢爲具美。","貢賢當上賞，景福視所履。","永播南熏音，垂之万年耳。"]', '诗', 'shi', '', NULL, '雜諷九首 五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a8d504-765e-43c6-913f-1d68e477137d', '雜諷九首 六', '杂諷九首 六', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["有蘗何青青，空城雪霜裏。","千林盡枯槁，苦節獨不死。","他遭匠石顧，總入犧黃美。","遂得保天年，私心未爲耻。","高從宿梟怪，下亦容螻蟻。","大廈若掄材，亭亭託君子。"]', '["有蘗何青青，空城雪霜裏。","千林尽枯槁，苦節独不死。","他遭匠石顧，總入犧黄美。","遂得保天年，私心未爲耻。","高從宿梟怪，下亦容螻蟻。","大廈若掄材，亭亭託君子。"]', '诗', 'shi', '', NULL, '雜諷九首 六 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce2c388-d5f6-442e-9cbb-fab548eba754', '雜諷九首 七', '杂諷九首 七', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["左右佩劒者，彼此亦相笑。","趨時與閉門，喧寂不同調。","潛機取聲利，自許臻乎妙。","志士以神窺，慚然真可弔。","天之發遐籟，大小隨萬竅。","魁其罏冶姿，形質惟所召。","鼗笙磬竽瑟，是必登清廟。","伊聖不可欺，誰能守蓬藋。"]', '["左右佩劒者，彼此亦相笑。","趨时與閉门，喧寂不同調。","潛機取声利，自許臻乎妙。","志士以神窺，慚然真可弔。","天之發遐籟，大小隨万竅。","魁其罏冶姿，形質惟所召。","鼗笙磬竽瑟，是必登清廟。","伊聖不可欺，誰能守蓬藋。"]', '诗', 'shi', '', NULL, '雜諷九首 七 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b72ad09-dfcf-4385-a61a-0c14ec9e4fac', '雜諷九首 八', '杂諷九首 八', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["橫笛喝秋風，清商入疏越。","君居不夜城，肯怨孤戍月。","吳兵甚犀利，太白光突兀。","日已費千金，厪聞侵一撥。","豈無惡年少，縱酒遊俠窟。","募爲敢死軍，去以梟叛卒。","豈無中林士，貫穿學問骨。","兵法五十家，浩蕩如溟渤。","高懸鹿皮睡，清澗時依樾。","分已諾煙霞，全遺事干謁。","既非格猛獸，未可輕華髪。","北面師其謀，幾能止征伐。","何妨秦堇勇，又有曹劌說。","堯舜尚詢芻，公乎聽無忽。"]', '["橫笛喝秋风，清商入疏越。","君居不夜城，肯怨孤戍月。","吳兵甚犀利，太白光突兀。","日已費千金，厪闻侵一撥。","豈無惡年少，縱酒游俠窟。","募爲敢死軍，去以梟叛卒。","豈無中林士，貫穿学问骨。","兵法五十家，浩蕩如溟渤。","高懸鹿皮睡，清澗时依樾。","分已諾煙霞，全遺事干謁。","既非格猛獸，未可轻华髪。","北面師其謀，幾能止征伐。","何妨秦堇勇，又有曹劌说。","堯舜尚詢芻，公乎听無忽。"]', '诗', 'shi', '', NULL, '雜諷九首 八 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a16caf-080b-49d7-9b6f-1c7fdc430826', '雜諷九首 九', '杂諷九首 九', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朝爲壯士歌，暮爲壯士歌。","壯士心獨苦，傍人謂之何。","古鐵久不快，倚天無處磨。","將來易水上，猶足生寒波。","捷可搏飛狖，健能超槖駞。","羣兒被堅利，索手安馮河。","驚飆掃長林，直木謝𬄭科。","嚴霜凍大澤，僵龍不如蛇。","昔者天血碧，吾徒安歎嗟。"]', '["朝爲壯士歌，暮爲壯士歌。","壯士心独苦，傍人謂之何。","古鐵久不快，倚天無处磨。","將来易水上，猶足生寒波。","捷可搏飞狖，健能超槖駞。","羣兒被堅利，索手安馮河。","驚飆掃长林，直木謝𬄭科。","嚴霜凍大澤，僵龙不如蛇。","昔者天血碧，吾徒安歎嗟。"]', '诗', 'shi', '', NULL, '雜諷九首 九 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a622aeb1-8637-4eb6-9566-1032e18ed9f3', '美人', '美人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["美人抱瑤瑟，哀怨彈別鶴。","雌雄南北飛，一旦異棲託。","諒非金石性，安得宛如昨。","生爲竝蒂花，亦有先後落。","秋林對斜日，光景自相薄。","猶欲悟君心，朝朝佩蘭若。"]', '["美人抱瑤瑟，哀怨彈別鹤。","雌雄南北飞，一旦異棲託。","諒非金石性，安得宛如昨。","生爲竝蒂花，亦有先後落。","秋林对斜日，光景自相薄。","猶欲悟君心，朝朝佩蘭若。"]', '诗', 'shi', '', NULL, '美人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e44e91-b5b8-4c28-ba19-b267d670481b', '感事', '感事', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["將軍被鮫函，祗畏金石鏃。","豈知讒箭利，一中成赤族。","古來信簧舌，巧韻淒鏘曲。","君聞悅耳音，盡日聽不足。","初因起毫髪，漸可離骨肉。","所以賢達心，求人須任目。"]', '["將軍被鮫函，祗畏金石鏃。","豈知讒箭利，一中成赤族。","古来信簧舌，巧韻淒鏘曲。","君闻悅耳音，尽日听不足。","初因起毫髪，漸可離骨肉。","所以賢達心，求人須任目。"]', '诗', 'shi', '', NULL, '感事 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11eba15b-ac12-4ec5-9c89-277ab47742ef', '素絲', '素絲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["園客麗獨繭，詩人吟五緵。","如何墨子淚，反以悲途窮。","我意豈如是，願參天地功。","爲綫補君衮，爲弦繫君桐。","左右脩闕職，宮商還古風。","端然潔白心，可與神明通。"]', '["园客丽独繭，诗人吟五緵。","如何墨子泪，反以悲途窮。","我意豈如是，願參天地功。","爲綫補君衮，爲弦繫君桐。","左右脩闕職，宮商還古风。","端然潔白心，可與神明通。"]', '诗', 'shi', '', NULL, '素絲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c34582b-c825-4822-86ad-6d2437384a2f', '次幽獨君韻 一', '次幽独君韻 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["靈氣獨不死，尚能成綺文。","如何孤窆裏，猶自讀三墳。"]', '["靈氣独不死，尚能成綺文。","如何孤窆裏，猶自读三墳。"]', '诗', 'shi', '', NULL, '次幽獨君韻 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394ef011-f628-4391-a86d-6576901f9dbb', '次幽獨君韻 二', '次幽独君韻 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["落日送萬古，秋聲含七哀。","枯株不蕭瑟，枝幹虛崔嵬。","伊昔臨大道，歌鐘醉高臺。","臺今已平地，祗有春風迴。","明月白草死，積陰荒隴推。","聖賢亦如此，慟絕真悠哉。"]', '["落日送万古，秋声含七哀。","枯株不蕭瑟，枝幹虛崔嵬。","伊昔臨大道，歌鐘醉高台。","台今已平地，祗有春风迴。","明月白草死，積陰荒隴推。","聖賢亦如此，慟絕真悠哉。"]', '诗', 'shi', '', NULL, '次幽獨君韻 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04459fc9-0e2c-4410-9726-2887b54a1ac7', '贈遠', '贈远', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["芙蓉匣中鏡，欲照心還嬾。","本是細腰人，別來羅帶緩。","從君出門後，不奏雲和管。","妾思冷如簧，時時望君暖。","心期夢中見，路永魂夢短。","怨坐泣西風，秋窗月華滿。"]', '["芙蓉匣中镜，欲照心還嬾。","本是細腰人，別来羅带緩。","從君出门後，不奏云和管。","妾思冷如簧，时时望君暖。","心期梦中见，路永魂梦短。","怨坐泣西风，秋窗月华满。"]', '诗', 'shi', '', NULL, '贈遠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d1ecb0-582d-4a3e-a8e9-b9b130fcaba3', '村夜二篇 一', '村夜二篇 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江上冬日短，裴回草堂暝。","鴻當絕塞來，客向孤村病。","緜緜起歸念，咽咽興微詠。","菊逕月方高，橘齋霜已併。","盤飱蔬粟粗，史籍籤牌盛。","目冷松桂寒，耳喧兒女競。","開瓶浮蟻綠，試筆秋毫勁。","晝戶亦重關，寒屏遞相映。","詩從騷雅得，字向鉛槧正。","遇敵舞蛇矛，逢談捉犀柄。","無名升甲乙，有志扶荀孟。","守道希昔賢，爲文通古聖。","幽憂廢長劒，顦顇慚清鏡。","祗會魚鳥情，詎知時俗性。","浮虛多徇勢，老嬾圖歷聘。","既不務人知，空餘樂天命。","吾家在田野，家事苦遼敻。","耕稼一以微，囷倉自然罄。","愁襟風葉亂，獨坐燈花迸。","明發成浩歌，誰能少傾聽。"]', '["江上冬日短，裴回草堂暝。","鴻當絕塞来，客向孤村病。","緜緜起归念，咽咽兴微詠。","菊逕月方高，橘斋霜已併。","盤飱蔬粟粗，史籍籤牌盛。","目冷松桂寒，耳喧兒女競。","开瓶浮蟻綠，試笔秋毫勁。","晝戶亦重关，寒屏遞相映。","诗從騷雅得，字向鉛槧正。","遇敵舞蛇矛，逢談捉犀柄。","無名升甲乙，有志扶荀孟。","守道希昔賢，爲文通古聖。","幽憂廢长劒，顦顇慚清镜。","祗會鱼鸟情，詎知时俗性。","浮虛多徇勢，老嬾圖歷聘。","既不務人知，空餘乐天命。","吾家在田野，家事苦遼敻。","耕稼一以微，囷倉自然罄。","愁襟风葉亂，独坐灯花迸。","明發成浩歌，誰能少傾听。"]', '诗', 'shi', '', NULL, '村夜二篇 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e507d5f-d26e-4a22-954e-08c96e3e5bdf', '村夜二篇 二', '村夜二篇 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["世既賤文章，歸來事耕稼。","伊人著農道，我亦賦田舍。","所悲勞者苦，敢用詞爲詫。","祗効芻牧言，誰防輕薄駡。","嘻今居寵祿，各自矜雄霸。","堂上考華鐘，門前竚高駕。","纖洪動絲竹，水陸供鱠炙。","小雨靜樓臺，微風動蘭麝。","吹噓川可倒，眄睞花爭奼。","萬戶膏血窮，一筵歌舞價。","安知勤播植，卒歲無閑暇。","種以春鳸初，獲從秋隼下。","專專望穜稑，搰搰條桑柘。","日晏腹未充，霜繁體猶躶。","平生守仁義，所疾唯狙詐。","上誦周孔書，沈溟至酣籍。","豈無致君術，堯舜不上下。","豈無活國方，頗牧齊教化。","蛟龍任乾死，雲雨終不借。","羿臂束如囚，徒勞誇善射。","才能誚箕斗，辯可移嵩華。","若與虻輩量，飢寒殆相亞。","長吟倚清瑟，孤憤生遙夜。","自古有遺賢，吾容偏稱謝。"]', '["世既賤文章，归来事耕稼。","伊人著農道，我亦賦田舍。","所悲勞者苦，敢用词爲詫。","祗効芻牧言，誰防轻薄駡。","嘻今居寵祿，各自矜雄霸。","堂上考华鐘，门前竚高駕。","纖洪动絲竹，水陸供鱠炙。","小雨静楼台，微风动蘭麝。","吹噓川可倒，眄睞花爭奼。","万戶膏血窮，一筵歌舞價。","安知勤播植，卒歲無闲暇。","種以春鳸初，獲從秋隼下。","專專望穜稑，搰搰條桑柘。","日晏腹未充，霜繁體猶躶。","平生守仁義，所疾唯狙詐。","上誦周孔书，沈溟至酣籍。","豈無致君術，堯舜不上下。","豈無活国方，頗牧齊教化。","蛟龙任乾死，云雨終不借。","羿臂束如囚，徒勞誇善射。","才能誚箕斗，辯可移嵩华。","若與虻輩量，飢寒殆相亞。","长吟倚清瑟，孤憤生遙夜。","自古有遺賢，吾容偏稱謝。"]', '诗', 'shi', '', NULL, '村夜二篇 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57465762-a4b3-4a39-99ac-0d1143961b31', '記事', '記事', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["本作漁釣徒，心將遂疎放。","苦爲飢寒累，未得恣閑暢。","去年十二月，身住霅溪上。","病裏賀豐登，雞豚聊饋餉。","巍峩卞山雪，凝冽不可向。","瘦骨倍加寒，徒爲厚繒纊。","晴來露青靄，千仞缺尋丈。","臥恐玉華銷，時時推枕望。","雖然營衛困，亦覺精神王。","把筆強題詩，粗言環怪狀。","吳興鄭太守，文律頗清壯。","鳳尾與鯨牙，紛披落雜唱。","緘書寄城內，搪突無以況。","料峭採蓮船，縱橫簸天浪。","方傾謝公酒，忽值莊生喪。","默默阻音徽，臨風但惆悵。","春歸迨秋末，固自嬰微恙。","歲晏弗躬親，何由免欺誑。","今來觀刈獲，乃在松江並。","門外兩潮過，波瀾光蕩漾。","都緣新卜築，是事皆草創。","爾後如有年，還應愜微尚。","天高氣味爽，野迥襟懷曠。","感物動牢愁，憤時頻骯髒。","平生樂篇翰，至老安敢忘。","駿骨正牽鹽，玄文終覆醬。","嗟今多赤舌，見善惟蔽謗。","忖度大爲防，涵容寬作量。","圖書筐簏外，關眼皆賸長。","餓隸亦勝無，薄田家所仰。","稍離飢寒患，學古真可強。","聖道庶經營，世途多踉蹌。","近聞天子詔，復許私醞釀。","促使舂酒材，呼兒具盆盎。","宵長擁吟褐，日晏開書幌。","我醉卿可還，陶然似元亮。"]', '["本作漁釣徒，心將遂疎放。","苦爲飢寒累，未得恣闲暢。","去年十二月，身住霅溪上。","病裏賀豐登，雞豚聊饋餉。","巍峩卞山雪，凝冽不可向。","瘦骨倍加寒，徒爲厚繒纊。","晴来露青靄，千仞缺尋丈。","臥恐玉华銷，时时推枕望。","雖然營衛困，亦覺精神王。","把笔強題诗，粗言环怪狀。","吳兴鄭太守，文律頗清壯。","鳳尾與鯨牙，紛披落杂唱。","緘书寄城內，搪突無以況。","料峭採蓮船，縱橫簸天浪。","方傾謝公酒，忽值莊生喪。","默默阻音徽，臨风但惆悵。","春归迨秋末，固自嬰微恙。","歲晏弗躬親，何由免欺誑。","今来观刈獲，乃在松江並。","门外兩潮過，波瀾光蕩漾。","都緣新卜築，是事皆草創。","爾後如有年，還應愜微尚。","天高氣味爽，野迥襟懷曠。","感物动牢愁，憤时頻骯髒。","平生乐篇翰，至老安敢忘。","駿骨正牽鹽，玄文終覆醬。","嗟今多赤舌，见善惟蔽謗。","忖度大爲防，涵容寬作量。","圖书筐簏外，关眼皆賸长。","餓隸亦勝無，薄田家所仰。","稍離飢寒患，学古真可強。","聖道庶經營，世途多踉蹌。","近闻天子詔，复許私醞釀。","促使舂酒材，呼兒具盆盎。","宵长擁吟褐，日晏开书幌。","我醉卿可還，陶然似元亮。"]', '诗', 'shi', '', NULL, '記事 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37beceea-294d-4754-9afc-c35d7267b608', '孤雁', '孤雁', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["我生天地間，獨作南賓雁。","哀鳴慕前侶，不免飲啄晏。","雖蒙小雅詠，未脫魚網患。","況是婚禮須，憂爲弋者篡。","晴鳶爭上下，意氣苦凌慢。","吾常嚇鴛雛，爾輩安足訕。","迴頭語晴鳶，汝食腐鼠慣。","無異駑駘羣，戀短豆皂棧。","豈知瀟湘岸，葭菼蘋萍間。","有石形狀奇，寒流古來灣。","閑看麋鹿志，了不憂芻豢。","世所重巾冠，何妨野夫丱。","騷人誇蕙芷，易象取陸莧。","漆園逍遙篇，中亦載斥鷃。","汝惟材性下，嗜好不可諫。","身雖慕高翔，糞壤是盻盼。","或聞通鬼魅，怪祟立可辯。","硩蔟書尚存，寧容恣妖幻。"]', '["我生天地间，独作南賓雁。","哀鳴慕前侶，不免饮啄晏。","雖蒙小雅詠，未脫鱼網患。","況是婚禮須，憂爲弋者篡。","晴鳶爭上下，意氣苦凌慢。","吾常嚇鴛雛，爾輩安足訕。","迴头語晴鳶，汝食腐鼠慣。","無異駑駘羣，戀短豆皂棧。","豈知瀟湘岸，葭菼蘋萍间。","有石形狀奇，寒流古来灣。","闲看麋鹿志，了不憂芻豢。","世所重巾冠，何妨野夫丱。","騷人誇蕙芷，易象取陸莧。","漆园逍遙篇，中亦載斥鷃。","汝惟材性下，嗜好不可諫。","身雖慕高翔，糞壤是盻盼。","或闻通鬼魅，怪祟立可辯。","硩蔟书尚存，寧容恣妖幻。"]', '诗', 'shi', '', NULL, '孤雁 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7782bee4-6ffc-4909-b441-71ab6cd74692', '南涇漁父', '南涇漁父', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["予方任疎慵，地僻即所好。","江流背村落，偶往心已嫪。","田家相去遠，岑寂且縱傲。","出戶手先筇，見人頭未帽。","南涇有漁父，往往攜稚造。","問其所以漁，對我真蹈道。","我初簎魚鼈，童丱至於耄。","窟穴與生成，自然通壺奧。","孜孜戒吾屬，天物不可暴。","大小參去留，候其孳養報。","終朝獲魚利，魚亦未常耗。","同覆天地中，違仁辜覆燾。","余觀爲政者，此意諒難到。","民皆死搜求，莫肯興愍悼。","今年川澤旱，前歲山源潦。","牒訴已盈庭，聞之類禽噪。","譬如死雞鶩，豈不容乳抱。","孟子譏宋人，非其揠苗躁。","吾嘉漁父旨，雅叶賢哲操。","倘遇採詩官，斯文誠敢告。"]', '["予方任疎慵，地僻即所好。","江流背村落，偶往心已嫪。","田家相去远，岑寂且縱傲。","出戶手先筇，见人头未帽。","南涇有漁父，往往携稚造。","问其所以漁，对我真蹈道。","我初簎鱼鼈，童丱至於耄。","窟穴與生成，自然通壺奧。","孜孜戒吾屬，天物不可暴。","大小參去留，候其孳養報。","終朝獲鱼利，鱼亦未常耗。","同覆天地中，違仁辜覆燾。","余观爲政者，此意諒难到。","民皆死搜求，莫肯兴愍悼。","今年川澤旱，前歲山源潦。","牒訴已盈庭，闻之類禽噪。","譬如死雞鶩，豈不容乳抱。","孟子譏宋人，非其揠苗躁。","吾嘉漁父旨，雅叶賢哲操。","倘遇採诗官，斯文誠敢告。"]', '诗', 'shi', '', NULL, '南涇漁父 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdfa5fdd-4f9b-4355-9b27-61b0ef9c62f2', '引泉詩', '引泉诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["上嗣位六載，吾宗刺桐川。","余來拜旌戟，詔下之明年。","是時春三月，繞郭花蟬聯。","嵐盤百萬髻，上插黃金鈿。","授以道士館，置榻於東偏。","滿院聲碧樹，空堂形老仙。","本性樂凝淡，及來更虛玄。","焚香禮真像，盥手披靈編。","新定山角角，烏龍獨巉然。","除非淨晴日，不見蒼崖巔。","上有拏雲峰，下有噴壑泉。","泉分數十汊，落處皆崢潺。","寒聲入爛醉，聒破西窗眠。","支筇起獨尋，祗在牆東邊。","呼童具畚鍤，立鑿莓苔穿。","灇淙一派墮，練帶橫斜牽。","亂石拋落落，寒流響濺濺。","狂奴七里瀨，縮到疎楹前。","跳花潑半散，湧沫飛旋圓。","勢束三峽挂，瀉危孤磴懸。","曾聞瑤池溜，亦灌朱草田。","鳧伯弄翠蘂，鸞雛舞丹煙。","凌風捩桂柂，隔霧馳犀船。","況當玄元家，嘗著道德篇。","上善可比水，斯文參五千。","精靈若在此，肯惡微波傳。","不擬爭滴瀝，還應會淪漣。","出門復飛箭，合勢浮青天。","必有學真子，鹿冠秋鶴顏。","如能輔余志，日使疏其源。"]', '["上嗣位六載，吾宗刺桐川。","余来拜旌戟，詔下之明年。","是时春三月，繞郭花蟬聯。","嵐盤百万髻，上插黄金鈿。","授以道士館，置榻於东偏。","满院声碧樹，空堂形老仙。","本性乐凝淡，及来更虛玄。","焚香禮真像，盥手披靈編。","新定山角角，烏龙独巉然。","除非淨晴日，不见蒼崖巔。","上有拏云峰，下有噴壑泉。","泉分數十汊，落处皆崢潺。","寒声入爛醉，聒破西窗眠。","支筇起独尋，祗在牆东邊。","呼童具畚鍤，立鑿莓苔穿。","灇淙一派墮，練带橫斜牽。","亂石拋落落，寒流响濺濺。","狂奴七里瀨，縮到疎楹前。","跳花潑半散，湧沫飞旋圓。","勢束三峽挂，瀉危孤磴懸。","曾闻瑤池溜，亦灌朱草田。","鳧伯弄翠蘂，鸾雛舞丹煙。","凌风捩桂柂，隔霧驰犀船。","況當玄元家，嘗著道德篇。","上善可比水，斯文參五千。","精靈若在此，肯惡微波傳。","不擬爭滴瀝，還應會淪漣。","出门复飞箭，合勢浮青天。","必有学真子，鹿冠秋鹤顏。","如能輔余志，日使疏其源。"]', '诗', 'shi', '', NULL, '引泉詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d88e80-b3f5-4ffc-9055-75a305294d73', '紀夢遊甘露寺', '紀梦游甘露寺', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["昔臥嵩高雲，雲窗正寒夕。","披裘忽生夢，似到空王宅。","峨天一峰立，欄楯橫半壁。","級倚綠巔差，關臨赤霄闢。","捫虛陟孤峭，不翅千餘尺。","疊掌望罘罳，分明袒肩釋。","凌香稽首罷，嘹嘵□□□。","高戶乘北風，聲號大波白。","光中目難送，定驗方可覿。","樹細鴻濛煙，島疎零落碧。","須臾羣籟入，空水相噴激。","積浪亞寒堆，呀如鬬危石。","跳音簇鞞鼓，濺沫交矛戟。","鳥疾帆亦奔，紛紛助勁敵。","思非水靈怒，即是飢龍擘。","怯懾不敢前，荷襟汗霑霢。","迴經定僧處，泉木光相射。","巖磴雲族栖，柖柯露華適。","逍遙得真趨，邐迤尋常跡。","山腹貯孤亭，嵐根四垂帟。","誰題雪月句，乃是曹劉格。","閬闕一枝瓊，邊樓數聲笛。","吟高矍然起，若自蒼旻擲。","短燭墮餘花，圓蟾挂斜魄。","自從神錫境，無處不登陟。","忽上南徐山，心期豁而獲。","豈伊煩惱骨，合到清涼域。","暗得胡蝶身，幽期盡相識。","奈何有名氏，未列金閨籍。","翻慙丱頂童，得奉真如策。","雲濤觸風望，毫管和煙搦。","聊記夢中遊，留之問禪客。"]', '["昔臥嵩高云，云窗正寒夕。","披裘忽生梦，似到空王宅。","峨天一峰立，欄楯橫半壁。","級倚綠巔差，关臨赤霄闢。","捫虛陟孤峭，不翅千餘尺。","叠掌望罘罳，分明袒肩釋。","凌香稽首罷，嘹嘵□□□。","高戶乘北风，声號大波白。","光中目难送，定驗方可覿。","樹細鴻濛煙，島疎零落碧。","須臾羣籟入，空水相噴激。","積浪亞寒堆，呀如鬬危石。","跳音簇鞞鼓，濺沫交矛戟。","鸟疾帆亦奔，紛紛助勁敵。","思非水靈怒，即是飢龙擘。","怯懾不敢前，荷襟汗霑霢。","迴經定僧处，泉木光相射。","巖磴云族栖，柖柯露华適。","逍遙得真趨，邐迤尋常跡。","山腹貯孤亭，嵐根四垂帟。","誰題雪月句，乃是曹劉格。","閬闕一枝瓊，邊楼數声笛。","吟高矍然起，若自蒼旻擲。","短燭墮餘花，圓蟾挂斜魄。","自從神錫境，無处不登陟。","忽上南徐山，心期豁而獲。","豈伊煩惱骨，合到清涼域。","暗得胡蝶身，幽期尽相識。","奈何有名氏，未列金閨籍。","翻慙丱頂童，得奉真如策。","云濤觸风望，毫管和煙搦。","聊記梦中游，留之问禪客。"]', '诗', 'shi', '', NULL, '紀夢遊甘露寺 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb66a1e-6d7c-4fc2-ab05-af191b0d110b', '惜花', '惜花', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["人壽期滿百，花開唯一春。","其間風雨至，旦夕旋爲塵。","若使花解愁，愁於看花人。"]', '["人壽期满百，花开唯一春。","其间风雨至，旦夕旋爲塵。","若使花解愁，愁於看花人。"]', '诗', 'shi', '', NULL, '惜花 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7885fc9a-d9f0-4e31-94f6-17008c393baa', '別離', '別離', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["丈夫非無淚，不灑離別間。","杖劒對尊酒，耻爲游子顏。","蝮蛇一螫手，壯士即解腕。","所志在功名，離別何足歎。"]', '["丈夫非無泪，不灑離別间。","杖劒对尊酒，耻爲游子顏。","蝮蛇一螫手，壯士即解腕。","所志在功名，離別何足歎。"]', '诗', 'shi', '', NULL, '別離 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04217a87-def6-4d3b-ade5-82d67c8ff185', '鳴雁行', '鳴雁行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朔風動地來，吹起沙上聲。","閨中有邊思，玉筯此時橫。","莫怕兒女恨，主人烹不鳴。"]', '["朔风动地来，吹起沙上声。","閨中有邊思，玉筯此时橫。","莫怕兒女恨，主人烹不鳴。"]', '诗', 'shi', '', NULL, '鳴雁行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48de0646-18f2-4d47-911d-acf2b114eb9d', '短歌行', '短歌行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["爪牙在身上，陷穽猶可制。","爪牙在胸中，劒戢無所畏。","人言畏猛虎，誰是撩頭弊。","祗見古來心，姦雄暗相噬。"]', '["爪牙在身上，陷穽猶可制。","爪牙在胸中，劒戢無所畏。","人言畏猛虎，誰是撩头弊。","祗见古来心，姦雄暗相噬。"]', '诗', 'shi', '', NULL, '短歌行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61c9833f-452a-40be-a006-61cfa24294a1', '挾瑟歌', '挾瑟歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["挾瑟爲君撫，君嫌聲太古。","寥寥倚浪系，㗫㗫沈湘語。","賴有秋風知，清泠吹玉柱。"]', '["挾瑟爲君撫，君嫌声太古。","寥寥倚浪系，㗫㗫沈湘語。","賴有秋风知，清泠吹玉柱。"]', '诗', 'shi', '', NULL, '挾瑟歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62461c87-1bbc-425b-8ac3-469205706146', '婕妤怨', '婕妤怨', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["妾貌非傾國，君王忽然寵。","南山掌上來，下敵新恩重。","後宮多窈窕，日日學新聲。","一落君王耳，南山又須輕。"]', '["妾貌非傾国，君王忽然寵。","南山掌上来，下敵新恩重。","後宮多窈窕，日日学新声。","一落君王耳，南山又須轻。"]', '诗', 'shi', '', NULL, '婕妤怨 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd983b0-d029-4a17-baf3-45c22fc54eec', '江南曲', '江南曲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["爲愛江南春，涉江聊采蘋。","水深煙浩浩，空對雙車輪。","車輪明月團，車蓋浮雲盤。","雲月徒自好，水中行路難。","遙遙洛陽道，夾道生春草。","寄語櫂船郎，莫誇風浪好。"]', '["爲愛江南春，涉江聊采蘋。","水深煙浩浩，空对雙车輪。","车輪明月團，车蓋浮云盤。","云月徒自好，水中行路难。","遙遙洛陽道，夾道生春草。","寄語櫂船郎，莫誇风浪好。"]', '诗', 'shi', '', NULL, '江南曲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81295de7-b833-4f4d-8cb0-e172990a4b59', '漁具詩 網', '漁具诗 網', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["大罟綱目繁，空江波浪黑。","沈沈到波底，恰共波同色。","牽時萬鬐入，已有千鈞力。","尚悔不橫流，恐他人更得。"]', '["大罟綱目繁，空江波浪黑。","沈沈到波底，恰共波同色。","牽时万鬐入，已有千鈞力。","尚悔不橫流，恐他人更得。"]', '诗', 'shi', '', NULL, '漁具詩 網 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9d77d14-6fac-40cc-9295-4baaba20d939', '漁具詩 罩', '漁具诗 罩', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["左手揭圓罛，輕橈弄舟子。","不知潛鱗處，但去籠煙水。","時穿紫屏破，忽值朱衣起。","貴得不貴名，敢論魴與鯉。"]', '["左手揭圓罛，轻橈弄舟子。","不知潛鱗处，但去籠煙水。","时穿紫屏破，忽值朱衣起。","貴得不貴名，敢論魴與鯉。"]', '诗', 'shi', '', NULL, '漁具詩 罩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debbda55-2f49-4a32-b593-36a6c1ad5baa', '漁具詩 𦊔', '漁具诗 𦊔', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["有意烹小鮮，乘流駐孤櫂。","雖然煩取舍，未肯求津要。","多爲蝦蜆誤，已分鵁鶄笑。","寄語龍伯人，荒唐不同調。"]', '["有意烹小鲜，乘流駐孤櫂。","雖然煩取舍，未肯求津要。","多爲蝦蜆誤，已分鵁鶄笑。","寄語龙伯人，荒唐不同調。"]', '诗', 'shi', '', NULL, '漁具詩 𦊔 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf9b5a8-c8ac-4912-b7d0-ee2508788f6c', '漁具詩 釣筒', '漁具诗 釣筒', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["短短截筠光，悠悠臥江色。","蓬差樐相應，雨慢煙交織。","須臾中芳餌，迅疾如飛翼。","彼竭我還浮，君看不爭得。"]', '["短短截筠光，悠悠臥江色。","蓬差樐相應，雨慢煙交织。","須臾中芳餌，迅疾如飞翼。","彼竭我還浮，君看不爭得。"]', '诗', 'shi', '', NULL, '漁具詩 釣筒 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60406526-f24f-4df0-977a-fed1ee7e6cee', '漁具詩 釣車', '漁具诗 釣车', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["溪上持隻輪，溪邊指茅屋。","閑乘風水便，敢議朱丹轂。","高多倚衡懼，下有折軸速。","曷若載逍遙，歸來臥雲族。"]', '["溪上持隻輪，溪邊指茅屋。","闲乘风水便，敢議朱丹轂。","高多倚衡懼，下有折軸速。","曷若載逍遙，归来臥云族。"]', '诗', 'shi', '', NULL, '漁具詩 釣車 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ed43a3f-7ffe-4d88-b89e-6a46debe57c1', '漁具詩 魚梁', '漁具诗 鱼梁', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["能編似雲薄，橫絕清川口。","缺處欲隨波，波中先置笱。","投身入籠檻，自古難飛走。","盡日水濱吟，殷勤謝漁叟。"]', '["能編似云薄，橫絕清川口。","缺处欲隨波，波中先置笱。","投身入籠檻，自古难飞走。","尽日水濱吟，殷勤謝漁叟。"]', '诗', 'shi', '', NULL, '漁具詩 魚梁 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7c7629-6d10-4a0c-a913-dd73de89b242', '漁具詩 叉魚', '漁具诗 叉鱼', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春溪正含綠，良夜才參半。","持矛若羽輕，列燭如星爛。","傷鱗跳密藻，碎首沈遙岸。","盡族染東流，傍人作佳翫。"]', '["春溪正含綠，良夜才參半。","持矛若羽轻，列燭如星爛。","傷鱗跳密藻，碎首沈遙岸。","尽族染东流，傍人作佳翫。"]', '诗', 'shi', '', NULL, '漁具詩 叉魚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2430e9-83db-48e2-adfa-a44d536b60e9', '漁具詩 射魚', '漁具诗 射鱼', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["彎弓注碧潯，掉尾行涼沚。","青楓下晚照，正在澄明裏。","抨弦斷荷扇，濺血殷菱蘂。","若使禽荒聞，移之暴煙水。"]', '["彎弓注碧潯，掉尾行涼沚。","青楓下晚照，正在澄明裏。","抨弦斷荷扇，濺血殷菱蘂。","若使禽荒闻，移之暴煙水。"]', '诗', 'shi', '', NULL, '漁具詩 射魚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4de9147-15ee-401c-a918-f6f5c65d5520', '漁具詩 鳴桹', '漁具诗 鳴桹', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水淺藻荇澀，[釣]罩無所及。","鏗如木鐸音，勢若金鉦急。","敺之就深處，用以資俯拾。","搜羅爾甚微，遁去將何入。"]', '["水淺藻荇澀，[釣]罩無所及。","鏗如木鐸音，勢若金鉦急。","敺之就深处，用以資俯拾。","搜羅爾甚微，遁去將何入。"]', '诗', 'shi', '', NULL, '漁具詩 鳴桹 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75af895-78e0-4198-95e9-183432f6d16d', '漁具詩 滬', '漁具诗 滬', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬植禦洪波，森然倒林薄。","千顱咽雲上，過半隨潮落。","其間風信背，更值雷聲惡。","天道亦裒多，吾將移海若。"]', '["万植禦洪波，森然倒林薄。","千顱咽云上，過半隨潮落。","其间风信背，更值雷声惡。","天道亦裒多，吾將移海若。"]', '诗', 'shi', '', NULL, '漁具詩 滬 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb52ff3d-9421-4d13-8136-17c86472de89', '漁具詩 𥶠', '漁具诗 𥶠', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["斬木置水中，枝條互相蔽。","寒魚遂家此，自以爲生計。","春冰忽融冶，盡取無遺裔。","所託成禍機，臨川一凝睇。"]', '["斬木置水中，枝條互相蔽。","寒鱼遂家此，自以爲生計。","春冰忽融冶，尽取無遺裔。","所託成禍機，臨川一凝睇。"]', '诗', 'shi', '', NULL, '漁具詩 𥶠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7168f21d-651a-49e1-b3e2-6d099a809de4', '漁具詩 種魚', '漁具诗 種鱼', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鑿池收赬鱗，疎疎置雲嶼。","還同汗漫遊，遂以江湖處。","如非一神守，潛被蛟龍主。","蛟龍若無道，跛鼈亦可禦。"]', '["鑿池收赬鱗，疎疎置云嶼。","還同汗漫游，遂以江湖处。","如非一神守，潛被蛟龙主。","蛟龙若無道，跛鼈亦可禦。"]', '诗', 'shi', '', NULL, '漁具詩 種魚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78cb1054-975b-4b4f-808e-b2ab7a83c8da', '漁具詩 藥魚', '漁具诗 藥鱼', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["香餌綴金鉤，日中懸者幾。","盈川是毒流，細大同時死。","不唯空飼犬，便可將貽蟻。","苟負竭澤心，其他盡如此。"]', '["香餌綴金鉤，日中懸者幾。","盈川是毒流，細大同时死。","不唯空飼犬，便可將貽蟻。","苟負竭澤心，其他尽如此。"]', '诗', 'shi', '', NULL, '漁具詩 藥魚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d206a9-cf78-4ed4-9851-b76eb4d5b846', '漁具詩 舴艋', '漁具诗 舴艋', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["篷櫂兩三事，天然相與閑。","朝隨穉子去，暮唱菱歌還。","倚石遲後侶，徐橈供遠山。","君看萬斛載，沈溺須臾間。"]', '["篷櫂兩三事，天然相與闲。","朝隨穉子去，暮唱菱歌還。","倚石遲後侶，徐橈供远山。","君看万斛載，沈溺須臾间。"]', '诗', 'shi', '', NULL, '漁具詩 舴艋 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('154d9034-7d18-4ded-95c7-992864161a5f', '漁具詩 笭箵', '漁具诗 笭箵', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰謂笭箵小，我謂笭箵大。","盛魚自足餐，寘璧能爲害。","時將刷蘋浪，又取懸藤帶。","不及腰上金，何勞問蓍蔡。"]', '["誰謂笭箵小，我謂笭箵大。","盛鱼自足餐，寘璧能爲害。","时將刷蘋浪，又取懸藤带。","不及腰上金，何勞问蓍蔡。"]', '诗', 'shi', '', NULL, '漁具詩 笭箵 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe786b0-ad26-469e-bdae-cb46162088cd', '奉和襲美添漁具五篇 漁菴', '奉和襲美添漁具五篇 漁菴', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["結茅次煙水，用以資嘯傲。","豈謂釣家流，忽同禪室號。","閑憑山叟占，晚有溪禽嫪。","華屋莫相非，各隨吾所好。"]', '["結茅次煙水，用以資嘯傲。","豈謂釣家流，忽同禪室號。","闲憑山叟占，晚有溪禽嫪。","华屋莫相非，各隨吾所好。"]', '诗', 'shi', '', NULL, '奉和襲美添漁具五篇 漁菴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460b6510-baf5-40a6-9687-15e2ba9654cf', '奉和襲美添漁具五篇 釣磯', '奉和襲美添漁具五篇 釣磯', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["揀得白雲根，秋潮未曾沒。","坡陁坐鼇背，散漫垂龍髪。","持竿從掩霧，置酒復待月。","即此放神情，何勞適吳越。"]', '["揀得白云根，秋潮未曾沒。","坡陁坐鼇背，散漫垂龙髪。","持竿從掩霧，置酒复待月。","即此放神情，何勞適吳越。"]', '诗', 'shi', '', NULL, '奉和襲美添漁具五篇 釣磯 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c206039-d6ce-44ba-8cf8-c04275459c36', '奉和襲美添漁具五篇 蓑衣', '奉和襲美添漁具五篇 蓑衣', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山前度微雨，不廢小澗漁。","上有青襏襫，下有新腒疎。","滴瀝珠影泫，離披嵐彩虛。","君看荷製者，不得安吾廬。"]', '["山前度微雨，不廢小澗漁。","上有青襏襫，下有新腒疎。","滴瀝珠影泫，離披嵐彩虛。","君看荷製者，不得安吾廬。"]', '诗', 'shi', '', NULL, '奉和襲美添漁具五篇 蓑衣 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb22119-688e-4175-9ad8-24a54153454b', '奉和襲美添漁具五篇 篛笠', '奉和襲美添漁具五篇 篛笠', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朝攜下楓浦，晚戴出煙艇。","冒雪或平簷，聽泉時仄頂。","飆移靄然色，波亂危如影。","不識九衢塵，終年居下泂。"]', '["朝携下楓浦，晚戴出煙艇。","冒雪或平簷，听泉时仄頂。","飆移靄然色，波亂危如影。","不識九衢塵，終年居下泂。"]', '诗', 'shi', '', NULL, '奉和襲美添漁具五篇 篛笠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e47a2a-f165-46f3-9087-5384dff721a8', '奉和襲美添漁具五篇 背蓬', '奉和襲美添漁具五篇 背蓬', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["敏手劈江筠，隨身織煙殼。","沙禽固不知，釣伴猶初覺。","閑從翠微拂，靜唱滄浪濯。","見說萬山潭，漁童盡能學。"]', '["敏手劈江筠，隨身织煙殼。","沙禽固不知，釣伴猶初覺。","闲從翠微拂，静唱滄浪濯。","见说万山潭，漁童尽能学。"]', '诗', 'shi', '', NULL, '奉和襲美添漁具五篇 背蓬 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0dd798-330d-46f6-863a-ae6326f56b46', '樵人十詠 樵谿', '樵人十詠 樵谿', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山高谿且深，蒼蒼但羣木。","抽條欲千尺，衆亦疑樸𣙙。","一朝蒙翦伐，萬古辭林麓。","若遇燎玄穹，微煙出雲族。"]', '["山高谿且深，蒼蒼但羣木。","抽條欲千尺，衆亦疑樸𣙙。","一朝蒙翦伐，万古辞林麓。","若遇燎玄穹，微煙出云族。"]', '诗', 'shi', '', NULL, '樵人十詠 樵谿 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6d7b3f4-bb62-420b-a90f-3903be7f10ca', '樵人十詠 樵家', '樵人十詠 樵家', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["草木黃落時，比鄰見相喜。","門當清澗盡，屋在寒雲裏。","山棚日纔下，野竈煙初起。","所謂順天民，唐堯亦如此。"]', '["草木黄落时，比鄰见相喜。","门當清澗尽，屋在寒云裏。","山棚日纔下，野竈煙初起。","所謂順天民，唐堯亦如此。"]', '诗', 'shi', '', NULL, '樵人十詠 樵家 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8688b69-461d-456b-bd6f-7436b0d04cff', '樵人十詠 樵叟', '樵人十詠 樵叟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["自小即胼胝，至今凋鬢髪。","所圖山褐厚，所愛山鑪熱。","不知冠蓋好，但信煙霞活。","富貴如疾顛，吾從老岩穴。"]', '["自小即胼胝，至今凋鬢髪。","所圖山褐厚，所愛山鑪熱。","不知冠蓋好，但信煙霞活。","富貴如疾顛，吾從老岩穴。"]', '诗', 'shi', '', NULL, '樵人十詠 樵叟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00aea0a5-3436-4402-9af0-2688cb86862d', '樵人十詠 樵子', '樵人十詠 樵子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["生自蒼崖邊，能諳白雲養。","纔穿遠林去，已在孤峰上。","薪和野花束，步帶山詞唱。","日暮不歸來，柴扉有人望。"]', '["生自蒼崖邊，能諳白云養。","纔穿远林去，已在孤峰上。","薪和野花束，步带山词唱。","日暮不归来，柴扉有人望。"]', '诗', 'shi', '', NULL, '樵人十詠 樵子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e5c8b7-da20-47b2-9346-7dc9b64f8e32', '樵人十詠 樵徑', '樵人十詠 樵徑', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["石脉青靄間，行行自幽絕。","方愁山繚繞，更值雲遮截。","爭推好林浪，共約歸時節。","不似名利途，相期覆車轍。"]', '["石脉青靄间，行行自幽絕。","方愁山繚繞，更值云遮截。","爭推好林浪，共約归时節。","不似名利途，相期覆车轍。"]', '诗', 'shi', '', NULL, '樵人十詠 樵徑 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a98992a3-bc33-4e14-b829-790822cb6d71', '樵人十詠 樵斧', '樵人十詠 樵斧', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["淬礪秋水清，攜持遠山曙。","丁丁在前澗，杳杳無尋處。","巢傾鳥猶在，樹盡猨方去。","授鉞者何人，吾今易其慮。"]', '["淬礪秋水清，携持远山曙。","丁丁在前澗，杳杳無尋处。","巢傾鸟猶在，樹尽猨方去。","授鉞者何人，吾今易其慮。"]', '诗', 'shi', '', NULL, '樵人十詠 樵斧 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c096dde-c0ed-42ac-be8c-22074bbe7b72', '樵人十詠 樵擔', '樵人十詠 樵擔', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["輕無斗儲價，重則筋力絕。","欲下半巖時，憂襟兩如結。","風高勢還却，雪厚疑中折。","負荷誠獨難，移之贈來哲。"]', '["轻無斗儲價，重則筋力絕。","欲下半巖时，憂襟兩如結。","风高勢還却，雪厚疑中折。","負荷誠独难，移之贈来哲。"]', '诗', 'shi', '', NULL, '樵人十詠 樵擔 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8cf2075-747b-403d-9585-9cee93b1eb09', '樵人十詠 樵風', '樵人十詠 樵风', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朝隨早潮去，暮帶殘陽返。","向背得清飆，相追無近遠。","採山一何遲，服道常苦蹇。","仙術信能爲，年華未將晚。"]', '["朝隨早潮去，暮带殘陽返。","向背得清飆，相追無近远。","採山一何遲，服道常苦蹇。","仙術信能爲，年华未將晚。"]', '诗', 'shi', '', NULL, '樵人十詠 樵風 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b4d480-ffc1-4ec1-bb07-318f36525998', '樵人十詠 樵火', '樵人十詠 樵火', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["積雪報松塢，蠹根然草堂。","深鑪與遠燒，此夜仍交光。","或似坐奇獸，或如焚異香。","堪嗟宦遊子，凍死道路傍。"]', '["積雪報松塢，蠹根然草堂。","深鑪與远燒，此夜仍交光。","或似坐奇獸，或如焚異香。","堪嗟宦游子，凍死道路傍。"]', '诗', 'shi', '', NULL, '樵人十詠 樵火 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ead8cd7-6e19-444a-979e-bce9cea25213', '樵人十詠 樵歌', '樵人十詠 樵歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["縱調爲野吟，徐徐下雲磴。","因知負樵樂，不減援琴興。","出林方自轉，隔水猶相應。","但取天壤情，何求郢人稱。"]', '["縱調爲野吟，徐徐下云磴。","因知負樵乐，不減援琴兴。","出林方自轉，隔水猶相應。","但取天壤情，何求郢人稱。"]', '诗', 'shi', '', NULL, '樵人十詠 樵歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177e65b6-6cdd-4cbc-b0e0-acebe17d879b', '奉和襲美酒中十詠 酒星', '奉和襲美酒中十詠 酒星', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬古醇酎氣，結而成晶熒。","降爲嵇阮徒，動與尊罍幷。","不獨祭天廟，亦應邀客星。","何當八月槎，載我遊青冥。"]', '["万古醇酎氣，結而成晶熒。","降爲嵇阮徒，动與尊罍幷。","不独祭天廟，亦應邀客星。","何當八月槎，載我游青冥。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒星 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3575d526-3618-4fe3-a57a-688c159435c7', '奉和襲美酒中十詠 酒泉', '奉和襲美酒中十詠 酒泉', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["初懸碧崖口，漸注青谿腹。","味既敵中山，飲寧拘一斛。","春疑浸花骨，暮若酣雲族。","此地得封侯，終身持美祿。"]', '["初懸碧崖口，漸注青谿腹。","味既敵中山，饮寧拘一斛。","春疑浸花骨，暮若酣云族。","此地得封侯，終身持美祿。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒泉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d76a16-2ae2-4ea2-92e7-82befdc74ac4', '奉和襲美酒中十詠 酒篘', '奉和襲美酒中十詠 酒篘', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山齋醞方熟，野童編近成。","持來歡伯內，坐使賢人清。","不待盎中滿，旋供花下傾。","汪汪日可挹，未羨黃金籯。"]', '["山斋醞方熟，野童編近成。","持来歡伯內，坐使賢人清。","不待盎中满，旋供花下傾。","汪汪日可挹，未羨黄金籯。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒篘 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11139fa-b500-42f8-8903-0c4251195b84', '奉和襲美酒中十詠 酒牀', '奉和襲美酒中十詠 酒牀', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["六尺樣何奇，溪邊濯來潔。","糟深貯方半，石重流還咽。","閑移秋病可，偶聽寒夢缺。","往往枕眠時，自疑陶靖節。"]', '["六尺樣何奇，溪邊濯来潔。","糟深貯方半，石重流還咽。","闲移秋病可，偶听寒梦缺。","往往枕眠时，自疑陶靖節。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒牀 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d21f850-0cfe-4328-a018-3b72bbc14226', '奉和襲美酒中十詠 酒壚', '奉和襲美酒中十詠 酒壚', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["錦里多佳人，當壚自沽酒。","高低過反坫，大小隨圓瓿。","數錢紅燭下，滌器春江口。","若得奉君歡，十千求一斗。"]', '["錦里多佳人，當壚自沽酒。","高低過反坫，大小隨圓瓿。","數錢紅燭下，滌器春江口。","若得奉君歡，十千求一斗。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒壚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8091b191-449d-4456-8840-ad514f3622b9', '奉和襲美酒中十詠 酒樓', '奉和襲美酒中十詠 酒楼', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["百尺江上起，東風吹酒香。","行人落帆上，遠樹涵殘陽。","凝睇復凝睇，一觴還一觴。","須知凭欄客，不醉難爲腸。"]', '["百尺江上起，东风吹酒香。","行人落帆上，远樹涵殘陽。","凝睇复凝睇，一觴還一觴。","須知凭欄客，不醉难爲腸。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒樓 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a353e4fe-4308-42ca-bd27-8df0a72266b3', '奉和襲美酒中十詠 酒旗', '奉和襲美酒中十詠 酒旗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["搖搖倚青岸，遠蕩遊人思。","風欹翠竹杠，雨澹香醪字。","纔來隔煙見，已覺臨江遲。","大斾非不榮，其如有王事。"]', '["搖搖倚青岸，远蕩游人思。","风欹翠竹杠，雨澹香醪字。","纔来隔煙见，已覺臨江遲。","大斾非不榮，其如有王事。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒旗 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a6752c-d954-47d4-a494-4bae4ed83ade', '奉和襲美酒中十詠 酒尊', '奉和襲美酒中十詠 酒尊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["黃金即爲侈，白石又太拙。","斲得奇樹根，中如老蛟穴。","時招山下叟，共酌林間月。","盡醉兩忘言，誰能作天舌。"]', '["黄金即爲侈，白石又太拙。","斲得奇樹根，中如老蛟穴。","时招山下叟，共酌林间月。","尽醉兩忘言，誰能作天舌。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒尊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa09077-3220-4fd4-aa0c-9568a0e23ecb', '奉和襲美酒中十詠 酒城', '奉和襲美酒中十詠 酒城', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["何代驅生靈，築之爲釀地。","殊無甲兵守，但有糟漿氣。","雉堞屹如狂，女牆低似醉。","必若據而爭，先登儀狄氏。"]', '["何代驱生靈，築之爲釀地。","殊無甲兵守，但有糟漿氣。","雉堞屹如狂，女牆低似醉。","必若據而爭，先登儀狄氏。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒城 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90bdeecd-8318-4bef-a295-dcf6df02b68d', '奉和襲美酒中十詠 酒鄉', '奉和襲美酒中十詠 酒乡', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰知此中路，暗出虛無際。","廣莫是鄰封，華胥爲附麗。","三杯聞古樂，伯雅逢遺裔。","自爾等榮枯，何勞問玄弟。"]', '["誰知此中路，暗出虛無際。","廣莫是鄰封，华胥爲附丽。","三杯闻古乐，伯雅逢遺裔。","自爾等榮枯，何勞问玄弟。"]', '诗', 'shi', '', NULL, '奉和襲美酒中十詠 酒鄉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39f42324-d398-4064-b60a-79a451be4d81', '添酒中六詠 酒池', '添酒中六詠 酒池', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬斛輸曲沼，千鍾未爲多。","殘霞入醍齊，遠岸澄白酇。","后土亦沈醉，姦臣空浩歌。","邇來荒淫君，尚得乘餘波。"]', '["万斛輸曲沼，千鍾未爲多。","殘霞入醍齊，远岸澄白酇。","后土亦沈醉，姦臣空浩歌。","邇来荒淫君，尚得乘餘波。"]', '诗', 'shi', '', NULL, '添酒中六詠 酒池 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee8265d-697c-45ef-a281-5b3ea95b89d6', '添酒中六詠 酒龍', '添酒中六詠 酒龙', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["銅雀羽儀麗，金龍光彩奇。","潛傾鄴宮酒，忽作商庭漦。","若怒鱗甲赤，如酣頭角垂。","君臣坐相滅，安用驕奢爲。"]', '["銅雀羽儀丽，金龙光彩奇。","潛傾鄴宮酒，忽作商庭漦。","若怒鱗甲赤，如酣头角垂。","君臣坐相滅，安用驕奢爲。"]', '诗', 'shi', '', NULL, '添酒中六詠 酒龍 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce49d04-05bf-47c7-a10c-643d57bdc54a', '添酒中六詠 酒甕', '添酒中六詠 酒甕', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["候煖麴糵調，覆深苫蓋淨。","溢處每淋漓，沈來還濎瀅。","常聞清涼酎，可養希夷性。","盜飲以爲名，得非君子病。"]', '["候煖麴糵調，覆深苫蓋淨。","溢处每淋漓，沈来還濎瀅。","常闻清涼酎，可養希夷性。","盜饮以爲名，得非君子病。"]', '诗', 'shi', '', NULL, '添酒中六詠 酒甕 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac14ca5b-707f-4239-9df8-3a7649647420', '添酒中六詠 酒船', '添酒中六詠 酒船', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["昔人性何誕，欲載無窮酒。","波上任浮身，風來即開口。","荒唐意難遂，沈湎名不朽。","千古如比肩，問君能繼不。"]', '["昔人性何誕，欲載無窮酒。","波上任浮身，风来即开口。","荒唐意难遂，沈湎名不朽。","千古如比肩，问君能繼不。"]', '诗', 'shi', '', NULL, '添酒中六詠 酒船 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba0ad7a-0251-44e9-9015-9a3edb296b17', '添酒中六詠 酒鎗', '添酒中六詠 酒鎗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["景山實名士，所玩垂清塵。","嘗作酒家語，自言中聖人。","奇器質含古，挫糟未應醇。","唯懷魏公子，即此飛觴頻。"]', '["景山實名士，所玩垂清塵。","嘗作酒家語，自言中聖人。","奇器質含古，挫糟未應醇。","唯懷魏公子，即此飞觴頻。"]', '诗', 'shi', '', NULL, '添酒中六詠 酒鎗 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8366d23-ac39-4970-be2a-f19463104aa0', '添酒中六詠 酒杯', '添酒中六詠 酒杯', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["叔夜傲天壤，不將琴酒疎。","製爲酒中物，恐是琴之餘。","一弄廣陵散，又裁絕交書。","頹然擲林下，身世俱何如。"]', '["叔夜傲天壤，不將琴酒疎。","製爲酒中物，恐是琴之餘。","一弄廣陵散，又裁絕交书。","頹然擲林下，身世俱何如。"]', '诗', 'shi', '', NULL, '添酒中六詠 酒杯 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094e8152-864b-40a0-8bef-3a2e368ef4fa', '奉和襲美茶具十詠 茶塢', '奉和襲美茶具十詠 茶塢', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["茗地曲隈回，野行多繚繞。","向陽就中密，背澗差還少。","遙盤雲髻慢，亂簇香篝小。","何處好幽期，滿巖春露曉。"]', '["茗地曲隈回，野行多繚繞。","向陽就中密，背澗差還少。","遙盤云髻慢，亂簇香篝小。","何处好幽期，满巖春露晓。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶塢 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d08f041-f1d6-4c56-bc37-f7ce711d1976', '奉和襲美茶具十詠 茶人', '奉和襲美茶具十詠 茶人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["天賦識靈草，自然鍾野姿。","閑來北山下，似與東風期。","雨後探芳去，雲間幽路危。","唯應報春鳥，得共斯人知。"]', '["天賦識靈草，自然鍾野姿。","闲来北山下，似與东风期。","雨後探芳去，云间幽路危。","唯應報春鸟，得共斯人知。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2aeb1a-e51f-4180-a8af-7281b8b267c1', '奉和襲美茶具十詠 茶筍', '奉和襲美茶具十詠 茶筍', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["所孕和氣深，時抽玉苕短。","輕煙漸結華，嫩蘂初成管。","尋來青靄曙，欲去紅雲煖。","秀色自難逢，傾筐不曾滿。"]', '["所孕和氣深，时抽玉苕短。","轻煙漸結华，嫩蘂初成管。","尋来青靄曙，欲去紅云煖。","秀色自难逢，傾筐不曾满。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶筍 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac53c59-6600-497b-b08c-84fac2d5b536', '奉和襲美茶具十詠 茶籯', '奉和襲美茶具十詠 茶籯', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["金刀劈翠筠，織似波文斜。","製作自野老，攜持伴山娃。","昨日鬬煙粒，今朝貯綠華。","爭歌調笑曲，日暮方還家。"]', '["金刀劈翠筠，织似波文斜。","製作自野老，携持伴山娃。","昨日鬬煙粒，今朝貯綠华。","爭歌調笑曲，日暮方還家。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶籯 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39f41c50-f6f9-48eb-8b34-ee81eef5048d', '奉和襲美茶具十詠 茶舍', '奉和襲美茶具十詠 茶舍', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["旋取山上材，架爲山下屋。","門因水勢斜，壁任巖隈曲。","朝隨鳥俱散，暮與雲同宿。","不憚採掇勞，祗憂官未足。"]', '["旋取山上材，架爲山下屋。","门因水勢斜，壁任巖隈曲。","朝隨鸟俱散，暮與云同宿。","不憚採掇勞，祗憂官未足。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶舍 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aef4ca3-512d-443f-81f6-6f7b0e6d98f3', '奉和襲美茶具十詠 茶竈', '奉和襲美茶具十詠 茶竈', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["無突抱輕嵐，有煙映初旭。","盈鍋玉泉沸，滿甑雲芽熟。","奇香襲春桂，嫩色凌秋菊。","煬者若吾徒，年年看不足。"]', '["無突抱轻嵐，有煙映初旭。","盈鍋玉泉沸，满甑云芽熟。","奇香襲春桂，嫩色凌秋菊。","煬者若吾徒，年年看不足。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶竈 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2c8f19-5499-476b-adf2-936795dd3218', '奉和襲美茶具十詠 茶焙', '奉和襲美茶具十詠 茶焙', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["左右擣凝膏，朝昏布煙縷。","方圓隨樣拍，次第依層取。","山謠縱高下，火候還文武。","見說焙前人，時時炙花脯。"]', '["左右擣凝膏，朝昏布煙縷。","方圓隨樣拍，次第依層取。","山謠縱高下，火候還文武。","见说焙前人，时时炙花脯。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶焙 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac95600-20cf-4836-ae71-673f804e8a0b', '奉和襲美茶具十詠 茶鼎', '奉和襲美茶具十詠 茶鼎', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["新泉氣味良，古鐵形狀醜。","那堪風雪夜，更值煙霞友。","曾過赬石下，又住清溪口。","且共薦臯盧，何勞傾斗酒。"]', '["新泉氣味良，古鐵形狀醜。","那堪风雪夜，更值煙霞友。","曾過赬石下，又住清溪口。","且共薦臯盧，何勞傾斗酒。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶鼎 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3d5abd-45ec-425a-9ded-a8bbc90a2641', '奉和襲美茶具十詠 茶甌', '奉和襲美茶具十詠 茶甌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["昔人謝塸埞，徒爲妍詞飾。","豈如珪璧姿，又有煙嵐色。","光參筠席上，韻雅金罍側。","直使于闐君，從來未嘗識。"]', '["昔人謝塸埞，徒爲妍词飾。","豈如珪璧姿，又有煙嵐色。","光參筠席上，韻雅金罍側。","直使于闐君，從来未嘗識。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 茶甌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e85e0d00-d945-494d-ac10-c77b2756adba', '奉和襲美茶具十詠 煮茶', '奉和襲美茶具十詠 煮茶', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["閑來松間坐，看煮松上雪。","時於浪花裏，併下藍英末。","傾餘精爽健，忽似氛埃滅。","不合別觀書，但宜窺玉札。"]', '["闲来松间坐，看煮松上雪。","时於浪花裏，併下藍英末。","傾餘精爽健，忽似氛埃滅。","不合別观书，但宜窺玉札。"]', '诗', 'shi', '', NULL, '奉和襲美茶具十詠 煮茶 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a526bb16-2274-4966-ab74-bcfca61e5559', '置酒行', '置酒行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["落塵花片排香痕，闌珊醉露栖愁魂。","洞庭波色惜不得，東風領入黃金尊。","千筠擲毫春譜大，碧舞紅啼相倡和。","安知寂寞西海頭，青𥳇未垂孤鳳餓。"]', '["落塵花片排香痕，闌珊醉露栖愁魂。","洞庭波色惜不得，东风領入黄金尊。","千筠擲毫春譜大，碧舞紅啼相倡和。","安知寂寞西海头，青𥳇未垂孤鳳餓。"]', '诗', 'shi', '', NULL, '置酒行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a252887-e6d7-4c41-a14d-7f4050d4a099', '江湖散人歌', '江湖散人歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江湖散人天骨奇，短髪搔來蓬半垂。","手提孤篁曳寒繭，口誦太古滄浪詞。","詞云太古萬萬古，民性甚野無風期。","夜棲止與禽獸雜，獨自構架縱橫枝。","因而稱曰有巢氏，民共敬貴如君師。","當時只效烏鵲輩，豈是有意陳尊卑。","無端後聖穿鑿破，一派前導千流隨。","多方惱亂元氣死，日使文字生姦欺。","聖人事業轉銷耗，尚有漁者存熙熙。","風波不獨困一士，凡百器具皆能施。","罛疎滬腐鱸鱖脫，止失檢馭無讒疵。","人間所謂好男子，我見婦女留鬚眉。","奴顏婢膝真乞丐，反以正直爲狂癡。","所以頭欲散，不散弁峩巍。","所以腰欲散，不散珮陸離。","行散任之適，坐散從傾欹。","語散空谷應，笑散春雲披。","衣散單複便，食散酸醎宜。","書散渾真草，酒散甘醇醨。","屋散勢斜直，樹散行參差。","客散忘簪屨，禽散虛籠池。","物外一以散，中心散何疑。","不共諸侯分邑里，不與天子專隍陴。","靜則守桑柘，亂則逃妻兒。","金鑣貝帶未嘗識，白刃殺我窮生爲。","或聞蕃將負恩澤，號令鐵馬如風馳。","大君年小丞相少，當軸自請都旌旗。","神鋒悉出羽林仗，繢畫日月蟠龍螭。","太宗基業甚牢固，小醜背叛當殲夷。","禁軍近自肅宗置，抑遏輔國爭雄雌。","必然大段剪兇逆，須召勁勇持軍麾。","四方賊壘猶占地，死者暴骨生寒飢。","歸來輙擬荷鋤笠，詬吏已責租錢遲。","興師十萬一日費，不啻千金何以支。","祗今利口且箕斂，何暇俛首哀惸嫠。","均荒補敗豈無術，布在方冊撐頹隵。","冰霜襦袴易反掌，白面諸郎殊不知。","江湖散人悲古道，悠悠幸寄羲皇傲。","官家未議活蒼生，拜賜江湖散人號。"]', '["江湖散人天骨奇，短髪搔来蓬半垂。","手提孤篁曳寒繭，口誦太古滄浪词。","词云太古万万古，民性甚野無风期。","夜棲止與禽獸杂，独自構架縱橫枝。","因而稱曰有巢氏，民共敬貴如君師。","當时只效烏鵲輩，豈是有意陳尊卑。","無端後聖穿鑿破，一派前導千流隨。","多方惱亂元氣死，日使文字生姦欺。","聖人事業轉銷耗，尚有漁者存熙熙。","风波不独困一士，凡百器具皆能施。","罛疎滬腐鱸鱖脫，止失檢馭無讒疵。","人间所謂好男子，我见婦女留鬚眉。","奴顏婢膝真乞丐，反以正直爲狂癡。","所以头欲散，不散弁峩巍。","所以腰欲散，不散珮陸離。","行散任之適，坐散從傾欹。","語散空谷應，笑散春云披。","衣散單複便，食散酸醎宜。","书散渾真草，酒散甘醇醨。","屋散勢斜直，樹散行參差。","客散忘簪屨，禽散虛籠池。","物外一以散，中心散何疑。","不共諸侯分邑里，不與天子專隍陴。","静則守桑柘，亂則逃妻兒。","金鑣貝带未嘗識，白刃殺我窮生爲。","或闻蕃將負恩澤，號令鐵马如风驰。","大君年小丞相少，當軸自請都旌旗。","神鋒悉出羽林仗，繢畫日月蟠龙螭。","太宗基業甚牢固，小醜背叛當殲夷。","禁軍近自肅宗置，抑遏輔国爭雄雌。","必然大段剪兇逆，須召勁勇持軍麾。","四方賊壘猶占地，死者暴骨生寒飢。","归来輙擬荷鋤笠，詬吏已責租錢遲。","兴師十万一日費，不啻千金何以支。","祗今利口且箕斂，何暇俛首哀惸嫠。","均荒補敗豈無術，布在方冊撐頹隵。","冰霜襦袴易反掌，白面諸郎殊不知。","江湖散人悲古道，悠悠幸寄羲皇傲。","官家未議活蒼生，拜賜江湖散人號。"]', '诗', 'shi', '', NULL, '江湖散人歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efa4111e-73c5-4d4a-8ea6-d970c9385562', '五歌 放牛', '五歌 放牛', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江草秋窮似秋半，十角吳牛放江岸。","鄰肩抵尾乍依隈，橫去斜奔忽分散。","荒陂斷塹無端入，背上時時孤鳥立。","日暮相將帶雨歸，田家煙火微茫濕。"]', '["江草秋窮似秋半，十角吳牛放江岸。","鄰肩抵尾乍依隈，橫去斜奔忽分散。","荒陂斷塹無端入，背上时时孤鸟立。","日暮相將带雨归，田家煙火微茫濕。"]', '诗', 'shi', '', NULL, '五歌 放牛 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cf054c-6fd0-4cb2-a37e-02ac722b9d89', '五歌 水鳥', '五歌 水鸟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水鳥山禽雖異名，天工各與雙翅翎。","雛巢吞啄即一例，游處高卑殊不停。","則有觜鈹爪戟勁立直眎者，擊搏挽裂圖羶腥。","如此等色恣豪橫，聳身往往凌青冥。","爲人羅絆取材力，韋韝綵綬懸金鈴。","三驅不以鳥捕鳥，矢下先得聞諸經。","超然可繼義勇後，恰似有志行天刑。","鷗閑鶴散兩自遂，意思不受人丁寧。","今朝櫂倚寒江汀，舂鉏翡翠參鵁鶄。","孤翹側睨瞥滅沒，未是即肯馴簷楹。","婦女衣襟便佞舌，始得金籠日提挈。","精神卓犖背人飛，冷抱蒹葭宿煙月。","我與時情大乖刺，祗是江禽有毛髪。","慇懃謝汝莫相猜，歸來長短同羣活。"]', '["水鸟山禽雖異名，天工各與雙翅翎。","雛巢吞啄即一例，游处高卑殊不停。","則有觜鈹爪戟勁立直眎者，擊搏挽裂圖羶腥。","如此等色恣豪橫，聳身往往凌青冥。","爲人羅絆取材力，韋韝綵綬懸金鈴。","三驱不以鸟捕鸟，矢下先得闻諸經。","超然可繼義勇後，恰似有志行天刑。","鷗闲鹤散兩自遂，意思不受人丁寧。","今朝櫂倚寒江汀，舂鉏翡翠參鵁鶄。","孤翹側睨瞥滅沒，未是即肯馴簷楹。","婦女衣襟便佞舌，始得金籠日提挈。","精神卓犖背人飞，冷抱蒹葭宿煙月。","我與时情大乖刺，祗是江禽有毛髪。","慇懃謝汝莫相猜，归来长短同羣活。"]', '诗', 'shi', '', NULL, '五歌 水鳥 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b82a916-fdb7-4132-9241-b61d520984c7', '五歌 刈穫', '五歌 刈穫', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["自春徂秋天弗雨，廉廉早稻纔遮畝。","芒粒稀疎熟更輕，地與禾頭不相拄。","我來愁築心如堵，更聽農夫夜深語。","凶年是物即爲災，百陣野鳧千穴鼠。","平明抱杖入田中，十穗蕭條九穗空。","敢言一歲囷倉實，不了如今朝暮舂。","天職誰司下民籍，苟有區區宜㭊㭊。","本作耕耘意若何，蟲豸兼教食人食。","古者爲邦須蓄積，魯饑尚責如齊糴。","今之爲政異當時，一任流離恣徵索。","平生幸遇華陽客，向日餐霞轉肥白。","欲賣耕牛棄水田，移家且傍三茅宅。"]', '["自春徂秋天弗雨，廉廉早稻纔遮畝。","芒粒稀疎熟更轻，地與禾头不相拄。","我来愁築心如堵，更听農夫夜深語。","凶年是物即爲災，百陣野鳧千穴鼠。","平明抱杖入田中，十穗蕭條九穗空。","敢言一歲囷倉實，不了如今朝暮舂。","天職誰司下民籍，苟有區區宜㭊㭊。","本作耕耘意若何，蟲豸兼教食人食。","古者爲邦須蓄積，魯饑尚責如齊糴。","今之爲政異當时，一任流離恣徵索。","平生幸遇华陽客，向日餐霞轉肥白。","欲賣耕牛棄水田，移家且傍三茅宅。"]', '诗', 'shi', '', NULL, '五歌 刈穫 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0918d722-8bc2-4a3d-b288-c5880b5d4691', '五歌 雨夜', '五歌 雨夜', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["屋小茅乾雨聲大，自疑身著蓑衣臥。","兼似孤舟小泊時，風吹折葦來相佐。","我有愁襟無可那，纔成好夢剛驚破。","背壁殘燈不及螢，重挑却向燈前坐。"]', '["屋小茅乾雨声大，自疑身著蓑衣臥。","兼似孤舟小泊时，风吹折葦来相佐。","我有愁襟無可那，纔成好梦剛驚破。","背壁殘灯不及螢，重挑却向灯前坐。"]', '诗', 'shi', '', NULL, '五歌 雨夜 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200abdc2-254b-48b2-8496-5b975c2e2e86', '五歌 食魚', '五歌 食鱼', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江南春旱魚無澤，歲晏未曾腥鼎鬲。","今朝有客賣鱸魴，手提見我長於尺。","呼兒舂取紅蓮米，輕重相當加十倍。","且作吳羹助早餐，飽臥晴簷曝寒背。","橫戈負羽正紛紛，祗用驍雄不用文。","爭如曉夕謳吟樣，好伴滄洲白鳥羣。"]', '["江南春旱鱼無澤，歲晏未曾腥鼎鬲。","今朝有客賣鱸魴，手提见我长於尺。","呼兒舂取紅蓮米，轻重相當加十倍。","且作吳羹助早餐，飽臥晴簷曝寒背。","橫戈負羽正紛紛，祗用驍雄不用文。","爭如晓夕謳吟樣，好伴滄洲白鸟羣。"]', '诗', 'shi', '', NULL, '五歌 食魚 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e1d557-b65a-4829-996e-7015c74aa9ed', '丁隱君歌', '丁隐君歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["華陽道士南遊歸，手中半卷青蘿衣。","自言逋客持贈我，乃是錢搪丁翰之。","連江大抵多奇岫，獨話君家最奇秀。","盤燒天竺春筍肥，琴倚洞庭秋石瘦。","草堂暗引龍泓溜，老樹根株若蹲獸。","霜濃果熟未容收，往往兒童雜猨狖。","去歲猖狂有黃寇，官軍解散無人鬬。","滿城奔迸翰之閑，只把枯松塞圭竇。","前度相逢正賣文，一錢不直虛云云。","今來利作採樵客，可以拋身麋鹿羣。","丁隱君，丁隱君，叩頭且莫變名氏，即日更尋丁隱君。"]', '["华陽道士南游归，手中半卷青蘿衣。","自言逋客持贈我，乃是錢搪丁翰之。","連江大抵多奇岫，独話君家最奇秀。","盤燒天竺春筍肥，琴倚洞庭秋石瘦。","草堂暗引龙泓溜，老樹根株若蹲獸。","霜濃果熟未容收，往往兒童杂猨狖。","去歲猖狂有黄寇，官軍解散無人鬬。","满城奔迸翰之闲，只把枯松塞圭竇。","前度相逢正賣文，一錢不直虛云云。","今来利作採樵客，可以拋身麋鹿羣。","丁隐君，丁隐君，叩头且莫变名氏，即日更尋丁隐君。"]', '诗', 'shi', '', NULL, '丁隱君歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78761f91-dc8a-4ae9-8810-5daf2304cf05', '紫溪翁歌', '紫溪翁歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一丘之木，其棲深也屋，吾容不辱。","一溪之石，其居平也席，吾勞以息。","一竇之泉，其音清也弦，吾方在懸。","得乎人，得乎天，吾不知所以然而然。"]', '["一丘之木，其棲深也屋，吾容不辱。","一溪之石，其居平也席，吾勞以息。","一竇之泉，其音清也弦，吾方在懸。","得乎人，得乎天，吾不知所以然而然。"]', '诗', 'shi', '', NULL, '紫溪翁歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbaa025f-cbda-47fb-baa4-00acf6cbd275', '賡歌', '賡歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["采江之魚兮，朝船有鱸。","采江之蔬兮，暮筐有蒲。","左圖且書，右琴與壺。","壽歟夭歟，貴歟賤歟。"]', '["采江之鱼兮，朝船有鱸。","采江之蔬兮，暮筐有蒲。","左圖且书，右琴與壺。","壽歟夭歟，貴歟賤歟。"]', '诗', 'shi', '', NULL, '賡歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e9bd87-2d5d-4594-a292-91849fc4703d', '鶴媒歌', '鹤媒歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["偶繫漁舟汀樹枝，因看射鳥令人悲。","盤空野鶴忽然下，背翳見媒心不疑。","媒閑靜立如無事，清唳時時入遙吹。","裴回未忍過南塘，且應同聲就同類。","梳翎宛若相逢喜，祗怕纔來又驚起。","窺鱗啄藻乍低昂，立定當胸流一矢。","媒歡舞躍勢離披，似諂功能邀弩兒。","雲飛水宿各自物，妬侶害羣猶爾爲。","而況世間有名利，外頭笑語中猜忌。","君不見荒陂野鶴陷良媒，同類同聲真可畏。"]', '["偶繫漁舟汀樹枝，因看射鸟令人悲。","盤空野鹤忽然下，背翳见媒心不疑。","媒闲静立如無事，清唳时时入遙吹。","裴回未忍過南塘，且應同声就同類。","梳翎宛若相逢喜，祗怕纔来又驚起。","窺鱗啄藻乍低昂，立定當胸流一矢。","媒歡舞躍勢離披，似諂功能邀弩兒。","云飞水宿各自物，妬侶害羣猶爾爲。","而況世间有名利，外头笑語中猜忌。","君不见荒陂野鹤陷良媒，同類同声真可畏。"]', '诗', 'shi', '', NULL, '鶴媒歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf63533-4fe0-46a6-982f-ed945ef9bc7b', '慶封宅古井行', '慶封宅古井行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["古甓團團蘚花碧，鼎渫寒泉深百尺。","江南戴白盡能言，此地曾爲慶封宅。","慶封嗜酒荒齊政，齊人剪族封奔迸。","雖過魯國羞魯儒，欲弄吳民竊吳柄。","吳分巖邑號朱方，子家負固心彊梁。","澤車豪馬馳似水，錦鳳玉龍森若牆。","一朝雲夢圍兵至，胸陷鋒鋩腦塗地。","因知富德不富財，顏氏簞瓢有深意。","宣父嘗違盜泉水，懦夫立事貪夫止。","今歌此井示吳人，斷綆沉瓶自茲始。"]', '["古甓團團蘚花碧，鼎渫寒泉深百尺。","江南戴白尽能言，此地曾爲慶封宅。","慶封嗜酒荒齊政，齊人剪族封奔迸。","雖過魯国羞魯儒，欲弄吳民竊吳柄。","吳分巖邑號朱方，子家負固心彊梁。","澤车豪马驰似水，錦鳳玉龙森若牆。","一朝云梦圍兵至，胸陷鋒鋩腦塗地。","因知富德不富財，顏氏簞瓢有深意。","宣父嘗違盜泉水，懦夫立事貪夫止。","今歌此井示吳人，斷綆沉瓶自茲始。"]', '诗', 'shi', '', NULL, '慶封宅古井行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cfb58cd-7d67-4789-b137-f709383031fc', '小雞山樵人歌', '小雞山樵人歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["長其船兮利其斧，輸予薪兮勿予侮。","田予登兮穀予庾，突晨煙兮蓬縷縷。","窗有明兮編有古，飽而安兮惟編是伍，時不用兮吾無汝撫。"]', '["长其船兮利其斧，輸予薪兮勿予侮。","田予登兮穀予庾，突晨煙兮蓬縷縷。","窗有明兮編有古，飽而安兮惟編是伍，时不用兮吾無汝撫。"]', '诗', 'shi', '', NULL, '小雞山樵人歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a2b832-5114-4dc7-ac24-ab678a02e61a', '吳俞兒舞歌 劒俞', '吳俞兒舞歌 劒俞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["枝月喉，櫂霜脊，北斗離離在寒碧。","龍魂清，虎尾白，秋照海心同一色。","纛影吒沙千影側，神豪髪直。","四睨之人股佶栗，欲定不定定不得。","舂牘殘，兒且止，狄胡有膽大如山，怖亦死。"]', '["枝月喉，櫂霜脊，北斗離離在寒碧。","龙魂清，虎尾白，秋照海心同一色。","纛影吒沙千影側，神豪髪直。","四睨之人股佶栗，欲定不定定不得。","舂牘殘，兒且止，狄胡有膽大如山，怖亦死。"]', '诗', 'shi', '', NULL, '吳俞兒舞歌 劒俞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06d3899-567d-4285-bd18-aabd8977a985', '吳俞兒舞歌 矛俞', '吳俞兒舞歌 矛俞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["手盤風，頭背分。","電光戰扇，欲刺敲心留半綫。","纏肩繞脰，𧞔合眩旋。","卓植赴列，奪避中節。","前衝函禮穴，上指孛彗滅，與君一用來有截。"]', '["手盤风，头背分。","電光戰扇，欲刺敲心留半綫。","纏肩繞脰，𧞔合眩旋。","卓植赴列，奪避中節。","前衝函禮穴，上指孛彗滅，與君一用来有截。"]', '诗', 'shi', '', NULL, '吳俞兒舞歌 矛俞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9594393c-6dc9-43b7-b8f1-7b895431b896', '吳俞兒舞歌 弩俞', '吳俞兒舞歌 弩俞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["牛來開弦，人爲置鏃。","捩機關，迸山谷。","鹿駭澀，隼擊遲。","析毫中睫，洞腋分龜。","達堅壘，殘雄師。","可以冠猛樂壯曲，抑揚蹈厲。","有裂犀兕之氣者，非公與。"]', '["牛来开弦，人爲置鏃。","捩機关，迸山谷。","鹿駭澀，隼擊遲。","析毫中睫，洞腋分龟。","達堅壘，殘雄師。","可以冠猛乐壯曲，抑揚蹈厲。","有裂犀兕之氣者，非公與。"]', '诗', 'shi', '', NULL, '吳俞兒舞歌 弩俞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3d4e82-aed6-40d0-a57b-e529905f26ef', '句曲山朝真詞二首 迎真', '句曲山朝真词二首 迎真', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["九華磬荅寒泉急，十絕幡搖翠微濕。","司命旍旌未下來，焚香抱簡凝神立。","殘星下照霓襟冷，缺月纔分鶴輪影。","空洞靈章發一聲，春來萬壑煙花醒。"]', '["九华磬荅寒泉急，十絕幡搖翠微濕。","司命旍旌未下来，焚香抱簡凝神立。","殘星下照霓襟冷，缺月纔分鹤輪影。","空洞靈章發一声，春来万壑煙花醒。"]', '诗', 'shi', '', NULL, '句曲山朝真詞二首 迎真 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7aa10e-e6ad-483f-98f2-94f5f2dc3aae', '句曲山朝真詞二首 送真', '句曲山朝真词二首 送真', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["縈雲鳳髻飄然解，玉鉞玄干儼先邁。","朝真弟子悄無言，再拜碧杯添沆瀣。","火{金靈}跳躍龍毛蓋，腦髪青青赮綷綷。","萬象銷沈一瞬間，空餘月外聞殘佩。"]', '["縈云鳳髻飄然解，玉鉞玄干儼先邁。","朝真弟子悄無言，再拜碧杯添沆瀣。","火{金靈}跳躍龙毛蓋，腦髪青青赮綷綷。","万象銷沈一瞬间，空餘月外闻殘佩。"]', '诗', 'shi', '', NULL, '句曲山朝真詞二首 送真 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949a318f-fa86-4f0b-8fb1-ada5bad20bc8', '戰秋辭', '戰秋辞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["八月空堂，前臨隙荒。","抽關散扇，晨烏未光。","左右物態，森疎強梁。","天隨子爽駴恂慄，恍軍庸之我當。","濠然而溝，壘然而牆。","纛然而桂，隊然而篁。","杉巉攢矛，蕉標建常。","槁艾矢束，矯蔓弦張。","蛙合助吹，鳥分啓行。","若革進而金止，固違陰而就陽。","無何，雲顏師，風旨伯，蒼茫慘澹，隳危摵劃。","煙蒙上焚，雨陣下棘。","如濠者注，如壘者闢，如纛者亞，如隊者析，如矛者折，如常者拆，如矢者仆，如弦者磔，如吹者瘖，如行者惕，石有髪兮盡纍，木有耳兮咸馘。","雲風雨煙，乘勝之勢驕。","杉篁蕉蔓，敗北之氣摵。","天隨子曰：吁！秋無神則已，如其有神，吾爲爾羞之。","南北畿圻，盜興五朞。","方州大都，虎節龍旗。","瓦解冰碎，瓜分豆離。","斧抵耋老，干穿乳兒。","昨宇今燼，朝人暮尸。","萬犢一啗，千倉一炊。","擾踐邊朔，殲傷蜑夷。","制質守帥，披攘城池。","弓弮不刓，甲綴不離。","兇渠歌笑，裂地無疑。","天有四序，秋爲司刑。","少昊負扆，親朝百靈。","蓐收相臣，太白將星。","可霾可電，可風可霆。","可塹溺顛陷，可夭札迷冥。","曾忘鏖剪，自意澄寧。","苟蜡禮之云責，觸天怒而誰丁。","奈何欺荒庭，凌壞砌，摋崇茝，批宿蕙。","揭編茅而逞力，斷緯蕭而作勢。","不過約弱欹垂，戕殘廢替。","可謂棄其本而趨其末，捨其大而從其細也。","辭猶未已，色若媿恥。","於是墮者止，偃者起。"]', '["八月空堂，前臨隙荒。","抽关散扇，晨烏未光。","左右物態，森疎強梁。","天隨子爽駴恂慄，恍軍庸之我當。","濠然而溝，壘然而牆。","纛然而桂，隊然而篁。","杉巉攢矛，蕉標建常。","槁艾矢束，矯蔓弦張。","蛙合助吹，鸟分啓行。","若革進而金止，固違陰而就陽。","無何，云顏師，风旨伯，蒼茫慘澹，隳危摵劃。","煙蒙上焚，雨陣下棘。","如濠者注，如壘者闢，如纛者亞，如隊者析，如矛者折，如常者拆，如矢者仆，如弦者磔，如吹者瘖，如行者惕，石有髪兮尽纍，木有耳兮咸馘。","云风雨煙，乘勝之勢驕。","杉篁蕉蔓，敗北之氣摵。","天隨子曰：吁！秋無神則已，如其有神，吾爲爾羞之。","南北畿圻，盜兴五朞。","方州大都，虎節龙旗。","瓦解冰碎，瓜分豆離。","斧抵耋老，干穿乳兒。","昨宇今燼，朝人暮尸。","万犢一啗，千倉一炊。","擾踐邊朔，殲傷蜑夷。","制質守帥，披攘城池。","弓弮不刓，甲綴不離。","兇渠歌笑，裂地無疑。","天有四序，秋爲司刑。","少昊負扆，親朝百靈。","蓐收相臣，太白將星。","可霾可電，可风可霆。","可塹溺顛陷，可夭札迷冥。","曾忘鏖剪，自意澄寧。","苟蜡禮之云責，觸天怒而誰丁。","奈何欺荒庭，凌壞砌，摋崇茝，批宿蕙。","揭編茅而逞力，斷緯蕭而作勢。","不過約弱欹垂，戕殘廢替。","可謂棄其本而趨其末，捨其大而從其細也。","辞猶未已，色若媿恥。","於是墮者止，偃者起。"]', '诗', 'shi', '', NULL, '戰秋辭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c692b37-a166-4fad-a9e5-15bdc3405975', '祝牛宮辭', '祝牛宮辞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["四牸三牯，中一去乳。","天霜降寒，納此室處。","老農拘拘，度地不畝。","東西幾何，七舉其武。","南北幾何，丈二加五。","偶楹當閑，載尺入土。","太歲在亥，餘不足數。","上締蓬茅，下遠官府。","耕耨以時，飲食得所。","或寢或臥，免風免雨。","宜爾子孫，實我倉庾。"]', '["四牸三牯，中一去乳。","天霜降寒，納此室处。","老農拘拘，度地不畝。","东西幾何，七舉其武。","南北幾何，丈二加五。","偶楹當闲，載尺入土。","太歲在亥，餘不足數。","上締蓬茅，下远官府。","耕耨以时，饮食得所。","或寢或臥，免风免雨。","宜爾子孫，實我倉庾。"]', '诗', 'shi', '', NULL, '祝牛宮辭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a8bf44-b319-4467-bbf3-42b70cc4cbcc', '迎潮送潮辭 迎潮', '迎潮送潮辞 迎潮', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江霜嚴兮楓葉丹，潮聲高兮墟落寒。","鷗巢卑兮漁箔短，遠岸沒兮光爛爛。","潮之德兮無際，既充其大兮又充其細。","密幽人兮欵柴門，寂寞流連兮依稀舊痕。","濡腴澤槁兮潮之恩，不尸其功兮歸於混元。"]', '["江霜嚴兮楓葉丹，潮声高兮墟落寒。","鷗巢卑兮漁箔短，远岸沒兮光爛爛。","潮之德兮無際，既充其大兮又充其細。","密幽人兮欵柴门，寂寞流連兮依稀旧痕。","濡腴澤槁兮潮之恩，不尸其功兮归於混元。"]', '诗', 'shi', '', NULL, '迎潮送潮辭 迎潮 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd461073-ba62-4320-acee-87365b1dd2e1', '迎潮送潮辭 送潮', '迎潮送潮辞 送潮', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["潮西來兮又東下，日染中流兮紅灑灑。","汀葭蒼兮嶼蓼枯，風騷牢兮愁煙孤。","大幾望兮微將晦翳，睨瀛溶兮斂然而退。","愛長波兮數數，一幅巾兮無纓可濯。","帆生塵兮檝有衣，悵潮之還兮吾猶未歸。"]', '["潮西来兮又东下，日染中流兮紅灑灑。","汀葭蒼兮嶼蓼枯，风騷牢兮愁煙孤。","大幾望兮微將晦翳，睨瀛溶兮斂然而退。","愛长波兮數數，一幅巾兮無纓可濯。","帆生塵兮檝有衣，悵潮之還兮吾猶未归。"]', '诗', 'shi', '', NULL, '迎潮送潮辭 送潮 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81876772-2380-492b-be1f-22e68976d9f8', '問吳宮辭', '问吳宮辞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["彼吳之宮兮江之郍涯，複道盤兮當高且斜。","波搖疏兮霧濛箔，菡萏國兮鴛鴦家。","鸞之簫兮蛟之瑟，駢筠參差兮界絲密。","讌曲房兮上初日，月落星稀兮歌酣未畢。","越山叢叢兮越溪疾，美人雄劒兮相先後出。","火姑蘇兮沼長洲，此宮之麗人兮留乎不留。","霜氛重兮孤榜曉，遠樹扶蘇兮愁煙悄眇。","欲摭愁煙兮問故基，又恐愁煙兮推白鳥。"]', '["彼吳之宮兮江之郍涯，複道盤兮當高且斜。","波搖疏兮霧濛箔，菡萏国兮鴛鴦家。","鸾之簫兮蛟之瑟，駢筠參差兮界絲密。","讌曲房兮上初日，月落星稀兮歌酣未畢。","越山叢叢兮越溪疾，美人雄劒兮相先後出。","火姑蘇兮沼长洲，此宮之丽人兮留乎不留。","霜氛重兮孤榜晓，远樹扶蘇兮愁煙悄眇。","欲摭愁煙兮问故基，又恐愁煙兮推白鸟。"]', '诗', 'shi', '', NULL, '問吳宮辭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9f361c9-9922-4527-a77b-3c221e618f48', '螢詩', '螢诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["肖翹雖振羽，戚促盡疑冰。","風助流還急，煙遮點漸凝。","不須輕列宿，纔可擬孤燈。","莫倚隋家事，曾煩下詔徵。"]', '["肖翹雖振羽，戚促尽疑冰。","风助流還急，煙遮点漸凝。","不須轻列宿，纔可擬孤灯。","莫倚隋家事，曾煩下詔徵。"]', '诗', 'shi', '', NULL, '螢詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8115dc0c-1669-4c12-b7e4-ee0c793dc411', '蟬', '蟬', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["祗憑風作使，全仰柳爲都。","一腹清何甚，雙翎薄更無。","伴貂金換酒，幷雀畫成圖。","恐是千年恨，偏令落日呼。"]', '["祗憑风作使，全仰柳爲都。","一腹清何甚，雙翎薄更無。","伴貂金換酒，幷雀畫成圖。","恐是千年恨，偏令落日呼。"]', '诗', 'shi', '', NULL, '蟬 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('980b31b0-9ced-4403-b8c8-2f9740da30c0', '秋熱', '秋熱', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["自惜秋捐扇，今來意未衰。","慇懃付柔握，淅瀝待清吹。","午氣朱崖近，宵聲白羽隨。","總如南國候，無復婕妤悲。"]', '["自惜秋捐扇，今来意未衰。","慇懃付柔握，淅瀝待清吹。","午氣朱崖近，宵声白羽隨。","總如南国候，無复婕妤悲。"]', '诗', 'shi', '', NULL, '秋熱 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a65189f-536c-4efc-9573-36e336f8ad34', '村中晚望', '村中晚望', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["抱杖柴門立，江村日易斜。","鴈寒猶憶侶，人病更離家。","短鬢看成雪，雙眸舊有花。","何須萬里外，即此是天涯。"]', '["抱杖柴门立，江村日易斜。","鴈寒猶憶侶，人病更離家。","短鬢看成雪，雙眸旧有花。","何須万里外，即此是天涯。"]', '诗', 'shi', '', NULL, '村中晚望 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb06c787-a424-4600-a546-a140dbfe2191', '四明山詩 石窗', '四明山诗 石窗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["石窗何處見，萬仞倚晴虛。","積靄迷青璅，殘霞動綺疏。","山應列圓嶠，宮便接方諸。","祗有三奔客，時來教隱書。"]', '["石窗何处见，万仞倚晴虛。","積靄迷青璅，殘霞动綺疏。","山應列圓嶠，宮便接方諸。","祗有三奔客，时来教隐书。"]', '诗', 'shi', '', NULL, '四明山詩 石窗 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('341cf4a4-ff3c-42d4-85d9-a0a670f3e271', '四明山詩 過雲', '四明山诗 過云', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["相訪一程雲，雲深路僅分。","嘯臺隨日辨，樵斧帶風聞。","曉著衣全濕，寒衝酒不醺。","幾迴歸思靜，髣髴見蘇君。"]', '["相訪一程云，云深路僅分。","嘯台隨日辨，樵斧带风闻。","晓著衣全濕，寒衝酒不醺。","幾迴归思静，髣髴见蘇君。"]', '诗', 'shi', '', NULL, '四明山詩 過雲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea82da93-b4cd-4f6a-a240-8221d373a72d', '四明山詩 雲南', '四明山诗 云南', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雲南更有溪，丹礫盡無泥。","藥有巴賨賣，枝多越鳥啼。","夜清先月午，秋近少嵐迷。","若得山顏住，芝𥰭手自攜。"]', '["云南更有溪，丹礫尽無泥。","藥有巴賨賣，枝多越鸟啼。","夜清先月午，秋近少嵐迷。","若得山顏住，芝𥰭手自携。"]', '诗', 'shi', '', NULL, '四明山詩 雲南 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286906ac-00b2-4567-937e-ba5e5644b5e1', '四明山詩 雲北', '四明山诗 云北', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雲北是陽川，人家洞壑連。","壇當星斗下，樓拶翠微邊。","一半遙峰雨，三條古井煙。","金庭如有路，應到左神天。"]', '["云北是陽川，人家洞壑連。","壇當星斗下，楼拶翠微邊。","一半遙峰雨，三條古井煙。","金庭如有路，應到左神天。"]', '诗', 'shi', '', NULL, '四明山詩 雲北 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d71c826-2e14-43e8-8f93-e5ba34de594e', '四明山詩 鹿亭', '四明山诗 鹿亭', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鹿亭巖下置，時領白麛過。","草細眠應久，泉香飲自多。","認聲來月塢，尋跡到煙蘿。","早晚吞金液，騎將上絳河。"]', '["鹿亭巖下置，时領白麛過。","草細眠應久，泉香饮自多。","認声来月塢，尋跡到煙蘿。","早晚吞金液，騎將上絳河。"]', '诗', 'shi', '', NULL, '四明山詩 鹿亭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05cc5afb-1c3a-4942-804c-1149b79636f6', '四明山詩 樊榭', '四明山诗 樊榭', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["樊榭何年築，人應白日飛。","至今山客說，時駕玉麟歸。","乳蔕緣松嫩，芝臺出石微。","憑欄虛目斷，不見羽華衣。"]', '["樊榭何年築，人應白日飞。","至今山客说，时駕玉麟归。","乳蔕緣松嫩，芝台出石微。","憑欄虛目斷，不见羽华衣。"]', '诗', 'shi', '', NULL, '四明山詩 樊榭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edef742a-1fcd-49a4-bd51-4a0995fdfce1', '四明山詩 潺湲洞', '四明山诗 潺湲洞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["石淺洞門深，潺潺萬古音。","似吹雙羽管，如奏落霞琴。","倒穴漂龍沫，穿松濺鶴襟。","何人乘月弄，應作上清吟。"]', '["石淺洞门深，潺潺万古音。","似吹雙羽管，如奏落霞琴。","倒穴漂龙沫，穿松濺鹤襟。","何人乘月弄，應作上清吟。"]', '诗', 'shi', '', NULL, '四明山詩 潺湲洞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09976f10-91ee-4c4d-a663-eb8dfe0755b7', '四明山詩 青櫺子', '四明山诗 青櫺子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山實號青櫺，環岡次第生。","外形堅綠殼，中味敵璚英。","墮石樵兒拾，敲林宿鳥驚。","亦應仙吏守，時取薦層城。"]', '["山實號青櫺，环岡次第生。","外形堅綠殼，中味敵璚英。","墮石樵兒拾，敲林宿鸟驚。","亦應仙吏守，时取薦層城。"]', '诗', 'shi', '', NULL, '四明山詩 青櫺子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5320f946-4527-46f4-9688-028d6284a859', '四明山詩 鞠侯', '四明山诗 鞠侯', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["何事鞠侯名，先封在四明。","但爲連臂飲，不作斷腸聲。","野蔓垂纓細，寒泉佩玉清。","滿林遊宦子，誰爲作君卿。"]', '["何事鞠侯名，先封在四明。","但爲連臂饮，不作斷腸声。","野蔓垂纓細，寒泉佩玉清。","满林游宦子，誰爲作君卿。"]', '诗', 'shi', '', NULL, '四明山詩 鞠侯 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56af20a6-2789-425a-97ed-28a37552cc37', '奉和襲美贈魏處士五貺詩 五瀉舟', '奉和襲美贈魏处士五貺诗 五瀉舟', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["樣自桐川得，詞因隱地成。","好漁翁亦喜，新白鳥還驚。","沙際擁江沫，渡頭橫雨聲。","尚應嫌越相，遺禍不遺名。"]', '["樣自桐川得，词因隐地成。","好漁翁亦喜，新白鸟還驚。","沙際擁江沫，渡头橫雨声。","尚應嫌越相，遺禍不遺名。"]', '诗', 'shi', '', NULL, '奉和襲美贈魏處士五貺詩 五瀉舟 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35fd5ab8-af29-47f0-9e4c-cfb438197174', '奉和襲美贈魏處士五貺詩 華頂杖', '奉和襲美贈魏处士五貺诗 华頂杖', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["萬古陰崖雪，靈根不爲枯。","瘦於霜鶴脛，奇似黑龍鬚。","拄訪譚玄客，持看潑墨圖。","湖雲如有路，兼可到仙都。"]', '["万古陰崖雪，靈根不爲枯。","瘦於霜鹤脛，奇似黑龙鬚。","拄訪譚玄客，持看潑墨圖。","湖云如有路，兼可到仙都。"]', '诗', 'shi', '', NULL, '奉和襲美贈魏處士五貺詩 華頂杖 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d24f28-4a33-482c-a499-75c9be660fe0', '奉和襲美贈魏處士五貺詩 太湖硯', '奉和襲美贈魏处士五貺诗 太湖硯', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰截小秋灘，閑窺四緒寬。","繞爲千嶂遠，深置一潭寒。","坐久雲應出，詩成墨未乾。","不知新博物，何處擬重刊。"]', '["誰截小秋灘，闲窺四緒寬。","繞爲千嶂远，深置一潭寒。","坐久云應出，诗成墨未乾。","不知新博物，何处擬重刊。"]', '诗', 'shi', '', NULL, '奉和襲美贈魏處士五貺詩 太湖硯 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29579d48-f7ae-43e6-a27e-ed64fbcbd246', '奉和襲美贈魏處士五貺詩 烏龍養和', '奉和襲美贈魏处士五貺诗 烏龙養和', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["養和名字好，偏寄道情深。","所以親逋客，兼能助五禽。","倚肩滄海望，鉤膝白雲吟。","不是逍遙侶，誰知世外心。"]', '["養和名字好，偏寄道情深。","所以親逋客，兼能助五禽。","倚肩滄海望，鉤膝白云吟。","不是逍遙侶，誰知世外心。"]', '诗', 'shi', '', NULL, '奉和襲美贈魏處士五貺詩 烏龍養和 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c813b9b4-133e-4917-8057-7d3104635788', '奉和襲美贈魏處士五貺詩 訶陵尊', '奉和襲美贈魏处士五貺诗 訶陵尊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚骼匠成尊，猶殘海浪痕。","外堪欺玳瑁，中可酌崑崙。","水繞苔磯曲，山當草閣門。","此中醒復醉，何必問乾坤。"]', '["鱼骼匠成尊，猶殘海浪痕。","外堪欺玳瑁，中可酌崑崙。","水繞苔磯曲，山當草閣门。","此中醒复醉，何必问乾坤。"]', '诗', 'shi', '', NULL, '奉和襲美贈魏處士五貺詩 訶陵尊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbfe0efd-b325-42e2-8acf-1e9481292556', '奉酬襲美早春病中書事', '奉酬襲美早春病中书事', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["祗貪詩調苦，不計病容生。","我亦休文瘦，君能叔寶清。","藥須勤一服，春莫累多情。","欲入毘耶問，無人敵浄名。"]', '["祗貪诗調苦，不計病容生。","我亦休文瘦，君能叔寶清。","藥須勤一服，春莫累多情。","欲入毘耶问，無人敵浄名。"]', '诗', 'shi', '', NULL, '奉酬襲美早春病中書事 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648e367d-98fd-40cb-81bd-bd9053a6e982', '又酬次韻', '又酬次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["從來多遠思，尤向靜中生。","所以令心苦，還應是骨清。","酒香偏入夢，花落又關情。","積此風流事，爭無後世名。"]', '["從来多远思，尤向静中生。","所以令心苦，還應是骨清。","酒香偏入梦，花落又关情。","積此风流事，爭無後世名。"]', '诗', 'shi', '', NULL, '又酬次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa5747e1-1858-4a46-b497-cbafc0ad1a60', '奉酬襲美秋晚見題二首 一', '奉酬襲美秋晚见題二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["爲愛晚窗明，門前亦嬾行。","圖書看得熟，鄰里見還生。","鳥啄琴材響，僧傳藥味精。","緣君多古思，攜手上空城。"]', '["爲愛晚窗明，门前亦嬾行。","圖书看得熟，鄰里见還生。","鸟啄琴材响，僧傳藥味精。","緣君多古思，携手上空城。"]', '诗', 'shi', '', NULL, '奉酬襲美秋晚見題二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30293bd1-f00d-432a-b438-dd74b2e73291', '奉酬襲美秋晚見題二首 二', '奉酬襲美秋晚见題二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["何事樂漁樵，巾車或倚橈。","和詩盈古篋，賒酒半寒瓢。","失雨園蔬赤，無風蚛葉彫。","清言一相遺，吾道未全消。"]', '["何事乐漁樵，巾车或倚橈。","和诗盈古篋，賒酒半寒瓢。","失雨园蔬赤，無风蚛葉彫。","清言一相遺，吾道未全消。"]', '诗', 'shi', '', NULL, '奉酬襲美秋晚見題二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cfea701-9290-48cd-b138-1ebc137218bc', '奉和襲美初冬章上人院', '奉和襲美初冬章上人院', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["每伴來方丈，還如到四禪。","菊承荒砌露，茶待遠山泉。","畫古全無跡，林寒却有煙。","相看吟未竟，金磬已泠然。"]', '["每伴来方丈，還如到四禪。","菊承荒砌露，茶待远山泉。","畫古全無跡，林寒却有煙。","相看吟未竟，金磬已泠然。"]', '诗', 'shi', '', NULL, '奉和襲美初冬章上人院 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a99ea4f7-ac36-4f00-acaf-8b358fccb61c', '襲美見題郊居十首因次韻酬之以伸榮謝 一', '襲美见題郊居十首因次韻酬之以伸榮謝 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["近來唯樂靜，移傍故城居。","閑打修琴料，時封謝藥書。","夜停江上鳥，晴曬篋中魚。","出亦圖何事，無勞置棧車。"]', '["近来唯乐静，移傍故城居。","闲打修琴料，时封謝藥书。","夜停江上鸟，晴曬篋中鱼。","出亦圖何事，無勞置棧车。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d54911-b851-4bfa-a8a8-3bccb95eba2b', '襲美見題郊居十首因次韻酬之以伸榮謝 二', '襲美见題郊居十首因次韻酬之以伸榮謝 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["倩人醫病樹，看僕補衡茅。","散髪還同阮，無心敢慕巢。","簡便書露竹，尊待破霜匏。","日好林間坐，煙蘿近欲交。"]', '["倩人醫病樹，看僕補衡茅。","散髪還同阮，無心敢慕巢。","簡便书露竹，尊待破霜匏。","日好林间坐，煙蘿近欲交。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1694aa-4e82-49e1-bfa4-834ca62023a4', '襲美見題郊居十首因次韻酬之以伸榮謝 三', '襲美见題郊居十首因次韻酬之以伸榮謝 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["倭僧留海紙，山匠製雲牀。","嬾外應無敵，貧中直是王。","池平鷗思喜，花盡蝶情忙。","欲問新秋計，菱絲一畝強。"]', '["倭僧留海紙，山匠製云牀。","嬾外應無敵，貧中直是王。","池平鷗思喜，花尽蝶情忙。","欲问新秋計，菱絲一畝強。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b088cb-0760-406e-ad25-12aac4d5d646', '襲美見題郊居十首因次韻酬之以伸榮謝 四', '襲美见題郊居十首因次韻酬之以伸榮謝 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["故山空自擲，當路竟誰知。","祗有經時策，全無養拙資。","病深憐灸客，炊晚信樵兒。","謾欲陳風俗，周官未採詩。"]', '["故山空自擲，當路竟誰知。","祗有經时策，全無養拙資。","病深怜灸客，炊晚信樵兒。","謾欲陳风俗，周官未採诗。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57e63595-354e-4518-aedb-3199dc5de124', '襲美見題郊居十首因次韻酬之以伸榮謝 五', '襲美见題郊居十首因次韻酬之以伸榮謝 五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["福地能容壍，玄關詎有扉。","靜思瓊版字，閑洗鐵筇衣。","鳥破涼煙下，人衝暮雨歸。","故園秋草夢，猶記綠微微。"]', '["福地能容壍，玄关詎有扉。","静思瓊版字，闲洗鐵筇衣。","鸟破涼煙下，人衝暮雨归。","故园秋草梦，猶記綠微微。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0acb4e-9b4f-487b-8f01-0a54ac38659d', '襲美見題郊居十首因次韻酬之以伸榮謝 六', '襲美见題郊居十首因次韻酬之以伸榮謝 六', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水影沈魚器，鄰聲動緯車。","燕輕捎墜葉，蜂嬾臥燋花。","說史評諸例，論兵到百家。","明時如不用，歸去種桑麻。"]', '["水影沈鱼器，鄰声动緯车。","燕轻捎墜葉，蜂嬾臥燋花。","说史評諸例，論兵到百家。","明时如不用，归去種桑麻。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 六 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9edd45e4-0dfa-4120-97a8-58996ce16fbd', '襲美見題郊居十首因次韻酬之以伸榮謝 七', '襲美见題郊居十首因次韻酬之以伸榮謝 七', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["禹穴奇編缺，雷平異境殘。","靜吟封籙檢，歸興削帆竿。","白石堪爲飯，青蘿好作冠。","幾時當斗柄，同上步罡壇。"]', '["禹穴奇編缺，雷平異境殘。","静吟封籙檢，归兴削帆竿。","白石堪爲飯，青蘿好作冠。","幾时當斗柄，同上步罡壇。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 七 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e738d519-b9d3-443a-bb92-bee9287dcfe0', '襲美見題郊居十首因次韻酬之以伸榮謝 八', '襲美见題郊居十首因次韻酬之以伸榮謝 八', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["強起披衣坐，徐行處暑天。","上階來鬬雀，移樹去驚蟬。","莫問鹽車駿，誰看醬瓿玄。","黃金如可化，相近買雲泉。"]', '["強起披衣坐，徐行处暑天。","上階来鬬雀，移樹去驚蟬。","莫问鹽车駿，誰看醬瓿玄。","黄金如可化，相近買云泉。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 八 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767e8df8-13e7-401e-8716-fa12ad99fb0e', '襲美見題郊居十首因次韻酬之以伸榮謝 九', '襲美见題郊居十首因次韻酬之以伸榮謝 九', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["野入青蕪巷，陂侵白竹門。","風高開栗刺，沙淺露芹根。","迸鼠緣藤桁，飢烏立石盆。","東吳雖不改，誰是武王孫。"]', '["野入青蕪巷，陂侵白竹门。","风高开栗刺，沙淺露芹根。","迸鼠緣藤桁，飢烏立石盆。","东吳雖不改，誰是武王孫。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 九 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af0eca6a-417b-4fec-b0f7-284820122e11', '襲美見題郊居十首因次韻酬之以伸榮謝 十', '襲美见題郊居十首因次韻酬之以伸榮謝 十', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["疎慵真有素，時勢盡無能。","風月雖爲敵，林泉幸未憎。","酒材經夏闕，詩債待秋徵。","祗有君同癖，閑來對曲肱。"]', '["疎慵真有素，时勢尽無能。","风月雖爲敵，林泉幸未憎。","酒材經夏闕，诗債待秋徵。","祗有君同癖，闲来对曲肱。"]', '诗', 'shi', '', NULL, '襲美見題郊居十首因次韻酬之以伸榮謝 十 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd6e645-170e-4363-8860-37f11f969b32', '和張廣文賁旅泊吳門次韻', '和張廣文賁旅泊吳门次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["高秋能叩觸，天籟忽成文。","苦調雖潛倚，靈音自絕羣。","茅峰曾醮斗，笠澤久眠雲。","許伴山中躅，三年任一醺。"]', '["高秋能叩觸，天籟忽成文。","苦調雖潛倚，靈音自絕羣。","茅峰曾醮斗，笠澤久眠云。","許伴山中躅，三年任一醺。"]', '诗', 'shi', '', NULL, '和張廣文賁旅泊吳門次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7410d1e-8595-45e8-a734-300391d89a35', '又次前韻酬廣文', '又次前韻酬廣文', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["獨倚秋光岸，風漪學簟文。","玄堪教鳳集，書好換鵝羣。","葉墮平臺月，香消古徑雲。","強歌非白紵，聊以送餘醺。"]', '["独倚秋光岸，风漪学簟文。","玄堪教鳳集，书好換鵝羣。","葉墮平台月，香消古徑云。","強歌非白紵，聊以送餘醺。"]', '诗', 'shi', '', NULL, '又次前韻酬廣文 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb12412d-2bbe-48d2-80e7-b3b05d196027', '送延陵張宰', '送延陵張宰', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春盡未離關，之官亦似閑。","不嫌請薄俸，爲喜帶名山。","默禱三真後，高吟十字還。","祗應江上鳥，時下訟庭間。"]', '["春尽未離关，之官亦似闲。","不嫌請薄俸，爲喜带名山。","默禱三真後，高吟十字還。","祗應江上鸟，时下訟庭间。"]', '诗', 'shi', '', NULL, '送延陵張宰 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087341a4-1c74-4e0c-b832-eddc91048a2c', '送人罷官歸茅山', '送人罷官归茅山', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["呼僮曉拂鞍，歸上大茅端。","薄俸雖休入，明霞自足餐。","暗霜松粒赤，疎雨草堂寒。","又鑿中峰石，重修醮月壇。"]', '["呼僮晓拂鞍，归上大茅端。","薄俸雖休入，明霞自足餐。","暗霜松粒赤，疎雨草堂寒。","又鑿中峰石，重修醮月壇。"]', '诗', 'shi', '', NULL, '送人罷官歸茅山 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed5bbbf-a7ea-428a-9f22-00773c5b57cc', '立春日', '立春日', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["去年花落時，題作送春詩。","自爲重相見，應無今日悲。","道孤逢識寡，身病買名遲。","一夜東風起，開簾不敢窺。"]', '["去年花落时，題作送春诗。","自爲重相见，應無今日悲。","道孤逢識寡，身病買名遲。","一夜东风起，开簾不敢窺。"]', '诗', 'shi', '', NULL, '立春日 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dcbff2b-29e8-4802-926c-6fee68446b8e', '中秋夜寄友生', '中秋夜寄友生', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["秋來一度滿，重見色難齊。","獨坐猶過午，同吟不到西。","疎芒唯斗在，殘白合河迷。","更憶前年望，孤舟泊大溪。"]', '["秋来一度满，重见色难齊。","独坐猶過午，同吟不到西。","疎芒唯斗在，殘白合河迷。","更憶前年望，孤舟泊大溪。"]', '诗', 'shi', '', NULL, '中秋夜寄友生 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd041c2-5765-4068-b3ee-07699c082d67', '奉和襲美古杉三十韻', '奉和襲美古杉三十韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["衆木盡相遺，孤芳獨任奇。","鍤天形硉兀，當殿勢𢼮危。","恐是夸娥怒，教臨嶻嶭衰。","節穿開耳目，根癭坐熊羆。","世只論榮落，人誰問等衰。","有巔從日上，無葉與秋欺。","虎搏應難動，鵰蹲不敢遲。","戰鋒新缺齾，燒岸黑𪑿黧。","鬬死龍骸雜，爭奔鹿角差。","肢銷洪水腦，稜聳梵天眉。","磔索珊瑚湧，森嚴獬豸窺。","向空分犖指，衝浪出鯨鬐。","楊僕船橦在，蚩尤陣纛隳。","下連金粟固，高用鐵菱披。","挺若苻堅棰，浮於祖納椎。","崢嶸驚露鶴，䟐趚閡雲螭。","傍宇將支壓，撐霄欲抵隵。","背交蟲臂挶，相向鶻拳追。","格筆差猶立，階干卓未麾。","鬼神應暗畫，風雨恐潛移。","已覺寒松伏，偏宜后土疲。","好邀清嘯傲，堪映古茅茨。","材大應容蝎，年深必孕夔。","後雕依佛氏，初植必僧彌。","擁腫煩莊辯，槎牙費庾詞。","詠多靈符困，搜苦化權卑。","類既區中寡，朋當物外推。","蟠桃標日域，珠草侍仙墀。","真宰誠求夢，春工幸可醫。","若能噓嶰竹，猶足動華滋。"]', '["衆木尽相遺，孤芳独任奇。","鍤天形硉兀，當殿勢𢼮危。","恐是夸娥怒，教臨嶻嶭衰。","節穿开耳目，根癭坐熊羆。","世只論榮落，人誰问等衰。","有巔從日上，無葉與秋欺。","虎搏應难动，鵰蹲不敢遲。","戰鋒新缺齾，燒岸黑𪑿黧。","鬬死龙骸杂，爭奔鹿角差。","肢銷洪水腦，稜聳梵天眉。","磔索珊瑚湧，森嚴獬豸窺。","向空分犖指，衝浪出鯨鬐。","楊僕船橦在，蚩尤陣纛隳。","下連金粟固，高用鐵菱披。","挺若苻堅棰，浮於祖納椎。","崢嶸驚露鹤，䟐趚閡云螭。","傍宇將支壓，撐霄欲抵隵。","背交蟲臂挶，相向鶻拳追。","格笔差猶立，階干卓未麾。","鬼神應暗畫，风雨恐潛移。","已覺寒松伏，偏宜后土疲。","好邀清嘯傲，堪映古茅茨。","材大應容蝎，年深必孕夔。","後雕依佛氏，初植必僧彌。","擁腫煩莊辯，槎牙費庾词。","詠多靈符困，搜苦化權卑。","類既區中寡，朋當物外推。","蟠桃標日域，珠草侍仙墀。","真宰誠求梦，春工幸可醫。","若能噓嶰竹，猶足动华滋。"]', '诗', 'shi', '', NULL, '奉和襲美古杉三十韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8647dc9e-1f83-4b73-8ae9-8ab0bd38ef86', '奉和襲美新秋言懷三十韻次韻', '奉和襲美新秋言懷三十韻次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["身閑唯愛靜，籬外是荒郊。","地僻憐同巷，庭喧厭累巢。","岸聲搖舴艋，窗影辨蠨蛸。","徑祗溪禽下，關唯野客敲。","竹岡從古凸，池緣本來䫜。","早藕擎霜節，涼花束紫梢。","漁情隨錘網，獵興起鳴𩩉。","好夢經年說，名方著處抄。","才疎惟自補，技癢欲誰抓。","窗靜常懸䕹，鞭閑不正鞘。","山衣輕斧藻，天籟逸弦匏。","蕙轉風前帶，桃烘雨後膠。","蘚乾黏晚砌，煙濕動晨庖。","沈約便圖籍，揚雄重酒肴。","目曾窺絕洞，耳不犯征鐃。","曆外窮飛朔，蓍中記伏爻。","石林空寂歷，雲肆肯嘵譊。","松桂何妨蠹，龜龍亦任嘲。","未能丹作髓，誰相紫爲胞。","莫把榮枯異，但和大小包。","由弓猨不捷，梁圈虎忘虓。","舊友懷三益，關山阻二崤。","道隨書簏古，時共釣輪拋。","好作忘機士，須爲莫逆交。","看君馳諫草，憐我臥衡茅。","出處雖冥默，薰蕕肯溷殽。","岸沙從鶴印，崖蜜勸人𦾱。","白菌盈枯枿，黃精滿綠筲。","仙因隱居信，禪是淨名教。","勿謂江湖永，終浮一大瓟。"]', '["身闲唯愛静，籬外是荒郊。","地僻怜同巷，庭喧厭累巢。","岸声搖舴艋，窗影辨蠨蛸。","徑祗溪禽下，关唯野客敲。","竹岡從古凸，池緣本来䫜。","早藕擎霜節，涼花束紫梢。","漁情隨錘網，獵兴起鳴𩩉。","好梦經年说，名方著处抄。","才疎惟自補，技癢欲誰抓。","窗静常懸䕹，鞭闲不正鞘。","山衣轻斧藻，天籟逸弦匏。","蕙轉风前带，桃烘雨後膠。","蘚乾黏晚砌，煙濕动晨庖。","沈約便圖籍，揚雄重酒肴。","目曾窺絕洞，耳不犯征鐃。","曆外窮飞朔，蓍中記伏爻。","石林空寂歷，云肆肯嘵譊。","松桂何妨蠹，龟龙亦任嘲。","未能丹作髓，誰相紫爲胞。","莫把榮枯異，但和大小包。","由弓猨不捷，梁圈虎忘虓。","旧友懷三益，关山阻二崤。","道隨书簏古，时共釣輪拋。","好作忘機士，須爲莫逆交。","看君驰諫草，怜我臥衡茅。","出处雖冥默，薰蕕肯溷殽。","岸沙從鹤印，崖蜜勸人𦾱。","白菌盈枯枿，黄精满綠筲。","仙因隐居信，禪是淨名教。","勿謂江湖永，終浮一大瓟。"]', '诗', 'shi', '', NULL, '奉和襲美新秋言懷三十韻次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a48118-a069-45c2-b41a-bd8c7f58e9c5', '和襲美江南書情二十韻寄祕閣韋校書貽之商洛宋先輩垂文二同年次韻', '和襲美江南书情二十韻寄祕閣韋校书貽之商洛宋先輩垂文二同年次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["我志如魚樂，君詞稱鳳銜。","暫來從露冕，何事買雲巖。","水石應容病，松篁未聽讒。","罐香松蠹膩，山信藥苗緘。","愛鷺欹危立，思猨矍鑠獑。","謝才偏許朓，阮放最憐咸。","大樂寧忘缶，奇工肯顧瑊。","客愁迷舊隱，鷹健想秋毚。","硯缺猶慵琢，文繁却要芟。","雨餘幽沼淨，霞散遠峰巉。","洗筆煙成段，培花土作杴。","訪僧還覓伴，醫鶴自須監。","荒廟猶懷季，清灘幾夢嚴。","背風開蠹簡，衝浪試新帆。","悶憶年支酒，閑裁古樣衫。","釣家隨野舫，仙蘊逐雕函。","度歲賒羸馬，先春買小𧍧。","共疏泉入竹，同坐月過杉。","染翰窮高致，懷賢發至諴。","不堪潘子鬢，愁促易髟髟。"]', '["我志如鱼乐，君词稱鳳銜。","暫来從露冕，何事買云巖。","水石應容病，松篁未听讒。","罐香松蠹膩，山信藥苗緘。","愛鷺欹危立，思猨矍鑠獑。","謝才偏許朓，阮放最怜咸。","大乐寧忘缶，奇工肯顧瑊。","客愁迷旧隐，鷹健想秋毚。","硯缺猶慵琢，文繁却要芟。","雨餘幽沼淨，霞散远峰巉。","洗笔煙成段，培花土作杴。","訪僧還覓伴，醫鹤自須監。","荒廟猶懷季，清灘幾梦嚴。","背风开蠹簡，衝浪試新帆。","悶憶年支酒，闲裁古樣衫。","釣家隨野舫，仙蘊逐雕函。","度歲賒羸马，先春買小𧍧。","共疏泉入竹，同坐月過杉。","染翰窮高致，懷賢發至諴。","不堪潘子鬢，愁促易髟髟。"]', '诗', 'shi', '', NULL, '和襲美江南書情二十韻寄祕閣韋校書貽之商洛宋先輩垂文二同年次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbfa56d2-f2b4-4363-854a-7affc2f17546', '憶襲美洞庭觀步奉和次韻', '憶襲美洞庭观步奉和次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["聞君遊靜境，雅具更摐摐。","竹傘遮雲徑，藤鞋踏蘚矼。","杖斑花不一，尊大癭成雙。","水鳥行沙嶼，山僧禮石幢。","已甘三秀味，誰念百牢腔。","遠棹投何處，殘陽到幾窗。","仙謠珠樹曲，村餉白醅[缸]。","地里方吳會，人風似冉厖。","探幽非遯世，尋勝肯迷邦。","爲讀江南傳，何賢過二龐。"]', '["闻君游静境，雅具更摐摐。","竹傘遮云徑，藤鞋踏蘚矼。","杖斑花不一，尊大癭成雙。","水鸟行沙嶼，山僧禮石幢。","已甘三秀味，誰念百牢腔。","远棹投何处，殘陽到幾窗。","仙謠珠樹曲，村餉白醅[缸]。","地里方吳會，人风似冉厖。","探幽非遯世，尋勝肯迷邦。","爲读江南傳，何賢過二龐。"]', '诗', 'shi', '', NULL, '憶襲美洞庭觀步奉和次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba4b018-7ade-4c42-801f-4e76d93dec45', '江墅言懷', '江墅言懷', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["病身兼稚子，田舍劣相容。","跡共公卿絕，貧須稼穡供。","月方行到閏，霜始近言濃。","樹少棲禽雜，村孤守犬重。","汀洲藏晚弋，籬落露寒舂。","野弁欹還整，家書拆又封。","杉篁宜夕照，窗戶倚疎鐘。","南北唯聞戰，縱橫未勝農。","大春雖苦學，叔夜本多慵。","直使貂裘弊，猶堪過一冬。"]', '["病身兼稚子，田舍劣相容。","跡共公卿絕，貧須稼穡供。","月方行到閏，霜始近言濃。","樹少棲禽杂，村孤守犬重。","汀洲藏晚弋，籬落露寒舂。","野弁欹還整，家书拆又封。","杉篁宜夕照，窗戶倚疎鐘。","南北唯闻戰，縱橫未勝農。","大春雖苦学，叔夜本多慵。","直使貂裘弊，猶堪過一冬。"]', '诗', 'shi', '', NULL, '江墅言懷 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dada512-e466-44b1-bd68-509718e7a373', '自和次前韻', '自和次前韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["命既時相背，才非世所容。","著書粮易絕，多病藥難供。","夢爲懷山數，愁因戒酒濃。","鳥媒呈不一，魚寨下仍重。","晚桁蓑兼褐，晴簷織帶舂。","著籤分水味，標石認田封。","此地家三戶，何人祿萬鍾。","草堂聊當貴，金穴任輕農。","把釣竿初冷，題詩筆未慵。","莫憂寒事晚，江上少嚴冬。"]', '["命既时相背，才非世所容。","著书粮易絕，多病藥难供。","梦爲懷山數，愁因戒酒濃。","鸟媒呈不一，鱼寨下仍重。","晚桁蓑兼褐，晴簷织带舂。","著籤分水味，標石認田封。","此地家三戶，何人祿万鍾。","草堂聊當貴，金穴任轻農。","把釣竿初冷，題诗笔未慵。","莫憂寒事晚，江上少嚴冬。"]', '诗', 'shi', '', NULL, '自和次前韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71dcbf87-1934-4a67-a024-f6cceeaade7f', '秋日遣懷十六韻寄道侶', '秋日遣懷十六韻寄道侶', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["盡日臨風坐，雄詞妙略兼。","共知時世薄，寧恨歲華淹。","且把靈方試，休憑吉夢占。","夜然燒汞火，朝煉洗金鹽。","有路求真隱，無媒舉孝廉。","自然成嘯傲，不是學沈潛。","水恨同心隔，霜愁兩鬢霑。","鶴屏憐掩扇，烏帽愛垂簷。","雅調宜觀樂，清才稱典籤。","冠𢼮玄髪少，書健紫毫尖。","故疾因秋召，塵容畏日黔。","壯圖須行行，儒服謾襜襜。","片石聊當枕，橫煙欲代簾。","蠹根延穴蟻，疎葉漏庭蟾。","藥鼎高低鑄，雲菴早晚苫。","胡麻如重寄，從誚我無厭。"]', '["尽日臨风坐，雄词妙略兼。","共知时世薄，寧恨歲华淹。","且把靈方試，休憑吉梦占。","夜然燒汞火，朝煉洗金鹽。","有路求真隐，無媒舉孝廉。","自然成嘯傲，不是学沈潛。","水恨同心隔，霜愁兩鬢霑。","鹤屏怜掩扇，烏帽愛垂簷。","雅調宜观乐，清才稱典籤。","冠𢼮玄髪少，书健紫毫尖。","故疾因秋召，塵容畏日黔。","壯圖須行行，儒服謾襜襜。","片石聊當枕，橫煙欲代簾。","蠹根延穴蟻，疎葉漏庭蟾。","藥鼎高低鑄，云菴早晚苫。","胡麻如重寄，從誚我無厭。"]', '诗', 'shi', '', NULL, '秋日遣懷十六韻寄道侶 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49876ad5-0c71-4887-8e44-20d4e8d04abf', '京口與友生話別', '京口與友生話別', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["共是悲秋客，相逢恨不堪。","鴈頻辭蘇北，人尚在江南。","名利機初發，樵漁事先諳。","松門穿戴寺，荷徑繞秦潭。","繩檢真難束，疎慵却易耽。","枕當高樹穩，茶試遠泉甘。","架上經唯一，尊前雅祗三。","風雲勞夢想，天地入醺酣。","曆自堯階數，書因禹穴探。","御龍雖世祿，下馬亦清譚。","國計徒盈策，家儲不滿甔。","斷簾從燕出，𢼮弁請人簪。","木墜涼來葉，山橫霽後嵐。","竹窗深䆗窱，苔洞綠龕弇。","積行依顏子，和光則老聃。","杖誠爲虎節，披信作鮫函。","養鷺看窺沼，尋僧助結菴。","功名思馬援，歌唱咽羊曇。","乞食羞孤鳳，無衣羨八蠶。","繫帆留宿客，吟句任羸驂。","寵鶴空無衛，占烏未見𨝸。","香還須是桂，青會出於藍。","蜀酒時傾瓿，吳鰕徧發坩。","玉封千挺藕，霜閉一筒柑。","惜佩終邀禍，辭環好激貪。","宗溟雖甽澮，成廈必楩柟。","碧玉雕琴薦，黃金飾劒鐔。","煙緣莎砌引，水爲藥畦擔。","博物君能繼，多才我尚慙。","別離猶得在，秋鬢未鬖鬖。"]', '["共是悲秋客，相逢恨不堪。","鴈頻辞蘇北，人尚在江南。","名利機初發，樵漁事先諳。","松门穿戴寺，荷徑繞秦潭。","繩檢真难束，疎慵却易耽。","枕當高樹穩，茶試远泉甘。","架上經唯一，尊前雅祗三。","风云勞梦想，天地入醺酣。","曆自堯階數，书因禹穴探。","御龙雖世祿，下马亦清譚。","国計徒盈策，家儲不满甔。","斷簾從燕出，𢼮弁請人簪。","木墜涼来葉，山橫霽後嵐。","竹窗深䆗窱，苔洞綠龕弇。","積行依顏子，和光則老聃。","杖誠爲虎節，披信作鮫函。","養鷺看窺沼，尋僧助結菴。","功名思马援，歌唱咽羊曇。","乞食羞孤鳳，無衣羨八蠶。","繫帆留宿客，吟句任羸驂。","寵鹤空無衛，占烏未见𨝸。","香還須是桂，青會出於藍。","蜀酒时傾瓿，吳鰕徧發坩。","玉封千挺藕，霜閉一筒柑。","惜佩終邀禍，辞环好激貪。","宗溟雖甽澮，成廈必楩柟。","碧玉雕琴薦，黄金飾劒鐔。","煙緣莎砌引，水爲藥畦擔。","博物君能繼，多才我尚慙。","別離猶得在，秋鬢未鬖鬖。"]', '诗', 'shi', '', NULL, '京口與友生話別 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61935c96-3ada-4783-8f8e-7d4680ec635d', '丹陽道中寄友生', '丹陽道中寄友生', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["煙樹綠微微，春流浸竹扉。","短蓑攜稚去，孤艇載魚歸。","海俗蘆編室，村娃練束衣。","舊栽奴橘老，新刈女桑肥。","錦鯉衝風擲，絲禽掠浪飛。","短亭幽徑入，陳廟數峰圍。","地廢金牛暗，陵荒石獸稀。","思君同一望，帆上怨餘暉。"]', '["煙樹綠微微，春流浸竹扉。","短蓑携稚去，孤艇載鱼归。","海俗蘆編室，村娃練束衣。","旧栽奴橘老，新刈女桑肥。","錦鯉衝风擲，絲禽掠浪飞。","短亭幽徑入，陳廟數峰圍。","地廢金牛暗，陵荒石獸稀。","思君同一望，帆上怨餘暉。"]', '诗', 'shi', '', NULL, '丹陽道中寄友生 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7243a9fc-9499-425b-abea-cef3c66d2ef3', '寄茅山何道士', '寄茅山何道士', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["終身持玉舃，丹訣未應傳。","況是曾同宿，相違便隔年。","問顏知更少，聽話想踰玄。","古籙文垂露，新金汞絕煙。","蜂供和餌蜜，人寄買溪錢。","紫燕長巢硐，青龜忽上蓮。","篋藏徵隱詔，囊佩攝生篇。","圃暖芝臺秀，巖春乳管圓。","池栖子孫鶴，堂宿弟兄仙。","幸閱靈書次，心期賜一編。"]', '["終身持玉舃，丹訣未應傳。","況是曾同宿，相違便隔年。","问顏知更少，听話想踰玄。","古籙文垂露，新金汞絕煙。","蜂供和餌蜜，人寄買溪錢。","紫燕长巢硐，青龟忽上蓮。","篋藏徵隐詔，囊佩攝生篇。","圃暖芝台秀，巖春乳管圓。","池栖子孫鹤，堂宿弟兄仙。","幸閱靈书次，心期賜一編。"]', '诗', 'shi', '', NULL, '寄茅山何道士 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d1f06d-7da3-40be-bb99-4006eeafad65', '江南秋懷寄華陽山人', '江南秋懷寄华陽山人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["櫛髪涼天曙，含毫故國情。","歸心一夜極，病體九秋輕。","忽起襜褕詠，因悲絡緯鳴。","逢山即堪隱，何路可圖榮。","揲策空占命，持竿不釣名。","忘憂如有待，縱嬾似無營。","小徑纔分草，斜扉劣辨荆。","冷荷承露菂，疎菊臥煙莖。","譜爲聽琴閱，圖緣看海㡠。","鷺毛浮島白，魚尾撇波赬。","庭橘低攀嗅，園葵旋折烹。","餓烏窺食案，鬬鼠落書棚。","種豆悲楊惲，投瓜憶衛旍。","東林誰處士，南郭自先生。","分野星多蹇，連山卦少亨。","衣裾徒博大，文籍漫縱橫。","蘭葉騷人佩，蓴絲內史羹。","鶡冠難適越，羊酪未饒傖。","倚嘯微抽恨，論玄好析酲。","栖遲勞鼓篋，豪俠愛金籯。","鍊藥傳丹鼎，嘗茶試石𪼿。","沼連枯葦暗，窗對脫梧明。","未達譏張翰，非才嫉禰衡。","遠懷魂易黯，幽憤骨堪驚。","礪缺知矛利，磨瑕見璧瑛。","道源疏滴瀝，儒肆售精誠。","敢歎良時擲，猶勝亂世攖。","相秦猶幾死，王漢尚當黥。","飲啄期應定，窮通勢莫爭。","髡鉗爲皂隸，譚笑得公卿。","浴日安知量，追風不計程。","塵埃張耳分，肝膽季心傾。","諭蜀專操檄，通甌獨請纓。","匹夫能曲踊，萬騎可橫行。","許國輕妻子，防邊重戰耕。","俄分上尊酒，驟厭五侯鯖。","靜默供三語，從容等一枰。","弘深司馬法，雄傑貳師兵。","朔雪埋烽燧，寒笳裂斾旌。","乘時收句注，即日埽欃槍。","武昔威殊俗，文今被八紘。","琮璜陳始畢，韶夏教初成。","芽孽羣妖滅，松筠百度貞。","郎官青瑣拜，使者繡衣迎。","帝道將雲闢，澆波漸砥平。","學徒羞說霸，佳士恥爲跉。","負杖歌栖畝，操觚賦北征。","才當曹斗怯，書比惠車盈。","謝氏憐兒女，郄家貴舅甥。","唯荒稚珪宅，莫贈景山鎗。","賢彥風流遠，江湖思緒縈。","謳啞搖舴艋，出沒漾鵁鶄。","晚樹參差碧，奇峰邐迤晴。","水喧揌紫芡，村響{姊女=臼}香秔。","荷笠漁翁古，穿籬守犬獰。","公衫白紵卷，田餉綠筲擎。","地與膏腴錯，人多富壽幷。","相歡時帖泰，獨坐歲崢嶸。","唧嘖蛩吟壁，連軒鶴舞楹。","戍風飄疊鼓，鄰月動哀箏。","未得文章力，何由俸祿請。","和鉛還搰搰，持斧自丁丁。","驚懼疑凋朽，功勤過屑瓊。","凝神披夕秀，盡力取朝英。","蠹簡開塵篋，寒燈立曉檠。","靜翻詞客系，閑難史官評。","天地寧舒慘，山川自變更。","秖能分跖惠，誰解等殤彭。","項豈重瞳聖，夔憂一足𨆪。","阮高酣麴糵，莊達謝犧牲。","齚舌無勞話，寬心豈可盛。","但從罏冶鍛，莫受罻羅嬰。","硯撥萍根洗，舟衝蓼穗撐。","短牀編翠竹，低机凭紅檉。","霜信催楊柳，煙容褭杜蘅。","桁排巢燕燕，屏畫醉猩猩。","嬾檜推嵐影，飛泉撼玉琤。","𦪽{舟卭}尋遠近，握槊鬬輸贏。","枝壓離披瓠，簷垂礧磊橙。","忘情及宗炳，抱疾過劉楨。","野饋夸菰飯，江商賈蔗餳。","送神枹瓦釜，留客上瓷觥。","舉楫揮青劒，鳴榔扣遠鉦。","鳥行沈莽碧，魚隊破泓澄。","手戟非吾事，腰鎌且發硎。","諒難求摽摽，聊欲取錚錚。","幾歎蟲甘蓼，還思鹿美苹。","愁長難自剪，歌斷有誰賡。","未去師黃石，空能說白珩。","性湍休激浪，言莠罷抽萌。","地僻琴尊獨，溪寒杖屨清。","物齊消臆對，戈倒共心盟。","絲曳靈妃瑟，金涵太子笙。","幽棲膠竹塢，仙慮驛蓬瀛。","想像珠襦鳳，追飛翠蘂鶯。","霧簾深杳悄，雲磬冷敲鏗。","籙字多階品，華陽足弟兄。","焚香凝一室，盡日思層城。","匿景崦嵫色，呀空渤澥聲。","吾當營巨黍，東去射長鯨。"]', '["櫛髪涼天曙，含毫故国情。","归心一夜極，病體九秋轻。","忽起襜褕詠，因悲絡緯鳴。","逢山即堪隐，何路可圖榮。","揲策空占命，持竿不釣名。","忘憂如有待，縱嬾似無營。","小徑纔分草，斜扉劣辨荆。","冷荷承露菂，疎菊臥煙莖。","譜爲听琴閱，圖緣看海㡠。","鷺毛浮島白，鱼尾撇波赬。","庭橘低攀嗅，园葵旋折烹。","餓烏窺食案，鬬鼠落书棚。","種豆悲楊惲，投瓜憶衛旍。","东林誰处士，南郭自先生。","分野星多蹇，連山卦少亨。","衣裾徒博大，文籍漫縱橫。","蘭葉騷人佩，蓴絲內史羹。","鶡冠难適越，羊酪未饒傖。","倚嘯微抽恨，論玄好析酲。","栖遲勞鼓篋，豪俠愛金籯。","鍊藥傳丹鼎，嘗茶試石𪼿。","沼連枯葦暗，窗对脫梧明。","未達譏張翰，非才嫉禰衡。","远懷魂易黯，幽憤骨堪驚。","礪缺知矛利，磨瑕见璧瑛。","道源疏滴瀝，儒肆售精誠。","敢歎良时擲，猶勝亂世攖。","相秦猶幾死，王漢尚當黥。","饮啄期應定，窮通勢莫爭。","髡鉗爲皂隸，譚笑得公卿。","浴日安知量，追风不計程。","塵埃張耳分，肝膽季心傾。","諭蜀專操檄，通甌独請纓。","匹夫能曲踊，万騎可橫行。","許国轻妻子，防邊重戰耕。","俄分上尊酒，驟厭五侯鯖。","静默供三語，從容等一枰。","弘深司马法，雄傑貳師兵。","朔雪埋烽燧，寒笳裂斾旌。","乘时收句注，即日埽欃槍。","武昔威殊俗，文今被八紘。","琮璜陳始畢，韶夏教初成。","芽孽羣妖滅，松筠百度貞。","郎官青瑣拜，使者繡衣迎。","帝道將云闢，澆波漸砥平。","学徒羞说霸，佳士恥爲跉。","負杖歌栖畝，操觚賦北征。","才當曹斗怯，书比惠车盈。","謝氏怜兒女，郄家貴舅甥。","唯荒稚珪宅，莫贈景山鎗。","賢彥风流远，江湖思緒縈。","謳啞搖舴艋，出沒漾鵁鶄。","晚樹參差碧，奇峰邐迤晴。","水喧揌紫芡，村响{姊女=臼}香秔。","荷笠漁翁古，穿籬守犬獰。","公衫白紵卷，田餉綠筲擎。","地與膏腴錯，人多富壽幷。","相歡时帖泰，独坐歲崢嶸。","唧嘖蛩吟壁，連軒鹤舞楹。","戍风飄叠鼓，鄰月动哀箏。","未得文章力，何由俸祿請。","和鉛還搰搰，持斧自丁丁。","驚懼疑凋朽，功勤過屑瓊。","凝神披夕秀，尽力取朝英。","蠹簡开塵篋，寒灯立晓檠。","静翻词客系，闲难史官評。","天地寧舒慘，山川自变更。","秖能分跖惠，誰解等殤彭。","項豈重瞳聖，夔憂一足𨆪。","阮高酣麴糵，莊達謝犧牲。","齚舌無勞話，寬心豈可盛。","但從罏冶鍛，莫受罻羅嬰。","硯撥萍根洗，舟衝蓼穗撐。","短牀編翠竹，低机凭紅檉。","霜信催楊柳，煙容褭杜蘅。","桁排巢燕燕，屏畫醉猩猩。","嬾檜推嵐影，飞泉撼玉琤。","𦪽{舟卭}尋远近，握槊鬬輸贏。","枝壓離披瓠，簷垂礧磊橙。","忘情及宗炳，抱疾過劉楨。","野饋夸菰飯，江商賈蔗餳。","送神枹瓦釜，留客上瓷觥。","舉楫揮青劒，鳴榔扣远鉦。","鸟行沈莽碧，鱼隊破泓澄。","手戟非吾事，腰鎌且發硎。","諒难求摽摽，聊欲取錚錚。","幾歎蟲甘蓼，還思鹿美苹。","愁长难自剪，歌斷有誰賡。","未去師黄石，空能说白珩。","性湍休激浪，言莠罷抽萌。","地僻琴尊独，溪寒杖屨清。","物齊消臆对，戈倒共心盟。","絲曳靈妃瑟，金涵太子笙。","幽棲膠竹塢，仙慮驛蓬瀛。","想像珠襦鳳，追飞翠蘂鶯。","霧簾深杳悄，云磬冷敲鏗。","籙字多階品，华陽足弟兄。","焚香凝一室，尽日思層城。","匿景崦嵫色，呀空渤澥声。","吾當營巨黍，东去射长鯨。"]', '诗', 'shi', '', NULL, '江南秋懷寄華陽山人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64dc25b6-a75b-42a1-941d-73a802a27fa9', '送宣武從事越中按獄', '送宣武從事越中按獄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曉看呈使範，知欲敕星軺。","水國難驅傳，山城便倚橈。","秉籌先獨立，持法稱高標。","旌斾臨危堞，金絲發麗譙。","別愁當翠巘，冤望隔風潮。","木落孤帆迥，江寒疊鼓飄。","客鴻吳島盡，殘雪剡汀消。","坐想休秦獄，春應到柳條。"]', '["晓看呈使範，知欲敕星軺。","水国难驱傳，山城便倚橈。","秉籌先独立，持法稱高標。","旌斾臨危堞，金絲發丽譙。","別愁當翠巘，冤望隔风潮。","木落孤帆迥，江寒叠鼓飄。","客鴻吳島尽，殘雪剡汀消。","坐想休秦獄，春應到柳條。"]', '诗', 'shi', '', NULL, '送宣武從事越中按獄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14a5755b-bbbc-4dea-8ada-dcd134bcdec9', '江南冬至和人懷洛下', '江南冬至和人懷洛下', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["昔居清洛涯，長恨苦寒遲。","自作江南客，稀遲下雪時。","有煙棲菊梗，無凍落杉枝。","背日能尋徑，臨風尚覆棋。","鳥聲渾欲轉，草色固應知。","與看平湖上，東流或片澌。"]', '["昔居清洛涯，长恨苦寒遲。","自作江南客，稀遲下雪时。","有煙棲菊梗，無凍落杉枝。","背日能尋徑，臨风尚覆棋。","鸟声渾欲轉，草色固應知。","與看平湖上，东流或片澌。"]', '诗', 'shi', '', NULL, '江南冬至和人懷洛下 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271089d4-cd26-496f-b6b4-5399856ba610', '謹和諫議罷郡敘懷六韻', '謹和諫議罷郡敘懷六韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["已報東吳政，初捐左契歸。","天應酬苦節，人不犯寒威。","江上思重借，朝端望載飢。","紫泥封夜詔，金殿賜春衣。","對酒情何遠，裁詩思極微。","待升鎔造日，江海問漁扉。"]', '["已報东吳政，初捐左契归。","天應酬苦節，人不犯寒威。","江上思重借，朝端望載飢。","紫泥封夜詔，金殿賜春衣。","对酒情何远，裁诗思極微。","待升鎔造日，江海问漁扉。"]', '诗', 'shi', '', NULL, '謹和諫議罷郡敘懷六韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc244ab7-824f-4baa-9129-e02fd4dab206', '二遺詩', '二遺诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰從毫末見參天，又到蒼蒼化石年。","萬古清風吹作籟，一條寒溜滴成穿。","閑追金帶徒勞恨，靜格朱絲更可憐。","幸與野人俱散誕，不煩良匠更雕鐫。"]', '["誰從毫末见參天，又到蒼蒼化石年。","万古清风吹作籟，一條寒溜滴成穿。","闲追金带徒勞恨，静格朱絲更可怜。","幸與野人俱散誕，不煩良匠更雕鐫。"]', '诗', 'shi', '', NULL, '二遺詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8e01e8-a224-46ad-b4a0-a498f110d84d', '鵁鶄', '鵁鶄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["詞賦曾誇鸀鳿流，果爲名誤別滄洲。","雖蒙靜置疎籠晚，不似閑栖折葦秋。","自昔稻粱高鳥畏，至今珪組野人讐。","防徽避繳無窮事，好與裁書謝白鷗。"]', '["词賦曾誇鸀鳿流，果爲名誤別滄洲。","雖蒙静置疎籠晚，不似闲栖折葦秋。","自昔稻粱高鸟畏，至今珪組野人讐。","防徽避繳無窮事，好與裁书謝白鷗。"]', '诗', 'shi', '', NULL, '鵁鶄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e01fe7b-4c03-4c18-82a3-554192e91ab2', '新秋月夕客有自遠相尋者作吳體二首以贈 一', '新秋月夕客有自远相尋者作吳體二首以贈 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["風初寥寥月乍滿，杉篁左右供餘清。","因君一話故山事，憶鶴互應深溪聲。","雲門老森定未起，白閣道士遙相迎。","日聞羽檄日夜急，掉臂欲歸巖下行。"]', '["风初寥寥月乍满，杉篁左右供餘清。","因君一話故山事，憶鹤互應深溪声。","云门老森定未起，白閣道士遙相迎。","日闻羽檄日夜急，掉臂欲归巖下行。"]', '诗', 'shi', '', NULL, '新秋月夕客有自遠相尋者作吳體二首以贈 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a89d8103-f76c-4ab0-b5fe-07fea12bb2d1', '新秋月夕客有自遠相尋者作吳體二首以贈 二', '新秋月夕客有自远相尋者作吳體二首以贈 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["驚聞遠客訪良夜，扶病起坐綸巾欹。","清談白紵思悄悄，玉繩銀漢光離離。","三吳煙霧且如此，百越琛賮來何時。","林端片月落未落，強慰別情言後期。"]', '["驚闻远客訪良夜，扶病起坐綸巾欹。","清談白紵思悄悄，玉繩銀漢光離離。","三吳煙霧且如此，百越琛賮来何时。","林端片月落未落，強慰別情言後期。"]', '诗', 'shi', '', NULL, '新秋月夕客有自遠相尋者作吳體二首以贈 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a1268e-057e-4b10-91fc-f9a779ee4af2', '閑書', '闲书', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["病學高僧置一牀，披衣纔暇即焚香。","閑階雨過苔花潤，小簟風來薤葉涼。","南國羽書催部曲，東山毛褐傲羲皇。","升平聞道無時節，試問中林亦不妨。"]', '["病学高僧置一牀，披衣纔暇即焚香。","闲階雨過苔花潤，小簟风来薤葉涼。","南国羽书催部曲，东山毛褐傲羲皇。","升平闻道無时節，試问中林亦不妨。"]', '诗', 'shi', '', NULL, '閑書 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28052148-ec29-4e56-b658-f9ccc40b7f80', '獨夜', '独夜', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["新秋霽夜有清境，窮襜病容無佳期。","生公把經向石說，而我對月須人爲。","獨行獨坐亦獨酌，獨玩獨吟還獨悲。","古稱獨坐與獨立，若比羣居終校奇。"]', '["新秋霽夜有清境，窮襜病容無佳期。","生公把經向石说，而我对月須人爲。","独行独坐亦独酌，独玩独吟還独悲。","古稱独坐與独立，若比羣居終校奇。"]', '诗', 'shi', '', NULL, '獨夜 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c8be2e6-1f83-446e-ab36-af171471b70b', '寄吳融', '寄吳融', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一夜秋聲入井桐，數枝危綠怕西風。","霏霏晚砌煙華上，淅淅疎簾雨氣通。","君整輸蹄名未了，我依琴鶴病相攻。","到頭江畔從漁事，織作中流萬尺篊。"]', '["一夜秋声入井桐，數枝危綠怕西风。","霏霏晚砌煙华上，淅淅疎簾雨氣通。","君整輸蹄名未了，我依琴鹤病相攻。","到头江畔從漁事，织作中流万尺篊。"]', '诗', 'shi', '', NULL, '寄吳融 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0546f1e5-3920-4af5-820c-1473e6b70cc0', '中秋待月', '中秋待月', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["轉缺霜輪上轉遲，好風偏似送佳期。","簾斜樹隔情無限，燭暗香殘坐不辭。","最愛笙調聞北里，漸看星澹失南箕。","何人爲校清涼力，未似初圓欲午時。"]', '["轉缺霜輪上轉遲，好风偏似送佳期。","簾斜樹隔情無限，燭暗香殘坐不辞。","最愛笙調闻北里，漸看星澹失南箕。","何人爲校清涼力，未似初圓欲午时。"]', '诗', 'shi', '', NULL, '中秋待月 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c6900a-4be3-44cb-9a58-346a4c8fa498', '重憶白菊', '重憶白菊', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["我憐貞白重寒芳，前後叢生夾小堂。","月朵暮開無絕豔，風莖時動有奇香。","何慙謝雪清才詠，不羨劉梅貴主妝。","更憶幽窗凝一夢，夜來村落有微霜。"]', '["我怜貞白重寒芳，前後叢生夾小堂。","月朵暮开無絕豔，风莖时动有奇香。","何慙謝雪清才詠，不羨劉梅貴主妝。","更憶幽窗凝一梦，夜来村落有微霜。"]', '诗', 'shi', '', NULL, '重憶白菊 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('862844aa-45ce-422e-b5c4-d7ac72d41014', '別墅懷歸', '別墅懷归', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水國初冬和暖天，南榮方好背陽眠。","題詩朝憶復暮憶，見月上弦還下弦。","遙爲晚花吟白菊，近炊香稻識紅蓮。","何人授我黃金百，買取蘇君負郭田。"]', '["水国初冬和暖天，南榮方好背陽眠。","題诗朝憶复暮憶，见月上弦還下弦。","遙爲晚花吟白菊，近炊香稻識紅蓮。","何人授我黄金百，買取蘇君負郭田。"]', '诗', 'shi', '', NULL, '別墅懷歸 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2a431d-c0e3-43c6-85ea-ec86a9cab574', '寄淮南鄭寶書記', '寄淮南鄭寶书記', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["記室千年翰墨孤，唯君才學似應徐。","五丁驅得神功盡，二酉搜來祕檢疎。","煬帝帆檣留澤國，淮王牋奏入班書。","清詞醉草無因見，但釣寒江半尺鱸。"]', '["記室千年翰墨孤，唯君才学似應徐。","五丁驱得神功尽，二酉搜来祕檢疎。","煬帝帆檣留澤国，淮王牋奏入班书。","清词醉草無因见，但釣寒江半尺鱸。"]', '诗', 'shi', '', NULL, '寄淮南鄭寶書記 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4468968-5cdd-4373-88d8-9e077cb5413d', '小雪後書事', '小雪後书事', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["時候頻過小雪天，江南寒色未曾偏。","楓汀尚憶逢人別，麥隴唯應欠雉眠。","更擬結茅臨水次，偶因行藥到村前。","鄰翁意緒相安慰，多說明年是稔年。"]', '["时候頻過小雪天，江南寒色未曾偏。","楓汀尚憶逢人別，麦隴唯應欠雉眠。","更擬結茅臨水次，偶因行藥到村前。","鄰翁意緒相安慰，多说明年是稔年。"]', '诗', 'shi', '', NULL, '小雪後書事 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1c76e0-9240-44d6-974f-40f99b316461', '寒夜同襲美訪北禪院寂上人', '寒夜同襲美訪北禪院寂上人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["月樓風殿靜沈沈，披拂霜華訪道林。","鳥在寒枝棲影動，人依古堞坐禪深。","明時尚阻青雲步，半夜猶追白石吟。","自是海邊鷗伴侶，不勞金偈更降心。"]', '["月楼风殿静沈沈，披拂霜华訪道林。","鸟在寒枝棲影动，人依古堞坐禪深。","明时尚阻青云步，半夜猶追白石吟。","自是海邊鷗伴侶，不勞金偈更降心。"]', '诗', 'shi', '', NULL, '寒夜同襲美訪北禪院寂上人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2a184c-ed68-4f7e-a95b-baa4713d2709', '和襲美江南道中懷茅山廣文南陽博士三首次韻 一', '和襲美江南道中懷茅山廣文南陽博士三首次韻 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一片輕帆背夕陽，望三峰拜七真堂。","天寒夜漱雲牙淨，雪壞晴梳石髪香。","自拂煙霞安筆格，獨開封檢試砂牀。","莫言洞府能招隱，會輾飆輪見玉皇。"]', '["一片轻帆背夕陽，望三峰拜七真堂。","天寒夜漱云牙淨，雪壞晴梳石髪香。","自拂煙霞安笔格，独开封檢試砂牀。","莫言洞府能招隐，會輾飆輪见玉皇。"]', '诗', 'shi', '', NULL, '和襲美江南道中懷茅山廣文南陽博士三首次韻 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ae7f24-5ebc-4659-81ee-8d1148225c18', '和襲美江南道中懷茅山廣文南陽博士三首次韻 二', '和襲美江南道中懷茅山廣文南陽博士三首次韻 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["壺中行坐可攜天，何況林間息萬緣。","組綬任垂三品石，佩環從落四公泉。","丹臺已運陰陽火，碧簡須雕次第仙。","想得雷平春色動，五芝煙甲又芊眠。"]', '["壺中行坐可携天，何況林间息万緣。","組綬任垂三品石，佩环從落四公泉。","丹台已運陰陽火，碧簡須雕次第仙。","想得雷平春色动，五芝煙甲又芊眠。"]', '诗', 'shi', '', NULL, '和襲美江南道中懷茅山廣文南陽博士三首次韻 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59edd019-e5bc-49de-8087-565a66615751', '和襲美江南道中懷茅山廣文南陽博士三首次韻 三', '和襲美江南道中懷茅山廣文南陽博士三首次韻 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["良常應不動移文，金醴從酸亦自醺。","桂父舊歌飛絳雪，桐孫新韻倚玄雲。","春臨柳谷鶯先覺，曙醮蕪香鶴共聞。","珍重雙雙玉條脫，盡憑三島寄羊君。"]', '["良常應不动移文，金醴從酸亦自醺。","桂父旧歌飞絳雪，桐孫新韻倚玄云。","春臨柳谷鶯先覺，曙醮蕪香鹤共闻。","珍重雙雙玉條脫，尽憑三島寄羊君。"]', '诗', 'shi', '', NULL, '和襲美江南道中懷茅山廣文南陽博士三首次韻 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67acc701-5804-4954-a387-7e3446e411ef', '早春雪中作吳體寄襲美', '早春雪中作吳體寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["迎春避臘不肯下，欺花凍草還飄然。","光填馬窟蓋塞外，勢壓鶴巢偏殿巔。","山爐癭節萬狀火，墨突乾衰孤穗煙。","君披鶴氅獨自立，何人解道真神仙。"]', '["迎春避臘不肯下，欺花凍草還飄然。","光填马窟蓋塞外，勢壓鹤巢偏殿巔。","山爐癭節万狀火，墨突乾衰孤穗煙。","君披鹤氅独自立，何人解道真神仙。"]', '诗', 'shi', '', NULL, '早春雪中作吳體寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0864724d-33dd-4764-ba28-3e666e408866', '奉和襲美吳中言情見寄次韻', '奉和襲美吳中言情见寄次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["菰煙蘆雪是儂鄉，釣線隨身好坐忘。","徒愛右軍遺點畫，閑披左氏得膏盲。","無因月殿聞移屧，秖有風汀去採香。","莫問江邊漁艇子，玉皇看賜羽衣裳。"]', '["菰煙蘆雪是儂乡，釣線隨身好坐忘。","徒愛右軍遺点畫，闲披左氏得膏盲。","無因月殿闻移屧，秖有风汀去採香。","莫问江邊漁艇子，玉皇看賜羽衣裳。"]', '诗', 'shi', '', NULL, '奉和襲美吳中言情見寄次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51066268-58a2-4769-aa2e-2f08e004b514', '和襲美揚州看辛夷花次韻', '和襲美揚州看辛夷花次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["柳疎梅墮少春叢，天遣花神別致功。","高處朵稀難避日，動時枝弱易爲風。","堪將亂蘂添雲肆，若得千株便雪宮。","不待羣芳應有意，等閑桃杏即爭紅。"]', '["柳疎梅墮少春叢，天遣花神別致功。","高处朵稀难避日，动时枝弱易爲风。","堪將亂蘂添云肆，若得千株便雪宮。","不待羣芳應有意，等闲桃杏即爭紅。"]', '诗', 'shi', '', NULL, '和襲美揚州看辛夷花次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f9a560-1be4-474b-adc9-4fcf6b73b3be', '奉和襲美行次野梅次韻', '奉和襲美行次野梅次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["飛櫂參差拂早梅，強欺寒色尚低徊。","風憐薄媚留香與，月會深情借豔開。","梁殿得非蕭帝瑞，齊宮應是玉兒媒。","不知謝客離腸醒，臨水應添萬恨來。"]', '["飞櫂參差拂早梅，強欺寒色尚低徊。","风怜薄媚留香與，月會深情借豔开。","梁殿得非蕭帝瑞，齊宮應是玉兒媒。","不知謝客離腸醒，臨水應添万恨来。"]', '诗', 'shi', '', NULL, '奉和襲美行次野梅次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca94aa16-25bf-4656-8ceb-add843482a4c', '奉和襲美暇日獨處見寄', '奉和襲美暇日独处见寄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["謝府殷樓少暇時，又拋清宴入書帷。","三千餘歲上下古，八十一家文字奇。","冷夢漢臯懷鹿隱，靜憐煙島覺鴻離。","知君滿篋前朝事，鳳諾龍奴借與窺。"]', '["謝府殷楼少暇时，又拋清宴入书帷。","三千餘歲上下古，八十一家文字奇。","冷梦漢臯懷鹿隐，静怜煙島覺鴻離。","知君满篋前朝事，鳳諾龙奴借與窺。"]', '诗', 'shi', '', NULL, '奉和襲美暇日獨處見寄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0979fa35-44e8-4a9b-87a1-53c54a7623dc', '奉和襲美見訪不遇', '奉和襲美见訪不遇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["爲愁煙岸老塵囂，扶病呼兒斸翠苕。","秖道府中持簡牘，不知林下訪漁樵。","花盤小墢晴初壓，葉擁疎籬凍未燒。","倚杖徧吟春照午，一池冰段幾多消。"]', '["爲愁煙岸老塵囂，扶病呼兒斸翠苕。","秖道府中持簡牘，不知林下訪漁樵。","花盤小墢晴初壓，葉擁疎籬凍未燒。","倚杖徧吟春照午，一池冰段幾多消。"]', '诗', 'shi', '', NULL, '奉和襲美見訪不遇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0456f0b8-354c-4f3e-8994-67f6b476cd21', '酬襲美見寄海蟹', '酬襲美见寄海蟹', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["藥杯應阻蟹螯香，却乞江邊採捕郎。","自是揚雄知郭索，且非何胤敢餦餭。","骨清猶似含春靄，沫白還疑帶海霜。","強作南朝風雅客，夜來偷醉早梅傍。"]', '["藥杯應阻蟹螯香，却乞江邊採捕郎。","自是揚雄知郭索，且非何胤敢餦餭。","骨清猶似含春靄，沫白還疑带海霜。","強作南朝风雅客，夜来偷醉早梅傍。"]', '诗', 'shi', '', NULL, '酬襲美見寄海蟹 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250efd4e-1ed3-437b-b7c0-eef9b606a21c', '奉和襲美開元寺客省早景即事次韻', '奉和襲美开元寺客省早景即事次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["日上罘罳疊影紅，一聲清梵萬緣空。","䙰褷滿地貝多雪，料峭入樓于闐風。","水榭初抽寥泬思，竹窗猶挂夢魂中。","靈香散盡禪家接，誰共殷源小品同。"]', '["日上罘罳叠影紅，一声清梵万緣空。","䙰褷满地貝多雪，料峭入楼于闐风。","水榭初抽寥泬思，竹窗猶挂梦魂中。","靈香散尽禪家接，誰共殷源小品同。"]', '诗', 'shi', '', NULL, '奉和襲美開元寺客省早景即事次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1766d7ae-8530-425d-b958-9a0dbcb58c31', '獨夜有懷因作吳體寄襲美', '独夜有懷因作吳體寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["人吟側景抱凍竹，鶴夢缺月沈枯梧。","清澗無波鹿無魄，白雲有根虬有鬚。","雲虬澗鹿真逸調，刀名錐利非良圖。","不然快作燕市飲，笑撫肉枅眠酒壚。"]', '["人吟側景抱凍竹，鹤梦缺月沈枯梧。","清澗無波鹿無魄，白云有根虬有鬚。","云虬澗鹿真逸調，刀名錐利非良圖。","不然快作燕市饮，笑撫肉枅眠酒壚。"]', '诗', 'shi', '', NULL, '獨夜有懷因作吳體寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f10e7d-dcb5-40b3-b1c3-a296b9e53600', '闔閭城北有賣花翁討春之士往往造焉因招襲美', '闔閭城北有賣花翁討春之士往往造焉因招襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["故城邊有賣花翁，水曲舟輕去盡通。","十畝芳菲爲舊業，一家煙雨是元功。","閑添藥品年年別，笑指生涯樹樹紅。","若要見春歸處所，不過攜手問東風。"]', '["故城邊有賣花翁，水曲舟轻去尽通。","十畝芳菲爲旧業，一家煙雨是元功。","闲添藥品年年別，笑指生涯樹樹紅。","若要见春归处所，不過携手问东风。"]', '诗', 'shi', '', NULL, '闔閭城北有賣花翁討春之士往往造焉因招襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2537eacf-f276-4ee2-a05a-a28c1ea2da07', '奉和襲美病中庭際海石榴花盛發見寄次韻', '奉和襲美病中庭際海石榴花盛發见寄次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["紫府真人餉露囊，猗蘭燈燭未熒煌。","丹華乞曙先侵日，金焰欺寒却照霜。","誰與佳名從海曲，秖應芳裔出河陽。","那堪謝氏庭前見，一段清香染郄郎。"]', '["紫府真人餉露囊，猗蘭灯燭未熒煌。","丹华乞曙先侵日，金焰欺寒却照霜。","誰與佳名從海曲，秖應芳裔出河陽。","那堪謝氏庭前见，一段清香染郄郎。"]', '诗', 'shi', '', NULL, '奉和襲美病中庭際海石榴花盛發見寄次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65cecff-9bb6-4565-b5e8-76e10af7c359', '襲美以春橘見惠兼之雅篇因次韻酬謝', '襲美以春橘见惠兼之雅篇因次韻酬謝', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["到春猶作九秋鮮，應是親封白帝煙。","良玉有漿須讓味，明珠無纇亦羞圓。","堪居漢苑霜梨上，合在仙家火棗前。","珍重更過三十子，不堪分付野人邊。"]', '["到春猶作九秋鲜，應是親封白帝煙。","良玉有漿須讓味，明珠無纇亦羞圓。","堪居漢苑霜梨上，合在仙家火棗前。","珍重更過三十子，不堪分付野人邊。"]', '诗', 'shi', '', NULL, '襲美以春橘見惠兼之雅篇因次韻酬謝 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e945645-bde4-40ef-9408-94f5540fd002', '奉和襲美病中書情寄上崔諫議次韻', '奉和襲美病中书情寄上崔諫議次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["或偃虛齋或在公，藹然林下昔賢風。","庭前有蜨爭煙蘂，簾外無人報水筒。","行藥不離深幌底，寄書多向遠山中。","西園夜燭偏堪憶，曾爲題詩刻半紅。"]', '["或偃虛斋或在公，藹然林下昔賢风。","庭前有蜨爭煙蘂，簾外無人報水筒。","行藥不離深幌底，寄书多向远山中。","西园夜燭偏堪憶，曾爲題诗刻半紅。"]', '诗', 'shi', '', NULL, '奉和襲美病中書情寄上崔諫議次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a029f2b-8cf8-4020-a34f-d269a55f1f78', '奉酬襲美病中見寄', '奉酬襲美病中见寄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["逢花逢月便相招，忽臥雲航隔野橋。","春恨與誰同酩酊，玄言何處問逍遙？","題詩石上空迴筆，拾蕙汀邊獨倚橈。","早晚却還巖下電，共尋芳徑結煙條。"]', '["逢花逢月便相招，忽臥云航隔野橋。","春恨與誰同酩酊，玄言何处问逍遙？","題诗石上空迴笔，拾蕙汀邊独倚橈。","早晚却還巖下電，共尋芳徑結煙條。"]', '诗', 'shi', '', NULL, '奉酬襲美病中見寄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4dff51a-63a5-4692-9d43-e594a6b23cc1', '奉和襲美病孔雀', '奉和襲美病孔雀', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["嬾移金翠傍簷楹，斜倚芳叢舊態生。","唯奈瘴煙籠飲啄，可堪春雨滯飛鳴。","鴛鴦水畔迴頭羨，荳蔻圖前舉眼驚。","爭得鷓鴣來伴著，不妨還校有心情。"]', '["嬾移金翠傍簷楹，斜倚芳叢旧態生。","唯奈瘴煙籠饮啄，可堪春雨滯飞鳴。","鴛鴦水畔迴头羨，荳蔻圖前舉眼驚。","爭得鷓鴣来伴著，不妨還校有心情。"]', '诗', 'shi', '', NULL, '奉和襲美病孔雀 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26fbc610-4881-47dd-89be-cdb571e8367c', '上元日道室焚修寄襲美', '上元日道室焚修寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["三清今日聚靈官，玉刺齊抽謁廣寒。","執蓋冒花香寂歷，侍晨交佩響闌珊。","將排鳳節分階易，欲校龍書下筆難。","唯有世塵中小兆，夜來心拜七星壇。"]', '["三清今日聚靈官，玉刺齊抽謁廣寒。","執蓋冒花香寂歷，侍晨交佩响闌珊。","將排鳳節分階易，欲校龙书下笔难。","唯有世塵中小兆，夜来心拜七星壇。"]', '诗', 'shi', '', NULL, '上元日道室焚修寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5cce92-e418-490b-b2c9-466d980e70f4', '正月十五惜春寄襲美', '正月十五惜春寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["六分春色一分休，滿眼東波盡是愁。","花匠凝寒應束手，酒龍多病尚垂頭。","無窮嬾惰齊中散，有底機謀敵右侯。","見織短篷裁小檝，拿煙閑弄箇漁舟。"]', '["六分春色一分休，满眼东波尽是愁。","花匠凝寒應束手，酒龙多病尚垂头。","無窮嬾惰齊中散，有底機謀敵右侯。","见织短篷裁小檝，拿煙闲弄箇漁舟。"]', '诗', 'shi', '', NULL, '正月十五惜春寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d574758-645d-4e24-b3ab-06e3d6bccde1', '襲美病中聞余遊顔家園見寄次韻酬之', '襲美病中闻余游顔家园见寄次韻酬之', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["日華風蕙正交光，羯末相攜籍草塘。","佳酒旋傾醽醁嫩，短船閑弄木蘭香。","煙絲鳥拂來縈帶，蘂榼人收去約簧。","今日好爲聯句會，不成剛爲欠檀郎。"]', '["日华风蕙正交光，羯末相携籍草塘。","佳酒旋傾醽醁嫩，短船闲弄木蘭香。","煙絲鸟拂来縈带，蘂榼人收去約簧。","今日好爲聯句會，不成剛爲欠檀郎。"]', '诗', 'shi', '', NULL, '襲美病中聞余遊顔家園見寄次韻酬之 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1d44780-ce15-4c43-94bb-7ce74b759772', '春雨即事寄襲美', '春雨即事寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["小謝輕埃日日飛，城邊江上阻春暉。","雖愁野岸花房凍，還得山家藥笋肥。","雙屐著頻看齒折，敗裘披苦見毛稀。","比鄰釣叟無塵事，灑笠鳴蓑夜半歸。"]', '["小謝轻埃日日飞，城邊江上阻春暉。","雖愁野岸花房凍，還得山家藥笋肥。","雙屐著頻看齒折，敗裘披苦见毛稀。","比鄰釣叟無塵事，灑笠鳴蓑夜半归。"]', '诗', 'shi', '', NULL, '春雨即事寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89af9c4e-06b6-46a9-b994-023dd2679032', '奉和襲美抱疾杜門見寄次韻', '奉和襲美抱疾杜门见寄次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雖失春城醉上期，下帷裁徧未裁詩。","因吟郢岸百畝蕙，[欲]采商崖三秀枝。","棲野鶴籠寬使織，施山僧飯別教炊。","但醫沈約重瞳健，不怕江花不滿枝。"]', '["雖失春城醉上期，下帷裁徧未裁诗。","因吟郢岸百畝蕙，[欲]采商崖三秀枝。","棲野鹤籠寬使织，施山僧飯別教炊。","但醫沈約重瞳健，不怕江花不满枝。"]', '诗', 'shi', '', NULL, '奉和襲美抱疾杜門見寄次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d64f41f9-6b33-4410-b13c-04787501b254', '偶掇野蔬寄襲美有作', '偶掇野蔬寄襲美有作', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["野園煙裏自幽尋，嫩甲香蕤引漸深。","行歇每依鵶舅影，挑頻時見鼠姑心。","凌風藹彩初攜籠，帶露虛疎或貯襟。","欲助春盤還愛否，不妨蕭灑似家林。"]', '["野园煙裏自幽尋，嫩甲香蕤引漸深。","行歇每依鵶舅影，挑頻时见鼠姑心。","凌风藹彩初携籠，带露虛疎或貯襟。","欲助春盤還愛否，不妨蕭灑似家林。"]', '诗', 'shi', '', NULL, '偶掇野蔬寄襲美有作 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a22096-2cae-486f-b7ec-c529f4165ff1', '奉和襲美臥疾感春見寄次韻', '奉和襲美臥疾感春见寄次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["共尋花思極飛騰，病帶春寒去未能。","煙徑水涯多好鳥，竹牀蒲椅但高僧。","須知日富爲神授，秖有家貧免盜憎。","除却數函圖籍外，更將何事結良朋。"]', '["共尋花思極飞腾，病带春寒去未能。","煙徑水涯多好鸟，竹牀蒲椅但高僧。","須知日富爲神授，秖有家貧免盜憎。","除却數函圖籍外，更將何事結良朋。"]', '诗', 'shi', '', NULL, '奉和襲美臥疾感春見寄次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b97979fd-9237-4e6c-bf1e-6a940bf1f257', '徐方平後聞赦因寄襲美', '徐方平後闻赦因寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["新春旒扆御翬軒，海內初傳渙汗恩。","秦獄已收爲厲氣，瘴江初返未招魂。","英材盡作龍蛇蟄，戰地多成虎豹村。","除却數般傷痛外，不知何事及王孫。"]', '["新春旒扆御翬軒，海內初傳渙汗恩。","秦獄已收爲厲氣，瘴江初返未招魂。","英材尽作龙蛇蟄，戰地多成虎豹村。","除却數般傷痛外，不知何事及王孫。"]', '诗', 'shi', '', NULL, '徐方平後聞赦因寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb9bfd0-9781-4aa6-801d-a1c78f836be6', '襲美以魚牋見寄因謝成篇', '襲美以鱼牋见寄因謝成篇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["擣成霜粒細鱗鱗，知作愁吟喜見分。","向日乍驚新繭色，臨風時辨白萍文。","好將花下承金粉，堪送天邊詠碧雲。","見倚小窗親襞染，盡圖春色寄夫君。"]', '["擣成霜粒細鱗鱗，知作愁吟喜见分。","向日乍驚新繭色，臨风时辨白萍文。","好將花下承金粉，堪送天邊詠碧云。","见倚小窗親襞染，尽圖春色寄夫君。"]', '诗', 'shi', '', NULL, '襲美以魚牋見寄因謝成篇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b99aff-2d9e-4582-bc3a-e5148063df26', '次和襲美病後春思', '次和襲美病後春思', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["氣和靈府漸氤氳，酒有賢人藥有君。","七字篇章看月得，百勞言語傍花聞。","閑尋古寺消晴日，最憶深溪枕夜雲。","早晚共搖孤艇去，紫屏風外碧波文。"]', '["氣和靈府漸氤氳，酒有賢人藥有君。","七字篇章看月得，百勞言語傍花闻。","闲尋古寺消晴日，最憶深溪枕夜云。","早晚共搖孤艇去，紫屏风外碧波文。"]', '诗', 'shi', '', NULL, '次和襲美病後春思 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a96fa86-d57a-4917-9e79-202ffc475ed6', '襲美以公齋小宴見招因代書寄之', '襲美以公斋小宴见招因代书寄之', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["早雲纔破漏春陽，野客晨興喜又忙。","自與酌量煎藥水，別教安置曬書牀。","依方釀酒愁遲去，借樣裁巾怕索將。","唯待數般幽事了，不妨還入少年場。"]', '["早云纔破漏春陽，野客晨兴喜又忙。","自與酌量煎藥水，別教安置曬书牀。","依方釀酒愁遲去，借樣裁巾怕索將。","唯待數般幽事了，不妨還入少年場。"]', '诗', 'shi', '', NULL, '襲美以公齋小宴見招因代書寄之 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b98d39d0-afcf-43e7-9cb4-0a81f61d7af2', '京口', '京口', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["江干古渡傷離情，斷山零落春潮平。","東風料峭客帆遠，落葉夕陽天際明。","戰舸昔浮千騎去，釣舟今載一翁輕。","可憐宋帝籌帷處，蒼翠無煙草自生。"]', '["江干古渡傷離情，斷山零落春潮平。","东风料峭客帆远，落葉夕陽天際明。","戰舸昔浮千騎去，釣舟今載一翁轻。","可怜宋帝籌帷处，蒼翠無煙草自生。"]', '诗', 'shi', '', NULL, '京口 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b32a1de-0f10-4b71-b1ec-138aa2a73298', '潤州送人往長洲', '潤州送人往长洲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["秋來頻上向吳亭，每上思歸意剩生。","廢苑池臺煙裏色，夜村蓑笠雨中聲。","汀洲月下菱船疾，楊柳風高酒斾輕。","君住松江多少日，爲嘗鱸鱠與蓴羹。"]', '["秋来頻上向吳亭，每上思归意剩生。","廢苑池台煙裏色，夜村蓑笠雨中声。","汀洲月下菱船疾，楊柳风高酒斾轻。","君住松江多少日，爲嘗鱸鱠與蓴羹。"]', '诗', 'shi', '', NULL, '潤州送人往長洲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58056a54-5131-4dd3-ae83-7118e61e2d03', '潤州江口送人謁池陽衛郎中', '潤州江口送人謁池陽衛郎中', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山翁曾約舊交歡，須拂侯門側注冠。","月在石頭搖戍角，風生江口亞帆竿。","閑隨野醉溪聲鬧，獨伴清譚曉色殘。","待取新秋歸更好，九華蒼翠入樓寒。"]', '["山翁曾約旧交歡，須拂侯门側注冠。","月在石头搖戍角，风生江口亞帆竿。","闲隨野醉溪声鬧，独伴清譚晓色殘。","待取新秋归更好，九华蒼翠入楼寒。"]', '诗', 'shi', '', NULL, '潤州江口送人謁池陽衛郎中 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd9bc45-84a2-4167-a665-40fcad0d7485', '襲美以紗巾見惠繼以雅音因次韻酬謝', '襲美以紗巾见惠繼以雅音因次韻酬謝', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["薄如蟬翅背斜陽，不稱春前贈𦊔郎。","初覺頂寒生遠吹，預憂頭白透新霜。","堪窺水檻澄波影，好拂花牆亞蘂香。","知有芙蓉留自戴，欲峨煙霧訪黃房。"]', '["薄如蟬翅背斜陽，不稱春前贈𦊔郎。","初覺頂寒生远吹，預憂头白透新霜。","堪窺水檻澄波影，好拂花牆亞蘂香。","知有芙蓉留自戴，欲峨煙霧訪黄房。"]', '诗', 'shi', '', NULL, '襲美以紗巾見惠繼以雅音因次韻酬謝 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda9b159-4187-4385-acb2-4f63245ebc9f', '聞襲美有親迎之期因以寄賀', '闻襲美有親迎之期因以寄賀', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["梁鴻夫婦欲雙飛，細雨輕寒拂雉衣。","初下雪窗因眷戀，次乘煙幰奈光輝。","參差扇影分華月，斷續簫聲落翠微。","見說春風偏有賀，露花千朵照庭闈。"]', '["梁鴻夫婦欲雙飞，細雨轻寒拂雉衣。","初下雪窗因眷戀，次乘煙幰奈光輝。","參差扇影分华月，斷續簫声落翠微。","见说春风偏有賀，露花千朵照庭闈。"]', '诗', 'shi', '', NULL, '聞襲美有親迎之期因以寄賀 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44dde40-6356-4514-a255-3d7581decbcb', '襲美以巨魚之半見分因以酬謝', '襲美以巨鱼之半见分因以酬謝', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰與春江上信魚，可憐霜刃截來初。","鱗隳似撤騷人屋，腹斷疑傷遠客書。","避網幾跳山影破，逆風曾蹙浪花虛。","今朝最是家童喜，免泥荒畦掇野蔬。"]', '["誰與春江上信鱼，可怜霜刃截来初。","鱗隳似撤騷人屋，腹斷疑傷远客书。","避網幾跳山影破，逆风曾蹙浪花虛。","今朝最是家童喜，免泥荒畦掇野蔬。"]', '诗', 'shi', '', NULL, '襲美以巨魚之半見分因以酬謝 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('114b29ba-8b1e-4587-ba03-64819859287a', '奉和襲美館娃宮懷古次韻', '奉和襲美館娃宮懷古次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鏤楣消落濯春雨，蒼翠無言空斷崖。","草碧未能忘帝女，燕輕猶自識宮釵。","江山祗有愁容在，劒珮應和媿色埋。","賴在伍員騷思少，吳王纔免似荆懷。"]', '["鏤楣消落濯春雨，蒼翠無言空斷崖。","草碧未能忘帝女，燕轻猶自識宮釵。","江山祗有愁容在，劒珮應和媿色埋。","賴在伍員騷思少，吳王纔免似荆懷。"]', '诗', 'shi', '', NULL, '奉和襲美館娃宮懷古次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c54974c-54da-4ea6-b174-78096c428731', '同襲美遊北禪院', '同襲美游北禪院', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["連延花蔓映風廊，岸幘披襟到竹房。","居士祗今開梵處，先生曾是草玄堂。","清尊林下看香印，遠岫窗中挂鉢囊。","今日有情消未得，欲將名理問思光。"]', '["連延花蔓映风廊，岸幘披襟到竹房。","居士祗今开梵处，先生曾是草玄堂。","清尊林下看香印，远岫窗中挂鉢囊。","今日有情消未得，欲將名理问思光。"]', '诗', 'shi', '', NULL, '同襲美遊北禪院 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc899377-1490-41cc-b08f-d94a25741e38', '襲美以紫石硯見贈以詩迎之', '襲美以紫石硯见贈以诗迎之', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["霞骨堅來玉自愁，琢成飛燕古釵頭。","澄沙脆弱聞應伏，青鐵沈埋見亦羞。","最稱風亭批碧簡，好將雲竇漬寒流。","君能把贈閑吟客，徧寫江南物象酬。"]', '["霞骨堅来玉自愁，琢成飞燕古釵头。","澄沙脆弱闻應伏，青鐵沈埋见亦羞。","最稱风亭批碧簡，好將云竇漬寒流。","君能把贈闲吟客，徧寫江南物象酬。"]', '诗', 'shi', '', NULL, '襲美以紫石硯見贈以詩迎之 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('273cf284-b442-4d39-857f-7f924f97a400', '和襲美送孫發百篇遊天台', '和襲美送孫發百篇游天台', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["直應天授與詩情，百詠唯消一日成。","去把彩毫揮下國，歸參黃綬別春卿。","閑窺碧落懷煙霧，暫向金庭隱姓名。","珍重興公徒有賦，石梁深處是君行。"]', '["直應天授與诗情，百詠唯消一日成。","去把彩毫揮下国，归參黄綬別春卿。","闲窺碧落懷煙霧，暫向金庭隐姓名。","珍重兴公徒有賦，石梁深处是君行。"]', '诗', 'shi', '', NULL, '和襲美送孫發百篇遊天台 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81a71528-61bb-4d30-a217-d8391c8ea5a7', '奉和襲美聞開元寺開笋園寄章上人', '奉和襲美闻开元寺开笋园寄章上人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春龍爭地養檀欒，況是雙林雨後看。","迸出似毫當垤㙞，孤生如恨倚欄干。","凌虛勢欲齊金剎，折贈光宜照玉盤。","更得錦苞零落後，粉環高下挶煙寒。"]', '["春龙爭地養檀欒，況是雙林雨後看。","迸出似毫當垤㙞，孤生如恨倚欄干。","凌虛勢欲齊金剎，折贈光宜照玉盤。","更得錦苞零落後，粉环高下挶煙寒。"]', '诗', 'shi', '', NULL, '奉和襲美聞開元寺開笋園寄章上人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8df93b7-aafe-4e1b-aff5-86df9aca638d', '薔薇', '薔薇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["倚牆當戶自橫陳，致得貧家似不貧。","外布芳菲雖笑日，中含芒刺欲傷人。","清香往往生遙吹，狂蔓看看及四鄰。","遇有客來堪玩處，一端晴綺照煙新。"]', '["倚牆當戶自橫陳，致得貧家似不貧。","外布芳菲雖笑日，中含芒刺欲傷人。","清香往往生遙吹，狂蔓看看及四鄰。","遇有客来堪玩处，一端晴綺照煙新。"]', '诗', 'shi', '', NULL, '薔薇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460538a8-d323-4756-b234-6d3a60c757bf', '奉和襲美開元寺佛鉢詩', '奉和襲美开元寺佛鉢诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["空王初受逞神功，四鉢須臾現一重。","持次想添香積飯，覆時應帶步羅鍾。","光寒好照金毛鹿，響靜堪降白耳龍。","從此寶函香裏見，不須西去詣靈峰。"]', '["空王初受逞神功，四鉢須臾現一重。","持次想添香積飯，覆时應带步羅鍾。","光寒好照金毛鹿，响静堪降白耳龙。","從此寶函香裏见，不須西去詣靈峰。"]', '诗', 'shi', '', NULL, '奉和襲美開元寺佛鉢詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490d406d-f62d-4b7f-84ef-2c1a512197c7', '酬襲美夏首病愈見招次韻', '酬襲美夏首病愈见招次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雨多青合是垣衣，一幅蠻牋夜欵扉。","蕙帶又聞寬沈約，茅齋猶自憶王微。","方靈祗在君臣正，篆古須拋點畫肥。","除却伴談秋水外，野鷗何處更忘機。"]', '["雨多青合是垣衣，一幅蠻牋夜欵扉。","蕙带又闻寬沈約，茅斋猶自憶王微。","方靈祗在君臣正，篆古須拋点畫肥。","除却伴談秋水外，野鷗何处更忘機。"]', '诗', 'shi', '', NULL, '酬襲美夏首病愈見招次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409fb7ba-c1ad-4581-b878-cfdfd1965bec', '新夏東郊閑泛有懷襲美', '新夏东郊闲泛有懷襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["遲於春日好於秋，野客相攜上釣舟。","經略彴時冠暫亞，佩笭箵後帶頻搊。","蒹葭鷺起波搖笠，村落蠶眠樹挂鉤。","料得祗君能愛此，不爭煙水似封侯。"]', '["遲於春日好於秋，野客相携上釣舟。","經略彴时冠暫亞，佩笭箵後带頻搊。","蒹葭鷺起波搖笠，村落蠶眠樹挂鉤。","料得祗君能愛此，不爭煙水似封侯。"]', '诗', 'shi', '', NULL, '新夏東郊閑泛有懷襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6916b646-92a0-42d4-8712-e8cd8c0b0d24', '四月十五日道室書事寄襲美', '四月十五日道室书事寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["烏飯新炊芼臛香，道家齋日以爲常。","月苗杯舉存三洞，雲蘂函開叩九章。","一掬陽泉堪作雨，數銖秋石欲成霜。","可中值著雷平信，爲覓閑眠苦竹牀。"]', '["烏飯新炊芼臛香，道家斋日以爲常。","月苗杯舉存三洞，云蘂函开叩九章。","一掬陽泉堪作雨，數銖秋石欲成霜。","可中值著雷平信，爲覓闲眠苦竹牀。"]', '诗', 'shi', '', NULL, '四月十五日道室書事寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7236fa13-09b5-41ca-89b3-502cd7626eaa', '看壓新醅寄懷襲美', '看壓新醅寄懷襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曉壓糟牀漸有聲，旋如[荒]澗野泉清。","身前古態燻應出，世上愁痕滴合平。","飲啄斷年同鶴儉，風波終日看人爭。","尊中若使常能淥，兩綬通侯總強名。"]', '["晓壓糟牀漸有声，旋如[荒]澗野泉清。","身前古態燻應出，世上愁痕滴合平。","饮啄斷年同鹤儉，风波終日看人爭。","尊中若使常能淥，兩綬通侯總強名。"]', '诗', 'shi', '', NULL, '看壓新醅寄懷襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92d70db-4d9d-4f0e-9824-8d192e127ad5', '奉和襲美登初陽樓寄懷北平郎中', '奉和襲美登初陽楼寄懷北平郎中', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["遠窗浮檻亦成年，幾伴楊公白晝筵。","日暖煙花曾撲地，氣浮星象却歸天。","閑將水石侵軍壘，醉引笙歌上釣船。","無限恩波猶在目，東風吹起細漪漣。"]', '["远窗浮檻亦成年，幾伴楊公白晝筵。","日暖煙花曾撲地，氣浮星象却归天。","闲將水石侵軍壘，醉引笙歌上釣船。","無限恩波猶在目，东风吹起細漪漣。"]', '诗', 'shi', '', NULL, '奉和襲美登初陽樓寄懷北平郎中 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2840c59e-8415-40d2-b26b-427e3426aa03', '奉和夏初襲美見訪題小齋次韻', '奉和夏初襲美见訪題小斋次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["四鄰多是老農家，百樹雞桑半頃麻。","盡趁[晴]明修網架，每和煙雨掉繰車。","啼鸞偶坐身藏葉，餉婦歸來鬢有花。","不是對君吟復醉，更將何事送年華。"]', '["四鄰多是老農家，百樹雞桑半頃麻。","尽趁[晴]明修網架，每和煙雨掉繰车。","啼鸾偶坐身藏葉，餉婦归来鬢有花。","不是对君吟复醉，更將何事送年华。"]', '诗', 'shi', '', NULL, '奉和夏初襲美見訪題小齋次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec8b32f-f9e5-413b-b7fd-f6fa7b180847', '奉和襲美所居首夏水木尤清適然有作次韻', '奉和襲美所居首夏水木尤清適然有作次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["柿陰成列藥花空，却憶桐江下釣筒。","亦以魚蝦供熟鷺，近緣櫻笋識鄰翁。","閑分酒劑多還少，自記書籤白間紅。","更愛夜來風月好，轉思玄度對支公。"]', '["柿陰成列藥花空，却憶桐江下釣筒。","亦以鱼蝦供熟鷺，近緣櫻笋識鄰翁。","闲分酒劑多還少，自記书籤白间紅。","更愛夜来风月好，轉思玄度对支公。"]', '诗', 'shi', '', NULL, '奉和襲美所居首夏水木尤清適然有作次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5508557f-6b9d-4e70-b2d5-7b03223f97f4', '奉和襲美題達上人藥圃二首 一', '奉和襲美題達上人藥圃二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["藥味多從遠客齎，旋添花圃旋成畦。","三椏舊種根應異，九節初移葉尚低。","山莢便和幽澗石，水芝須帶本池泥。","從今直到清秋日，又有香苗幾番齊。"]', '["藥味多從远客齎，旋添花圃旋成畦。","三椏旧種根應異，九節初移葉尚低。","山莢便和幽澗石，水芝須带本池泥。","從今直到清秋日，又有香苗幾番齊。"]', '诗', 'shi', '', NULL, '奉和襲美題達上人藥圃二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f52ca4-1e94-48ee-b8f8-d0a7c07e1e56', '奉和襲美題達上人藥圃二首 二', '奉和襲美題達上人藥圃二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["淨名無語示清羸，藥草搜來喻更微。","一雨一風皆遂性，花開花落盡忘機。","教疏兔鏤金弦亂，自擁龍芻紫汞肥。","莫怪獨親幽圃坐，病容銷盡欲依歸。"]', '["淨名無語示清羸，藥草搜来喻更微。","一雨一风皆遂性，花开花落尽忘機。","教疏兔鏤金弦亂，自擁龙芻紫汞肥。","莫怪独親幽圃坐，病容銷尽欲依归。"]', '诗', 'shi', '', NULL, '奉和襲美題達上人藥圃二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f3dd2a8-e691-4a27-a8fb-2a7fb3273611', '奉和襲美懷華陽潤卿博士三首 一', '奉和襲美懷华陽潤卿博士三首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["幾降真官授隱書，洛公曾到夢中無。","眉間入靜三辰影，肘後通靈五嶽圖。","北洞樹形如曲蓋，東凹山色入薰爐。","金墟福地能容否，願作岡前蔣負芻。"]', '["幾降真官授隐书，洛公曾到梦中無。","眉间入静三辰影，肘後通靈五嶽圖。","北洞樹形如曲蓋，东凹山色入薰爐。","金墟福地能容否，願作岡前蔣負芻。"]', '诗', 'shi', '', NULL, '奉和襲美懷華陽潤卿博士三首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1923ae1e-9c18-4c18-9135-de2b8fff9473', '奉和襲美懷華陽潤卿博士三首 二', '奉和襲美懷华陽潤卿博士三首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["火景應難到洞宮，蕭閑堂冷任天風。","談玄麈尾拋雲底，服散龍胎在酒中。","有路還將赤城接，無泉不共紫河通。","奇編早晚教傳授，免以神仙問葛洪。"]', '["火景應难到洞宮，蕭闲堂冷任天风。","談玄麈尾拋云底，服散龙胎在酒中。","有路還將赤城接，無泉不共紫河通。","奇編早晚教傳授，免以神仙问葛洪。"]', '诗', 'shi', '', NULL, '奉和襲美懷華陽潤卿博士三首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be74ec29-dcd6-4cb7-b7e7-626c7cbfa76b', '奉和襲美懷華陽潤卿博士三首 三', '奉和襲美懷华陽潤卿博士三首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["終日焚香禮洞雲，更思琪樹轉勞神。","曾尋下泊常經月，不到中峰又累春。","仙道最高黃玉籙，暑天偏稱白綸巾。","清齋若見茅司命，乞取朱兒十二斤。"]', '["終日焚香禮洞云，更思琪樹轉勞神。","曾尋下泊常經月，不到中峰又累春。","仙道最高黄玉籙，暑天偏稱白綸巾。","清斋若见茅司命，乞取朱兒十二斤。"]', '诗', 'shi', '', NULL, '奉和襲美懷華陽潤卿博士三首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b40a3be-3820-484a-912d-c32789e5ecaf', '以竹夾膝寄贈襲美', '以竹夾膝寄贈襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["截得篔簹冷似龍，翠光橫在暑天中。","堪臨薤簟閑憑月，好向松窗臥跂風。","持贈敢齊青玉案，醉吟偏稱碧荷筒。","添君雅具教多著，爲著西齋譜一通。"]', '["截得篔簹冷似龙，翠光橫在暑天中。","堪臨薤簟闲憑月，好向松窗臥跂风。","持贈敢齊青玉案，醉吟偏稱碧荷筒。","添君雅具教多著，爲著西斋譜一通。"]', '诗', 'shi', '', NULL, '以竹夾膝寄贈襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e4c795-695c-457f-ab5e-b2b0e4f9ff83', '奉和襲美夏景無事因懷章來二上人次韻 一', '奉和襲美夏景無事因懷章来二上人次韻 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["簷外青陽有二梅，折來堪下凍醪杯。","高杉自欲生龍腦，小弁誰能寄鹿胎。","麗事肯教饒沈謝，談微何必減宗雷。","還聞擬結東林社，爭奈淵明醉不來。"]', '["簷外青陽有二梅，折来堪下凍醪杯。","高杉自欲生龙腦，小弁誰能寄鹿胎。","丽事肯教饒沈謝，談微何必減宗雷。","還闻擬結东林社，爭奈淵明醉不来。"]', '诗', 'shi', '', NULL, '奉和襲美夏景無事因懷章來二上人次韻 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e20449-dd3f-4148-ab13-f118b4a9253b', '奉和襲美夏景無事因懷章來二上人次韻 二', '奉和襲美夏景無事因懷章来二上人次韻 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["忽憶高僧坐夏堂，厭泉聲鬧笑雲忙。","山重海澹懷中印，月冷風微宿上方。","病後書求嵩少藥，定迴衣染貝多香。","何時更問逍遙義，五粒松陰半石牀。"]', '["忽憶高僧坐夏堂，厭泉声鬧笑云忙。","山重海澹懷中印，月冷风微宿上方。","病後书求嵩少藥，定迴衣染貝多香。","何时更问逍遙義，五粒松陰半石牀。"]', '诗', 'shi', '', NULL, '奉和襲美夏景無事因懷章來二上人次韻 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('019adac1-985d-4e12-8db7-3e961982b4fa', '頃自桐江得一釣車以襲美樂煙波之思因出以爲玩俄辱三篇復抒酬荅 一', '頃自桐江得一釣车以襲美乐煙波之思因出以爲玩俄辱三篇复抒酬荅 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["旋屈金鉤劈翠筠，手中盤作釣魚輪。","忘情不效孤醒客，有意閑窺百丈鱗。","雨似輕埃時一起，雲如高蓋強相親。","任他華轂低頭笑，此地終無覆敗人。"]', '["旋屈金鉤劈翠筠，手中盤作釣鱼輪。","忘情不效孤醒客，有意闲窺百丈鱗。","雨似轻埃时一起，云如高蓋強相親。","任他华轂低头笑，此地終無覆敗人。"]', '诗', 'shi', '', NULL, '頃自桐江得一釣車以襲美樂煙波之思因出以爲玩俄辱三篇復抒酬荅 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef56ddd4-d6c1-4ca9-ba42-327d4a8337ec', '頃自桐江得一釣車以襲美樂煙波之思因出以爲玩俄辱三篇復抒酬荅 二', '頃自桐江得一釣车以襲美乐煙波之思因出以爲玩俄辱三篇复抒酬荅 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曾招漁侶下清潯，獨繭初隨一錘深。","細輾煙華無轍跡，靜含風力有車音。","相呼野飯依芳草，迭和山歌逗遠林。","得失任渠但取樂，不曾生箇是非心。"]', '["曾招漁侶下清潯，独繭初隨一錘深。","細輾煙华無轍跡，静含风力有车音。","相呼野飯依芳草，迭和山歌逗远林。","得失任渠但取乐，不曾生箇是非心。"]', '诗', 'shi', '', NULL, '頃自桐江得一釣車以襲美樂煙波之思因出以爲玩俄辱三篇復抒酬荅 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('134a317c-5a66-4c9c-bdbe-818b82432e64', '頃自桐江得一釣車以襲美樂煙波之思因出以爲玩俄辱三篇復抒酬荅 三', '頃自桐江得一釣车以襲美乐煙波之思因出以爲玩俄辱三篇复抒酬荅 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["病來縣著脆緡絲，獨喜高情爲我持。","數幅尚凝煙雨態，三篇能賦蕙蘭詞。","雲深石靜閑眠穩，月上江平放溜遲。","第一莫教諳此境，倚天功業待君爲。"]', '["病来縣著脆緡絲，独喜高情爲我持。","數幅尚凝煙雨態，三篇能賦蕙蘭词。","云深石静闲眠穩，月上江平放溜遲。","第一莫教諳此境，倚天功業待君爲。"]', '诗', 'shi', '', NULL, '頃自桐江得一釣車以襲美樂煙波之思因出以爲玩俄辱三篇復抒酬荅 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a754f086-31f5-4c2a-a29e-75fb070935eb', '奉和襲美吳中書事寄漢南裴尚書', '奉和襲美吳中书事寄漢南裴尚书', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["風清地古帶前朝，遺事紛紛未寂寥。","三泖涼波魚蕝動，五茸春草雉媒嬌。","雲藏野寺分金剎，月在江樓倚玉簫。","不用懷歸忘此景，吳王看即奉弓招。"]', '["风清地古带前朝，遺事紛紛未寂寥。","三泖涼波鱼蕝动，五茸春草雉媒嬌。","云藏野寺分金剎，月在江楼倚玉簫。","不用懷归忘此景，吳王看即奉弓招。"]', '诗', 'shi', '', NULL, '奉和襲美吳中書事寄漢南裴尚書 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5ad378-7699-4492-b45a-96110cbafc10', '奉和襲美夏景沖澹偶作次韻二首 一', '奉和襲美夏景沖澹偶作次韻二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蟬雀參差在扇紗，竹襟輕利籜冠斜。","壚中有酒文園會，琴上無弦靖節家。","芝畹煙霞全覆穗，橘洲風浪半浮花。","閑思兩地忘名者，不信人間髪解華。"]', '["蟬雀參差在扇紗，竹襟轻利籜冠斜。","壚中有酒文园會，琴上無弦靖節家。","芝畹煙霞全覆穗，橘洲风浪半浮花。","闲思兩地忘名者，不信人间髪解华。"]', '诗', 'shi', '', NULL, '奉和襲美夏景沖澹偶作次韻二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad55be93-e9dc-4ee8-a0f5-6896930cd892', '奉和襲美夏景沖澹偶作次韻二首 二', '奉和襲美夏景沖澹偶作次韻二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["祗於池曲象山幽，便是瀟湘浸石樓。","斜拂芡盤輕鶩下，細穿菱線小鯢遊。","閑開茗焙嘗須徧，醉撥書帷臥始休。","莫道仙家無好爵，方諸還拜碧琳侯。"]', '["祗於池曲象山幽，便是瀟湘浸石楼。","斜拂芡盤轻鶩下，細穿菱線小鯢游。","闲开茗焙嘗須徧，醉撥书帷臥始休。","莫道仙家無好爵，方諸還拜碧琳侯。"]', '诗', 'shi', '', NULL, '奉和襲美夏景沖澹偶作次韻二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df43f52e-52ec-4c57-b642-55fc87bd68dc', '奉和襲美送李明府之任南海', '奉和襲美送李明府之任南海', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春盡之官直到秋，嶺雲深處凭瀧樓。","居人愛近沈珠浦，候吏多來拾翠洲。","賨稅盡應輸紫貝，蠻童多學佩金鉤。","知君不戀南枝久，拋却經冬白罽裘。"]', '["春尽之官直到秋，嶺云深处凭瀧楼。","居人愛近沈珠浦，候吏多来拾翠洲。","賨稅尽應輸紫貝，蠻童多学佩金鉤。","知君不戀南枝久，拋却經冬白罽裘。"]', '诗', 'shi', '', NULL, '奉和襲美送李明府之任南海 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed543462-e9fc-469f-90b3-be517207972c', '奉和襲美寄題羅浮軒轅先生所居', '奉和襲美寄題羅浮軒轅先生所居', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鼎成仙馭入崆峒，百世猶傳至道風。","暫應青詞爲穴鳳，却思丹徼伴冥鴻。","金公的的生爐際，瓊刃時時到夢中。","預恐浮山歸有日，載將雲室十洲東。"]', '["鼎成仙馭入崆峒，百世猶傳至道风。","暫應青词爲穴鳳，却思丹徼伴冥鴻。","金公的的生爐際，瓊刃时时到梦中。","預恐浮山归有日，載將云室十洲东。"]', '诗', 'shi', '', NULL, '奉和襲美寄題羅浮軒轅先生所居 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af29797-a15b-4015-9ce4-682121b3ea1e', '奉和襲美寄瓊州楊舍人', '奉和襲美寄瓊州楊舍人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["明時非罪謫何偏，鵩鳥巢南更數千。","酒滿椰杯消毒霧，風隨蕉葉下瀧船。","人多藥戶生狂蠱，吏有珠官出俸錢。","祗以直誠天自信，不勞詩句詠貪泉。"]', '["明时非罪謫何偏，鵩鸟巢南更數千。","酒满椰杯消毒霧，风隨蕉葉下瀧船。","人多藥戶生狂蠱，吏有珠官出俸錢。","祗以直誠天自信，不勞诗句詠貪泉。"]', '诗', 'shi', '', NULL, '奉和襲美寄瓊州楊舍人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2fa396d-70cd-45f4-8712-8ecdf94a9fab', '奉和襲美宿報恩寺水閣', '奉和襲美宿報恩寺水閣', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["峰抱池光曲岸平，月臨虛檻夜何清。","僧穿小檜纔分影，魚擲高荷漸有聲。","因憶故山吟易苦，各橫秋簟夢難成。","周顒不用裁書勸，自得涼天證道情。"]', '["峰抱池光曲岸平，月臨虛檻夜何清。","僧穿小檜纔分影，鱼擲高荷漸有声。","因憶故山吟易苦，各橫秋簟梦难成。","周顒不用裁书勸，自得涼天證道情。"]', '诗', 'shi', '', NULL, '奉和襲美宿報恩寺水閣 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('532d2568-d1e2-44bd-b718-bba17ccaca10', '奉和襲美醉中偶作見寄次韻', '奉和襲美醉中偶作见寄次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["海鶴飄飄韻莫儕，在公猶與俗情乖。","初呈酒務求專判，合禱山祠請自差。","永夜譚玄侵罔象，一生交態忘形骸。","憐君醉墨風流甚，幾度題詩小謝齋。"]', '["海鹤飄飄韻莫儕，在公猶與俗情乖。","初呈酒務求專判，合禱山祠請自差。","永夜譚玄侵罔象，一生交態忘形骸。","怜君醉墨风流甚，幾度題诗小謝斋。"]', '诗', 'shi', '', NULL, '奉和襲美醉中偶作見寄次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a46c38a2-3d88-431f-bc89-45e05935d057', '奉和襲美寄滑州李副使員外', '奉和襲美寄滑州李副使員外', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["洛生閑詠正抽毫，忽傍旌旗著戰袍。","檄下連營皆破膽，劒離孤匣欲吹毛。","清秋月色臨軍壘，半夜淮聲入賊壕。","除却征南爲上將，平徐功業更誰高。"]', '["洛生闲詠正抽毫，忽傍旌旗著戰袍。","檄下連營皆破膽，劒離孤匣欲吹毛。","清秋月色臨軍壘，半夜淮声入賊壕。","除却征南爲上將，平徐功業更誰高。"]', '诗', 'shi', '', NULL, '奉和襲美寄滑州李副使員外 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467bf2f1-bb36-42a2-b5ea-3db404c026c6', '奉和襲美吳中言懷寄南海二同年', '奉和襲美吳中言懷寄南海二同年', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曾見凌風上赤霄，盡將華藻赴嘉招。","城連虎踞山圖麗，路入龍編海舶遙。","江客漁歌衝白荇，野禽人語映紅蕉。","庭中必有君遷樹，莫向空臺望漢朝。"]', '["曾见凌风上赤霄，尽將华藻赴嘉招。","城連虎踞山圖丽，路入龙編海舶遙。","江客漁歌衝白荇，野禽人語映紅蕉。","庭中必有君遷樹，莫向空台望漢朝。"]', '诗', 'shi', '', NULL, '奉和襲美吳中言懷寄南海二同年 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d14540-c7ae-4459-8d6b-ec981019501a', '奉和襲美傷史拱山人', '奉和襲美傷史拱山人', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曾說山棲欲去尋，豈知霜骨葬寒林。","常依淨住師冥目，兼事容成學算心。","逋客預齋還梵唱，老猨窺祭亦悲吟。","唯君獨在江雲外，誰誄孤貞置峴岑。"]', '["曾说山棲欲去尋，豈知霜骨葬寒林。","常依淨住師冥目，兼事容成学算心。","逋客預斋還梵唱，老猨窺祭亦悲吟。","唯君独在江云外，誰誄孤貞置峴岑。"]', '诗', 'shi', '', NULL, '奉和襲美傷史拱山人 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d6db10-6db2-4a32-8d2d-7089da23db47', '白鷗詩', '白鷗诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["慣向溪頭漾淺沙，薄煙微雨是生涯。","時時失伴沈山影，往往爭飛雜浪花。","晚樹清涼還𪈺鳿，舊巢零落寄蒹葭。","池塘信美應難戀，針在魚脣劒在蝦。"]', '["慣向溪头漾淺沙，薄煙微雨是生涯。","时时失伴沈山影，往往爭飞杂浪花。","晚樹清涼還𪈺鳿，旧巢零落寄蒹葭。","池塘信美應难戀，針在鱼脣劒在蝦。"]', '诗', 'shi', '', NULL, '白鷗詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72bb2ea7-b273-4ce1-bc38-422bcbde17e6', '懷楊台文楊鼎文二秀才', '懷楊台文楊鼎文二秀才', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["秋早相逢待得春，崇蘭清露小山雲。","寒花獨自愁中見，曙角多同醒後聞。","釣具每隨輕舸去，詩題閑上小樓分。","重思醉墨縱橫甚，書破羊欣白練裙。"]', '["秋早相逢待得春，崇蘭清露小山云。","寒花独自愁中见，曙角多同醒後闻。","釣具每隨轻舸去，诗題闲上小楼分。","重思醉墨縱橫甚，书破羊欣白練裙。"]', '诗', 'shi', '', NULL, '懷楊台文楊鼎文二秀才 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc453316-379b-49b4-9de2-0396e35ba189', '奉和襲美謝友人惠人參', '奉和襲美謝友人惠人參', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["五葉初成椵樹陰，紫團峰外即雞林。","名參鬼蓋須難見，材似人形不可尋。","品第已聞升碧簡，攜持應合重黃金。","殷勤潤取相如肺，封禪書成動帝心。"]', '["五葉初成椵樹陰，紫團峰外即雞林。","名參鬼蓋須难见，材似人形不可尋。","品第已闻升碧簡，携持應合重黄金。","殷勤潤取相如肺，封禪书成动帝心。"]', '诗', 'shi', '', NULL, '奉和襲美謝友人惠人參 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ad0c6e-d439-4346-bee0-57b83a5af89d', '嚴子重以詩遊於名勝間舊矣余晚於江南相遇甚樂不幸且沒襲美作詩序而弔之其名真不朽矣又何戚其死哉余因息悲而爲之和', '嚴子重以诗游於名勝间旧矣余晚於江南相遇甚乐不幸且沒襲美作诗序而弔之其名真不朽矣又何戚其死哉余因息悲而爲之和', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["每值江南日落春，十年詩酒愛逢君。","芙蓉湖上吟船倚，翡翠巖前醉馬分。","祗有汀洲連舊業，豈無章疏動遺文。","猶憐未卜佳城處，更斸要離冢畔雲。"]', '["每值江南日落春，十年诗酒愛逢君。","芙蓉湖上吟船倚，翡翠巖前醉马分。","祗有汀洲連旧業，豈無章疏动遺文。","猶怜未卜佳城处，更斸要離冢畔云。"]', '诗', 'shi', '', NULL, '嚴子重以詩遊於名勝間舊矣余晚於江南相遇甚樂不幸且沒襲美作詩序而弔之其名真不朽矣又何戚其死哉余因息悲而爲之和 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e21b8768-2d97-429b-92dc-f8befa26acf2', '算山', '算山', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["水繞蒼山固護來，當時盤踞實雄才。","周郎計策清宵定，曹氏樓船白晝灰。","五十八年爭虎視，三千餘騎騁龍媒。","何如今日家天下，閶闔門臨萬國開。"]', '["水繞蒼山固護来，當时盤踞實雄才。","周郎計策清宵定，曹氏楼船白晝灰。","五十八年爭虎視，三千餘騎騁龙媒。","何如今日家天下，閶闔门臨万国开。"]', '诗', 'shi', '', NULL, '算山 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2cff7fa-913e-490e-8365-9e2d3f1f8f23', '寄茅山何威儀二首 一', '寄茅山何威儀二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["大小三峰次九華，靈蹤今盡屬何家。","漢時仙上雲巔鶴，蜀地春開洞底花。","閑傍積嵐尋瀑眼，便凌殘雪探芝芽。","年來已奉黃庭教，夕鍊腥魂曉吸霞。"]', '["大小三峰次九华，靈蹤今尽屬何家。","漢时仙上云巔鹤，蜀地春开洞底花。","闲傍積嵐尋瀑眼，便凌殘雪探芝芽。","年来已奉黄庭教，夕鍊腥魂晓吸霞。"]', '诗', 'shi', '', NULL, '寄茅山何威儀二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e9180ea-ea08-4dd1-b5c2-c03094b56ca9', '寄茅山何威儀二首 二', '寄茅山何威儀二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["曾向人間拜節旄，乍疑因夢到仙曹。","身輕曳羽霞襟狹，髻聳峨煙鹿幘高。","山暖不葷峰上薤，水寒仍落洞中桃。","從聞此日搜奇話，轉覺魂飛夜夜勞。"]', '["曾向人间拜節旄，乍疑因梦到仙曹。","身轻曳羽霞襟狹，髻聳峨煙鹿幘高。","山暖不葷峰上薤，水寒仍落洞中桃。","從闻此日搜奇話，轉覺魂飞夜夜勞。"]', '诗', 'shi', '', NULL, '寄茅山何威儀二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d151a909-8bb6-4341-9951-70a672da74e1', '早秋吳體寄襲美', '早秋吳體寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["荒庭古樹只獨倚，敗蟬殘蛩苦相仍。","雖然詩膽大如斗，爭奈愁腸牽似繩。","短燭初添蕙幌影，微風漸折蕉衣稜。","安得彎弓似明月，快箭拂下西飛鵬。"]', '["荒庭古樹只独倚，敗蟬殘蛩苦相仍。","雖然诗膽大如斗，爭奈愁腸牽似繩。","短燭初添蕙幌影，微风漸折蕉衣稜。","安得彎弓似明月，快箭拂下西飞鵬。"]', '诗', 'shi', '', NULL, '早秋吳體寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb032c2-5d1b-41ac-9d6c-d48aa32a2b8c', '病中秋懷寄襲美', '病中秋懷寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["病容愁思苦相兼，清鏡無形未我嫌。","貪廣異蔬行徑窄，故求偏藥出錢添。","同人散後休賒酒，雙燕辭來始下簾。","更有是非齊未得，重憑詹尹拂龜占。"]', '["病容愁思苦相兼，清镜無形未我嫌。","貪廣異蔬行徑窄，故求偏藥出錢添。","同人散後休賒酒，雙燕辞来始下簾。","更有是非齊未得，重憑詹尹拂龟占。"]', '诗', 'shi', '', NULL, '病中秋懷寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b0d224e-bb8b-4477-bf7b-c980b8206c17', '秋賦有期因寄襲美', '秋賦有期因寄襲美', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雲似無心水似閑，忽思名在貢書間。","煙霞鹿弁聊懸著，隣里漁舠暫解還。","文章病來猶滿篋，藥苗衰後即離山。","廣寒宮樹枝多少，風送高低便可攀。"]', '["云似無心水似闲，忽思名在貢书间。","煙霞鹿弁聊懸著，隣里漁舠暫解還。","文章病来猶满篋，藥苗衰後即離山。","廣寒宮樹枝多少，风送高低便可攀。"]', '诗', 'shi', '', NULL, '秋賦有期因寄襲美 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6c0b41-cc48-428d-b9b3-51035ff608f4', '和襲美新秋即事次韻三首 一', '和襲美新秋即事次韻三首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["心似孤雲任所之，世塵中更有誰知。","愁尋冷落驚雙鬢，病得清涼減四支。","懷舊藥溪終獨往，宿枯杉寺已頻期。","兼須爲月求高處，即是霜輪殺滿時。"]', '["心似孤云任所之，世塵中更有誰知。","愁尋冷落驚雙鬢，病得清涼減四支。","懷旧藥溪終独往，宿枯杉寺已頻期。","兼須爲月求高处，即是霜輪殺满时。"]', '诗', 'shi', '', NULL, '和襲美新秋即事次韻三首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12f24c5-a890-41f7-a3dc-3480b85dcd3c', '和襲美新秋即事次韻三首 二', '和襲美新秋即事次韻三首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["帆檝衣裳盡釣徒，往來蹤跡遍三吳。","閑中展卷興亡小，醉後題詩點畫麤。","松島伴譚多道氣，竹窗孤夢豈良圖。","還須待致昇平了，即往扁舟放五湖。"]', '["帆檝衣裳尽釣徒，往来蹤跡遍三吳。","闲中展卷兴亡小，醉後題诗点畫麤。","松島伴譚多道氣，竹窗孤梦豈良圖。","還須待致昇平了，即往扁舟放五湖。"]', '诗', 'shi', '', NULL, '和襲美新秋即事次韻三首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c962b38-6bce-4753-b3cf-048bce54a385', '和襲美新秋即事次韻三首 三', '和襲美新秋即事次韻三首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["聲利從來解破除，秋灘唯憶下桐廬。","鸕鷀陣合殘陽少，蜻蛚吟高冷雨疎。","辯伏南華論指指，才非玄晏借書書。","當時任使真堪笑，波上三年學炙魚。"]', '["声利從来解破除，秋灘唯憶下桐廬。","鸕鷀陣合殘陽少，蜻蛚吟高冷雨疎。","辯伏南华論指指，才非玄晏借书书。","當时任使真堪笑，波上三年学炙鱼。"]', '诗', 'shi', '', NULL, '和襲美新秋即事次韻三首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5738ff-f3f7-4f72-b910-a75b2fa7eb8d', '和襲美贈南陽潤卿將歸雷平', '和襲美贈南陽潤卿將归雷平', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["朝市山林隱一般，却歸那減臥雲懽。","墮階紅葉誰收得，半盎清醪客酹乾。","玉笈詩成吟處曉，金沙泉落夢中寒。","真仙若降如相問，曾步星罡繞醮壇。"]', '["朝市山林隐一般，却归那減臥云懽。","墮階紅葉誰收得，半盎清醪客酹乾。","玉笈诗成吟处晓，金沙泉落梦中寒。","真仙若降如相问，曾步星罡繞醮壇。"]', '诗', 'shi', '', NULL, '和襲美贈南陽潤卿將歸雷平 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ddb9f06-1635-473c-b3f9-0915f5a1ec71', '顧道士亡弟子奉束帛乞銘於襲美因賦戲贈', '顧道士亡弟子奉束帛乞銘於襲美因賦戲贈', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["童初真府召爲郎，君與抽毫刻便房。","亦謂神仙同許郭，不妨才力似班揚。","比於黃絹詞尤妙，酬以霜縑價未當。","唯我有文無賣處，筆鋒銷盡墨池荒。"]', '["童初真府召爲郎，君與抽毫刻便房。","亦謂神仙同許郭，不妨才力似班揚。","比於黄絹词尤妙，酬以霜縑價未當。","唯我有文無賣处，笔鋒銷尽墨池荒。"]', '诗', 'shi', '', NULL, '顧道士亡弟子奉束帛乞銘於襲美因賦戲贈 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2217476d-c89f-4e95-ad3d-df3bee779244', '和訪寂上人不遇', '和訪寂上人不遇', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["芭蕉霜後石欄荒，林下無人閉竹房。","經抄未成拋素几，錫環應撼過寒塘。","蒲團爲拂浮埃散，茶器空懷碧餑香。","早晚却還宗炳社，夜深風雪對禪牀。"]', '["芭蕉霜後石欄荒，林下無人閉竹房。","經抄未成拋素几，錫环應撼過寒塘。","蒲團爲拂浮埃散，茶器空懷碧餑香。","早晚却還宗炳社，夜深风雪对禪牀。"]', '诗', 'shi', '', NULL, '和訪寂上人不遇 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26ff9c6-4ffa-4713-8da6-c39f8be1a5a7', '秋夕文宴', '秋夕文宴', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["筆陣初臨夜正清，擊銅遙認小金鉦。","飛觥壯若遊燕市，覓句難於下趙城。","隔嶺故人因會憶，傍簷棲鳥帶吟驚。","梁王座上多詞客，五韻甘心第七成。"]', '["笔陣初臨夜正清，擊銅遙認小金鉦。","飞觥壯若游燕市，覓句难於下趙城。","隔嶺故人因會憶，傍簷棲鸟带吟驚。","梁王座上多词客，五韻甘心第七成。"]', '诗', 'shi', '', NULL, '秋夕文宴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8840cb38-a035-4530-b453-98b784e5e602', '南陽廣文欲於荆襄卜居襲美有贈代酬次韻', '南陽廣文欲於荆襄卜居襲美有贈代酬次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["不知天隱在何鄉，且欲煙霞跡暫雙。","鶴廟未能齊月馭，鹿門聊擬竝雲窗。","蘚銜荒磴移桑屐，花浸春醪挹石缸。","莫惜查頭容釣伴，也應東印有餘江。"]', '["不知天隐在何乡，且欲煙霞跡暫雙。","鹤廟未能齊月馭，鹿门聊擬竝云窗。","蘚銜荒磴移桑屐，花浸春醪挹石缸。","莫惜查头容釣伴，也應东印有餘江。"]', '诗', 'shi', '', NULL, '南陽廣文欲於荆襄卜居襲美有贈代酬次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00fd630-3095-4d37-b8b2-61c2171dd00d', '和襲美寄毗陵魏處士朴', '和襲美寄毗陵魏处士朴', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["經苑初成墨沼開，何人林下肯尋來。","若非宗測圖山後，即是韓康賣藥迴。","溪籟自吟朱鷺曲，沙雲還作白鷗媒。","唯應地主公田熟，時送君家麴糵材。"]', '["經苑初成墨沼开，何人林下肯尋来。","若非宗測圖山後，即是韓康賣藥迴。","溪籟自吟朱鷺曲，沙云還作白鷗媒。","唯應地主公田熟，时送君家麴糵材。"]', '诗', 'shi', '', NULL, '和襲美寄毗陵魏處士朴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96133537-50b0-4887-9246-10761044699c', '和襲美初冬偶作寄南陽潤卿次韻', '和襲美初冬偶作寄南陽潤卿次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["逐日生涯敢計冬，可嗟寒事落然空。","窗憐返照緣書小，庭喜新霜爲橘紅。","衰柳尚能和月動，敗蘭猶擬倩煙籠。","不知海上今清淺，試與飛書問洛公。"]', '["逐日生涯敢計冬，可嗟寒事落然空。","窗怜返照緣书小，庭喜新霜爲橘紅。","衰柳尚能和月动，敗蘭猶擬倩煙籠。","不知海上今清淺，試與飞书问洛公。"]', '诗', 'shi', '', NULL, '和襲美初冬偶作寄南陽潤卿次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af1c36d0-3132-4e77-b8d8-9cc94fb6852d', '和襲美冬曉章上人院', '和襲美冬晓章上人院', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山寒偏是曉來多，況值禪窗雪氣和。","病客功夫經未演，故人書信納新磨。","閑臨靜案修茶品，獨傍深溪記藥科。","從此逍遙知有地，更乘清月伴君過。"]', '["山寒偏是晓来多，況值禪窗雪氣和。","病客功夫經未演，故人书信納新磨。","闲臨静案修茶品，独傍深溪記藥科。","從此逍遙知有地，更乘清月伴君過。"]', '诗', 'shi', '', NULL, '和襲美冬曉章上人院 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50286144-17d7-4a36-99e9-876194149ee3', '和襲美寄題鏡巖周尊師所居', '和襲美寄題镜巖周尊師所居', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["見說身輕鶴不如，石房無侶共雲居。","清晨自削靈香柹，獨夜空吟碧落書。","十洞飛精應徧吸，一簪秋髪未曾梳。","知君便入懸珠會，早晚東騎白鯉魚。"]', '["见说身轻鹤不如，石房無侶共云居。","清晨自削靈香柹，独夜空吟碧落书。","十洞飞精應徧吸，一簪秋髪未曾梳。","知君便入懸珠會，早晚东騎白鯉鱼。"]', '诗', 'shi', '', NULL, '和襲美寄題鏡巖周尊師所居 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af758bb-6918-4ed7-bebe-d9b23c981c5b', '寒夜文宴得驚字', '寒夜文宴得驚字', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["各將寒調觸詩情，旋見微澌入硯生。","霜月滿庭人暫起，汀洲半夜雁初驚。","三秋每爲仙題想，一日多因累句傾。","千里建康衰草外，含毫誰是憶昭明。"]', '["各將寒調觸诗情，旋见微澌入硯生。","霜月满庭人暫起，汀洲半夜雁初驚。","三秋每爲仙題想，一日多因累句傾。","千里建康衰草外，含毫誰是憶昭明。"]', '诗', 'shi', '', NULL, '寒夜文宴得驚字 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3888b080-f059-4c2f-a0b9-251a9796cd20', '送潤卿還華陽', '送潤卿還华陽', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["何事輕舟近臘回，茅家兄弟欲歸來。","封題玉洞虛無奏，點檢霜壇沆瀣杯。","雲肆先生分氣調，山圖公子愛詞才。","殷勤爲向東鄉薦，灑掃含真雪後臺。"]', '["何事轻舟近臘回，茅家兄弟欲归来。","封題玉洞虛無奏，点檢霜壇沆瀣杯。","云肆先生分氣調，山圖公子愛词才。","殷勤爲向东乡薦，灑掃含真雪後台。"]', '诗', 'shi', '', NULL, '送潤卿還華陽 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4682701c-4aa7-48e5-a603-16f6c3187c9f', '和襲美爲新羅弘惠上人撰靈鷲山周禪師碑送歸詩', '和襲美爲新羅弘惠上人撰靈鷲山周禪師碑送归诗', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一函迢遞過東瀛，祗爲先生處乞銘。","已得雄詞封靜檢，却懷孤影在禪庭。","春過異國人應寫，夜讀滄洲怪亦聽。","遙想勒成新塔下，盡望空碧禮文星。"]', '["一函迢遞過东瀛，祗爲先生处乞銘。","已得雄词封静檢，却懷孤影在禪庭。","春過異国人應寫，夜读滄洲怪亦听。","遙想勒成新塔下，尽望空碧禮文星。"]', '诗', 'shi', '', NULL, '和襲美爲新羅弘惠上人撰靈鷲山周禪師碑送歸詩 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5767520f-698f-41f6-b0c9-03ce46dda5ea', '和襲美寒日書齋即事三首每篇各用一韻 一', '和襲美寒日书斋即事三首每篇各用一韻 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["不必探幽上鬱岡，公齋吟嘯亦何妨。","唯求薏苡供僧食，別著氍毹待客牀。","春近帶煙分短蕙，曉來衝雪撼疎篁。","餘杭山酒猶封在，遙囑高人未肯嘗。"]', '["不必探幽上鬱岡，公斋吟嘯亦何妨。","唯求薏苡供僧食，別著氍毹待客牀。","春近带煙分短蕙，晓来衝雪撼疎篁。","餘杭山酒猶封在，遙囑高人未肯嘗。"]', '诗', 'shi', '', NULL, '和襲美寒日書齋即事三首每篇各用一韻 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4181c1b1-ffc9-406d-a3e9-36eab8a374e6', '和襲美寒日書齋即事三首每篇各用一韻 二', '和襲美寒日书斋即事三首每篇各用一韻 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["已上星津八月槎，文通猶自學丹砂。","仙經寫得空三洞，隱士招來別九華。","靜對真圖呼綠齒，偶開神室問黃芽。","方諸更是憐才子，錫賚於君合有差。"]', '["已上星津八月槎，文通猶自学丹砂。","仙經寫得空三洞，隐士招来別九华。","静对真圖呼綠齒，偶开神室问黄芽。","方諸更是怜才子，錫賚於君合有差。"]', '诗', 'shi', '', NULL, '和襲美寒日書齋即事三首每篇各用一韻 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ab42e3-b369-47d2-b409-76fa48f49e1e', '和襲美寒日書齋即事三首每篇各用一韻 三', '和襲美寒日书斋即事三首每篇各用一韻 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["名價皆酬百萬餘，尚憐方丈講玄虛。","西都賓問曾成賦，東海人求近著書。","茅洞煙霞侵寤寐，檀溪風月挂樵漁。","清朝還要廷臣在，兩地寧容便結廬。"]', '["名價皆酬百万餘，尚怜方丈講玄虛。","西都賓问曾成賦，东海人求近著书。","茅洞煙霞侵寤寐，檀溪风月挂樵漁。","清朝還要廷臣在，兩地寧容便結廬。"]', '诗', 'shi', '', NULL, '和襲美寒日書齋即事三首每篇各用一韻 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a1c8e76-e87d-432f-8040-4a5735e25ed5', '和襲美臘後送內大德從朂遊天台', '和襲美臘後送內大德從朂游天台', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["應緣南國盡南宗，欲訪靈溪路暗通。","歸思不離雙闕下，去程猶在四明東。","銅缾淨貯桃花雨，金策閑搖麥穗風。","若戀吾君先拜疏，爲論台嶽未封公。"]', '["應緣南国尽南宗，欲訪靈溪路暗通。","归思不離雙闕下，去程猶在四明东。","銅缾淨貯桃花雨，金策闲搖麦穗风。","若戀吾君先拜疏，爲論台嶽未封公。"]', '诗', 'shi', '', NULL, '和襲美臘後送內大德從朂遊天台 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366c7400-a019-4cce-b576-bac90d4566d2', '和襲美寄題玉霄峰葉涵象尊師所居', '和襲美寄題玉霄峰葉涵象尊師所居', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["天台一萬八千丈，師在浮雲端掩扉。","永夜祗知星斗大，深秋猶見海山微。","風前幾降青毛節，雪後應披白羽衣。","南望煙霞空再拜，欲將飛魄問靈威。"]', '["天台一万八千丈，師在浮云端掩扉。","永夜祗知星斗大，深秋猶见海山微。","风前幾降青毛節，雪後應披白羽衣。","南望煙霞空再拜，欲將飞魄问靈威。"]', '诗', 'shi', '', NULL, '和襲美寄題玉霄峰葉涵象尊師所居 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7a06e7-3b0b-48ce-923b-bae94930cb7b', '南陽廣文博士還雷平後寄', '南陽廣文博士還雷平後寄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["微微春色染林塘，親撥煙霞坐澗房。","陰洞雪膠知未入，濁醪風破的偷嘗。","芝臺曉用金鐺煮，星度閑將玉鉿量。","幾遍侍晨官欲降，曙壇先起獨焚香。"]', '["微微春色染林塘，親撥煙霞坐澗房。","陰洞雪膠知未入，濁醪风破的偷嘗。","芝台晓用金鐺煮，星度闲將玉鉿量。","幾遍侍晨官欲降，曙壇先起独焚香。"]', '诗', 'shi', '', NULL, '南陽廣文博士還雷平後寄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed715843-d7f4-4dd1-b943-37fab8d3bdf0', '和襲美題支山南峰僧次韻', '和襲美題支山南峰僧次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["眉毫霜細欲垂肩，自說初棲海嶽年。","萬壑煙霞秋後到，一林風雨夜深禪。","時翻貝葉添新藏，間插松枝護小泉。","好是清冬無外事，匡林齋罷向陽眠。"]', '["眉毫霜細欲垂肩，自说初棲海嶽年。","万壑煙霞秋後到，一林风雨夜深禪。","时翻貝葉添新藏，间插松枝護小泉。","好是清冬無外事，匡林斋罷向陽眠。"]', '诗', 'shi', '', NULL, '和襲美題支山南峰僧次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1897f41-d2ed-4e8c-9a2a-a4ddafc45a5e', '送董少卿遊茅山', '送董少卿游茅山', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["威輦高懸度世名，至今仙裔作公卿。","將隨羽節朝珠闕，曾佩魚符管赤城。","雲凍尚含孤石色，雪乾猶墮古松聲。","應知四扇靈方在，待取歸時綠髪生。"]', '["威輦高懸度世名，至今仙裔作公卿。","將隨羽節朝珠闕，曾佩鱼符管赤城。","云凍尚含孤石色，雪乾猶墮古松声。","應知四扇靈方在，待取归时綠髪生。"]', '诗', 'shi', '', NULL, '送董少卿遊茅山 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35038eec-a2e7-400a-a17b-f72b2384dcdd', '和襲美寄懷南陽潤卿', '和襲美寄懷南陽潤卿', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["高抱相逢各絕塵，水經山疏不離身。","才情未擬湯從事，玄解猶嫌竺道人。","霞染洞泉渾變紫，雪披江樹半和春。","誰憐故國無生計，唯種南塘二畝芹。"]', '["高抱相逢各絕塵，水經山疏不離身。","才情未擬湯從事，玄解猶嫌竺道人。","霞染洞泉渾变紫，雪披江樹半和春。","誰怜故国無生計，唯種南塘二畝芹。"]', '诗', 'shi', '', NULL, '和襲美寄懷南陽潤卿 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8befe67e-6ebc-480c-9a7c-84abec45ec47', '襲美將以綠罽爲贈因成四韻', '襲美將以綠罽爲贈因成四韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["三逕風霜若利刀，襜褕吹斷罥蓬蒿。","病中祗自悲龍具，世上何人識羽袍。","狐貉近懷珠履貴，薜蘿遙羨白巾高。","陳王輕煖如相遺，免致衰荷效廣騷。"]', '["三逕风霜若利刀，襜褕吹斷罥蓬蒿。","病中祗自悲龙具，世上何人識羽袍。","狐貉近懷珠履貴，薜蘿遙羨白巾高。","陳王轻煖如相遺，免致衰荷效廣騷。"]', '诗', 'shi', '', NULL, '襲美將以綠罽爲贈因成四韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3513bc24-80b0-4d61-b65b-0f5b44d7c34e', '和過張祜處士丹陽故居', '和過張祜处士丹陽故居', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["勝華通子共悲辛，荒逕今爲舊宅鄰。","一代交遊非不貴，五湖風月合教貧。","魂應絕地爲才鬼，名與遺編在史臣。","聞道平生多愛石，至今猶泣洞庭人。"]', '["勝华通子共悲辛，荒逕今爲旧宅鄰。","一代交游非不貴，五湖风月合教貧。","魂應絕地爲才鬼，名與遺編在史臣。","闻道平生多愛石，至今猶泣洞庭人。"]', '诗', 'shi', '', NULL, '和過張祜處士丹陽故居 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be6d3bbc-065a-4034-9a07-e69dc1a38b99', '和襲美寄廣文先生', '和襲美寄廣文先生', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["忽辭明主事真君，直取姜巴路入雲。","龍篆拜時輕誥命，霓襟披後小玄纁。","峰前北帝三元會，石上東卿九錫文。","應笑世間名利火，等閑靈府剩先焚。"]', '["忽辞明主事真君，直取姜巴路入云。","龙篆拜时轻誥命，霓襟披後小玄纁。","峰前北帝三元會，石上东卿九錫文。","應笑世间名利火，等闲靈府剩先焚。"]', '诗', 'shi', '', NULL, '和襲美寄廣文先生 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8a454d-172a-4d1b-b025-d93d7f2740b1', '和襲美先輩悼鶴', '和襲美先輩悼鹤', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一夜圓吭絕不鳴，八公虛道得千齡。","方添上客雲眠思，忽伴中仙劒解形。","但掩叢毛穿古堞，永留寒影在空屏。","君才幸自清如水，更向芝田爲刻銘。"]', '["一夜圓吭絕不鳴，八公虛道得千齡。","方添上客云眠思，忽伴中仙劒解形。","但掩叢毛穿古堞，永留寒影在空屏。","君才幸自清如水，更向芝田爲刻銘。"]', '诗', 'shi', '', NULL, '和襲美先輩悼鶴 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906627d5-30e9-4ed3-adeb-3de852f9be50', '幽居有白菊一叢因而成詠呈知己', '幽居有白菊一叢因而成詠呈知己', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["還是延年一種材，即將瑤朵冒霜開。","不如紅豔臨歌扇，欲伴黃英入酒杯。","陶令接䍦堪岸著，梁王高屋好欹來。","月中若有閑田地，爲勸嫦娥作意裁。"]', '["還是延年一種材，即將瑤朵冒霜开。","不如紅豔臨歌扇，欲伴黄英入酒杯。","陶令接䍦堪岸著，梁王高屋好欹来。","月中若有闲田地，爲勸嫦娥作意裁。"]', '诗', 'shi', '', NULL, '幽居有白菊一叢因而成詠呈知己 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ae32de-dca8-445a-bb0a-ec2d3730c1b3', '和襲美傷開元觀顧道士', '和襲美傷开元观顧道士', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["何事神超入杳冥，不騎孤鶴上三清。","多應白簡迎將去，即是朱陵鍊更生。","藥奠肯同椒醑味，雲謠空替薤歌聲。","武皇徒有飄飄思，誰問山中宰相名。"]', '["何事神超入杳冥，不騎孤鹤上三清。","多應白簡迎將去，即是朱陵鍊更生。","藥奠肯同椒醑味，云謠空替薤歌声。","武皇徒有飄飄思，誰问山中宰相名。"]', '诗', 'shi', '', NULL, '和襲美傷開元觀顧道士 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ab151d-4d19-4e8a-a5d3-e5cf10d7165e', '和襲美醉中即席贈潤卿博士次韻', '和襲美醉中即席贈潤卿博士次韻', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["共是虛皇簡上仙，清詞如羽欲飄然。","登山凡著幾緉屐，破浪欲乘千里船。","遠夢只留丹井畔，閑吟多在酒旗前。","誰知海上無名者，只記漁歌不記年。"]', '["共是虛皇簡上仙，清词如羽欲飄然。","登山凡著幾緉屐，破浪欲乘千里船。","远梦只留丹井畔，闲吟多在酒旗前。","誰知海上無名者，只記漁歌不記年。"]', '诗', 'shi', '', NULL, '和襲美醉中即席贈潤卿博士次韻 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f36695-b98f-4596-a3e9-505968f80136', '送浙東德師侍御罷府西歸', '送浙东德師侍御罷府西归', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["王謝遺蹤玉籍仙，三年閑上鄂君船。","詩懷白閣僧吟苦，俸買青田鶴價偏。","行次野楓臨遠水，醉中衰菊臥涼煙。","芙蓉散盡西歸去，唯有山陰九萬牋。"]', '["王謝遺蹤玉籍仙，三年闲上鄂君船。","诗懷白閣僧吟苦，俸買青田鹤價偏。","行次野楓臨远水，醉中衰菊臥涼煙。","芙蓉散尽西归去，唯有山陰九万牋。"]', '诗', 'shi', '', NULL, '送浙東德師侍御罷府西歸 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29ab8ef-1fd5-4d03-996f-6954fc59f25e', '送羊振文先輩往桂陽歸覲', '送羊振文先輩往桂陽归覲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["風雅先生去一麾，過庭才子趣歸期。","讓王門外開帆葉，義帝城中望戟支。","郢路漸寒飄雪遠，湘波初暖漲雲遲。","靈均精魄如能問，又得千年賈傅詞。"]', '["风雅先生去一麾，過庭才子趣归期。","讓王门外开帆葉，義帝城中望戟支。","郢路漸寒飄雪远，湘波初暖漲云遲。","靈均精魄如能问，又得千年賈傅词。"]', '诗', 'shi', '', NULL, '送羊振文先輩往桂陽歸覲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c3ca97-cd38-4bea-9d76-449daa688f33', '襲美留振文宴龜蒙抱病不赴猥示倡和因次韻酬謝', '襲美留振文宴龟蒙抱病不赴猥示倡和因次韻酬謝', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["綺席風開照露晴，祗將茶荈代雲觥。","繁弦似玉紛紛碎，佳妓如鴻一一驚。","毫健幾多飛藻客，羽寒寥落映花鶯。","幽人獨自西窗晚，閑凭香檉反照明。"]', '["綺席风开照露晴，祗將茶荈代云觥。","繁弦似玉紛紛碎，佳妓如鴻一一驚。","毫健幾多飞藻客，羽寒寥落映花鶯。","幽人独自西窗晚，闲凭香檉反照明。"]', '诗', 'shi', '', NULL, '襲美留振文宴龜蒙抱病不赴猥示倡和因次韻酬謝 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c241efaf-36b9-4e77-baba-b79607613cbd', '和襲美重送圓載上人歸日本國', '和襲美重送圓載上人归日本国', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["老思東極舊巖扉，却待秋風泛舶歸。","曉梵陽烏當石磬，夜禪陰火照田衣。","見翻經論多盈篋，親植杉松大幾圍。","遙想到時思魏闕，只應遙拜望斜暉。"]', '["老思东極旧巖扉，却待秋风泛舶归。","晓梵陽烏當石磬，夜禪陰火照田衣。","见翻經論多盈篋，親植杉松大幾圍。","遙想到时思魏闕，只應遙拜望斜暉。"]', '诗', 'shi', '', NULL, '和襲美重送圓載上人歸日本國 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ae61f4-2c69-478d-a990-2fc359511130', '和襲美褚家林亭', '和襲美褚家林亭', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["一陣西風起浪花，繞欄杆下散瑤華。","高窗曲檻仙侯府，臥葦荒芹白鳥家。","孤島待寒凝片月，遠山終日送餘霞。","若知方外還如此，不要秋乘上海槎。"]', '["一陣西风起浪花，繞欄杆下散瑤华。","高窗曲檻仙侯府，臥葦荒芹白鸟家。","孤島待寒凝片月，远山終日送餘霞。","若知方外還如此，不要秋乘上海槎。"]', '诗', 'shi', '', NULL, '和襲美褚家林亭 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3fe13c6-a425-41a7-bfa0-496d379024dc', '歸雁', '归雁', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["北走南征象我曹，天涯迢遞翼應勞。","似悲邊雪音猶苦，初背岳雲行未高。","月島聚栖防暗繳，風灘斜起避驚濤。","時人不問隨陽意，空拾欄邊翡翠毛。"]', '["北走南征象我曹，天涯迢遞翼應勞。","似悲邊雪音猶苦，初背岳云行未高。","月島聚栖防暗繳，风灘斜起避驚濤。","时人不问隨陽意，空拾欄邊翡翠毛。"]', '诗', 'shi', '', NULL, '歸雁 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8adf049e-d5b6-4528-a57b-37f25a89ea6c', '王先輩草堂', '王先輩草堂', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["松逕隈雲到靜堂，杏花臨澗水流香。","身從亂後全家隱，日校人間一倍長。","金籙漸加新品秩，玉皇偏賜羽衣裳。","何如聖代彈冠出，方朔曾爲漢侍郎。"]', '["松逕隈云到静堂，杏花臨澗水流香。","身從亂後全家隐，日校人间一倍长。","金籙漸加新品秩，玉皇偏賜羽衣裳。","何如聖代彈冠出，方朔曾爲漢侍郎。"]', '诗', 'shi', '', NULL, '王先輩草堂 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3d9685-5fca-49a7-8271-5222a935607a', '傷越', '傷越', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["越谿自古好風煙，盜束兵纏已半年。","訪戴客愁隨水遠，浣紗人泣共埃捐。","臨焦賴灑王師雨，欲墮重登刺史天。","早晚山川盡如故，清吟閑上鄂君船。"]', '["越谿自古好风煙，盜束兵纏已半年。","訪戴客愁隨水远，浣紗人泣共埃捐。","臨焦賴灑王師雨，欲墮重登刺史天。","早晚山川尽如故，清吟闲上鄂君船。"]', '诗', 'shi', '', NULL, '傷越 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4dfcf93-708b-46a6-8e25-785fcfaa810e', '新定陪太守一百五夜南館玩月', '新定陪太守一百五夜南館玩月', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["風雨教春處處傷，一宵雲盡見滄浪。","全無片燭侵光彩，只有清灘助雪霜。","煙蔽櫂歌歸浦潊，露將花影到衣裳。","却嫌殷浩南樓夕，一帶秋聲入恨長。"]', '["风雨教春处处傷，一宵云尽见滄浪。","全無片燭侵光彩，只有清灘助雪霜。","煙蔽櫂歌归浦潊，露將花影到衣裳。","却嫌殷浩南楼夕，一带秋声入恨长。"]', '诗', 'shi', '', NULL, '新定陪太守一百五夜南館玩月 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528aba2d-6a4f-4835-8ca3-00c3f8e726a3', '中元夜寄道侶二首 一', '中元夜寄道侶二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["學餌霜茸骨未輕，每逢真夕夢還清。","丁寧獨受金妃約，許與親題玉篆名。","月苦撼殘臨水珮，風微飄斷繫雲纓。","須臾枕上桐窗曉，露壓千枝滴滴聲。"]', '["学餌霜茸骨未轻，每逢真夕梦還清。","丁寧独受金妃約，許與親題玉篆名。","月苦撼殘臨水珮，风微飄斷繫云纓。","須臾枕上桐窗晓，露壓千枝滴滴声。"]', '诗', 'shi', '', NULL, '中元夜寄道侶二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0ffd0d-ece9-4fcf-80d6-6b3492952078', '中元夜寄道侶二首 二', '中元夜寄道侶二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["橘齋風露已清餘，東郭先生病未除。","孤枕易爲蛩破夢，短簷難得燕傳書。","廣雲披日君應近，倒影裁花我尚疎。","唯羨羽人襟似水，平持旄節步空虛。"]', '["橘斋风露已清餘，东郭先生病未除。","孤枕易爲蛩破梦，短簷难得燕傳书。","廣云披日君應近，倒影裁花我尚疎。","唯羨羽人襟似水，平持旄節步空虛。"]', '诗', 'shi', '', NULL, '中元夜寄道侶二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9565a1-1447-4ffd-b16d-c9bedd28febc', '寄懷華陽道士', '寄懷华陽道士', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["華陽門外五芝生，飡罷愁君入杳冥。","遙夜獨栖還有夢，昔年相見便忘形。","爲分科斗親鉛槧，與說蜉蝣坐竹櫺。","醮後幾時歸紫閣，別來終日誦黃庭。","閑教辨藥僮名甲，靜識窺巢鶴姓丁。","絕澗飲羊春水膩，傍林燒石野煙腥。","深沈谷響含疎磬，片段嵐光落畫屏。","休採古書探禹穴，自刊新曆鬬堯蓂。","珠宮鳳合迎蕭史，玉籍人誰訪蔡經。","架上黑椽長褐穩，案頭丹篆小符靈。","霓軒入洞齊初月，羽節升壇拜七星。","當路獨行衝虎豹，向風孤嘯起雷庭。","凝神密室多生白，敘事聊編盡殺青。","匝地山川皆暗寫，隱天竽籟祗閑聽。","分張火力燒金竈，拂拭苔痕洗酒缾。","翠壁上吟朝復暮，暖雲邊臥醉還醒。","倚身長短裁筇杖，倩客高低結草亭。","直用森嚴朝北帝，愛將清淺問東溟。","常思近圃看栽杏，擬借鄰峰伴采苓。","揜樹半扉晴靄靄，背琴殘燭曉熒熒。","舊來捫虱知王猛，欲去爲龍歎管寧。","蟾魄幾應臨蕙帳，漁竿猶尚枕楓汀。","銜煙細草無端綠，冒雨閑花作意馨。","掠岸驚波沈翡翠，入簷斜照礙蜻蜓。","初征漢棧宜飛檄，待破燕山好勒銘。","六轡未收千里馬，一囊空負九秋螢。","我悲雌伏真方枘，他騁雄材似建瓴。","合在深崖齊散朮，自求滄海點流萍。","頻拋俗物心還爽，遠憶幽期目剩暝。","見買扁舟束真誥，手披仙語任揚舲。"]', '["华陽门外五芝生，飡罷愁君入杳冥。","遙夜独栖還有梦，昔年相见便忘形。","爲分科斗親鉛槧，與说蜉蝣坐竹櫺。","醮後幾时归紫閣，別来終日誦黄庭。","闲教辨藥僮名甲，静識窺巢鹤姓丁。","絕澗饮羊春水膩，傍林燒石野煙腥。","深沈谷响含疎磬，片段嵐光落畫屏。","休採古书探禹穴，自刊新曆鬬堯蓂。","珠宮鳳合迎蕭史，玉籍人誰訪蔡經。","架上黑椽长褐穩，案头丹篆小符靈。","霓軒入洞齊初月，羽節升壇拜七星。","當路独行衝虎豹，向风孤嘯起雷庭。","凝神密室多生白，敘事聊編尽殺青。","匝地山川皆暗寫，隐天竽籟祗闲听。","分張火力燒金竈，拂拭苔痕洗酒缾。","翠壁上吟朝复暮，暖云邊臥醉還醒。","倚身长短裁筇杖，倩客高低結草亭。","直用森嚴朝北帝，愛將清淺问东溟。","常思近圃看栽杏，擬借鄰峰伴采苓。","揜樹半扉晴靄靄，背琴殘燭晓熒熒。","旧来捫虱知王猛，欲去爲龙歎管寧。","蟾魄幾應臨蕙帳，漁竿猶尚枕楓汀。","銜煙細草無端綠，冒雨闲花作意馨。","掠岸驚波沈翡翠，入簷斜照礙蜻蜓。","初征漢棧宜飞檄，待破燕山好勒銘。","六轡未收千里马，一囊空負九秋螢。","我悲雌伏真方枘，他騁雄材似建瓴。","合在深崖齊散朮，自求滄海点流萍。","頻拋俗物心還爽，远憶幽期目剩暝。","见買扁舟束真誥，手披仙語任揚舲。"]', '诗', 'shi', '', NULL, '寄懷華陽道士 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56db3b4-dc7f-4e8c-962b-954bb76e6954', '人日代客子', '人日代客子', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["人日兼春日，長懷復短懷。","遙知雙綵勝，併在一金釵。"]', '["人日兼春日，长懷复短懷。","遙知雙綵勝，併在一金釵。"]', '诗', 'shi', '', NULL, '人日代客子 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbbde73f-b005-4c1d-a416-01571d9d2ae1', '築城詞二首 一', '築城词二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["城上一培土，手中千萬杵。","築城畏不堅，堅城在何處。"]', '["城上一培土，手中千万杵。","築城畏不堅，堅城在何处。"]', '诗', 'shi', '', NULL, '築城詞二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05514976-4289-46d9-b59e-ab088bc3f3e8', '築城詞二首 二', '築城词二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["莫歎將軍逼，將軍要却敵。","城高功亦高，爾命何勞惜。"]', '["莫歎將軍逼，將軍要却敵。","城高功亦高，爾命何勞惜。"]', '诗', 'shi', '', NULL, '築城詞二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e34d9e-3977-435e-a8ee-f08fd701f8aa', '古意', '古意', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["君心莫淡薄，妾意正栖託。","願得雙車輪，一夜生四角。"]', '["君心莫淡薄，妾意正栖託。","願得雙车輪，一夜生四角。"]', '诗', 'shi', '', NULL, '古意 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1dcec84-ca73-4305-a0d2-c5781bb69528', '春曉', '春晓', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["春庭曉景別，清露花邐迤。","黃蜂一過慵，夜夜棲香蘂。"]', '["春庭晓景別，清露花邐迤。","黄蜂一過慵，夜夜棲香蘂。"]', '诗', 'shi', '', NULL, '春曉 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c366a49-2b55-4c25-889b-4ea6b9246238', '雜興', '杂兴', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["桃李傍簷楹，無人賞春華。","時情重不見，却憶菖蒲花。"]', '["桃李傍簷楹，無人賞春华。","时情重不见，却憶菖蒲花。"]', '诗', 'shi', '', NULL, '雜興 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3cce70b-38fa-4fa4-ac91-9971af141f89', '鴈', '鴈', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["南北路何長，中間萬弋張。","不知煙霧裏，幾隻到衡陽。"]', '["南北路何长，中间万弋張。","不知煙霧裏，幾隻到衡陽。"]', '诗', 'shi', '', NULL, '鴈 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b60a6e5-bcc9-4e72-b263-e97994d2f06c', '寄遠', '寄远', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鬢亂羞雲卷，眉空羨月生。","中原猶將將，何日重卿卿。"]', '["鬢亂羞云卷，眉空羨月生。","中原猶將將，何日重卿卿。"]', '诗', 'shi', '', NULL, '寄遠 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83eca31-7944-46e5-ad98-f3ae9346d860', '庭前', '庭前', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["合歡能解恚，萱草信忘憂。","盡向庭前種，萋萋特地愁。"]', '["合歡能解恚，萱草信忘憂。","尽向庭前種，萋萋特地愁。"]', '诗', 'shi', '', NULL, '庭前 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51909e1-5abd-4874-b427-e54961f8fcc2', '洞房怨', '洞房怨', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["玉鍤朝扶鬢，金梯晚下臺。","春衫將別淚，一夜兩難裁。"]', '["玉鍤朝扶鬢，金梯晚下台。","春衫將別泪，一夜兩难裁。"]', '诗', 'shi', '', NULL, '洞房怨 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e33fda-27ab-4a02-a7b3-d33e6087df71', '江行', '江行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["酒旗菰葉外，樓影浪花中。","醉帆張數幅，唯待鯉魚風。"]', '["酒旗菰葉外，楼影浪花中。","醉帆張數幅，唯待鯉鱼风。"]', '诗', 'shi', '', NULL, '江行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1a2604-5009-406e-8815-51f91aad4005', '巫峽', '巫峽', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["巫峽七百里，巫山十二重。","年年自雲雨，環佩竟誰逢。"]', '["巫峽七百里，巫山十二重。","年年自云雨，环佩竟誰逢。"]', '诗', 'shi', '', NULL, '巫峽 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be0032a1-e532-423e-b101-d635e589bd38', '歸路', '归路', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["漸入新豐路，衰紅映小橋。","渾如七年病，初得一丸銷。"]', '["漸入新豐路，衰紅映小橋。","渾如七年病，初得一丸銷。"]', '诗', 'shi', '', NULL, '歸路 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d2f7437-cfba-4fdd-84b1-39f4ef17b59b', '南塘曲', '南塘曲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["妾住東湖下，郎居南浦邊。","閑臨煙水望，認得采菱船。"]', '["妾住东湖下，郎居南浦邊。","闲臨煙水望，認得采菱船。"]', '诗', 'shi', '', NULL, '南塘曲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e64532-f5b4-4be2-8bf5-4e04894b301b', '黃金二首 一', '黄金二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["自古黃金貴，猶沽駿與才。","近來簪珥重，無可上高臺。"]', '["自古黄金貴，猶沽駿與才。","近来簪珥重，無可上高台。"]', '诗', 'shi', '', NULL, '黃金二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0288676e-e5dd-414d-a192-8da9f35d11d6', '黃金二首 二', '黄金二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["平分從滿篋，醉擲任成堆。","恰莫持千萬，明明買禍胎。"]', '["平分從满篋，醉擲任成堆。","恰莫持千万，明明買禍胎。"]', '诗', 'shi', '', NULL, '黃金二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ce2b59-3788-4e91-9a68-4b5b52ab1e77', '夕陽', '夕陽', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["渡口和帆落，城邊帶角收。","如何茂陵客，江上倚危樓。"]', '["渡口和帆落，城邊带角收。","如何茂陵客，江上倚危楼。"]', '诗', 'shi', '', NULL, '夕陽 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c62f5a2-a2a6-4684-8a53-393f954230b4', '殘雪', '殘雪', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["桂冷微停素，峰乾不徧嵐。","何谿背林處，猶覆定僧庵。"]', '["桂冷微停素，峰乾不徧嵐。","何谿背林处，猶覆定僧庵。"]', '诗', 'shi', '', NULL, '殘雪 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eddd93d-1a7d-460a-bfaa-61192e195c8d', '古態', '古態', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["古態日漸薄，新妝心更勞。","城中皆一尺，非妾髻鬟高。"]', '["古態日漸薄，新妝心更勞。","城中皆一尺，非妾髻鬟高。"]', '诗', 'shi', '', NULL, '古態 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cae44f6-ccf9-4932-9cea-41d7344a07da', '大堤', '大堤', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["大堤春日暮，驄馬解鏤衢。","請君留上客，容妾薦彫胡。"]', '["大堤春日暮，驄马解鏤衢。","請君留上客，容妾薦彫胡。"]', '诗', 'shi', '', NULL, '大堤 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6bba8e-fefd-45f3-9339-d5df10bd87a7', '金陵道', '金陵道', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["北鴈行行直，東流澹澹春。","當時六朝客，還道帝鄉人。"]', '["北鴈行行直，东流澹澹春。","當时六朝客，還道帝乡人。"]', '诗', 'shi', '', NULL, '金陵道 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965a5dde-7b0c-405d-b2a4-2ef4a8a3a508', '離騷', '離騷', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["天問復招魂，無因徹帝閽。","豈知千麗句，不敵一讒言。"]', '["天问复招魂，無因徹帝閽。","豈知千丽句，不敵一讒言。"]', '诗', 'shi', '', NULL, '離騷 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b20486-3cd2-437b-9c4b-a6bb24a7e6bc', '對酒', '对酒', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["後代稱歡伯，前賢號聖人。","且須謀日富，不要道家貧。"]', '["後代稱歡伯，前賢號聖人。","且須謀日富，不要道家貧。"]', '诗', 'shi', '', NULL, '對酒 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0dc788-c96a-4caf-96b1-c0e886ab267a', '寄南岳客乞靈蕪香', '寄南岳客乞靈蕪香', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["聞說融峰下，靈香似反魂。","春來正堪采，試爲斸雲根。"]', '["闻说融峰下，靈香似反魂。","春来正堪采，試爲斸云根。"]', '诗', 'shi', '', NULL, '寄南岳客乞靈蕪香 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7721cf9f-6c6c-4f7b-8e29-a72cebb980a5', '山陽燕中郊樂錄', '山陽燕中郊乐錄', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["淮上能無雨，回頭總是情。","蒲帆渾未織，爭得一歡成。"]', '["淮上能無雨，回头總是情。","蒲帆渾未织，爭得一歡成。"]', '诗', 'shi', '', NULL, '山陽燕中郊樂錄 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f64981-0035-498e-a4d5-46f827b78f91', '偶作', '偶作', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雙眉初出繭，兩鬢正藏鴉。","自有王昌在，何勞近宋家。"]', '["雙眉初出繭，兩鬢正藏鴉。","自有王昌在，何勞近宋家。"]', '诗', 'shi', '', NULL, '偶作 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df0b225b-e2aa-43f1-883b-5b452c21d6c2', '有示', '有示', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["相對莫辭貧，蓬蒿任塞門。","無情是金玉，不報主人恩。"]', '["相对莫辞貧，蓬蒿任塞门。","無情是金玉，不報主人恩。"]', '诗', 'shi', '', NULL, '有示 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d5b80a9-3acc-447d-bb24-6d7cc7f29b0e', '秋思三首 一', '秋思三首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["桐露珪初落，蘭風佩欲衰。","不知能賦客，何似枉刀兒。"]', '["桐露珪初落，蘭风佩欲衰。","不知能賦客，何似枉刀兒。"]', '诗', 'shi', '', NULL, '秋思三首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d3232eb-3b6f-498d-a8d5-9d7a89931485', '秋思三首 二', '秋思三首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["誰在嫖姚幕，能教霹靂車。","至今思禿尾，無以代寒葅。"]', '["誰在嫖姚幕，能教霹靂车。","至今思禿尾，無以代寒葅。"]', '诗', 'shi', '', NULL, '秋思三首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36cb29d6-fb6f-4a4f-8260-46f6c0f1b7ac', '秋思三首 三', '秋思三首 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["未得同虀杵，何時減藥囊。","莫言天帝醉，秦暴不靈長。"]', '["未得同虀杵，何时減藥囊。","莫言天帝醉，秦暴不靈长。"]', '诗', 'shi', '', NULL, '秋思三首 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b103f6a9-5b6f-47c1-ab4b-a44064142400', '早春', '早春', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["雨冷唯添暑，煙初不著春。","數枝花纇小，愁殺扈芳人。"]', '["雨冷唯添暑，煙初不著春。","數枝花纇小，愁殺扈芳人。"]', '诗', 'shi', '', NULL, '早春 陸龜蒙 shi');
